INSERT IGNORE INTO `formation_categories` (`id`, `slug`, `name`, `createdAt`) VALUES ('4c2f266b-8881-53c9-aff5-f6fef0653ae3', 'fincludia-academy', 'FINCLUDIA Academy', CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('aae7f78e-2e2d-50aa-a9a6-1fb7bb6039f3', 'academy-methode', 'FINCLUDIA Academy — Méthode, parcours et repères', 'Le modèle pédagogique de FINCLUDIA : niveaux de maîtrise N0 à N5, preuve de compétence, parcours par public, Budget Lab, dictionnaire des notions et sources.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Méthode, parcours et repères', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'beginner', '["Modèle pédagogique et niveaux de maîtrise", "Comment le site valide réellement les tests", "Skills Passport — preuve de compétence", "Parcours personnalisés par public cible", "Budget Lab — cas de répartition par profil", "Dictionnaire maître consolidé des notions", "Référentiel des sources"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '["LYC", "ETU", "JAC", "SAL", "EPG"]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('ab06cdfc-93e2-5217-a55e-c4b81fb94c51', 'aae7f78e-2e2d-50aa-a9a6-1fb7bb6039f3', 'Modèle pédagogique et niveaux de maîtrise', NULL, NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d5863472-858f-5bfd-bdf1-ff2fc81ee096', 'ab06cdfc-93e2-5217-a55e-c4b81fb94c51', 'text', 1, '{"html": "<p>FINCLUDIA utilise une progression par compétences : comprendre une notion, l’appliquer, produire une preuve, corriger ses erreurs puis réutiliser la compétence dans un cas plus complexe. Une bonne moyenne générale ne peut pas compenser une erreur critique de sécurité, de conformité ou de distinction réel/fictif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9cba3f03-f4fa-5699-a4dc-122959eae6c4', 'ab06cdfc-93e2-5217-a55e-c4b81fb94c51', 'table', 2, '{"headers": ["Niveau", "Compétence attendue", "Public indicatif", "Évaluation"], "rows": [["N0 — Découverte", "Reconnaître le vocabulaire et les décisions simples.", "Lycéens/débutants", "Définitions, classement, choix simples."], ["N1 — Fondamentaux", "Construire un budget, comprendre comptes, épargne, dette et objectifs.", "Étudiants/débutants adultes", "Calculs simples et missions guidées."], ["N2 — Autonomie", "Prendre des décisions personnelles structurées et expliquer les arbitrages.", "Jeunes actifs/salariés/familles", "Scénarios, stress tests, bilan personnel."], ["N3 — Pratique professionnelle", "Piloter une activité avec CA, prix, marge, trésorerie, BFR et obligations.", "Indépendants/TPE/startups", "Cas métier et outils de pilotage."], ["N4 — Pilotage", "Relier états financiers, forecast, financement, risques et performance.", "PME/PMI/startups matures", "Revues de direction, scénarios et décisions documentées."], ["N5 — Expertise appliquée", "Traiter des opérations complexes, internationales ou fortement réglementées.", "Dirigeants/import-export/trade", "Cas multi-risques, conformité et sources actives."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('68f8ee27-fcf8-5145-a52e-36a8a8ba2faf', 'aae7f78e-2e2d-50aa-a9a6-1fb7bb6039f3', 'Comment le site valide réellement les tests', NULL, NULL, 2, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('724abf98-4c0b-55fd-be3e-7fee1005e1c7', '68f8ee27-fcf8-5145-a52e-36a8a8ba2faf', 'table', 1, '{"headers": ["Mécanisme", "Règle V10"], "rows": [["Diagnostic d’entrée", "20 à 30 QCM à réponse unique, répartis par domaine. Il recommande un point d’entrée ; il ne délivre pas à lui seul une certification."], ["QCM de module", "Banque cible : 10 questions ; session : 5 tirées aléatoirement, ordre des réponses mélangé. Une seule bonne réponse. Seuil : 80 %."], ["Question critique", "Sécurité, fraude, conformité, fiscalité, crédit, séparation réel/fictif : réponse obligatoire correcte. Une erreur critique bloque le module même si la moyenne est élevée."], ["Exercice", "Réponse numérique, classement, tableau ou choix structuré. Seuil : 70 %. Les calculs numériques utilisent une tolérance paramétrée ; les classifications utilisent une clé de correction."], ["Mission", "Validation par l’outil FINCLUDIA : le site vérifie que l’utilisateur a réellement produit le budget, scénario, checklist, simulation ou livrable demandé."], ["Score de module", "50 % QCM + 30 % exercice + 20 % mission. Module validé si score ≥ 80 %, QCM ≥ 80 %, exercice ≥ 70 %, mission terminée et aucune erreur critique."], ["Rattrapage", "60-79 % : remédiation ciblée sur les notions ratées puis nouvelle session avec autres questions. <60 % : relecture guidée + exercice obligatoire avant nouveau test."], ["Cas intégrateur", "Cas structuré multi-étapes. Seuil : 75 %. Les éléments calculables sont corrigés automatiquement ; les justifications sont évaluées par critères explicites. Aux niveaux avancés, une revue humaine peut être ajoutée."], ["Passage de niveau", "Tous les modules obligatoires du niveau validés + moyenne de maîtrise ≥80 % + cas intégrateur ≥75 % + compétences critiques valides."], ["Exemption", "Un prétest ≥85 % peut dispenser de certains modules fondamentaux, sauf modules de sécurité, conformité et réglementation active."], ["Expiration ciblée", "Une compétence réglementaire peut passer « à actualiser » si sa source change ; les autres compétences restent acquises."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5d87e641-e388-5f54-84c5-dbd543352fb4', '68f8ee27-fcf8-5145-a52e-36a8a8ba2faf', 'text', 2, '{"html": "<h3>Formule de progression\\nScore_module = 0,50 × QCM + 0,30 × exercice + 0,20 × mission. Le niveau suivant est débloqué seulement si toutes les compétences obligatoires du niveau sont validées et si le cas intégrateur est réussi.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('f3412699-6cff-58c9-9426-afe3a105ba3d', 'aae7f78e-2e2d-50aa-a9a6-1fb7bb6039f3', 'Skills Passport — preuve de compétence', NULL, NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1f42103f-86e7-5829-8ebc-59ffa7687544', 'f3412699-6cff-58c9-9426-afe3a105ba3d', 'table', 1, '{"headers": ["Champ", "Fonction"], "rows": [["competency_id", "Compétence stable, reliée à un ou plusieurs modules."], ["module_id", "Module dans lequel la preuve a été obtenue."], ["Level", "N0 à N5."], ["qcm_score", "Score de connaissance."], ["exercise_score", "Score d’application."], ["mission_status", "Réalisée / à corriger / validée."], ["critical_errors", "Liste des erreurs bloquantes éventuelles."], ["mastery_score", "Score consolidé du module."], ["evidence_type", "Budget, simulation, tableau, checklist, cas, document."], ["evidence_ref", "Référence interne au résultat, sans données sensibles inutiles."], ["content_version", "Version du module et des règles utilisées."], ["verified_at", "Date de validation."], ["refresh_due", "Date de revue si la compétence dépend d’une règle évolutive."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('79a5deed-a9d7-5a9a-93c8-3e255f8757e5', 'aae7f78e-2e2d-50aa-a9a6-1fb7bb6039f3', 'Parcours personnalisés par public cible', NULL, NULL, 4, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4f495123-6fcc-5501-885e-c4ef462fd9dc', '79a5deed-a9d7-5a9a-93c8-3e255f8757e5', 'table', 1, '{"headers": ["Public", "Niveau conseillé", "Modules cœur", "Certification pédagogique"], "rows": [["Lycéen", "N0-N1", "BUD-01→03, BUD-07→08, BNK-01→02, BNK-06, ECO-01, ECO-03, INV-01, INV-06", "Passeport Avenir — Bases financières"], ["Étudiant", "N1", "BUD-01→05, BUD-07→11, BNK-02→06, ECO-03→04, INV-01→04 ; SAL-01", "Passeport Campus — Autonomie financière"], ["Jeune actif / premier emploi", "N1-N2", "BUD-01→12, BNK-02→06, ECO-03, ECO-05, INV-01→04", "Premier Revenu — Pilotage financier"], ["Demandeur d’emploi / chômeur", "N1-N2", "BUD-01→07, BUD-11, BNK-01→06, ECO-04, START-01→03, PRO-01", "Autonomie & Projet — Préparation financière"], ["Salarié", "N2", "BUD-02,04→12, BNK-03→07, INV-01→12, ECO-03,05→06 ; SAL-01, TAX-01", "Pilotage financier personnel"], ["Colocataire", "N1-N2", "BUD-02→04, COL-01→04, COL-07, BNK-06", "Gestion collective — Colocation"], ["Couple", "N1-N2", "BUD-02→07, COL-01→07, BNK-04→06, INV-01→03", "Gestion collective — Couple"], ["Famille", "N1-N3", "BUD-02→12, COL-01→07, BNK-02→07, INV-01→06, ECO-03 ; TAX-01, ETH-01 (optionnel)", "Résilience financière du foyer"], ["Épargnant débutant", "N1-N3", "BUD-05,10→12, INV-01→12, BNK-05→06, ECO-03,05", "Épargne & Investissement — Bases"], ["Artisan", "N2-N3", "PRO-01→11, AE-01→08 si statut applicable, BNK-03→06, BUS-02→05 ; TAX-01, ETH-01 (optionnel)", "Pilotage financier Artisan"], ["Profession libérale", "N2-N4", "PRO-01→11, LIB-01→06, BNK-03→07, BUS-01→05 ; TAX-01, ETH-01 (optionnel)", "Pilotage financier — Profession libérale"], ["Auto-entrepreneur", "N2-N3", "PRO-01→11, AE-01→08, BNK-03→07, MI-01→08 si micro-importation ; TAX-01, ETH-01 (optionnel)", "Gestion financière Auto-entrepreneur"], ["Porteur de projet", "N2-N3", "BUD-11, BNK-04→05, START-01→03, START-08→10, PRO-03→05, PRO-10", "Projet Innovant — Préparation financière"], ["Startuppeur / fondateur", "N2-N4", "START-01→10, BUS-02→06, BUS-12, ECO-08, BNK-04", "Startup Finance & Runway"], ["Startup en croissance", "N3-N5", "START-04→10, BUS-01→14, ECO-08→10, TR selon activité", "Finance & Pilotage Startup"], ["Micro-entreprise", "N2-N4", "PRO-01→11, BUS-01→08, BUS-12→13, BNK-04→05", "Gestion financière Micro-entreprise"], ["Dirigeant PME", "N3-N5", "BUS-01→14, ECO-02→10, BNK-04→05, TR selon exposition ; TAX-01, ESG-01", "Pilotage financier PME"], ["Dirigeant PMI / industrie", "N3-N5", "BUS-01→14 avec focus BUS-08→11, ECO-08→10, TR-01→12 si international ; TAX-01, ESG-01", "Pilotage financier industriel PMI"], ["Diaspora", "N2-N4", "DIA-01→08, BUD-12, BNK-03→06, INV-01→12, ECO-07", "Diaspora Finance & Projet Algérie"], ["Micro-importateur", "N3-N4", "AE-01→08, MI-01→08, TR-01→08, PRO-03→07", "Micro-Import Finance & Compliance"], ["Importateur", "N3-N5", "TR-01→09, TR-11→12, BUS-03→06, BUS-08, ECO-07→09", "Import Finance & Landed Cost"], ["Exportateur", "N3-N5", "TR-01→05, TR-09→12, BUS-03→06, ECO-07→10", "Export Finance & International Sales"], ["Commerce international avancé", "N4-N5", "TR-01→12, ECO-07→10, BUS-03→06, BUS-12", "Commerce international — Finance & opérations"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('825444fd-b9f7-5958-9513-8cc59ebddce4', '79a5deed-a9d7-5a9a-93c8-3e255f8757e5', 'text', 2, '{"html": "<h3>Règle de personnalisation\\nDeux utilisateurs appartenant au même public peuvent recevoir des séquences différentes. Le diagnostic, les objectifs, les compétences déjà acquises et les résultats déterminent les modules obligatoires, de renforcement et optionnels.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('97223674-fbdb-5f14-bbe0-3264bf4500a7', 'aae7f78e-2e2d-50aa-a9a6-1fb7bb6039f3', 'Budget Lab — cas de répartition par profil', NULL, NULL, 5, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('773e428d-edab-5b86-adee-980b44d28239', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 1, '{"html": "<p>Les budgets sont des scénarios pédagogiques fictifs en dinars algériens. Ils servent à enseigner une méthode ; ils ne représentent ni un coût officiel de la vie ni une norme de dépense.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('693f81d8-8016-56b0-abbe-08a483480343', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'table', 2, '{"headers": ["Profil fictive", "Répartition illustrative", "Modules liés"], "rows": [["Lycéen — 8 000 DA", "Transport 1 800 ; restauration 1 600 ; télécom 600 ; apprentissage 1 000 ; loisirs 1 000 ; projet 1 500 ; marge 500", "BUD-01→03, BUD-07"], ["Étudiant — 35 000 DA", "Logement/contribution 10 000 ; alimentation 7 000 ; transport 5 000 ; études 3 000 ; télécom 1 500 ; réserve 3 000 ; loisirs 2 500 ; marge 3 000", "BUD-02→05, BUD-07"], ["Demandeur d’emploi — ressources irrégulières 45 000 DA", "Base essentielle 30 000 ; recherche emploi/transport 4 000 ; télécom 2 000 ; réserve 5 000 ; projet/formation 3 000 ; marge 1 000", "BUD-02,04→05,11 ; ECO-04"], ["Salarié — 100 000 DA", "Logement 30 000 ; alimentation 18 000 ; transport 10 000 ; engagements 10 000 ; réserve/épargne 15 000 ; projets 7 000 ; loisirs 6 000 ; marge 4 000", "BUD-02→12"], ["Famille — 200 000 DA", "Logement 45 000 ; alimentation 38 000 ; transport 22 000 ; éducation 18 000 ; énergie/télécom 12 000 ; santé 8 000 ; dettes 15 000 ; réserve/objectifs 25 000 ; loisirs 10 000 ; provision irrégulière 7 000", "COL-01→07 ; BUD-04→06"], ["Artisan — CA fictif 250 000 DA", "Achats/coûts directs 90 000 ; atelier/transport/outils 40 000 ; réserve fiscale/sociale 25 000 ; trésorerie sécurité 25 000 ; investissement 20 000 ; rémunération personnelle 50 000", "PRO-01→08 ; PRO-09"], ["Profession libérale — encaissements 300 000 DA", "Charges pro 80 000 ; réserve fiscale/sociale 45 000 ; réserve pro 30 000 ; investissement 25 000 ; rémunération personnelle 120 000", "LIB-01→06 ; PRO-01→11"], ["Auto-entrepreneur — CA fictif 250 000 DA", "Coûts activité 75 000 ; réserve fiscal/social 25 000 ; cash sécurité 30 000 ; matériel/croissance 25 000 ; rémunération personnelle 95 000", "AE-01→08 ; PRO-01→11"], ["Startup — encaissements 1,2 M / décaissements 1,6 M DA", "Produit 500 000 ; équipe 600 000 ; vente/marketing 250 000 ; admin/outils 150 000 ; autres 100 000. Burn net simplifié : 400 000 DA/mois.", "START-04→07 ; BUS-04"], ["Micro-entreprise — CA fictif 1,5 M DA", "Coûts variables 600 000 ; salaires 300 000 ; charges fixes 220 000 ; fiscal/social 120 000 ; dette 80 000 ; investissement 80 000 ; marge cash avant BFR 100 000", "BUS-02→08"], ["PME/PMI — CA fictif 8 M DA", "Achats/variables 3,2 M ; masse salariale 2 M ; charges fixes 1,1 M ; dette 0,4 M ; fiscal 0,5 M ; CAPEX 0,3 M ; marge de trésorerie avant BFR 0,5 M", "BUS-01→14"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('840043a6-bcc3-58e9-a647-bf8beda820d1', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 3, '{"html": "<h2>6.1 Méthodes de répartition</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cf9ef46f-1a90-5a6a-ac66-2435f9ef8adf', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'table', 4, '{"headers": ["Méthode", "Principe", "Précaution"], "rows": [["Budget par enveloppes", "Fixer un plafond par catégorie et suivre le restant.", "Très utile pour dépenses variables."], ["Budget base zéro", "Affecter chaque dinar à une destination : dépenses, réserves, dette, objectif, marge.", "Ne signifie pas tout dépenser."], ["Répartition type 50/30/20", "Repère pédagogique besoins/envies/épargne-dette.", "Jamais une norme universelle ; adapter au revenu et aux charges."], ["Budget plancher", "Construire sur un revenu prudent lorsque les ressources sont irrégulières.", "Particulièrement utile aux indépendants."], ["Budget annuel mensualisé", "Transformer les dépenses annuelles prévisibles en provisions mensuelles.", "Rentrée scolaire, assurance, maintenance, taxes, renouvellements."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b970255c-584a-568e-a774-67d13f17803b', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 5, '{"html": "<h2>6.2 Mini-cours budgétaires par public</h2><p>Ces huit mini-cours complètent le Budget Lab. Les montants sont fictifs et pédagogiques : ils montrent une mécanique de répartition et ne constituent ni une moyenne nationale ni une norme de dépense.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('550ef387-5178-5052-8f86-8952d26cea7c', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 6, '{"html": "<h2>Mini-cours profil 7 — Construire le budget d''un lycéen</h2><ul><li><strong>Lycéen</strong> : adapter un budget au cycle de vie; identifier les priorités; mesurer la marge de manœuvre</li><li><strong>Notion</strong> : Définition — Réf.</li><li><strong>Budget</strong> : Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. — [S01], [S32]</li><li><strong>Revenu</strong> : Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. — [S08]</li><li><strong>Épargne</strong> : Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. — [S01], [S32]</li><li><strong>Dépense discrétionnaire</strong> : Dépense pouvant être réduite, différée ou arbitrée plus facilement qu’une dépense essentielle, selon les priorités de l’utilisateur. — [S47]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('439d0620-d627-5582-8f41-f5798b58fc57', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 7, '{"html": "<h3>Logique du budget</h3><p>Le budget illustratif utilise un niveau de ressources de 12 000 DA par mois. Il ne représente pas une moyenne nationale ; il sert à montrer la mécanique de répartition.</p><p>Objectif pédagogique : Économiser pour un ordinateur, une formation ou un projet scolaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0216d4be-9cbb-5370-a141-05b3bf46da8b', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'callout', 8, '{"variant": "info", "title": "Cas algérien", "html": "<p>Le budget total affecté est de 12 000 DA. Les postes doivent être ajustés au profil réel, et tout écart entre ressources et affectations doit être expliqué : épargne supplémentaire, réserve ou déficit à corriger.</p><p>Catégorie</p><p>Transport</p><p>Téléphone / Internet</p><p>Déjeuner / collation</p><p>Loisirs</p><p>Épargne projet</p><p>Réserve</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ea90c862-9508-577c-984d-f5826d7fba0c', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 9, '{"html": "<h3>Exercice</h3><p>Recréez ce budget avec un revenu inférieur de 15 %, puis avec un revenu supérieur de 15 %. Quels postes changent en premier ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4ff93cc5-c39d-5f58-9bff-810180b23f7d', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 10, '{"html": "<h3>Corrigé-type</h3><p>Corrigé-type : ressources -15 % = 10 200 DA ; +15 % = 13 800 DA. Protéger transport/études utiles et réduire en premier loisirs ou dépenses flexibles ; ajuster l’épargne-projet sans la supprimer automatiquement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8a1ec89e-0dc2-528c-b471-c8b9d092a65f', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 11, '{"html": "<h2>Mini-cours profil 8 — Construire le budget d''un étudiant</h2><ul><li><strong>Étudiant</strong> : adapter un budget au cycle de vie; identifier les priorités; mesurer la marge de manœuvre</li><li><strong>Notion</strong> : Définition — Réf.</li><li><strong>Budget</strong> : Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. — [S01], [S32]</li><li><strong>Revenu</strong> : Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. — [S08]</li><li><strong>Épargne</strong> : Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. — [S01], [S32]</li><li><strong>Fonds de sécurité</strong> : Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles. — [S03], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8fefe693-4369-54ed-9c6e-5d86d4e309c9', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 12, '{"html": "<h3>Logique du budget</h3><p>Le budget illustratif utilise un niveau de ressources de 30 000 DA par mois. Il ne représente pas une moyenne nationale ; il sert à montrer la mécanique de répartition.</p><p>Objectif pédagogique : Apprendre à arbitrer entre dépenses immédiates et autonomie future.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1110397f-556e-52c4-8c27-c5d0f4fd8c0d', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'callout', 13, '{"variant": "info", "title": "Cas algérien", "html": "<p>Le budget total affecté est de 30 000 DA. Les postes doivent être ajustés au profil réel, et tout écart entre ressources et affectations doit être expliqué : épargne supplémentaire, réserve ou déficit à corriger.</p><p>Catégorie</p><p>Transport</p><p>Alimentation</p><p>Téléphone / Internet</p><p>Études / fournitures</p><p>Vie sociale</p><p>Épargne</p><p>Réserve</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f83a7229-a7e0-513d-a1ef-be8bd15e6df3', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 14, '{"html": "<h3>Exercice</h3><p>Recréez ce budget avec un revenu inférieur de 15 %, puis avec un revenu supérieur de 15 %. Quels postes changent en premier ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8cf84c4c-7578-5f9d-9612-07221c44d0f1', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 15, '{"html": "<h3>Corrigé-type</h3><p>Corrigé-type : ressources -15 % = 25 500 DA ; +15 % = 34 500 DA. Priorité aux dépenses d’études, alimentation et transport ; vie sociale et dépenses flexibles sont les premiers leviers, puis réévaluer le rythme d’épargne.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('78e953c9-e3d9-5b84-ac75-31b84198e352', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 16, '{"html": "<h2>Mini-cours profil 9 — Construire le budget d''un salarié</h2><ul><li><strong>Salarié</strong> : adapter un budget au cycle de vie; identifier les priorités; mesurer la marge de manœuvre</li><li><strong>Notion</strong> : Définition — Réf.</li><li><strong>Budget</strong> : Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. — [S01], [S32]</li><li><strong>Revenu</strong> : Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. — [S08]</li><li><strong>Dette</strong> : Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. — [S01], [S32]</li><li><strong>Fonds de sécurité</strong> : Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles. — [S03], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ccc6a231-6eeb-5cb2-a16a-77810f0bf787', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 17, '{"html": "<h3>Logique du budget</h3><p>Le budget illustratif utilise un niveau de ressources de 90 000 DA par mois. Il ne représente pas une moyenne nationale ; il sert à montrer la mécanique de répartition.</p><p>Objectif pédagogique : Construire un fonds d''urgence puis financer un objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('492fc68e-3d2b-594e-974c-03172f0ebf13', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'callout', 18, '{"variant": "info", "title": "Cas algérien", "html": "<p>Le budget total affecté est de 90 000 DA. Les postes doivent être ajustés au profil réel, et tout écart entre ressources et affectations doit être expliqué : épargne supplémentaire, réserve ou déficit à corriger.</p><p>Catégorie</p><p>Logement / participation foyer</p><p>Alimentation</p><p>Transport</p><p>Télécom / abonnements</p><p>Dette</p><p>Épargne sécurité</p><p>Objectif</p><p>Discrétionnaire</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3ed19849-7526-5ebc-b2ef-edf9df77ba4a', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 19, '{"html": "<h3>Exercice</h3><p>Recréez ce budget avec un revenu inférieur de 15 %, puis avec un revenu supérieur de 15 %. Quels postes changent en premier ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6115291f-b33e-5e62-b000-ba5b9adf8a1f', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 20, '{"html": "<h3>Corrigé-type</h3><p>Corrigé-type : ressources -15 % = 76 500 DA ; +15 % = 103 500 DA. Protéger logement, alimentation, transport essentiel et échéances ; réduire discrétionnaire puis objectifs non urgents avant de fragiliser la réserve de sécurité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fbd88704-0b84-5fac-beb3-e5dfad6f5c31', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 21, '{"html": "<h2>Mini-cours profil 10 — Construire le budget d''un famille</h2><ul><li><strong>Famille</strong> : adapter un budget au cycle de vie; identifier les priorités; mesurer la marge de manœuvre</li><li><strong>Notion</strong> : Définition — Réf.</li><li><strong>Budget</strong> : Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. — [S01], [S32]</li><li><strong>Dépense commune</strong> : Dépense bénéficiant à plusieurs membres d’un groupe ou d’un foyer et répartie selon une règle acceptée. — [S32]</li><li><strong>Fonds de sécurité</strong> : Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles. — [S03], [S32]</li><li><strong>Objectif financier</strong> : Projet défini par un montant, un horizon, une priorité et une contribution à fournir. — [S01], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9b9f77ea-27ea-5814-aa14-adf4c7b14985', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 22, '{"html": "<h3>Logique du budget</h3><p>Le budget illustratif utilise un niveau de ressources de 180 000 DA par mois. Il ne représente pas une moyenne nationale ; il sert à montrer la mécanique de répartition.</p><p>Objectif pédagogique : Protéger le foyer tout en préparant logement, études et retraite.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('83d16ca8-91b9-58ea-a412-64592dd6f132', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'callout', 23, '{"variant": "info", "title": "Cas algérien", "html": "<p>Le budget total affecté est de 180 000 DA. Les postes doivent être ajustés au profil réel, et tout écart entre ressources et affectations doit être expliqué : épargne supplémentaire, réserve ou déficit à corriger.</p><p>Catégorie</p><p>Logement</p><p>Alimentation</p><p>Transport</p><p>Éducation / enfants</p><p>Santé</p><p>Énergie / télécom</p><p>Dette</p><p>Épargne sécurité</p><p>Projets</p><p>Loisirs</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('106c31d6-521a-578d-8510-a47f3e489640', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 24, '{"html": "<h3>Exercice</h3><p>Recréez ce budget avec un revenu inférieur de 15 %, puis avec un revenu supérieur de 15 %. Quels postes changent en premier ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f0adc2a5-828e-5e5d-a387-248e7b0c8d13', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 25, '{"html": "<h3>Corrigé-type</h3><p>Corrigé-type : ressources -15 % = 153 000 DA ; +15 % = 207 000 DA. Arbitrer d’abord loisirs/projets reportables ; préserver logement, alimentation, santé, éducation prioritaire et engagements critiques. Documenter la décision familiale.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('63f1b601-8f32-50de-a1b4-7b93d41c3cb6', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 26, '{"html": "<h2>Mini-cours profil 11 — Construire le budget d''un profession libérale</h2><ul><li><strong>Profession libérale</strong> : adapter un budget au cycle de vie; identifier les priorités; mesurer la marge de manœuvre</li><li><strong>Notion</strong> : Définition — Réf.</li><li><strong>Budget</strong> : Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. — [S01], [S32]</li><li><strong>Encaissement</strong> : Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés. — [S14], [S32]</li><li><strong>Provision</strong> : Somme mise progressivement de côté pour une dépense future prévisible, même si elle n’est pas encore exigible. — [S32]</li><li><strong>Trésorerie</strong> : Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. — [S14], [S30]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a0d2cbdc-be2b-50c8-9c41-f7639079f9cd', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 27, '{"html": "<h3>Logique du budget</h3><p>Le budget illustratif utilise un niveau de ressources de 240 000 DA par mois. Il ne représente pas une moyenne nationale ; il sert à montrer la mécanique de répartition.</p><p>Objectif pédagogique : Séparer finances professionnelles et personnelles.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('06fbfd98-9f88-5980-bf13-2a0537940f78', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'callout', 28, '{"variant": "info", "title": "Cas algérien", "html": "<p>Le budget total affecté est de 240 000 DA. Les postes doivent être ajustés au profil réel, et tout écart entre ressources et affectations doit être expliqué : épargne supplémentaire, réserve ou déficit à corriger.</p><p>Catégorie</p><p>Charges professionnelles</p><p>Provision fiscal/social</p><p>Revenu personnel</p><p>Réserve professionnelle</p><p>Investissement materiel</p><p>Formation</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f921bc98-a73e-535d-a34c-81e7a7929858', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 29, '{"html": "<h3>Exercice</h3><p>Recréez ce budget avec un revenu inférieur de 15 %, puis avec un revenu supérieur de 15 %. Quels postes changent en premier ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e6f564d7-61ca-5315-92e4-3222d7db2c1b', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 30, '{"html": "<h3>Corrigé-type</h3><p>Corrigé-type : encaissements -15 % = 204 000 DA ; +15 % = 276 000 DA. Ne pas confondre encaissement et revenu personnel : protéger charges pro, réserve fiscale/sociale et trésorerie ; ajuster rémunération personnelle et investissements reportables.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('96482ca7-23f0-58a7-9576-8479f7eede74', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 31, '{"html": "<h2>Mini-cours profil 12 — Construire le budget d''un auto-entrepreneur</h2><ul><li><strong>Auto-entrepreneur</strong> : adapter un budget au cycle de vie; identifier les priorités; mesurer la marge de manœuvre</li><li><strong>Notion</strong> : Définition — Réf.</li><li><strong>Auto-entrepreneur</strong> : Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles. — [S09], [S10]</li><li><strong>Chiffre d’affaires</strong> : Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable. — [S04], [S05]</li><li><strong>Provision</strong> : Somme mise progressivement de côté pour une dépense future prévisible, même si elle n’est pas encore exigible. — [S32]</li><li><strong>Trésorerie</strong> : Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. — [S14], [S30]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d0a41751-d5be-5d44-b150-d30dde6604e6', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 32, '{"html": "<h3>Logique du budget</h3><p>Le budget illustratif utilise un niveau de ressources de 180 000 DA par mois. Il ne représente pas une moyenne nationale ; il sert à montrer la mécanique de répartition.</p><p>Objectif pédagogique : Piloter le chiffre d''affaires, les dépenses et les obligations.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3c011615-881c-54d4-b918-e4f3374b81b3', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'callout', 33, '{"variant": "info", "title": "Cas algérien", "html": "<p>Le budget total affecté est de 180 000 DA. Les postes doivent être ajustés au profil réel, et tout écart entre ressources et affectations doit être expliqué : épargne supplémentaire, réserve ou déficit à corriger.</p><p>Catégorie</p><p>Dépenses activité</p><p>Provision fiscal/social</p><p>Rémunération personnelle</p><p>Trésorerie sécurité</p><p>Marketing / outils</p><p>Formation / croissance</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f978291c-a2c8-5fcc-97f2-6cfd5b80f535', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 34, '{"html": "<h3>Exercice</h3><p>Recréez ce budget avec un revenu inférieur de 15 %, puis avec un revenu supérieur de 15 %. Quels postes changent en premier ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('baa77508-2669-59ad-acb5-c7eceb020fb5', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 35, '{"html": "<h3>Corrigé-type</h3><p>Corrigé-type : CA -15 % = 153 000 DA ; +15 % = 207 000 DA. Protéger dépenses nécessaires à l’activité et provision fiscale/sociale ; réduire marketing/outils non essentiels ou croissance différable avant de consommer la trésorerie de sécurité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('af716186-99ca-5634-80c5-de0723eb4ddc', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 36, '{"html": "<h2>Mini-cours profil 13 — Construire le budget d''un entrepreneur / startup</h2><ul><li><strong>Entrepreneur / startup</strong> : adapter un budget au cycle de vie; identifier les priorités; mesurer la marge de manœuvre</li><li><strong>Notion</strong> : Définition — Réf.</li><li><strong>Burn</strong> : Consommation nette de trésorerie d’une startup sur une période lorsque ses décaissements dépassent ses encaissements. — [S32]</li><li><strong>Runway</strong> : Nombre de mois pendant lesquels une startup peut continuer à fonctionner avec sa trésorerie disponible sous une hypothèse donnée de consommation nette de cash. — [S32]</li><li><strong>Budget</strong> : Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. — [S01], [S32]</li><li><strong>Trésorerie</strong> : Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. — [S14], [S30]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('026c2a87-eeaa-5435-a69b-d41d256c4fef', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 37, '{"html": "<h3>Logique du budget</h3><p>Le budget illustratif utilise un niveau de ressources de 900 000 DA par mois. Il ne représente pas une moyenne nationale ; il sert à montrer la mécanique de répartition.</p><p>Objectif pédagogique : Maximiser le runway tout en finançant la traction.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b63e0696-ea3c-52bd-81e6-b1cf160cca26', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'callout', 38, '{"variant": "info", "title": "Cas algérien", "html": "<p>Le budget total affecté est de 900 000 DA. Les postes doivent être ajustés au profil réel, et tout écart entre ressources et affectations doit être expliqué : épargne supplémentaire, réserve ou déficit à corriger.</p><p>Catégorie</p><p>Salaires / prestataires</p><p>Produit / technologie</p><p>Marketing</p><p>Loyer / outils</p><p>Juridique / conformité</p><p>Réserve / runway</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('40777eab-2f64-5014-a957-b939f280f500', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 39, '{"html": "<h3>Exercice</h3><p>Recréez ce budget avec un revenu inférieur de 15 %, puis avec un revenu supérieur de 15 %. Quels postes changent en premier ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9eeacb58-5946-5058-839b-b47ea66f2350', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 40, '{"html": "<h3>Corrigé-type</h3><p>Corrigé-type : ressources -15 % = 765 000 DA ; +15 % = 1 035 000 DA. En scénario bas, prioriser produit critique, équipe indispensable et conformité ; retarder dépenses de croissance moins prouvées et surveiller l’effet sur burn/runway.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7e736aa7-7fe3-55c5-b5c0-6f8a7f0f6554', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 41, '{"html": "<h2>Mini-cours profil 14 — Construire le budget d''un pme / pmi</h2><ul><li><strong>PME / PMI</strong> : adapter un budget au cycle de vie; identifier les priorités; mesurer la marge de manœuvre</li><li><strong>Notion</strong> : Définition — Réf.</li><li><strong>Budget</strong> : Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. — [S01], [S32]</li><li><strong>Besoin en fonds de roulement</strong> : Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation. — [S15]</li><li><strong>Trésorerie</strong> : Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. — [S14], [S30]</li><li><strong>CAPEX</strong> : Dépense d’investissement destinée à acquérir ou améliorer un actif utilisé durablement dans l’activité. — [S13], [S42]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0ede3ba3-b757-5534-84c7-856031b6ba72', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 42, '{"html": "<h3>Logique du budget</h3><p>Le budget illustratif utilise un niveau de ressources de 8 000 000 DA par mois. Il ne représente pas une moyenne nationale ; il sert à montrer la mécanique de répartition.</p><p>Objectif pédagogique : Gérer marge, BFR, investissements et risques.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('56c5852c-4833-542c-9895-16a12cfc1131', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'callout', 43, '{"variant": "info", "title": "Cas algérien", "html": "<p>Le budget total affecté est de 8 000 000 DA. Les postes doivent être ajustés au profil réel, et tout écart entre ressources et affectations doit être expliqué : épargne supplémentaire, réserve ou déficit à corriger.</p><p>Catégorie</p><p>Achats / matières</p><p>Salaires</p><p>Frais généraux</p><p>Dette / leasing</p><p>Maintenance / logistique</p><p>Impôts / social provision</p><p>Capex / reserve</p><p>Marge / résultat cible</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a5ddcd67-5218-578b-b050-c21413dadc28', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 44, '{"html": "<h3>Exercice</h3><p>Recréez ce budget avec un revenu inférieur de 15 %, puis avec un revenu supérieur de 15 %. Quels postes changent en premier ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f9163229-64ee-569d-8dd1-6666e5f6a18c', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'text', 45, '{"html": "<h3>Corrigé-type</h3><p>Corrigé-type : ressources -15 % = 6 800 000 DA ; +15 % = 9 200 000 DA. Identifier coûts variables ajustables et coûts fixes incompressibles, protéger continuité opérationnelle, service de dette et conformité ; réviser CAPEX et stocks selon la demande et le BFR.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('0798581c-bfba-52da-99d2-07f8e570d8cb', 'aae7f78e-2e2d-50aa-a9a6-1fb7bb6039f3', 'course', '97223674-fbdb-5f14-bbe0-3264bf4500a7', 'QCM — Budget Lab', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
