INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('ff4a6103-a851-56cf-bae3-ced33ae6fed0', 'aae7f78e-2e2d-50aa-a9a6-1fb7bb6039f3', 'Dictionnaire maître consolidé des notions', NULL, NULL, 6, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d3ebd22b-dccd-5085-817e-2c8f9d13e10d', 'ff4a6103-a851-56cf-bae3-ced33ae6fed0', 'text', 1, '{"html": "<p>Une définition n’est écrite qu’une fois dans le référentiel. Les modules la réutilisent par concept_id et peuvent simplifier le langage selon le niveau sans modifier le sens.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('25a1486c-a528-5ea3-9aa9-03c1b77d78bc', 'ff4a6103-a851-56cf-bae3-ced33ae6fed0', 'table', 2, '{"headers": ["Concept", "Définition maître", "Références"], "rows": [["Action", "Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre.", "[S38], [S41]"], ["Arbitrage", "Choix entre plusieurs usages possibles d’une ressource limitée en fonction des priorités, contraintes et conséquences.", "[S01], [S02]"], ["ARR", "Annualisation pédagogique du revenu récurrent, souvent calculée à partir du MRR lorsque le modèle et la stabilité des revenus le permettent.", "[S32]"], ["Auto-entrepreneur", "Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles.", "[S09], [S10]"], ["Balance commerciale", "Différence entre exportations et importations de biens sur une période, selon le périmètre statistique retenu.", "[S32]"], ["Balance des paiements", "Cadre statistique retraçant les transactions économiques entre résidents d’une économie et non-résidents sur une période.", "[S32]"], ["Banque centrale", "Institution chargée de fonctions monétaires et financières publiques. En Algérie, la Banque d’Algérie veille notamment à la stabilité des prix, régule la liquidité et le crédit, surveille les systèmes de paiement, organise le marché des changes et contribue à la solidité du système bancaire.", "[S33], [S34]"], ["Besoin", "Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer.", "[S01], [S32]"], ["Besoin en fonds de roulement", "Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation.", "[S15]"], ["Bien-être financier", "État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière.", "[S03]"], ["Bilan", "État financier présentant la situation patrimoniale et financière d’une entité à une date donnée.", "[S13], [S42]"], ["BNC", "Bénéfices des professions non commerciales ; le régime simplifié BNC concerne notamment certaines professions libérales et détermine le bénéfice à partir des recettes et dépenses nécessaires.", "[S06]"], ["Bourse d’Alger", "Marché organisé des valeurs mobilières opéré par la SGBV sous le contrôle de la COSOB, avec des compartiments de titres de capital et de titres de créance.", "[S38], [S40], [S46]"], ["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01], [S32]"], ["Burn", "Consommation nette de trésorerie d’une startup sur une période lorsque ses décaissements dépassent ses encaissements.", "[S32]"], ["Business model", "Description de la manière dont l’entreprise crée son offre, la délivre à ses clients et génère des revenus.", "[S17]"], ["Business plan", "Dossier structurant le projet, ses hypothèses, son marché et ses prévisions financières, notamment compte de résultat, trésorerie, seuil de rentabilité et financement.", "[S18]"], ["CAC", "Coût d’acquisition client : dépenses commerciales/marketing attribuées à l’acquisition divisées par le nombre de nouveaux clients, selon une convention explicite.", "[S32]"], ["Cap table", "Tableau de répartition du capital d’une société entre fondateurs, investisseurs et autres détenteurs de titres.", "[S32]"], ["Capacité de remboursement", "Montant qu’un budget peut consacrer durablement à une échéance sans compromettre les dépenses essentielles, la sécurité et les autres engagements.", "[S22], [S32]"], ["CAPEX", "Dépense d’investissement destinée à acquérir ou améliorer un actif utilisé durablement dans l’activité.", "[S13], [S42]"], ["Cash Conversion Cycle", "Cycle de conversion du cash, généralement présenté comme DSO + DIO - DPO, pour visualiser la durée d’immobilisation du cash d’exploitation.", "[S32]"], ["Cash-flow personnel", "Différence entre ressources encaissées et sorties d’argent sur une période, après prise en compte des engagements suivis.", "[S32]"], ["Certification interne FINCLUDIA", "Attestation interne de compétences acquises à l’issue d’un parcours FINCLUDIA ; elle ne constitue ni diplôme d’État, ni agrément professionnel, ni autorisation réglementaire.", "[S32]"], ["Charge fixe", "Charge qui ne varie pas directement avec le volume d’activité à court terme, par exemple certains loyers ou abonnements.", "[S16]"], ["Charge variable", "Charge qui évolue avec le volume d’activité, par exemple certains achats de marchandises ou matières.", "[S16]"], ["Chiffre d’affaires", "Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable.", "[S04], [S05]"], ["Churn", "Taux de perte de clients ou de revenu récurrent sur une période, selon la convention de calcul affichée.", "[S32]"], ["Chômage", "Situation d’une personne sans emploi, disponible et recherchant un emploi selon la définition statistique applicable ; le taux dépend de la population active retenue.", "[S43], [S32]"], ["Classe d’actifs", "Catégorie d’investissements partageant des caractéristiques économiques et des profils de risque proches, par exemple actions ou obligations.", "[S38], [S41]"], ["Classification tarifaire", "Détermination du classement douanier d’une marchandise selon la nomenclature applicable ; elle doit être vérifiée auprès des sources compétentes.", "[S25], [S26]"], ["Clé de partage", "Règle qui détermine comment une dépense commune est répartie entre les personnes concernées.", "[S32]"], ["Comptabilité financière", "Système d’organisation de l’information financière permettant de saisir, classer, évaluer et présenter des données donnant une image fidèle de la situation, de la performance et de la trésorerie.", "[S13]"], ["Compte bancaire", "Relation de compte permettant d’enregistrer des opérations, de détenir un solde et d’utiliser des services de paiement selon les conditions de l’établissement.", "[S34], [S35]"], ["Compte de résultat", "État financier présentant produits et charges afin d’expliquer la performance d’une entité sur une période.", "[S13], [S42]"], ["Concentration", "Exposition excessive à un nombre limité d’actifs, d’émetteurs, de secteurs, de clients ou de risques.", "[S38], [S41]"], ["Conformité", "Respect des règles, procédures, autorisations et exigences applicables à une activité, un produit, une opération ou un acteur.", "[S25], [S31], [S32]"], ["Contrôle de conformité à l’importation", "Contrôle documentaire, visuel et, le cas échéant, analytique visant à vérifier la conformité des produits importés avant admission.", "[S25], [S31]"], ["Coût d’opportunité", "Valeur de la meilleure alternative à laquelle on renonce lorsqu’une ressource est affectée à un autre usage.", "[S02], [S32]"], ["Coût rendu", "Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus.", "[S19], [S25], [S32]"], ["Croissance économique", "Variation du niveau d’activité économique, souvent suivie par l’évolution du PIB réel entre deux périodes.", "[S43], [S32]"], ["Créance client", "Montant facturé à un client mais non encore encaissé.", "[S15], [S32]"], ["Crédit documentaire", "Engagement bancaire documentaire dans lequel le paiement dépend de la présentation de documents conformes aux termes convenus et aux règles applicables.", "[S19], [S21], [S32]"], ["Culture financière", "Combinaison de connaissances, compétences, attitudes et comportements permettant de prendre de bonnes décisions financières et d’améliorer son bien-être financier.", "[S01], [S02]"], ["Cycle économique", "Alternance de phases d’expansion, ralentissement ou contraction de l’activité, observée à travers plusieurs indicateurs et sans règle mécanique unique.", "[S43], [S32]"], ["Data room", "Espace structuré rassemblant les documents utiles à une analyse, une levée de fonds, un audit ou une relation avec un financeur.", "[S18], [S32]"], ["Demande", "Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions.", "[S32]"], ["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01], [S32]"], ["Dette fournisseur", "Montant dû à un fournisseur au titre d’achats ou services reçus et non encore réglés.", "[S15]"], ["Dette publique", "Ensemble des obligations financières des administrations publiques selon le périmètre statistique retenu.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6b31d1b2-8ca3-55b1-ad18-8b2ba1720f62', 'ff4a6103-a851-56cf-bae3-ced33ae6fed0', 'table', 3, '{"headers": ["Concept", "Définition maître", "Références"], "rows": [["Dilution", "Réduction du pourcentage de détention d’un actionnaire lorsque de nouveaux titres sont émis sans souscription proportionnelle de sa part.", "[S32]"], ["DIO", "Indicateur pédagogique du nombre moyen de jours pendant lesquels le stock reste immobilisé avant sa vente ou consommation.", "[S32]"], ["Diversification", "Répartition d’une exposition entre plusieurs actifs, émetteurs, secteurs ou catégories afin de réduire la dépendance à une seule source de risque ; elle ne supprime pas le risque de perte.", "[S01], [S41]"], ["Domiciliation bancaire du commerce extérieur", "Procédure bancaire encadrant certaines opérations de commerce extérieur conformément à la réglementation des changes et aux instructions de la Banque d’Algérie.", "[S20], [S21]"], ["DPO", "Indicateur pédagogique du délai moyen de règlement des fournisseurs, à rapprocher des achats à crédit.", "[S32]"], ["DSO", "Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période.", "[S30], [S32]"], ["Due diligence", "Démarche structurée de vérification d’une contrepartie, d’un projet ou d’une opération avant engagement.", "[S32]"], ["Décaissement", "Sortie effective de trésorerie ; il se distingue d’une charge comptable qui peut être constatée à une autre date.", "[S14], [S42]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Dépense commune", "Dépense bénéficiant à plusieurs membres d’un groupe ou d’un foyer et répartie selon une règle acceptée.", "[S32]"], ["Dépense fixe", "Dépense récurrente dont le montant varie peu à court terme, par exemple un loyer ou un abonnement.", "[S32]"], ["Dépense irrégulière", "Dépense non mensuelle mais prévisible ou possible, qui doit être anticipée par calendrier ou provision.", "[S32]"], ["Dépense variable", "Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport.", "[S32]"], ["Encaissement", "Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés.", "[S14], [S32]"], ["Enveloppe budgétaire", "Montant affecté à une catégorie ou un objectif pendant une période afin de suivre ce qui est prévu, consommé et restant.", "[S32]"], ["Envie", "Dépense souhaitée pour le confort, le plaisir ou la préférence, généralement plus facilement différable qu’un besoin.", "[S01], [S32]"], ["Facture", "Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables.", "[S04], [S05], [S32]"], ["Finance islamique", "Opérations de banque relevant du cadre algérien de la finance islamique, définies comme ne donnant pas lieu à la perception ou au versement d’intérêts et soumises aux règles spécifiques applicables.", "[S37]"], ["Flux de financement", "Flux qui modifient la taille ou la composition des capitaux propres et des emprunts.", "[S14]"], ["Flux de trésorerie d’exploitation", "Flux de trésorerie issus principalement des activités génératrices de revenus et des activités qui ne sont ni d’investissement ni de financement.", "[S14]"], ["Flux d’investissement", "Flux liés notamment à l’acquisition ou à la cession d’actifs à long terme et d’investissements non assimilés à de la trésorerie.", "[S14]"], ["FOMO", "Biais comportemental lié à la peur de manquer une opportunité, pouvant conduire à décider sous pression sans analyse suffisante.", "[S02], [S32]"], ["Fonds de roulement", "Ressources durables restant disponibles après financement des immobilisations et contribuant à couvrir le besoin en fonds de roulement.", "[S15], [S30]"], ["Fonds de sécurité", "Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles.", "[S03], [S32]"], ["Forecast", "Prévision révisée de l’activité et des résultats à partir des informations les plus récentes, distincte du budget initial.", "[S30], [S32]"], ["Frais bancaires", "Prix ou commission facturé par un établissement pour un produit, un service ou une opération ; l’utilisateur doit lire la grille tarifaire applicable et la date de validité.", "[S35]"], ["Horizon d’investissement", "Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné.", "[S02], [S41]"], ["IBS", "Impôt sur les bénéfices des sociétés, avec des taux différenciés selon la nature d’activité et les règles fiscales en vigueur.", "[S07]"], ["IFU", "Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur.", "[S04]"], ["Inclusion financière", "Accès et usage effectif de services financiers formels, adaptés et soutenables. Dans FINCLUDIA, elle inclut aussi la compréhension, la protection et la capacité à choisir de façon éclairée.", "[S01], [S35], [S36]"], ["Incoterms®", "Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises.", "[S19]"], ["Inflation", "Hausse générale et durable du niveau des prix ; son suivi en Algérie s’appuie notamment sur l’indice des prix à la consommation publié par l’ONS.", "[S43]"], ["Intérêt compose", "Mécanisme par lequel les gains d’une période s’ajoutent au capital et peuvent eux-mêmes produire des gains lors des périodes suivantes.", "[S02]"], ["Investissement en Algérie", "Projet de création, extension ou autre opération d’investissement relevant du cadre de la loi 22-18 et des procédures d’enregistrement et d’accompagnement de l’AAPI.", "[S28]"], ["IOB", "Intermédiaire en Opérations de Bourse : personne morale agréée par la COSOB pour exercer une ou plusieurs activités autorisées, dont la négociation de valeurs mobilières et, selon agrément, le conseil ou la gestion.", "[S39]"], ["IPC", "Indice des prix à la consommation mesurant l’évolution moyenne des prix d’un panier de biens et services selon la méthodologie statistique retenue.", "[S43]"], ["IRG sur salaires", "Impôt sur le revenu global appliqué aux traitements et salaires selon un barème progressif, des abattements et règles de retenue à la source.", "[S08]"], ["Label Startup", "Label algérien attribué sous conditions portant notamment sur l’âge de la société, l’innovation, le potentiel de croissance, la taille, le capital et le chiffre d’affaires selon le cadre en vigueur.", "[S11]"], ["Liquidité", "Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur.", "[S14], [S32]"], ["Liquidité financière", "Capacité à convertir un actif en monnaie disponible rapidement, à un coût et avec une perte de valeur limités.", "[S01], [S41]"], ["LTV", "Valeur économique estimée d’un client sur sa durée de relation, calculée selon les hypothèses de marge et de rétention affichées.", "[S32]"], ["Marché financier", "Ensemble organisé de mécanismes, acteurs et infrastructures permettant l’émission, la négociation, la conservation et le règlement de titres financiers.", "[S38], [S40]"], ["Marge sur coûts variables", "Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité.", "[S16]"], ["Matière première", "Ressource de base échangée et utilisée dans la production, dont le prix peut influencer coûts, inflation et commerce extérieur.", "[S32]"], ["Micro-importation", "Activité individuelle exercée sous statut auto-entrepreneur lors de déplacements à l’étranger pour importer à la revente des quantités limitées de biens dans les limites prévues par le décret 25-170.", "[S23], [S24]"], ["Mourabaha", "Opération de vente à marge connue dans laquelle l’établissement acquiert un bien puis le revend au client selon les conditions du produit autorisé.", "[S37]"], ["Moyen de paiement", "Instrument ou procédé permettant de transférer de la valeur ou d’exécuter un paiement : espèces, virement, carte, chèque ou solution de paiement autorisée.", "[S34], [S36]"], ["MRR", "Revenu mensuel récurrent utilisé comme indicateur pédagogique pour les modèles à abonnement ; il exclut les revenus non récurrents selon la convention retenue par FINCLUDIA.", "[S32]"], ["MVP", "Version minimale d’un produit permettant de tester une hypothèse centrale auprès d’utilisateurs avec un investissement limité.", "[S12], [S17], [S32]"], ["Objectif financier", "Projet défini par un montant, un horizon, une priorité et une contribution à fournir.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bca5f41f-512d-50d0-bb27-ff93b0c93eab', 'ff4a6103-a851-56cf-bae3-ced33ae6fed0', 'table', 4, '{"headers": ["Concept", "Définition maître", "Références"], "rows": [["Obligation", "Titre de créance par lequel l’investisseur prête des fonds à un émetteur selon des conditions de rémunération et de remboursement prévues.", "[S38], [S41]"], ["Offre", "Quantité d’un bien ou service que les producteurs sont disposés à proposer selon les prix et autres conditions.", "[S32]"], ["Open account", "Modalité dans laquelle la marchandise ou le service est fourni avant le paiement convenu, ce qui accroît généralement l’exposition du vendeur au risque client.", "[S19], [S32]"], ["Ordre de bourse", "Instruction transmise à un intermédiaire habilité pour acheter ou vendre un instrument financier selon des conditions définies.", "[S39], [S40]"], ["Origine des marchandises", "Lien économique ou douanier entre une marchandise et un pays, établi selon des règles spécifiques et pouvant influencer traitement et préférences.", "[S25], [S26]"], ["OTP", "Code d’authentification à usage unique utilisé pour confirmer une opération ou une connexion ; il doit rester secret.", "[S35], [S32]"], ["Patrimoine net", "Valeur des actifs détenus diminuée des dettes et autres passifs retenus.", "[S32]"], ["Phishing", "Technique de fraude visant à obtenir des informations sensibles ou provoquer une action en imitant un acteur de confiance.", "[S35], [S32]"], ["PIB", "Mesure de la valeur de la production finale de biens et services réalisée sur un territoire pendant une période ; il sert à suivre la taille et l’évolution de l’activité économique.", "[S43], [S32]"], ["PIB reel", "PIB corrigé des variations de prix afin de mieux mesurer l’évolution des volumes produits.", "[S32]"], ["Plan de trésorerie", "Prévision datée des encaissements et décaissements afin d’anticiper tensions, besoins ou excédents de liquidité.", "[S14], [S30]"], ["Point mort", "Temps nécessaire pour atteindre le seuil de rentabilité au cours d’une période.", "[S16]"], ["Politique budgétaire", "Décisions publiques portant sur les recettes, dépenses et solde budgétaire afin de financer l’action publique et d’influencer l’économie.", "[S32]"], ["Politique monétaire", "Ensemble des décisions et instruments par lesquels la banque centrale agit sur les conditions monétaires et financières afin de poursuivre ses objectifs, notamment la stabilité des prix.", "[S33], [S34]"], ["Portefeuille fictif", "Ensemble d’actifs simulés utilisé à des fins pédagogiques sans exécution réelle ni modification du patrimoine de l’utilisateur.", "[S32]"], ["Pouvoir d’achat", "Quantité de biens et services qu’un revenu ou un capital permet d’acquérir ; il évolue selon le niveau des prix et l’évolution des ressources.", "[S43], [S32]"], ["Prix de revient", "Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service.", "[S16], [S30]"], ["Productivité", "Rapport entre une production obtenue et les ressources utilisées pour la produire ; elle peut être mesurée par travailleur, heure de travail ou autre facteur.", "[S43], [S32]"], ["Projet innovant", "Parcours de labellisation comportant notamment description du projet, innovation, pitch deck, prototype, avancement et modèle économique.", "[S12]"], ["Provision", "Somme mise progressivement de côté pour une dépense future prévisible, même si elle n’est pas encore exigible.", "[S32]"], ["Quote-part", "Part d’une dépense commune attribuée à une personne selon une règle de partage égale, proportionnelle ou personnalisée.", "[S32]"], ["Relevé bancaire", "Document retraçant, pour une période, les opérations portées sur un compte et son solde selon les informations de l’établissement.", "[S35], [S32]"], ["Remise documentaire", "Mécanisme dans lequel des banques transmettent des documents contre paiement ou acceptation sans fournir le même engagement qu’un crédit documentaire.", "[S19], [S32]"], ["Rendement", "Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon.", "[S01], [S41]"], ["Reste à vivre", "Montant restant après déduction des catégories d’engagement retenues par le modèle ; la composition du calcul doit toujours être affichée.", "[S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"], ["Risque client", "Risque qu’un client paie en retard, ne paie pas ou crée une concentration excessive dans les revenus ou créances.", "[S30], [S32]"], ["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20], [S21]"], ["Risque de marché", "Risque de perte lié aux variations de prix, de taux, de change ou d’autres facteurs de marché.", "[S38], [S41]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02], [S22]"], ["Risque fournisseur", "Risque lié à la capacité, la qualité, la conformité, les délais ou la solidité d’un fournisseur.", "[S32]"], ["Risque logistique", "Risque de retard, perte, dommage, rupture ou surcoût lié au transport, stockage et circulation des marchandises.", "[S19], [S32]"], ["Risque réglementaire", "Risque qu’une règle applicable change, soit mal interprétée ou ne soit pas respectée, affectant une opération ou sa conformité.", "[S32]"], ["Runway", "Nombre de mois pendant lesquels une startup peut continuer à fonctionner avec sa trésorerie disponible sous une hypothèse donnée de consommation nette de cash.", "[S32]"], ["Réclamation bancaire", "Demande formalisée d’un client contestant un service, une opération ou un traitement ; les mécanismes de réclamation font partie de la protection de la clientèle.", "[S35]"], ["Résultat / bénéfice", "Excédent des produits sur les charges sur une période ; pour les BNC, la DGI définit le bénéfice comme l’excédent des recettes sur les dépenses nécessaires à l’exercice.", "[S06], [S13]"], ["Seuil de rentabilité", "Niveau de chiffre d’affaires à partir duquel l’entreprise couvre ses charges fixes et variables sans perte ni bénéfice.", "[S16]"], ["Solde budgétaire", "Différence entre les ressources d’une période et les dépenses effectivement supportées ou prévues sur cette même période.", "[S32]"], ["Solde collectif net", "Différence entre ce qu’un membre a payé pour le groupe et ce qu’il devait supporter selon la règle de partage.", "[S32]"], ["Stock", "Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés.", "[S13], [S42]"], ["Surface financière importateur", "Exigence bancaire applicable aux importations de biens destinés à la revente en l’état ; l’Instruction 05-2026 prévoit notamment l’appréciation préalable de la situation financière par la banque domiciliataire.", "[S29]"], ["Tableau de flux de trésorerie", "État financier expliquant les flux de trésorerie liés aux activités d’exploitation, d’investissement et de financement.", "[S14]"], ["Taux de change", "Prix d’une monnaie exprimé dans une autre monnaie ; pour toute opération réelle, la source, la date et la règle de change applicable doivent être conservées.", "[S20], [S21]"], ["Taux d’effort", "Indicateur pédagogique rapportant les remboursements de dettes aux revenus nets ; il ne constitue pas à lui seul une décision bancaire.", "[S32]"], ["Taux d’intérêt", "Prix du temps et du crédit exprimé en pourcentage selon une convention et une période ; son interprétation exige de préciser base, durée, frais et capitalisation.", "[S34], [S32]"], ["Taux d’épargne", "Part du revenu consacrée à l’épargne pendant une période : épargne / revenu × 100.", "[S32]"], ["Tolérance à la perte", "Capacité financière et psychologique à supporter une baisse de valeur sans compromettre un objectif ou une dépense essentielle.", "[S02], [S41]"], ["Transfert de fonds", "Mouvement d’argent entre personnes ou comptes ; FINCLUDIA distingue le déplacement de fonds d’un revenu nouvellement créé.", "[S20], [S32]"], ["Traçabilité", "Capacité à reconstituer l’origine, la date, la justification et les étapes d’une opération ou d’une décision.", "[S32]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14], [S30]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a41b7da3-76ae-521e-8254-a5790cc60f7a', 'ff4a6103-a851-56cf-bae3-ced33ae6fed0', 'table', 5, '{"headers": ["Concept", "Définition maître", "Références"], "rows": [["TVA", "Impôt calculé sur le chiffre d’affaires hors taxe pour les opérations et contribuables relevant des régimes concernés ; les taux et exonérations sont fixés par les textes en vigueur.", "[S05]"], ["Valeur en douane", "Base de valorisation utilisée pour le traitement douanier selon les règles applicables ; elle ne doit pas être confondue avec le seul prix fournisseur.", "[S25], [S26]"], ["Valorisation post-money", "Valeur conventionnelle après investissement ; dans un modèle simple, pré-money + nouvel investissement.", "[S32]"], ["Valorisation pré-money", "Valeur conventionnelle d’une société immédiatement avant une opération d’investissement.", "[S32]"], ["Écart budgétaire", "Différence entre une valeur réelle et une valeur budgétée ; son analyse vise à expliquer la cause avant de décider d’une action.", "[S30], [S32]"], ["Éducation financière bancaire", "Objectif de protection de la clientèle visant notamment la transparence et la capacité du client à prendre des décisions éclairées dans ses relations avec les banques et établissements concernés.", "[S22]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01], [S32]"], ["Charge", "Coût ou dépense supporté par un ménage ou une activité. En gestion d’entreprise, la charge est rattachée à une période et ne se confond pas toujours avec le décaissement immédiat.", "[S47]"], ["Dépense essentielle", "Dépense répondant à un besoin prioritaire dont la réduction immédiate peut compromettre les conditions de vie, la santé, le logement, la mobilité nécessaire ou la continuité d’une activité.", "[S47]"], ["Dépense discrétionnaire", "Dépense pouvant être réduite, différée ou arbitrée plus facilement qu’une dépense essentielle, selon les priorités de l’utilisateur.", "[S47]"], ["Budget base zéro", "Méthode budgétaire dans laquelle chaque dinar disponible reçoit une destination explicite : dépense, réserve, dette, objectif, investissement ou marge de sécurité.", "[S47]"], ["Se payer d’abord", "Principe consistant à programmer l’épargne ou la réserve avant les dépenses discrétionnaires, plutôt que d’épargner uniquement ce qui reste en fin de période.", "[S47]"], ["Fiche de paie", "Document décrivant la rémunération d’une période et ses composantes : base, primes ou indemnités, retenues sociales et fiscales et net à payer, selon la situation applicable.", "[S47]"], ["Salaire brut", "Rémunération avant les retenues sociales et fiscales applicables ; il ne correspond pas nécessairement au montant effectivement disponible pour le budget.", "[S47]"], ["Salaire net", "Montant de rémunération restant après les retenues applicables et servant de référence pratique pour le revenu réellement disponible, sous réserve des autres flux du ménage.", "[S47]"], ["Impôt", "Prélèvement obligatoire destiné au financement des charges publiques selon les règles applicables au contribuable, à l’assiette et à la période concernée.", "[S47]"], ["Taxe", "Prélèvement obligatoire établi selon une assiette ou un mécanisme défini par les textes en vigueur ; son traitement dépend du régime et de l’opération.", "[S47]"], ["Cotisation sociale", "Versement obligatoire ou volontaire selon le statut, destiné au financement de la protection sociale et/ou à l’ouverture de droits sociaux.", "[S47]"], ["Déclaration fiscale", "Obligation de communiquer à l’administration des informations selon un calendrier et un format déterminés ; elle peut conduire ou non à un paiement.", "[S47]"], ["Zakat", "Prélèvement religieux obligatoire pour les personnes et avoirs remplissant les conditions applicables. FINCLUDIA en présente une estimation pédagogique distincte de la fiscalité et renvoie les cas complexes vers une autorité qualifiée.", "[S47]"], ["Nisab", "Seuil de richesse à partir duquel la Zakat peut devenir exigible selon la catégorie d’avoirs et la méthodologie religieuse retenue ; sa valeur monétaire doit être datée et sourcée.", "[S47]"], ["Hawl", "Période de possession prise en compte dans certaines règles de Zakat ; son application dépend de la nature des avoirs et de la méthodologie religieuse suivie.", "[S47]"], ["Marge", "Écart entre un revenu ou chiffre d’affaires et une catégorie de coûts définie. Une marge doit toujours préciser son périmètre : marge brute, marge sur coûts variables, marge nette, etc.", "[S47]"], ["DSCR", "Debt Service Coverage Ratio : rapport entre un cash-flow disponible selon la convention retenue et le service de la dette sur la période. Il doit être interprété selon le secteur et le financeur.", "[S47]"], ["ROA", "Indicateur rapportant un résultat aux actifs mobilisés. Sa définition exacte dépend de la convention de résultat et d’actifs retenue.", "[S47]"], ["ROE", "Indicateur rapportant un résultat aux capitaux propres. Il doit être analysé avec la structure financière et le niveau de risque.", "[S47]"], ["Leasing", "Mode de financement de l’usage d’un actif selon un contrat de location financière dont les loyers, options, propriété finale et risques doivent être comparés au crédit et à l’achat comptant.", "[S47]"], ["Ijara", "Structure de finance islamique fondée sur une logique de location d’un actif selon les conditions contractuelles et réglementaires applicables.", "[S47]"], ["Musharaka", "Structure de finance islamique fondée sur une participation ou association au capital/au projet selon des modalités contractuelles définies.", "[S47]"], ["Crowdfunding", "Financement participatif mobilisant plusieurs contributeurs ou investisseurs autour d’un projet selon une forme et un cadre réglementaire déterminés.", "[S47]"], ["Dividende", "Distribution décidée par une société au profit des détenteurs de titres éligibles ; elle peut varier, être différée ou ne pas être versée.", "[S47]"], ["Sukuk", "Instrument de finance islamique structuré autour d’actifs, droits ou flux selon la structure retenue ; il ne doit pas être réduit à une simple obligation conventionnelle renommée.", "[S47]"], ["Allocation", "Répartition d’un budget ou d’un portefeuille entre plusieurs usages, actifs ou risques selon les objectifs, contraintes, horizon et besoin de liquidité.", "[S47]"], ["Indice boursier", "Mesure synthétique de la performance d’un ensemble de titres selon une méthodologie déterminée ; il sert de baromètre mais ne représente pas toute l’économie.", "[S47]"], ["Biais comportemental", "Tendance cognitive ou émotionnelle pouvant déformer l’analyse et la décision financière, par exemple surconfiance, ancrage, aversion aux pertes ou effet de foule.", "[S47]"], ["Finance verte", "Approche de financement ou d’investissement intégrant des objectifs environnementaux, tout en exigeant une analyse des coûts, économies, risques, durée et viabilité financière.", "[S47]"], ["Payback", "Délai de récupération simple d’un investissement, souvent estimé par investissement initial divisé par économie ou cash-flow annuel lorsque l’hypothèse de stabilité est acceptable.", "[S47]"], ["Actif", "Ressource économique détenue ou contrôlée par une personne ou une entité et susceptible de contribuer à sa situation patrimoniale ou à son activité.", "[S47]"], ["Passif", "Obligation ou dette envers un tiers figurant dans la structure financière d’une personne ou d’une entité.", "[S47]"], ["Capitaux propres", "Part résiduelle des actifs d’une entité après déduction de ses passifs, selon les règles comptables applicables.", "[S47]"], ["Current ratio", "Ratio de liquidité calculé comme actif courant divisé par passif courant ; son interprétation dépend du secteur, de la saisonnalité et de la qualité des actifs courants.", "[S47]"], ["Quick ratio", "Ratio de liquidité rapide calculé, de façon simplifiée, comme actif courant hors stocks divisé par passif courant.", "[S47]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('d9632cc6-e29e-5756-b2ae-c62b1be7e99a', 'aae7f78e-2e2d-50aa-a9a6-1fb7bb6039f3', 'Référentiel des sources', NULL, NULL, 7, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('970d3b50-0354-5660-824f-46ce472d2a46', 'd9632cc6-e29e-5756-b2ae-c62b1be7e99a', 'text', 1, '{"html": "<p>Les codes sources sont utilisés dans les définitions et modules. Les valeurs réglementaires évolutives doivent être stockées dans le Centre de confiance avec date d’effet, date de vérification et statut de fraîcheur.</p><ul><li><strong>S01</strong> : OCDE — Recommendation on Financial Literacy (2020) — https://legalinstruments.oecd.org/en/instruments/OECD-LEGAL-0461</li><li><strong>S02</strong> : OCDE — PISA 2022 Financial Literacy Framework — https://www.oecd.org/en/publications/pisa-2022-assessment-and-analytical-framework_dfe0bf9c-en/full-report/component-4.html</li><li><strong>S03</strong> : OCDE/G20 — Financial Well-being — https://www.oecd.org/en/publications/consumer-finance-risk-monitor-2026_61f7dbe0-en/full-report/monitoring-risks-faced-by-financial-consumers_19a99d0c.html</li><li><strong>S04</strong> : DGI Algérie — Régime IFU — https://www.mfdgi.gov.dz/fr/professionnels/services-pro/regime-forfaitaire-unique/ifu</li><li><strong>S05</strong> : DGI Algérie — TVA — https://www.mfdgi.gov.dz/fr/professionnels/services-pro/regime-reel/la-taxe-sur-la-valeur-ajoutee</li><li><strong>S06</strong> : DGI Algérie — Régime simplifié BNC — https://www.mfdgi.gov.dz/fr/professionnels/services-pro/regime-simplifie/le-regime-simplifie-bnc</li><li><strong>S07</strong> : DGI Algérie — IBS — https://www.mfdgi.gov.dz/fr/professionnels/services-pro/regime-reel/ibs</li><li><strong>S08</strong> : DGI Algérie — IRG traitements et salaires — https://www.mfdgi.gov.dz/fr/particuliers/irg-traitements-et-salaires</li><li><strong>S09</strong> : ANAE — Statut auto-entrepreneur — https://anae.dz/fr/</li><li><strong>S10</strong> : ANAE — Liste officielle des activités — https://activities.anae.dz/</li><li><strong>S11</strong> : Startup.dz — Label Startup — https://startup.dz/pour-les-startups/</li><li><strong>S12</strong> : Startup.dz — Label Projet Innovant — https://startup.dz/label-projet/</li><li><strong>S13</strong> : JORADP — Loi 07-11 portant système comptable financier — https://www.joradp.dz/ftp/jo-francais/2007/f2007074.pdf</li><li><strong>S14</strong> : IFRS Foundation — IAS 7 Statement of Cash Flows — https://www.ifrs.org/issued-standards/list-of-standards/ias-7-statement-of-cash-flows/</li><li><strong>S15</strong> : Bpifrance Création — Besoin en fonds de roulement — https://bpifrance-creation.fr/encyclopedie/previsions-financieres-business-plan/previsions-financieres/besoin-fonds-roulement-bfr</li><li><strong>S16</strong> : Bpifrance Création — Seuil de rentabilité — https://bpifrance-creation.fr/encyclopedie/previsions-financieres-business-plan/previsions-financieres/seuil-rentabilite</li><li><strong>S17</strong> : Bpifrance Création — Business model — https://bpifrance-creation.fr/boiteaoutils/decrire-son-business-model-modele-economique</li><li><strong>S18</strong> : Bpifrance Création — Business plan et prévisions — https://bpifrance-creation.fr/encyclopedie/previsions-financieres-business-plan/business-plan/faire-son-business-plan</li><li><strong>S19</strong> : ICC — Incoterms 2020 — https://iccwbo.org/business-solutions/incoterms-rules/</li><li><strong>S20</strong> : Banque d’Algérie — Réglementation des changes — https://www.bank-of-algeria.dz/devises-reglement/</li><li><strong>S21</strong> : Banque d’Algérie — Instructions importations/exportations — https://www.bank-of-algeria.dz/importations-exportations-instruction/</li><li><strong>S22</strong> : Banque d’Algérie — Règlement 25-03 protection de la clientèle — https://www.bank-of-algeria.dz/stoodroa/2025/05/Reglement-25-03-FR.pdf</li><li><strong>S23</strong> : JORADP — Décret exécutif 25-170 micro-importation — https://www.joradp.dz/FTP/jo-francais/2025/F2025040.pdf</li><li><strong>S24</strong> : ANAE — Guide micro-importateur — https://anae.dz/micro-importer/guide</li><li><strong>S25</strong> : Ministère du Commerce — Dossier importation et conformité — https://commerce.gov.dz/fr/3-depot-et-recevabilite-du-dossier-d-importation</li><li><strong>S26</strong> : Ministère du Commerce — Guide contrôle de conformité aux frontières — https://www.commerce.gov.dz/events/claff/guides/04-contr-front-fran.pdf</li><li><strong>S27</strong> : CNAS — Affiliation volontaire communauté nationale à l’étranger — https://teledeclaration.cnas.dz/signup.xhtml</li><li><strong>S28</strong> : AAPI — Guide pratique de l’investisseur en Algérie — https://aapi.dz/wp-content/uploads/2024/07/Guide-Investisseur_HCNRLI-1.pdf</li><li><strong>S29</strong> : Banque d’Algérie — Instruction 05-2026 surface financière importation revente en l’état — https://www.bank-of-algeria.dz/stoodroa/2026/05/Instruction-05-2026-Fr.pdf</li><li><strong>S30</strong> : Bpifrance Création — Indicateurs de gestion — https://bpifrance-creation.fr/encyclopedie/piloter-lentreprise/finance-pilotage-economique/indicateurs-gestion</li><li><strong>S31</strong> : Ministère du Commerce — Contrôle de conformité produits importés — https://commerce.gov.dz/fr/4-le-controle-de-la-conformite-des-produits-importes</li><li><strong>S32</strong> : Source interne projet FINCLUDIA</li><li><strong>S33</strong> : Institution officielle — Banque d’Algérie — Rôles et missions — https://www.bank-of-algeria.dz/role-et-mission/</li><li><strong>S34</strong> : Cadre legal — Banque d’Algérie — Loi n°23-09 portant loi monétaire et bancaire / cadre législatif — https://www.bank-of-algeria.dz/cadre-legislatif-et-reglementaire/</li><li><strong>S35</strong> : Règlement — Banque d’Algérie — Règlement n°25-03 relatif à la protection de la clientèle — https://www.bank-of-algeria.dz/stoodroa/2025/05/Reglement-25-03-FR.pdf</li><li><strong>S36</strong> : Règlement — Banque d’Algérie — Inclusion financière / règlements applicables — https://www.bank-of-algeria.dz/inclusion-financiere-reglement/</li><li><strong>S37</strong> : Règlement — Banque d’Algérie — Finance islamique / règlements — https://www.bank-of-algeria.dz/finance-islamique-reglement-2/</li><li><strong>S38</strong> : Autorité de marché — COSOB — Missions — https://cosob.dz/missions/</li><li><strong>S39</strong> : Autorité de marché — COSOB — Intermédiaires en Opérations de Bourse (IOB) — https://cosob.dz/entreprises-et-professionnels-du-marche/professionnels-du-marche/iob/</li><li><strong>S40</strong> : Autorité de marché — COSOB — SGBV / structure du marché de la Bourse d’Alger — https://cosob.dz/entreprises-et-professionnels-du-marche/entreprises/sgbv/</li><li><strong>S41</strong> : Autorité de marché — COSOB — Programme d’éducation et de formation financière — https://cosob.dz/education-financiere/formations/</li><li><strong>S42</strong> : Référence comptable international — IFRS Foundation — Conceptual Framework for Financial Reporting — https://www.ifrs.org/issued-standards/list-of-standards/conceptual-framework/</li><li><strong>S43</strong> : Statistique officielle — ONS Algérie — Indice des prix à la consommation et statistiques officielles — https://www.ons.dz/</li><li><strong>S44</strong> : Dispositif public — NESDA — Financement des micro-entreprises — https://www.nesda.dz/Home/Financement</li><li><strong>S45</strong> : Dispositif public — NESDA — Formation et accompagnement entrepreneurial — https://www.nesda.dz/Home/Formation</li><li><strong>S46</strong> : Infrastructure de marché — SGBV — Bourse d’Alger / cote officielle — https://sgbv.dz/?lang=fr&amp;mod=20&amp;page=rubrique</li><li><strong>S47</strong> : Source pédagogique intégrée — FINCLUDIA — Programme complet d’éducation financière — Algérie 2026 (septembre 2026) — concepts, mini-cours, exercices, QCM et budgets par publics.</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'academy-fondamentaux-budget-rsilience', 'FINCLUDIA Academy — Fondamentaux, budget & résilience', 'Argent, budget, enveloppes, réserves, dettes, objectifs, crédit, inflation, résilience et bilan personnel.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Fondamentaux, budget & résilience', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'beginner', '["BUD-01 — Comprendre l’argent et la culture financière", "BUD-02 — Construire un budget mensuel", "BUD-03 — Gérer son budget par enveloppes", "BUD-04 — Prévoir les dépenses irrégulières", "BUD-05 — Construire un fonds de sécurité", "BUD-06 — Gérer et prioriser ses dettes", "BUD-07 — Définir et financer ses objectifs", "BUD-08 — Banque, CCP, carte et sécurité numérique", "BUD-09 — Comprendre le crédit et son coût", "BUD-10 — Inflation, pouvoir d’achat et intérêts composés", "BUD-11 — Tester sa résilience financière", "BUD-12 — Construire son bilan financier personnel"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '["EPG", "ETU", "JAC", "LYC", "SAL"]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('9cbb2d64-2853-5c37-809f-2a2c48aae983', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'BUD-01 — Comprendre l’argent et la culture financière', 'Distinguer revenu, dépense, épargne, dette et patrimoine.', NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5fee07d1-8fbe-5398-8ddc-7a807c21501f', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Lycéens, étudiants, jeunes actifs, salariés, familles, épargnants"], ["Niveau", "N0-N2"], ["Objectif measurable", "Distinguer revenu, dépense, épargne, dette et patrimoine."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a703c526-d10c-5672-ac4e-9fd3a732358b', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Culture financière", "Combinaison de connaissances, compétences, attitudes et comportements permettant de prendre de bonnes décisions financières et d’améliorer son bien-être financier.", "[S01] [S02]"], ["Bien-être financier", "État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière.", "[S03]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01] [S32]"], ["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01] [S32]"], ["Obligation", "Titre de créance par lequel l’investisseur prête des fonds à un émetteur selon des conditions de rémunération et de remboursement prévues.", "[S38], [S41]"], ["Arbitrage", "Choix entre plusieurs usages possibles d’une ressource limitée en fonction des priorités, contraintes et conséquences.", "[S01], [S02]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('721eb998-2641-511b-8b95-7a0c103743b6', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Distinguer revenu, dépense, épargne, dette et patrimoine. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7dbe555d-e534-5340-9838-cd5d78ce636f', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Culture financière — Combinaison de connaissances, compétences, attitudes et comportements permettant de prendre de bonnes décisions financières et d’améliorer son bien-être financier. [S01] [S02]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Bien-être financier — État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière. [S03]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Dette — Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Obligation — Titre de créance par lequel l’investisseur prête des fonds à un émetteur selon des conditions de rémunération et de remboursement prévues. [S38], [S41]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Arbitrage — Choix entre plusieurs usages possibles d’une ressource limitée en fonction des priorités, contraintes et conséquences. [S01], [S02]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cd7ff209-023e-5566-8207-0b00cbd848b8', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Rôle de l’argent dans les décisions quotidiennes. L’argent est une ressource limitée qui permet de financer des besoins présents et des projets futurs. Chaque dépense implique un coût d’opportunité : utiliser 2 000 DA aujourd’hui signifie renoncer à un autre usage possible de ces 2 000 DA.</p><p>2. Différence entre besoin, envie et objectif. Un besoin répond à une nécessité ou une priorité de base ; une envie améliore le confort mais peut souvent être différée ; un objectif transforme une intention en montant, horizon et plan d’action. La distinction sert à hiérarchiser les dépenses sans jugement moral.</p><p>3. Notion de ressource limitée et arbitrage. Une ressource limitée ne peut pas financer simultanément tous les usages souhaités. Arbitrer consiste à comparer les conséquences de plusieurs choix et à affecter la ressource à l’usage jugé prioritaire au regard des contraintes et objectifs.</p><p>4. Introduction au bien-être financier : obligations, chocs, objectifs et confiance. Le bien-être financier ne signifie pas être riche. Il combine la capacité à payer ses obligations, absorber un choc, avancer vers des objectifs et comprendre suffisamment sa situation pour prendre des décisions avec confiance.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('960f19f4-9fe7-5532-b8e0-45059543c9ae', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Recenser les flux et les engagements de la période.</p><p>Étape 2. Classer ce qui est essentiel, flexible, futur ou exceptionnel.</p><p>Étape 3. Calculer le solde et, si nécessaire, un ratio simple.</p><p>Étape 4. Tester un scénario défavorable.</p><p>Étape 5. Choisir une action compatible avec la sécurité et l’objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('13fe2c78-24dd-5f8a-986a-29d96d3df666', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cc04fc77-0e33-5a46-819f-fa2d1eb7625e', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Comprendre l’argent et la culture financière », relevez les données disponibles, identifiez au moins quatre notions parmi Culture financière, Bien-être financier, Revenu, Dépense, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('53ceb1d5-a59e-51ce-8d09-06a09a904128', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 9, '{"html": "<h2>Approfondissement intégré — Argent, revenu, dépense, charge et budget</h2><ul><li><strong>Publics</strong> : Tous publics</li><li><strong>Compétences renforcées</strong> : distinguer revenu, dépense et charge; comprendre le rôle d''un budget; identifier les flux entrants et sortants</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Revenu</strong> : Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. — [S08]</li><li><strong>Dépense</strong> : Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. — [S32]</li><li><strong>Charge</strong> : Coût ou dépense supporté par un ménage ou une activité. En gestion d’entreprise, la charge est rattachée à une période et ne se confond pas toujours avec le décaissement immédiat. — [S47]</li><li><strong>Budget</strong> : Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. — [S01], [S32]</li><li><strong>Charge fixe</strong> : Charge qui ne varie pas directement avec le volume d’activité à court terme, par exemple certains loyers ou abonnements. — [S16]</li><li><strong>Charge variable</strong> : Charge qui évolue avec le volume d’activité, par exemple certains achats de marchandises ou matières. — [S16]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cbcd575a-4249-59bc-9943-05ea58e61e45', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 10, '{"html": "<h3>Définitions simples</h3><p>Le revenu est une entrée d''argent : salaire, bourse, honoraires, ventes, loyers ou autres ressources. Une dépense est une sortie d''argent. Une charge est une dépense liée à la vie courante ou au fonctionnement d''une activité. Le budget est un plan qui affecte des ressources limitées à des usages prioritaires.</p><p>Un budget n''est pas une punition. C''est un outil de décision : il permet de choisir avant que l''argent ne soit dépensé.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e4b5a200-d0de-5805-a1dc-49c1d9edc05c', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 11, '{"html": "<h3>Fixe, variable, essentielle et discrétionnaire</h3><p>Une charge fixe revient avec un montant relativement prévisible : loyer, abonnement, mensualité. Une dépense variable change avec l''usage : alimentation, transport, énergie. Une dépense essentielle répond à un besoin prioritaire ; une dépense discrétionnaire peut être réduite ou reportée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1322ee67-4d51-52c1-b5c0-fbf83b26fe2a', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Un salarié reçoit 90 000 DA. Il paie 25 000 DA de logement, 12 000 DA d''alimentation, 7 000 DA de transport, 5 000 DA d''abonnements et 10 000 DA de dépenses variables. Son budget ne doit pas commencer par « ce qu''il reste », mais par une affectation volontaire du revenu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3c650e16-71fd-5e53-9fcd-4087a6ada27e', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Prenez un mois réel ou fictif. Classez chaque mouvement en revenu, charge fixe, dépense variable, épargne ou dette. Calculez le solde.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('118bb144-df6a-50b4-a593-518f0d92fb0c', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : 1) additionner toutes les entrées ; 2) classer chaque sortie selon sa nature ; 3) ne pas compter deux fois un transfert interne ; 4) calculer solde = revenus - sorties ; 5) expliquer l’écart et identifier la part destinée à l’épargne ou au remboursement de dette.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('62a81d93-57c1-54f8-af72-362b844e7d7e', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('599e208f-7a6f-55e4-a5c2-f3287de8a1af', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Le budget sert principalement à :</strong><br>A. Prévoir l''usage de ressources limitées<br>B. Supprimer toutes les dépenses<br>C. Garantir un revenu<br>D. Remplacer un compte bancaire<br><em>A. Le budget organise les choix ; il ne crée pas de revenu.</em></li><li><strong>2. Un abonnement mensuel est généralement :</strong><br>A. Une dépense exceptionnelle<br>B. Une charge fixe<br>C. Un investissement<br>D. Une créance<br><em>B. Son caractère récurrent le rend relativement prévisible.</em></li><li><strong>3. Une dépense variable est :</strong><br>A. Toujours inutile<br>B. Toujours fixe<br>C. Dépendante de l''usage ou du volume<br>D. Un revenu<br><em>C. Elle évolue avec la consommation ou l''activité.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('048cdf3a-29a3-52bd-b46a-6e53f204bc7b', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un lycéen d’Alger reçoit 5 000 DA par mois pour transport, restauration et loisirs. S’il dépense 4 500 DA et met 500 DA de côté, il a transformé une partie de sa ressource en épargne plutôt qu’en consommation.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('01e9acfe-873d-5cef-b81a-c7c2c630867a', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Classer 12 opérations : salaire, bourse, loyer, abonnement internet, remboursement de dette, versement d’épargne, achat de vêtements, aide familiale reçue, etc.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bf295a8a-3e8f-5669-b107-5bde661f02d7', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>Chaque opération doit être classée selon sa nature. Une même opération peut être essentielle ou discrétionnaire selon le contexte, mais son type financier doit être correctement identifié.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a68ea71b-1e73-5c22-92df-b427a724294f', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('61b68e88-3829-5bae-b802-da12b66f5c59', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c1a5d7f8-b20e-57ab-80af-8666fec9d530', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('609c4e35-4695-5a12-acd6-910870b24731', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('545afc35-9899-5a30-ae15-8babc6eca369', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Renseigner une semaine de flux dans le journal FINCLUDIA."], ["Défi", "7 jours sans dépense invisible : noter 100 % des dépenses."], ["Outil lié", "Journal des transactions"], ["Preuve Skills Passport", "7 jours de transactions classées."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S02, S03, S08, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('12fa9dae-9afb-5ac9-89c3-05ca48e6a9f7', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'course', '9cbb2d64-2853-5c37-809f-2a2c48aae983', 'QCM — BUD-01', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('f06835e2-9ed7-58b6-b617-b745301746dc', '12fa9dae-9afb-5ac9-89c3-05ca48e6a9f7', 'single', 1, 'Quelle proposition définit le mieux « Culture financière » ?', 'La bonne réponse reprend la définition maître du concept « Culture financière ».', 1, '[]');
