INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('e803068e-1f43-579f-a948-aedfde359896', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'BUD-02 — Construire un budget mensuel', 'Construire un budget prévisionnel et comparer au réalisé.', NULL, 2, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bd579fe2-a294-5251-80f0-53b52c85eb87', 'e803068e-1f43-579f-a948-aedfde359896', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Tous publics particuliers"], ["Niveau", "N0-N2"], ["Objectif measurable", "Construire un budget prévisionnel et comparer au réalisé."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a0304697-599d-58f2-9fdd-161fb4cae95a', 'e803068e-1f43-579f-a948-aedfde359896', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de reference", "Réf."], "rows": [["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01] [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Cash-flow personnel", "Différence entre ressources encaissées et sorties d’argent sur une période, après prise en compte des engagements suivis.", "[S32]"], ["Arbitrage", "Choix entre plusieurs usages possibles d’une ressource limitée en fonction des priorités, contraintes et conséquences.", "[S01], [S02]"], ["Dépense variable", "Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport.", "[S32]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01], [S32]"], ["Dépense fixe", "Dépense récurrente dont le montant varie peu à court terme, par exemple un loyer ou un abonnement.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0ddf1b01-800f-5684-9a93-f9655ad19d98', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Construire un budget prévisionnel et comparer au réalisé. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a9739e09-96d5-51af-a41a-87fb873aff1b', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Cash-flow personnel — Différence entre ressources encaissées et sorties d’argent sur une période, après prise en compte des engagements suivis. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Arbitrage — Choix entre plusieurs usages possibles d’une ressource limitée en fonction des priorités, contraintes et conséquences. [S01], [S02]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Dépense variable — Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01], [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Dépense fixe — Dépense récurrente dont le montant varie peu à court terme, par exemple un loyer ou un abonnement. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('04d77e16-5fa5-51ae-b61d-be4bc2d0db2d', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Revenus fixes, variables et ponctuels. Les revenus fixes ou relativement stables peuvent servir de base au budget. Les revenus variables dépendent de l’activité ou des heures, tandis qu’un revenu ponctuel ne doit pas financer durablement une charge récurrente sans réserve suffisante.</p><p>2. Dépenses fixes, variables, périodiques et imprévues. Les dépenses fixes reviennent régulièrement ; les variables changent avec l’usage ; les périodiques sont prévisibles mais non mensuelles ; les imprévues sont incertaines. Cette classification détermine ce qui doit être budgété, provisionné ou couvert par une réserve.</p><p>3. Prévision vs réalisé. Le prévisionnel décrit ce que l’on pense encaisser et dépenser ; le réalisé décrit ce qui s’est effectivement produit. L’écart entre les deux permet de corriger les hypothèses et non de culpabiliser l’utilisateur.</p><p>4. Solde mensuel et arbitrage. Le solde mensuel mesure l’écart entre ressources et sorties sur la période. Un solde positif doit encore être affecté — réserve, dette, objectif ou dépense future — tandis qu’un solde négatif impose un arbitrage et une correction du budget.</p><p>Repère de calcul. Solde budgétaire = revenus de la période − dépenses de la période.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6616c775-7c67-5b57-955c-65a0738bd17a', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Recenser les flux et les engagements de la période.</p><p>Étape 2. Classer ce qui est essentiel, flexible, futur ou exceptionnel.</p><p>Étape 3. Calculer le solde et, si nécessaire, un ratio simple.</p><p>Étape 4. Tester un scénario défavorable.</p><p>Étape 5. Choisir une action compatible avec la sécurité et l’objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('85b50cbd-1cc6-5b92-a4d4-51372101a8f7', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7aaeb8fc-a14c-5e85-bf6b-4ed59c19a8c4', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Construire un budget mensuel », relevez les données disponibles, identifiez au moins quatre notions parmi Budget, Revenu, Dépense, Cash-flow personnel, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('513be8a0-f7c7-5291-8932-f5040ff75693', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 9, '{"html": "<h2>Approfondissement intégré — Construire un budget qui fonctionne</h2><ul><li><strong>Publics</strong> : Tous publics</li><li><strong>Compétences renforcées</strong> : construire un budget mensuel; choisir une méthode adaptée; éviter les budgets irréalistes</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Budget</strong> : Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. — [S01], [S32]</li><li><strong>Enveloppe budgétaire</strong> : Montant affecté à une catégorie ou un objectif pendant une période afin de suivre ce qui est prévu, consommé et restant. — [S32]</li><li><strong>Budget base zero</strong> : Méthode budgétaire dans laquelle chaque dinar disponible reçoit une destination explicite : dépense, réserve, dette, objectif, investissement ou marge de sécurité. — [S47]</li><li><strong>Se payer d’abord</strong> : Principe consistant à programmer l’épargne ou la réserve avant les dépenses discrétionnaires, plutôt que d’épargner uniquement ce qui reste en fin de période. — [S47]</li><li><strong>Solde budgétaire</strong> : Différence entre les ressources d’une période et les dépenses effectivement supportées ou prévues sur cette même période. — [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('033fbdc7-6934-5d5f-a1e5-6540f0290825', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 10, '{"html": "<h3>Quatre méthodes utiles</h3><p>Budget par enveloppes : un montant est affecté à chaque catégorie. Budget base zéro : chaque dinar reçoit une destination, y compris l''épargne. Règle 50/30/20 : repère pédagogique et non norme universelle ; elle peut être adaptée au niveau de revenu et aux contraintes locales. « Pay yourself first » : l''épargne est planifiée avant les dépenses discrétionnaires.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('51d44a82-f11f-546a-96fb-8947351a8595', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 11, '{"html": "<h3>Pourquoi personnaliser</h3><p>Un étudiant hébergé en résidence universitaire, un salarié locataire à Alger et une famille propriétaire n''ont pas la même structure de dépenses. FINCLUDIA doit donc proposer des répartitions personnalisables et non imposer un pourcentage unique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bb073ed1-7bef-56aa-994b-cb6748f65ebc', 'e803068e-1f43-579f-a948-aedfde359896', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Revenu mensuel fictif : 100 000 DA. Une répartition possible : 55 000 DA besoins essentiels, 15 000 DA épargne/objectifs, 10 000 DA dette, 20 000 DA dépenses flexibles. Cette structure doit être ajustée selon le logement, la famille et les engagements réels.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5626f460-aee2-5bd6-a37a-3cca38ad0d49', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Créez trois versions de votre budget : prudent, réaliste et confortable. Identifiez la première catégorie à réduire si le revenu baisse de 10 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('559d85e2-5771-56da-8474-a3689d93dfd9', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : le scénario prudent retient un revenu conservateur, protège l’essentiel et la réserve ; le scénario réaliste utilise les hypothèses les plus probables ; le scénario confortable n’est retenu qu’avec ressources suffisantes. En cas de baisse de 10 %, réduire d’abord les postes flexibles avant de fragiliser logement, santé, alimentation, transport essentiel ou engagements prioritaires.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('29c4c36e-927d-5e99-a877-0b446ef1da01', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4a734e7e-6c4e-5d78-abab-1af78a59130b', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. La règle 50/30/20 doit être :</strong><br>A. Appliquée obligatoirement<br>B. Utilisée comme repère adaptable<br>C. Réservée aux entreprises<br>D. Ignorée<br><em>B. Une règle budgétaire est un point de départ, pas une norme.</em></li><li><strong>2. Le budget base zéro signifie :</strong><br>A. Avoir zéro dinar<br>B. Donner une destination à l''ensemble du revenu<br>C. Ne jamais épargner<br>D. Payer uniquement en espèces<br><em>B. Chaque dinar est affecté à une fonction.</em></li><li><strong>3. « Se payer d''abord » signifie :</strong><br>A. Acheter un loisir d''abord<br>B. Réserver l''épargne avant le discrétionnaire<br>C. Payer ses fournisseurs en dernier<br>D. S''endetter<br><em>B. L''épargne devient une priorité planifiée.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bb86b72d-26d2-5b08-b9df-56918224b510', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une étudiante à Oran dispose de 25 000 DA d’aide familiale et 8 000 DA de revenus occasionnels. Ses dépenses prévues sont 12 000 DA logement, 7 000 DA transport/restauration, 4 000 DA télécom/études et 5 000 DA loisirs. Son budget doit montrer si elle peut dégager une épargne.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('024d456b-e892-5f11-b000-892d9d4db2c2', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Calculer le solde prévisionnel si les ressources sont 33 000 DA et les dépenses 28 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d58ae53d-0310-5deb-8523-78cfbac7492b', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>Solde = 33 000 - 28 000 = 5 000 DA avant toute autre affectation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('61b863fd-ecc1-5d79-a3b5-dbfed0c9c9c7', 'e803068e-1f43-579f-a948-aedfde359896', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f405c9f7-19be-585c-8154-d07885dc0042', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1fd1fa1b-7c80-5890-95eb-ecf1399ac44b', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e9f4f88d-031f-57da-9e5f-84e66663aca9', 'e803068e-1f43-579f-a948-aedfde359896', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0ede78c4-cf45-5cf4-9911-633d6036b21c', 'e803068e-1f43-579f-a948-aedfde359896', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un budget réel dans FINCLUDIA."], ["Défi", "Respecter le budget pendant 30 jours et expliquer les trois plus gros écarts."], ["Outil lié", "Budget mensuel"], ["Preuve Skills Passport", "Budget créé + écarts commentés."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S08, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('3cdded2e-a0ad-5709-871d-537e87c67832', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'course', 'e803068e-1f43-579f-a948-aedfde359896', 'QCM — BUD-02', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
