INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('74709c25-135c-54d6-9630-ed84ac81e4fd', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'BUD-03 — Gérer son budget par enveloppes', 'Affecter une mission à chaque dinar et contrôler les dépassements.', NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('de2e50c9-218d-5710-a160-255787ffcada', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Tous publics particuliers"], ["Niveau", "N0-N2"], ["Objectif measurable", "Affecter une mission à chaque dinar et contrôler les dépassements."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('645f5d6d-e3e6-5419-92f0-e5b3e7d627f0', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de reference", "Réf."], "rows": [["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01] [S32]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01] [S32]"], ["Enveloppe budgétaire", "Montant affecté à une catégorie ou un objectif pendant une période afin de suivre ce qui est prévu, consommé et restant.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f69ba00b-78fc-5c73-a82c-bc7ac1c896c7', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Affecter une mission à chaque dinar et contrôler les dépassements. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5bd1769e-7037-5eb7-9ab7-ec62ff9b0a7c', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Enveloppe budgétaire — Montant affecté à une catégorie ou un objectif pendant une période afin de suivre ce qui est prévu, consommé et restant. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('86e498bf-0379-5130-aa2c-42c9385c6674', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Créer des enveloppes personnalisées. Une enveloppe budgétaire attribue une limite ou une cible à une catégorie. Elle ne bloque pas nécessairement la dépense : elle rend visible le consommé, le reste et le risque de dépassement.</p><p>2. Suivre budget, consommé, engagé, reste et projection. « Suivre budget, consommé, engagé, reste et projection » transforme une intention en plan chiffré. Le budget doit distinguer ressources, priorités, engagements, marges de sécurité et écarts afin de permettre une correction en cours de période.</p><p>Repère de calcul. Solde budgétaire = revenus de la période − dépenses de la période.</p><p>3. Mettre en place des alertes configurables. Dans « Gérer son budget par enveloppes », mettre en place des alertes configurables est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9d183756-14db-51d0-b4b6-01f71466bc0b', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Recenser les flux et les engagements de la période.</p><p>Étape 2. Classer ce qui est essentiel, flexible, futur ou exceptionnel.</p><p>Étape 3. Calculer le solde et, si nécessaire, un ratio simple.</p><p>Étape 4. Tester un scénario défavorable.</p><p>Étape 5. Choisir une action compatible avec la sécurité et l’objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e39d4e0e-312f-586f-90a0-b732de88dd4c', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7712cf37-56cc-542c-be12-4acba96f0be5', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Gérer son budget par enveloppes », relevez les données disponibles, identifiez au moins quatre notions parmi Budget, Dépense, Épargne, Enveloppe budgétaire, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0b0ff340-40bd-5987-81d9-f03a8d39da7f', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un salarié de Blida affecte 30 000 DA au logement, 20 000 DA à l’alimentation, 12 000 DA au transport, 15 000 DA à l’épargne et 8 000 DA aux loisirs. À mi-mois, 7 000 DA de loisirs sont déjà consommés : l’enveloppe doit passer en vigilance selon le seuil choisi.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1c3c3780-4c35-5010-a892-95995ca8fad0', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Une enveloppe de 20 000 DA affiche 16 500 DA consommés. Calculer le taux de consommation et le reste.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a0eed90c-f8ea-5af6-927d-48a49ebbab87', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Taux = 16 500 / 20 000 = 82,5 %. Reste = 3 500 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('85ed4341-812e-5ee1-940b-583d8a7e9dc4', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dbf04cde-dfa5-513d-81d1-a2ef9981a000', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9c28610b-9523-5547-899e-2ac65f384b76', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('98fc0f55-0918-55a2-8df8-b8b39b2752dd', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7285b2c3-102e-5f04-8cab-ba52ee4af7c1', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer au moins 6 enveloppes."], ["Défi", "Finir un mois sans dépassement rouge, ou documenter les arbitrages réalisés."], ["Outil lié", "Budget & Enveloppes"], ["Preuve Skills Passport", "1 mois d’enveloppes complété."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('601581d0-dcab-5124-ba52-e04f9ad08cf2', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'course', '74709c25-135c-54d6-9630-ed84ac81e4fd', 'QCM — BUD-03', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
