INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('e94a82a9-f1d4-55e5-9b31-092da84309d3', '08e5a879-5213-5833-a3a0-0cca1afa20a2', 'single', 5, 'Quelle preuve doit permettre au site de confirmer l’application de la compétence ?', 'La progression repose sur une preuve d’application, pas seulement sur la consultation du contenu.', 1, '[]');
