INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'BUD-05 — Construire un fonds de sécurité', 'Mesurer et renforcer la capacité à absorber un choc.', NULL, 5, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7a0916e5-033b-5f28-a97e-96dbba73cd76', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Étudiants, jeunes actifs, salariés, familles"], ["Niveau", "N0-N2"], ["Objectif measurable", "Mesurer et renforcer la capacité à absorber un choc."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5b541388-a01f-5851-9838-2e5de7d4ca0b', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de reference", "Réf."], "rows": [["Fonds de sécurité", "Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles.", "[S03] [S32]"], ["Liquidité", "Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur.", "[S14] [S32]"], ["Bien-être financier", "État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière.", "[S03]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f5077226-7252-508e-96cf-87f9ce91ea6b', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Mesurer et renforcer la capacité à absorber un choc. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8bb25c01-9068-5636-bb5e-ce463b2a4db1', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Fonds de sécurité — Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles. [S03] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Liquidité — Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur. [S14] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Bien-être financier — État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière. [S03]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cb62aad4-c13c-5ddf-8cec-64b1cddde139', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Dépenses essentielles. Dans « Construire un fonds de sécurité », dépenses essentielles est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>2. Liquidités disponibles. La liquidité décrit la facilité avec laquelle une ressource peut être mobilisée rapidement sans forte perte de valeur. Un actif peut avoir de la valeur tout en étant peu utile pour régler une échéance immédiate.</p><p>3. Mois de réserve. Dans « Construire un fonds de sécurité », mois de réserve est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>Repère de calcul. Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p><p>4. Scénarios de perte de revenu. « Scénarios de perte de revenu » se travaille par scénarios. L''utilisateur fixe une hypothèse de base, une hypothèse défavorable et, si utile, une hypothèse favorable ; il compare ensuite les effets sur le budget, le cash, la marge ou le risque.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f390801b-795d-5daa-94ae-15435767badf', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Recenser les flux et les engagements de la période.</p><p>Étape 2. Classer ce qui est essentiel, flexible, futur ou exceptionnel.</p><p>Étape 3. Calculer le solde et, si nécessaire, un ratio simple.</p><p>Étape 4. Tester un scénario défavorable.</p><p>Étape 5. Choisir une action compatible avec la sécurité et l’objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('240799ef-c7cb-5e57-9f55-047941a712ce', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('93297a0d-b5ab-560b-a182-362fd6139406', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Construire un fonds de sécurité », relevez les données disponibles, identifiez au moins quatre notions parmi Fonds de sécurité, Liquidité, Bien-être financier, Dépense, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ebf27da-a51a-5d58-9c09-fe735b5f5f7e', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 9, '{"html": "<h2>Approfondissement intégré — Épargne de précaution et résilience</h2><ul><li><strong>Publics</strong> : Lycéen avancé, étudiant, salarié, famille, indépendant</li><li><strong>Compétences renforcées</strong> : comprendre le fonds d''urgence; calculer une cible en mois de dépenses; construire une réserve progressive</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Fonds de sécurité</strong> : Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles. — [S03], [S32]</li><li><strong>Épargne</strong> : Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. — [S01], [S32]</li><li><strong>Dépense essentielle</strong> : Dépense répondant à un besoin prioritaire dont la réduction immédiate peut compromettre les conditions de vie, la santé, le logement, la mobilité nécessaire ou la continuité d’une activité. — [S47]</li><li><strong>Dette</strong> : Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. — [S01], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('39bf6607-5a88-5581-aef4-b89ffbb7264d', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 10, '{"html": "<h3>Pourquoi une réserve ?</h3><p>Une panne, une dépense médicale, une baisse de revenu ou un client qui paie en retard peuvent déséquilibrer le budget. L''épargne de précaution réduit la nécessité de recourir à une dette coûteuse ou de vendre un actif dans l''urgence.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('74148a12-c028-569c-934f-f97be0f362f3', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 11, '{"html": "<h3>Calcul en mois</h3><p>On peut raisonner en mois de dépenses essentielles : réserve ÷ dépenses essentielles mensuelles. La cible dépend de la stabilité du revenu, du nombre de personnes à charge et de la protection disponible.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1cad8c88-3b4b-5d51-81f5-4d5e57b39f3b', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Une famille a 70 000 DA de dépenses essentielles mensuelles et 210 000 DA disponibles. Elle dispose donc de 3 mois de réserve. Si son objectif est 5 mois, elle doit atteindre 350 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('933ad9f7-1c5c-574a-ad1b-115edc82af30', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Calculez votre réserve actuelle en mois. Fixez une cible et calculez le versement mensuel nécessaire pour l''atteindre en 12 mois.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bd48b8e7-c392-5458-ab2d-97fb4602851d', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : mois de réserve = réserve disponible / dépenses essentielles mensuelles. Cible monétaire = dépenses essentielles x nombre de mois choisi. Versement mensuel indicatif = max(0 ; cible - réserve actuelle) / 12.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5a36bdf8-bc60-5ba1-bcaa-d04196d5376a', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b6bfa236-6655-5bff-8dc5-dfba2f4d7e2c', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Le fonds d''urgence sert d''abord à :</strong><br>A. Spéculer<br>B. Financer les imprévus<br>C. Acheter à crédit<br>D. Augmenter les dépenses<br><em>B. Il protège le budget contre les chocs.</em></li><li><strong>2. Une réserve de 240 000 DA pour 60 000 DA de dépenses essentielles représente :</strong><br>A. 2 mois<br>B. 3 mois<br>C. 4 mois<br>D. 6 mois<br><em>C. 240 000 / 60 000 = 4.</em></li><li><strong>3. Une cible d''urgence doit être :</strong><br>A. Identique pour tout le monde<br>B. Adaptée au risque et aux charges<br>C. Toujours 12 mois<br>D. Toujours zero<br><em>B. Le besoin de résilience dépend de la situation.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('624b41a0-7789-5e16-a878-37467291a37e', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un jeune actif dispose de 180 000 DA immédiatement disponibles et de 60 000 DA de dépenses essentielles mensuelles : sa réserve représente 3 mois selon la convention FINCLUDIA.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ff19f034-af0e-5a6f-80c8-cbf5eea8fd20', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Avec 240 000 DA de liquidités et 80 000 DA de dépenses essentielles, calculer la réserve.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7c732ad6-5953-5e20-a3ac-60426cc15e21', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>240 000 / 80 000 = 3 mois.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('05b1d4fd-8447-551e-a6f3-cebfc61aeb5d', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0dd3386a-5e91-58c2-99a9-c622530139da', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d953fb52-2dda-53f1-81c5-f6ba5f891754', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7f6931d9-8dff-50fa-8965-830e2b16f448', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9df827fb-ac34-5817-8e80-cb2551ce4962', '32283a52-dea4-5db2-97fb-4b8c660f5eb9', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Calculer sa réserve dans FINCLUDIA et définir une cible personnelle."], ["Défi", "Atteindre le premier palier de réserve défini par l’utilisateur."], ["Outil lié", "Réserve de sécurité"], ["Preuve Skills Passport", "Jauge réserve + plan de contribution."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S03, S14, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
