INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'BUD-06 — Gérer et prioriser ses dettes', 'Comprendre le coût d’une dette et tester plusieurs stratégies de remboursement.', NULL, 6, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e299ab3b-6dfe-50a6-b322-989c68e2de40', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Étudiants concernés, actifs, salariés, familles"], ["Niveau", "N0-N2"], ["Objectif measurable", "Comprendre le coût d’une dette et tester plusieurs stratégies de remboursement."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1d78f911-2164-5067-b0c2-76164069a292', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01] [S32]"], ["Cash-flow personnel", "Différence entre ressources encaissées et sorties d’argent sur une période, après prise en compte des engagements suivis.", "[S32]"], ["Bien-être financier", "État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière.", "[S03]"], ["Taux d’effort", "Indicateur pédagogique rapportant les remboursements de dettes aux revenus nets ; il ne constitue pas à lui seul une décision bancaire.", "[S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8282e110-69d9-5fa7-9a72-e4a1dd2a00c2', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre le coût d’une dette et tester plusieurs stratégies de remboursement. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e1c19b72-8601-5fd7-934c-720afcde966b', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Dette — Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Cash-flow personnel — Différence entre ressources encaissées et sorties d’argent sur une période, après prise en compte des engagements suivis. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Bien-être financier — État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière. [S03]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Taux d’effort — Indicateur pédagogique rapportant les remboursements de dettes aux revenus nets ; il ne constitue pas à lui seul une décision bancaire. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('63592ece-c31d-5718-839b-1634785ac1a3', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Capital restant, mensualité, durée et coût. Pour « Capital restant, mensualité, durée et coût », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>2. Taux d’effort personnel. Dans « Gérer et prioriser ses dettes », taux d’effort personnel est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>Repère de calcul. Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>3. Stratégies avalanche et boule de neige. Dans « Gérer et prioriser ses dettes », stratégies avalanche et boule de neige est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>4. Remboursement anticipé : effet à simuler, sans conseil bancaire automatique. Dans « Gérer et prioriser ses dettes », remboursement anticipé : effet à simuler, sans conseil bancaire automatique est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('912e9736-3abd-53c7-82d8-84b5b422ad9c', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Recenser les flux et les engagements de la période.</p><p>Étape 2. Classer ce qui est essentiel, flexible, futur ou exceptionnel.</p><p>Étape 3. Calculer le solde et, si nécessaire, un ratio simple.</p><p>Étape 4. Tester un scénario défavorable.</p><p>Étape 5. Choisir une action compatible avec la sécurité et l’objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ff7e5878-d9c2-5ced-ac81-e7c8d7c0f686', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a2bef99c-bec3-58b2-a6f3-8d6ace14474b', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Gérer et prioriser ses dettes », relevez les données disponibles, identifiez au moins quatre notions parmi Dette, Cash-flow personnel, Bien-être financier, Taux d’effort, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f6644db2-bcff-5463-ae32-67d971b27bcf', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un salarié rembourse deux crédits : 14 000 DA et 9 000 DA par mois. Son revenu net est 95 000 DA. FINCLUDIA calcule un effort personnel de 24,2 % et lui permet de simuler un versement supplémentaire.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('658eb6f4-83a6-560e-9202-394d94fa71f3', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Calculer le taux d’effort personnel pour 23 000 DA de mensualités et 95 000 DA de revenu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4cda6a0e-d077-5fee-8b2a-0438e07d604c', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>23 000 / 95 000 = 24,21 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1de0cd76-cda7-5a44-aedd-cf6871f27da4', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('09a95a58-0f80-52fb-87ae-799692b7fcff', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8da4e4c2-9ebb-5c16-9234-cffb734637cb', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b3355a17-4974-59a2-896a-707031692514', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('199eb1d6-17d5-5294-9acc-6fd2417d9d72', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Renseigner toutes les dettes et produire une carte d’endettement."], ["Défi", "Comparer trois stratégies : normale, avalanche, boule de neige."], ["Outil lié", "Dettes & Scénarios"], ["Preuve Skills Passport", "Carte des dettes + scénario sélectionné."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S03, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('08925370-bbde-5239-8ad9-b4f762c66493', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'course', '2b5210e2-1b7b-58d2-ab7b-9868c5342e1b', 'QCM — BUD-06', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
