INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('19095106-d8f2-5834-a383-48f4a8c53615', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'BUD-07 — Définir et financer ses objectifs', 'Transformer un projet en trajectoire chiffrée.', NULL, 7, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('feaa8698-5154-503b-a92a-75cc8cf26d89', '19095106-d8f2-5834-a383-48f4a8c53615', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Tous publics particuliers"], ["Niveau", "N0-N2"], ["Objectif measurable", "Transformer un projet en trajectoire chiffrée."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('39670a90-3ff2-5395-83c1-ea3cdc6fb188', '19095106-d8f2-5834-a383-48f4a8c53615', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Objectif financier", "Projet défini par un montant, un horizon, une priorité et une contribution à fournir.", "[S01] [S32]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01] [S32]"], ["Inflation", "Hausse générale du niveau des prix qui réduit le pouvoir d’achat d’une unité monétaire lorsque les revenus n’évoluent pas au même rythme.", "[S02]"], ["Intérêt compose", "Mécanisme par lequel les gains d’une période s’ajoutent au capital et peuvent eux-mêmes produire des gains lors des périodes suivantes.", "[S02]"], ["Arbitrage", "Choix entre plusieurs usages possibles d’une ressource limitée en fonction des priorités, contraintes et conséquences.", "[S01], [S02]"], ["Rendement", "Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon.", "[S01], [S41]"], ["Horizon d’investissement", "Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné.", "[S02], [S41]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('904bc377-7535-5106-b60f-4ac7b31d5fb5', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Transformer un projet en trajectoire chiffrée. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7b788271-dab4-55d5-bc2b-d74f5cf74b96', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Objectif financier — Projet défini par un montant, un horizon, une priorité et une contribution à fournir. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Inflation — Hausse générale du niveau des prix qui réduit le pouvoir d’achat d’une unité monétaire lorsque les revenus n’évoluent pas au même rythme. [S02]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Intérêt composé — Mécanisme par lequel les gains d’une période s’ajoutent au capital et peuvent eux-mêmes produire des gains lors des périodes suivantes. [S02]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Arbitrage — Choix entre plusieurs usages possibles d’une ressource limitée en fonction des priorités, contraintes et conséquences. [S01], [S02]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Rendement — Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon. [S01], [S41]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Horizon d’investissement — Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné. [S02], [S41]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e1f4aaea-c22e-5e70-9385-0c990128b288', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Montant cible, horizon, priorité. L’horizon est la durée pendant laquelle l’argent peut rester mobilisé avant d’être nécessaire. Il détermine la capacité à accepter fluctuation, immobilisation ou durée de financement.</p><p>2. Contribution périodique. Dans « Définir et financer ses objectifs », contribution périodique est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>3. Inflation et rendement comme hypothèses visibles. L’inflation est une hausse générale et durable du niveau des prix. Son effet concret dépend de la structure de consommation de chaque ménage et de l’évolution de ses revenus.</p><p>Repère de calcul. Rendement réel exact = (1 + rendement nominal) ÷ (1 + inflation) − 1.</p><p>4. Arbitrage entre plusieurs objectifs. Dans « Définir et financer ses objectifs », arbitrage entre plusieurs objectifs est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d764e7e6-d1c3-5baf-bd84-485fd878461f', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Recenser les flux et les engagements de la période.</p><p>Étape 2. Classer ce qui est essentiel, flexible, futur ou exceptionnel.</p><p>Étape 3. Calculer le solde et, si nécessaire, un ratio simple.</p><p>Étape 4. Tester un scénario défavorable.</p><p>Étape 5. Choisir une action compatible avec la sécurité et l’objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ded35281-234e-5788-a970-77dbca29d99e', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Capitalisation composée : valeur future = capital initial × (1 + taux)^nombre de périodes, lorsque cette hypothèse est pertinente.</p><p>Rendement réel exact = (1 + rendement nominal) ÷ (1 + inflation) − 1.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5cac15c0-e896-5021-8c65-55032695e84a', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Définir et financer ses objectifs », relevez les données disponibles, identifiez au moins quatre notions parmi Objectif financier, Épargne, Inflation, Intérêt composé, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f6478b6e-d32f-5380-b31f-d6a3f7fb1df1', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 9, '{"html": "<h2>Approfondissement intégré — Objectifs financiers, intérêts composés et inflation</h2><ul><li><strong>Publics</strong> : Étudiants, salariés, familles, entrepreneurs</li><li><strong>Compétences renforcées</strong> : fixer un objectif SMART; comprendre la capitalisation; distinguer rendement nominal et réel</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Objectif financier</strong> : Projet défini par un montant, un horizon, une priorité et une contribution à fournir. — [S01], [S32]</li><li><strong>Intérêt compose</strong> : Mécanisme par lequel les gains d’une période s’ajoutent au capital et peuvent eux-mêmes produire des gains lors des périodes suivantes. — [S02]</li><li><strong>Inflation</strong> : Hausse générale et durable du niveau des prix ; son suivi en Algérie s’appuie notamment sur l’indice des prix à la consommation publié par l’ONS. — [S43]</li><li><strong>Rendement</strong> : Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon. — [S01], [S41]</li><li><strong>Pouvoir d’achat</strong> : Quantité de biens et services qu’un revenu ou un capital permet d’acquérir ; il évolue selon le niveau des prix et l’évolution des ressources. — [S43], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('73a05b14-cfcc-5b70-9568-72c3d3aab04c', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 10, '{"html": "<h3>Objectif financier</h3><p>Un objectif doit comporter un montant et une date : « 1 200 000 DA d''apport dans 5 ans » est plus exploitable que « économiser davantage ».</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2a40b16b-c139-53a5-878d-d5116ba6de34', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 11, '{"html": "<h3>Capitalisation</h3><p>Les intérêts composés signifient que les gains futurs peuvent eux-mêmes produire des gains. Dans FINCLUDIA, le simulateur doit distinguer capital versé, gain théorique et valeur réelle après inflation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('00b1e160-5382-5e66-b9e7-be7b1534647c', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 12, '{"html": "<h3>Inflation</h3><p>L''inflation réduit le pouvoir d''achat de la monnaie. Un rendement nominal positif peut donner un gain réel faible si les prix progressent presque autant.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('96724206-81dd-5322-96f5-07f9ad807ab0', '19095106-d8f2-5834-a383-48f4a8c53615', 'callout', 13, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Vous disposez de 200 000 DA et ajoutez 15 000 DA/mois pendant 10 ans. Le montant futur dépend du rendement hypothétique, mais le résultat doit toujours être présenté comme simulation et non comme garantie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4b8a929e-4344-5b2b-9078-64e411e32183', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 14, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Fixez un objectif à 3, 5 ou 10 ans. Calculez le montant mensuel nécessaire sans rendement, puis comparez avec un scénario de rendement hypothétique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f09f92a5-9226-5ee7-875f-09703ac170dd', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 15, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : sans rendement, contribution mensuelle = (objectif - capital déjà disponible) / nombre de mois. Avec rendement hypothétique, utiliser le simulateur en affichant taux, fréquence, horizon et caractère non garanti ; comparer ensuite valeur nominale et valeur réelle après inflation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4c6a4f93-d7a6-51ae-a17f-c99ef079949a', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 16, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9cc4e829-ce1b-5d22-813f-7ec0701740e3', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 17, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Un objectif financier utile contient :</strong><br>A. Seulement un souhait<br>B. Un montant et un horizon<br>C. Une marque de banque<br>D. Un taux garanti<br><em>B. Il doit être mesurable.</em></li><li><strong>2. L''inflation :</strong><br>A. Augmente toujours le pouvoir d''achat<br>B. Réduit le pouvoir d''achat à prix croissants<br>C. Supprime les dettes<br>D. Garantit le rendement<br><em>B. Une même somme achète alors moins de biens.</em></li><li><strong>3. Un rendement hypothétique de 6 % est :</strong><br>A. Une promesse<br>B. Une hypothèse de simulation<br>C. Un droit acquis<br>D. Un impôt<br><em>B. Les rendements futurs sont incertains.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('677ac176-67de-56fd-9c16-890a5821cdc6', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 18, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une salariée à Constantine vise 600 000 DA pour un apport dans 36 mois et possède déjà 150 000 DA. Sans rendement, il reste 450 000 DA à financer, soit 12 500 DA par mois.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b7526a86-5403-5b5e-be53-5393cb25ba95', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 19, '{"html": "<h2>Exercice d’application</h2><p>Objectif 300 000 DA dans 20 mois, capital actuel 80 000 DA, sans rendement : calculer l’effort mensuel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7ea85b56-670d-5efe-84f8-39bcc61f95cd', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 20, '{"html": "<h2>Corrigé-type</h2><p>(300 000 - 80 000) / 20 = 11 000 DA par mois.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bc6a7e13-2d7b-5605-a2ac-adc2100d2d0d', '19095106-d8f2-5834-a383-48f4a8c53615', 'table', 21, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('553a0257-afb2-58d1-ab67-d5a9b8654f93', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 22, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ccc7d7d6-b43e-5a0f-9090-43ce94f9afb6', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 23, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c55288e4-4433-53e1-b7b1-178f5381c28f', '19095106-d8f2-5834-a383-48f4a8c53615', 'text', 24, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cb3596f9-d123-5e25-acb0-7cf81dbb8c32', '19095106-d8f2-5834-a383-48f4a8c53615', 'table', 25, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer 3 objectifs : court, moyen et long terme."], ["Défi", "Financer les premiers 10 % d’un objectif réel ou simulé."], ["Outil lié", "Objectifs"], ["Preuve Skills Passport", "Objectif avec trajectoire et date cible."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S02, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('c7cc33c6-dffd-5d44-8951-e7787f3f6c2d', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'course', '19095106-d8f2-5834-a383-48f4a8c53615', 'QCM — BUD-07', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('ad8eb243-5a04-596b-a2c8-205f14233b33', 'c7cc33c6-dffd-5d44-8951-e7787f3f6c2d', 'single', 1, 'Quelle proposition définit le mieux « Objectif financier » ?', 'La bonne réponse reprend la définition maître du concept « Objectif financier ».', 1, '[]');
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('0264701f-0571-5a3b-a95b-122039314189', 'ad8eb243-5a04-596b-a2c8-205f14233b33', 1, 'Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('e4e09865-df1d-5758-98ee-c4b464cb221a', 'ad8eb243-5a04-596b-a2c8-205f14233b33', 2, 'Hausse générale du niveau des prix qui réduit le pouvoir d’achat d’une unité monétaire lorsque les revenus n’évoluent pas au même rythme.', 0);
