INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('503dd64f-9b9a-534f-b284-1115cb97dce2', 'c7cc33c6-dffd-5d44-8951-e7787f3f6c2d', 'single', 2, 'Quelle action correspond le mieux à l’objectif du module « Définir et financer ses objectifs » ?', 'La compétence est validée par une action observable directement reliée à l’objectif du module.', 1, '[]');
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('cbbfdf3f-2f5e-5f9b-aa82-5595798eccfe', '503dd64f-9b9a-534f-b284-1115cb97dce2', 1, 'Prendre une décision uniquement à partir du solde du compte sans examiner le budget.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('97dd287f-8a1e-53ac-863c-da9087764824', '503dd64f-9b9a-534f-b284-1115cb97dce2', 2, 'Ignorer les hypothèses, la période et les sources dès qu’un chiffre est disponible.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('990a3263-8150-59d1-af34-efdca38da72c', '503dd64f-9b9a-534f-b284-1115cb97dce2', 3, 'Choisir systématiquement l’option la plus coûteuse parce qu’elle paraît plus complète.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('872607bc-2759-5cea-b06e-c7732b495c64', '503dd64f-9b9a-534f-b284-1115cb97dce2', 4, 'Créer 3 objectifs : court, moyen et long terme.', 1);
INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('6275296e-f326-5eb0-abcf-aed3ca46853c', 'c7cc33c6-dffd-5d44-8951-e7787f3f6c2d', 'single', 3, 'Dans le cas pratique du module, quelle démarche est la plus correcte ?', 'Le corrigé-type exige un raisonnement explicite, traçable et cohérent avec les données du cas.', 1, '[]');
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('0c97d88b-1cc4-59eb-9eb2-3373598b846a', '6275296e-f326-5eb0-abcf-aed3ca46853c', 1, '(300 000 - 80 000) / 20 = 11 000 DA par mois.', 1);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('4fc55993-fc85-54d3-b1f9-7184f01fc8a5', '6275296e-f326-5eb0-abcf-aed3ca46853c', 2, 'Choisir une réponse sans calcul ni justification, puis modifier les données pour obtenir le résultat souhaité.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('0193e216-dc0f-524d-8b39-b90ef5fd40c0', '6275296e-f326-5eb0-abcf-aed3ca46853c', 3, 'Confondre une hypothèse pédagogique avec une règle réglementaire applicable à tous.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('7bb815f5-2d65-54c5-9d8c-f6329c1e9da3', '6275296e-f326-5eb0-abcf-aed3ca46853c', 4, 'Supprimer les données qui ne confirment pas la première intuition.', 0);
INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('35f3448c-8ce8-5853-9c50-bd16885d9ce3', 'c7cc33c6-dffd-5d44-8951-e7787f3f6c2d', 'single', 4, 'Lorsqu’une donnée réglementaire, bancaire, fiscale ou de marché est utilisée, quel réflexe FINCLUDIA est correct ?', 'FINCLUDIA versionne les règles évolutives et sépare toujours simulation, information et décision.', 1, '[]');
