INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('a1be0c21-2941-5711-bd4a-d415cbe6e516', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'BUD-08 — Banque, CCP, carte et sécurité numérique', 'Comprendre les services de paiement et réduire les risques de fraude.', NULL, 8, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bef74d61-41c5-549a-b05e-55c91795d678', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Lycéens+, tous adultes"], ["Niveau", "N0-N2"], ["Objectif measurable", "Comprendre les services de paiement et réduire les risques de fraude."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0168814c-0219-5bd5-8351-fc7878635e10', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Culture financière", "Combinaison de connaissances, compétences, attitudes et comportements permettant de prendre de bonnes décisions financières et d’améliorer son bien-être financier.", "[S01] [S02]"], ["Éducation financière bancaire", "Objectif de protection de la clientèle visant notamment la transparence et la capacité du client à prendre des décisions éclairées dans ses relations avec les banques et établissements concernés.", "[S22]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Compte bancaire", "Relation de compte permettant d’enregistrer des opérations, de détenir un solde et d’utiliser des services de paiement selon les conditions de l’établissement.", "[S34], [S35]"], ["Phishing", "Technique de fraude visant à obtenir des informations sensibles ou provoquer une action en imitant un acteur de confiance.", "[S35], [S32]"], ["Demande", "Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions.", "[S32]"], ["OTP", "Code d’authentification à usage unique utilisé pour confirmer une opération ou une connexion ; il doit rester secret.", "[S35], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d5f57f2b-1c0b-5dea-86af-e81290d4846c', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre les services de paiement et réduire les risques de fraude. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f679dd35-b5af-5b92-ae1d-3111cb530f51', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Culture financière — Combinaison de connaissances, compétences, attitudes et comportements permettant de prendre de bonnes décisions financières et d’améliorer son bien-être financier. [S01] [S02]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Éducation financière bancaire — Objectif de protection de la clientèle visant notamment la transparence et la capacité du client à prendre des décisions éclairées dans ses relations avec les banques et établissements concernés. [S22]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Compte bancaire — Relation de compte permettant d’enregistrer des opérations, de détenir un solde et d’utiliser des services de paiement selon les conditions de l’établissement. [S34], [S35]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Phishing — Technique de fraude visant à obtenir des informations sensibles ou provoquer une action en imitant un acteur de confiance. [S35], [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Demande — Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>OTP — Code d’authentification à usage unique utilisé pour confirmer une opération ou une connexion ; il doit rester secret. [S35], [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0d2b4404-eaa5-52ba-b1ba-d001ae84ffe9', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Compte bancaire et CCP. Dans « Banque, CCP, carte et sécurité numérique », compte bancaire et ccp est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>2. Carte et paiement électronique. Dans « Banque, CCP, carte et sécurité numérique », carte et paiement électronique est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>3. Frais, plafonds et conditions. Dans « Banque, CCP, carte et sécurité numérique », frais, plafonds et conditions est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>4. OTP, phishing, ingénierie sociale, confidentialité. Le phishing cherche à obtenir des identifiants ou provoquer une action par usurpation et urgence artificielle. Le bon réflexe est de ne pas suivre le lien reçu et de contacter l’institution par son canal officiel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('83653d62-6671-5af6-8a8a-eab6f2186340', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Recenser les flux et les engagements de la période.</p><p>Étape 2. Classer ce qui est essentiel, flexible, futur ou exceptionnel.</p><p>Étape 3. Calculer le solde et, si nécessaire, un ratio simple.</p><p>Étape 4. Tester un scénario défavorable.</p><p>Étape 5. Choisir une action compatible avec la sécurité et l’objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('74c5fbd7-6527-52c2-9f77-419b223680ab', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Banque, CCP, carte et sécurité numérique », relevez les données disponibles, identifiez au moins quatre notions parmi Culture financière, Éducation financière bancaire, Risque financier, Compte bancaire, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0979ad28-b8a5-5443-ac42-eb2a829c5a91', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un utilisateur reçoit un SMS demandant son code OTP pour ''valider un remboursement''. Le bon réflexe pédagogique est de ne jamais transmettre un code de sécurité reçu pour autoriser une opération.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a10dc663-8ffb-56ed-982e-f79175486b28', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Identifier parmi 8 situations celles qui présentent un signal de fraude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('829d4407-a637-5fd1-919c-3328ec76e05f', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Toute demande de mot de passe, code OTP ou coordonnées confidentielles via un canal non authentifié doit déclencher une vigilance forte.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('106f6e8c-8b43-5630-b7cf-f2da9a920ec9', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('953277ed-5c22-5746-835e-d2e34515ce7a', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e8361a86-ba67-5d08-b354-5de5ebcd7805', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a798c83a-7ca8-5c36-bb75-28786e311431', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0bc08805-fc54-5033-8028-2a5821d4e83c', 'a1be0c21-2941-5711-bd4a-d415cbe6e516', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Passer le quiz sécurité et configurer les notifications."], ["Défi", "Détecter 10 scénarios de fraude sans erreur."], ["Outil lié", "Sécurité numérique"], ["Preuve Skills Passport", "Badge Sécurité financière numérique."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S02, S22"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
