INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('b7dda9b9-b81a-5b4d-8251-f013a3d321e5', '511cf6ff-c59d-55c2-86fe-380c2321c06b', 4, 'Supprimer les données qui ne confirment pas la première intuition.', 0);
INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('078688c4-cf10-5f8b-a3a1-62fc55fe3ac4', 'dcf157bb-4b0a-5b4f-9f54-c8042a3355b6', 'single', 4, 'Lorsqu’une donnée réglementaire, bancaire, fiscale ou de marché est utilisée, quel réflexe FINCLUDIA est correct ?', 'FINCLUDIA versionne les règles évolutives et sépare toujours simulation, information et décision.', 1, '[]');
