INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('2eb96ce0-59b2-56a3-8162-8613b050eda4', 'dcf157bb-4b0a-5b4f-9f54-c8042a3355b6', 'single', 5, 'Quelle preuve doit permettre au site de confirmer l’application de la compétence ?', 'La progression repose sur une preuve d’application, pas seulement sur la consultation du contenu.', 1, '[]');
