INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('3b716b07-76c6-5d71-b49d-25905ced1e3c', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'BUD-09 — Comprendre le crédit et son coût', 'Comprendre la mensualité, la durée, l’apport et le coût total sans promettre l’éligibilité.', NULL, 9, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('11f76bad-394f-55ac-af8d-ac9b091c121d', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Jeunes actifs, salariés, familles"], ["Niveau", "N0-N2"], ["Objectif measurable", "Comprendre la mensualité, la durée, l’apport et le coût total sans promettre l’éligibilité."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('05f29753-03e6-5ca7-a95f-5d4dd091e57c', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01] [S32]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Éducation financière bancaire", "Objectif de protection de la clientèle visant notamment la transparence et la capacité du client à prendre des décisions éclairées dans ses relations avec les banques et établissements concernés.", "[S22]"], ["Reste à vivre", "Montant restant après déduction des catégories d’engagement retenues par le modèle ; la composition du calcul doit toujours être affichée.", "[S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"], ["Offre", "Quantité d’un bien ou service que les producteurs sont disposés à proposer selon les prix et autres conditions.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3728a952-db29-5bf4-82e0-00c7670933a6', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre la mensualité, la durée, l’apport et le coût total sans promettre l’éligibilité. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('04ddd2d2-74c7-5dff-9f8e-bd08ffe95410', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Dette — Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Éducation financière bancaire — Objectif de protection de la clientèle visant notamment la transparence et la capacité du client à prendre des décisions éclairées dans ses relations avec les banques et établissements concernés. [S22]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Reste à vivre — Montant restant après déduction des catégories d’engagement retenues par le modèle ; la composition du calcul doit toujours être affichée. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Offre — Quantité d’un bien ou service que les producteurs sont disposés à proposer selon les prix et autres conditions. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6117ec0c-e9d4-5d5d-b701-ddcfd3159f4c', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Capital emprunté, apport, durée, taux et frais. Dans « Comprendre le crédit et son coût », capital emprunté, apport, durée, taux et frais est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>2. Mensualité et coût total. Pour « Mensualité et coût total », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>3. Reste à vivre et stress de revenu. Dans « Comprendre le crédit et son coût », reste à vivre et stress de revenu est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>4. Comparaison prudente de scénarios. « Comparaison prudente de scénarios » se travaille par scénarios. L''utilisateur fixe une hypothèse de base, une hypothèse défavorable et, si utile, une hypothèse favorable ; il compare ensuite les effets sur le budget, le cash, la marge ou le risque.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('edcee9e7-070b-542e-a3cb-cd411a551dcb', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Recenser les flux et les engagements de la période.</p><p>Étape 2. Classer ce qui est essentiel, flexible, futur ou exceptionnel.</p><p>Étape 3. Calculer le solde et, si nécessaire, un ratio simple.</p><p>Étape 4. Tester un scénario défavorable.</p><p>Étape 5. Choisir une action compatible avec la sécurité et l’objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('62ceec15-e1e2-513d-a77b-29df8b3a7333', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5aad658d-3f8c-54e7-b78e-1b1f0efeadcf', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Comprendre le crédit et son coût », relevez les données disponibles, identifiez au moins quatre notions parmi Dette, Risque financier, Éducation financière bancaire, Reste à vivre, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a83c0931-de47-5f52-84c5-401e6c72d794', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 9, '{"html": "<h2>Approfondissement intégré — Dette, crédit et surendettement</h2><ul><li><strong>Publics</strong> : Lycéens avancés, étudiants, salariés, familles, professionnels</li><li><strong>Compétences renforcées</strong> : distinguer dette productive et dette sous tension; comprendre mensualité, durée et coût total; repérer les signes de surendettement</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Dette</strong> : Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. — [S01], [S32]</li><li><strong>Capacité de remboursement</strong> : Montant qu’un budget peut consacrer durablement à une échéance sans compromettre les dépenses essentielles, la sécurité et les autres engagements. — [S22], [S32]</li><li><strong>Taux d’effort</strong> : Indicateur pédagogique rapportant les remboursements de dettes aux revenus nets ; il ne constitue pas à lui seul une décision bancaire. — [S32]</li><li><strong>Taux d’intérêt</strong> : Prix du temps et du crédit exprimé en pourcentage selon une convention et une période ; son interprétation exige de préciser base, durée, frais et capitalisation. — [S34], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4cee32ec-071d-5c5e-8731-380ac020336b', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 10, '{"html": "<h3>Une dette n''est pas seulement un taux</h3><p>Pour comprendre un crédit, il faut regarder le montant emprunté, l''apport, la durée, la mensualité, les frais, les garanties et le coût total. Un financement apparemment moins cher par mois peut coûter davantage s''il est très long.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9c0b323b-0fea-5622-b65f-1fb7aa42a2c9', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 11, '{"html": "<h3>Dette productive ou pression financière</h3><p>Une dette qui finance un actif productif peut être rationnelle, mais elle n''est jamais automatiquement « bonne ». Elle doit produire suffisamment de valeur ou de cash pour supporter son coût.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('31beaa7f-c0d7-5d6e-9596-9074cb221e1f', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 12, '{"html": "<h3>Signes de tension</h3><p>Accumulation de retards, recours à une nouvelle dette pour payer l''ancienne, absence de réserve, mensualités trop lourdes et impossibilité de couvrir les dépenses essentielles sont des signaux d''alerte.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4851122b-8bed-5a9c-95f4-4fba4c5350c6', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'callout', 13, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Deux crédits financent le même achat : l''un a une mensualité plus faible mais une durée plus longue. FINCLUDIA doit comparer le coût total et l''impact mensuel, pas seulement la mensualité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('008c5d3b-d3cc-57c7-a0ad-03a4f2fc215c', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 14, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Pour trois dettes fictives, classez-les selon : coût, urgence, risque et possibilité de remboursement anticipé. Comparez méthode avalanche et méthode boule de neige.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eb6daebe-6a76-5e58-af3a-5c74af754ac0', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 15, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : traiter d’abord les retards ou dettes créant un risque critique. Méthode avalanche : priorité au coût effectif le plus élevé ; boule de neige : priorité au plus petit solde pour accélérer le nombre de dettes clôturées. La décision finale doit préserver les dépenses essentielles et éviter de recréer une dette.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8f59ec7e-b4c6-59b7-bba1-078f0c52f2f7', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 16, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bd7327d8-3f4e-5a5b-b8c8-833873197a09', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 17, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Le meilleur crédit est toujours celui avec :</strong><br>A. La plus petite mensualité<br>B. Le plus faible coût total compatible avec la situation<br>C. La plus longue durée<br>D. Le plus grand montant<br><em>B. La décision dépend du coût et de la capacité.</em></li><li><strong>2. Le surendettement est notamment signalé par :</strong><br>A. Une épargne régulière<br>B. Le recours à une dette pour payer une dette<br>C. Un budget positif<br>D. Des revenus diversifiés<br><em>B. C''est un signal de déséquilibre.</em></li><li><strong>3. Une dette productive est automatiquement sans risque :</strong><br>A. Oui<br>B. Non<br>C. Seulement pour une PME<br>D. Seulement à taux fixe<br><em>B. Le projet peut sous-performer ou le cash-flow être insuffisant.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dac75021-139e-555c-8ea4-80979e4bd857', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 18, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Deux financements de 2 000 000 DA peuvent avoir la même mensualité mais des durées ou frais différents. FINCLUDIA doit montrer le coût total et non seulement la mensualité.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('621b661f-e016-51d3-aedd-faf5d06fcdc5', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 19, '{"html": "<h2>Exercice d’application</h2><p>Comparer deux offres fictives : A = 40 000 DA × 60 mois + 20 000 DA de frais ; B = 36 000 DA × 72 mois + 10 000 DA de frais.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d83d24df-1bfd-575b-9981-a61b1c27b543', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 20, '{"html": "<h2>Corrigé-type</h2><p>A coûte 2 420 000 DA ; B coûte 2 602 000 DA. La mensualité plus basse de B ne signifie pas un coût total plus faible.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2a1810c0-05e0-5ffa-b18f-c6dfadfd092e', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'table', 21, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('04dbb2ce-49c4-52f4-91d9-d4f37fe473a2', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 22, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('735cec2c-ffcc-5326-b126-cfc360624ce3', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'text', 23, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
