INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('26c5a44d-d244-5b78-a15d-d03f51e81e8e', '3b716b07-76c6-5d71-b49d-25905ced1e3c', 'table', 25, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Simuler un crédit avec au moins 3 durées."], ["Défi", "Trouver un scénario qui réduit le coût total sans dépasser la mensualité cible choisie."], ["Outil lié", "Simulateur crédit"], ["Preuve Skills Passport", "Comparaison de 3 scénarios."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S02, S22, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
