INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'BUD-10 — Inflation, pouvoir d’achat et intérêts composés', 'Comprendre pourquoi temps, inflation et rendement modifient la valeur de l’argent.', NULL, 10, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cd1068c7-143b-54a1-ae19-dbfea8577a5c', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Lycéens+, adultes"], ["Niveau", "N0-N2"], ["Objectif mesurable", "Comprendre pourquoi temps, inflation et rendement modifient la valeur de l’argent."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c3eac56a-8fa4-55d5-b05c-cd176fb6d6a2', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Inflation", "Hausse générale du niveau des prix qui réduit le pouvoir d’achat d’une unité monétaire lorsque les revenus n’évoluent pas au même rythme.", "[S02]"], ["Intérêt compose", "Mécanisme par lequel les gains d’une période s’ajoutent au capital et peuvent eux-mêmes produire des gains lors des périodes suivantes.", "[S02]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01] [S32]"], ["Pouvoir d’achat", "Quantité de biens et services qu’un revenu ou un capital permet d’acquérir ; il évolue selon le niveau des prix et l’évolution des ressources.", "[S43], [S32]"], ["Rendement", "Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon.", "[S01], [S41]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cb2bf0af-78d8-5648-a808-de210775591d', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre pourquoi temps, inflation et rendement modifient la valeur de l’argent. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('37c87aa5-dcbf-5939-aa3e-8fcb27092e94', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Inflation — Hausse générale du niveau des prix qui réduit le pouvoir d’achat d’une unité monétaire lorsque les revenus n’évoluent pas au même rythme. [S02]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Intérêt composé — Mécanisme par lequel les gains d’une période s’ajoutent au capital et peuvent eux-mêmes produire des gains lors des périodes suivantes. [S02]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Pouvoir d’achat — Quantité de biens et services qu’un revenu ou un capital permet d’acquérir ; il évolue selon le niveau des prix et l’évolution des ressources. [S43], [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Rendement — Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon. [S01], [S41]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c2e0a357-c3c1-51b3-aa24-6a5fc77c3e04', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Valeur nominale et valeur réelle. Dans « Inflation, pouvoir d’achat et intérêts composés », valeur nominale et valeur réelle est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>2. Capitalisation. Dans « Inflation, pouvoir d’achat et intérêts composés », capitalisation est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>Repère de calcul. Capitalisation composée : valeur future = capital initial × (1 + taux)^nombre de périodes, lorsque cette hypothèse est pertinente.</p><p>3. Hypothèses et incertitude. « Hypothèses et incertitude » se travaille par scénarios. L''utilisateur fixe une hypothèse de base, une hypothèse défavorable et, si utile, une hypothèse favorable ; il compare ensuite les effets sur le budget, le cash, la marge ou le risque.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('de43e89e-d914-51ba-842c-cc407a2f6207', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Recenser les flux et les engagements de la période.</p><p>Étape 2. Classer ce qui est essentiel, flexible, futur ou exceptionnel.</p><p>Étape 3. Calculer le solde et, si nécessaire, un ratio simple.</p><p>Étape 4. Tester un scénario défavorable.</p><p>Étape 5. Choisir une action compatible avec la sécurité et l’objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7cbd4e42-506b-5569-b919-ea6b7ac9f317', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Capitalisation composée : valeur future = capital initial × (1 + taux)^nombre de périodes, lorsque cette hypothèse est pertinente.</p><p>Rendement réel exact = (1 + rendement nominal) ÷ (1 + inflation) − 1.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('25b278f2-6665-5327-b0da-1ad1fe5c47e8', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Inflation, pouvoir d’achat et intérêts composés », relevez les données disponibles, identifiez au moins quatre notions parmi Inflation, Intérêt composé, Épargne, Pouvoir d’achat, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8348e7e6-3798-527d-bf60-ed9c54e50181', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une épargne de 500 000 DA peut augmenter nominalement tout en perdant du pouvoir d’achat si son rendement reste inférieur à l’inflation. FINCLUDIA doit afficher les deux lectures.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0280cb2e-fb84-5c57-a607-95374e252667', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Comparer un capital de 200 000 DA placé à 5 % pendant 2 ans avec et sans capitalisation annuelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('abcca0db-3cf7-5e0a-8d6f-17a3b833b01b', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Avec capitalisation annuelle : 200 000 × 1,05² = 220 500 DA. Sans capitalisation simple sur deux ans : 220 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a236386f-1830-5c2d-8bd2-41f62b6fe1a4', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2dbd87d3-9d1a-5ea5-b666-92c39a16058b', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1988b6ab-4242-5fd2-87a5-f8e37cac2671', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('33689188-5de7-58ed-be49-3de7ab7b3ab0', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('169494dd-d786-5b2a-b6da-800006174f01', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Lancer un simulateur épargne nominal/réel."], ["Défi", "Créer trois scénarios inflation/rendement et expliquer la différence."], ["Outil lié", "Épargne & Inflation"], ["Preuve Skills Passport", "Simulation enregistrée."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S02, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('869edc84-5ad4-5344-8639-4c99ae2f23b7', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'course', '858c9b3e-cbba-52f2-bbfd-ded3f038a808', 'QCM — BUD-10', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
