INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ea5a5184-4bfb-5ae9-a459-da02f1c78c92', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Actifs, salariés, familles"], ["Niveau", "N0-N2"], ["Objectif measurable", "Mesurer l’effet d’un choc sur le budget et la réserve."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('572ff163-3d03-5e57-be22-d52126b71c4d', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Fonds de sécurité", "Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles.", "[S03] [S32]"], ["Cash-flow personnel", "Différence entre ressources encaissées et sorties d’argent sur une période, après prise en compte des engagements suivis.", "[S32]"], ["Bien-être financier", "État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière.", "[S03]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Action", "Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre.", "[S38], [S41]"], ["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01], [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d0d9ee76-df0e-513a-a4bd-acd982171de8', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Mesurer l’effet d’un choc sur le budget et la réserve. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('94374525-11f5-5c22-9911-25b53e91aaad', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Fonds de sécurité — Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles. [S03] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Cash-flow personnel — Différence entre ressources encaissées et sorties d’argent sur une période, après prise en compte des engagements suivis. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Bien-être financier — État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière. [S03]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Action — Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre. [S38], [S41]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01], [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c0e18a8b-6a5c-55c0-a4cc-924f4f8d1431', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Stress test revenu. Un stress test modifie volontairement une hypothèse — baisse de revenu, hausse de prix, retard client, variation de change — afin d’observer la résistance du budget ou de la trésorerie.</p><p>2. Stress test dépenses. Un stress test modifie volontairement une hypothèse — baisse de revenu, hausse de prix, retard client, variation de change — afin d’observer la résistance du budget ou de la trésorerie.</p><p>3. Dépense exceptionnelle. Dans « Tester sa résilience financière », dépense exceptionnelle est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>4. Plan d’action priorisé. Dans « Tester sa résilience financière », plan d’action priorisé est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('817200e3-ba98-51a0-b702-fb4659a3c398', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Recenser les flux et les engagements de la période.</p><p>Étape 2. Classer ce qui est essentiel, flexible, futur ou exceptionnel.</p><p>Étape 3. Calculer le solde et, si nécessaire, un ratio simple.</p><p>Étape 4. Tester un scénario défavorable.</p><p>Étape 5. Choisir une action compatible avec la sécurité et l’objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('febcd2eb-fc5c-523f-9e1b-1392f8ea5831', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5085ef14-8f1a-5972-a5f2-72b94d37761e', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Tester sa résilience financière », relevez les données disponibles, identifiez au moins quatre notions parmi Fonds de sécurité, Cash-flow personnel, Bien-être financier, Risque financier, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('18ac6bc4-d92a-5ecc-8da7-9b36c72b5748', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un foyer disposant de 140 000 DA de revenus et 115 000 DA de dépenses teste une baisse de revenu de 20 %. Le revenu tombe à 112 000 DA : le budget devient déficitaire de 3 000 DA avant toute adaptation.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a342f235-1d6a-50b9-bcd0-0813d1e6bfb1', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Revenus 120 000 DA, dépenses 100 000 DA. Tester une baisse de revenu de 15 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5f34b626-50c8-5682-a90b-5459af9e5c39', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Nouveau revenu = 102 000 DA ; solde = 2 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('222f0beb-7b86-54fa-bfc2-cc5729ea138a', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('60d11e88-53a8-51c5-9eba-dd2e74121fe7', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cfc269b5-be1d-52aa-94cc-5f5864316dfa', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b053578d-71de-59cc-a43a-6f32c7dfcd57', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b231edd3-1189-500c-9c28-eb04693ca36f', 'ed3afd0a-8ecf-5226-9797-d02a87ab6622', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Réaliser 3 stress tests personnels."], ["Défi", "Construire un plan en 3 actions pour le scénario le plus défavorable."], ["Outil lié", "Résilience"], ["Preuve Skills Passport", "Rapport stress test + actions."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S03, S22, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
