INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('236ca526-47d5-5ebd-b71f-ae827f42e13b', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Jeunes actifs, salariés, familles, épargnants"], ["Niveau", "N0-N2"], ["Objectif measurable", "Faire la synthèse entre actifs, dettes, liquidité, objectifs et progrès."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6b51a6ea-010e-5953-96a4-c6b65d71e6c4', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Patrimoine net", "Valeur des actifs détenus diminuée des dettes et autres passifs retenus.", "[S32]"], ["Liquidité", "Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur.", "[S14] [S32]"], ["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01] [S32]"], ["Objectif financier", "Projet défini par un montant, un horizon, une priorité et une contribution à fournir.", "[S01] [S32]"], ["Bilan", "État financier présentant la situation patrimoniale et financière d’une entité à une date donnée.", "[S13], [S42]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('20d402e2-6d80-5d2d-bffc-5fd1df18ec01', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Faire la synthèse entre actifs, dettes, liquidité, objectifs et progrès. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('677909dc-586e-5e7b-8734-8cb4a72c74a4', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Patrimoine net — Valeur des actifs détenus diminuée des dettes et autres passifs retenus. [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Liquidité — Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur. [S14] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Dette — Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Objectif financier — Projet défini par un montant, un horizon, une priorité et une contribution à fournir. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p><p>Bilan — État financier présentant la situation patrimoniale et financière d’une entité à une date donnée. [S13], [S42]</p><p>Application dans ce module. La compétence attendue est de transformer la notion en décision de budget : identifier le flux, mesurer son effet sur le solde, puis vérifier qu’il reste compatible avec les dépenses essentielles, la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('193995c7-a816-58e4-8b3b-9d602f1c5f97', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Inventaire des actifs. Dans « Construire son bilan financier personnel », inventaire des actifs est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>2. Inventaire des dettes. « Inventaire des dettes » doit être relié à la nature et à la durée du besoin, au coût total, aux garanties éventuelles et à la capacité de remboursement. Une mensualité faible n''est pas suffisante pour juger la qualité d''un financement.</p><p>Repère de calcul. Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>3. Valeur nette. Dans « Construire son bilan financier personnel », valeur nette est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p><p>4. Part liquide vs actifs moins liquides. Ce point demande de comparer des notions proches sans les confondre. Pour « Part liquide vs actifs moins liquides », l''utilisateur doit identifier le critère qui change — nature du flux, horizon, risque, propriétaire, date ou base de calcul — puis appliquer ce critère à un exemple réel ou fictif.</p><p>5. Évolution dans le temps. Dans « Construire son bilan financier personnel », évolution dans le temps est relié au budget concret de l''utilisateur. Il faut identifier le montant ou la situation concernée, distinguer ce qui est obligatoire de ce qui est ajustable, mesurer l''effet sur le solde puis choisir une affectation compatible avec la réserve et les objectifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dfce4e3a-1dc6-5540-881a-ff4f39df9964', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Recenser les flux et les engagements de la période.</p><p>Étape 2. Classer ce qui est essentiel, flexible, futur ou exceptionnel.</p><p>Étape 3. Calculer le solde et, si nécessaire, un ratio simple.</p><p>Étape 4. Tester un scénario défavorable.</p><p>Étape 5. Choisir une action compatible avec la sécurité et l’objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e18f31bd-019a-5631-82ca-c17697455ed1', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4c541f5f-c77f-59d9-8d3c-21886c81f687', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Construire son bilan financier personnel », relevez les données disponibles, identifiez au moins quatre notions parmi Patrimoine net, Liquidité, Dette, Objectif financier, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6b373c70-2f77-597f-9c7f-7d5a32090a07', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un salarié possède 700 000 DA de liquidités, un véhicule estimé à 1 800 000 DA et une dette restante de 900 000 DA. Son patrimoine net pédagogique est 1 600 000 DA, sans préjuger de la valeur de revente réelle du véhicule.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1f89b8fd-015a-5b73-a8f3-f2f7a754b600', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Actifs = 3 200 000 DA ; dettes = 1 050 000 DA. Calculer le patrimoine net.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('26d29e7f-4777-5a92-bb5c-ebd11debba29', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>3 200 000 - 1 050 000 = 2 150 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6353984d-239c-59eb-834b-7c502de46cb4', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('634c0d77-f06c-5b2e-8173-928a2143e304', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e1036cf1-305e-5b84-bc2e-0f5febe0b0fa', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('74597a49-4d01-5158-bc1f-f6406471de56', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2b5a25f0-ef29-547d-bb21-657c412e56a1', '11ba985e-cae8-5317-8f73-6ad5cbf9e1f8', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Compléter la vue Patrimoine."], ["Défi", "Mettre à jour le bilan 3 mois plus tard et commenter l’évolution."], ["Outil lié", "Patrimoine"], ["Preuve Skills Passport", "Bilan financier personnel daté."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S14, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
