INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('4986a344-4a1b-5a4c-9179-7cf3e5cec871', 'f18d4f80-8a87-58d9-b8a7-af9bb2a6d574', 'Cas intégrateur corrigé — Fondamentaux, budget & résilience', NULL, NULL, 13, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('467e0369-c348-5ed0-8a24-71569166c447', '4986a344-4a1b-5a4c-9179-7cf3e5cec871', 'text', 1, '{"html": "<h3>Scénario\\nSamir, jeune actif à Alger, reçoit 92 000 DA nets par mois. Ses dépenses essentielles moyennes sont de 58 000 DA. Il rembourse 12 000 DA de crédit, prévoit 96 000 DA de dépenses annuelles irrégulières, dispose de 75 000 DA de liquidités et veut constituer 300 000 DA pour une formation dans 18 mois. Une hausse fictive de 6 % de certains prix est testée comme scénario pédagogique.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('40cfe558-c5a9-5563-93c4-cc536ecf7dfd', '4986a344-4a1b-5a4c-9179-7cf3e5cec871', 'text', 2, '{"html": "<h2>Travail demandé</h2><p>1. Construire le budget mensuel après mensualisation des dépenses annuelles.</p><p>2. Calculer le reste disponible après dépenses essentielles, dette et provision.</p><p>3. Calculer le nombre de mois de réserve actuelle.</p><p>4. Proposer une contribution mensuelle à l’objectif formation compatible avec le budget.</p><p>5. Recalculer le budget sous scénario de +6 % sur 30 000 DA de dépenses sensibles.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('47916cbe-9417-583e-9c24-3c056e50be90', '4986a344-4a1b-5a4c-9179-7cf3e5cec871', 'text', 3, '{"html": "<h2>Corrigé-type</h2><p>Provision mensuelle = 96 000/12 = 8 000 DA. Après 58 000 + 12 000 + 8 000, il reste 14 000 DA avant objectif/loisirs. Réserve actuelle = 75 000/58 000 ≈ 1,29 mois. Une contribution de 14 000 DA/mois atteindrait 252 000 DA en 18 mois, donc insuffisante pour 300 000 DA sans autre ressource : il faut augmenter l’horizon, réduire certaines dépenses ou ajouter une ressource. Scénario inflation : 30 000 × 1,06 = 31 800 DA, soit +1 800 DA ; le reste tombe à 12 200 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('51525c29-d59c-5e76-9c19-845a11b033de', '4986a344-4a1b-5a4c-9179-7cf3e5cec871', 'table', 4, '{"headers": ["Critère", "Poids"], "rows": [["Exactitude technique / calculs", "35 %"], ["Interprétation et décision", "25 %"], ["Gestion du risque / conformité", "20 %"], ["Traçabilité et sources", "10 %"], ["Clarté de l’explication", "10 %"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f04c8d73-5583-5d1c-b442-89588498e028', '4986a344-4a1b-5a4c-9179-7cf3e5cec871', 'text', 5, '{"html": "<h3>Validation du cas intégrateur\\nSeuil : 75 %. Une erreur critique de sécurité, conformité, fraude, règle réglementaire active ou confusion réel/fictif doit être corrigée avant validation, même si le score global atteint 75 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('cd7fb3bb-93fd-5bf7-8371-60c525fdcc16', 'academy-banque-inclusion', 'FINCLUDIA Academy — Banque & inclusion', 'Système financier, comptes, paiements, frais, crédit, droits du client, sécurité, finance islamique et inclusion.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Banque & inclusion', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'beginner', '["BNK-01 — Comprendre le système financier algérien", "BNK-02 — Compte, CCP, carte, virement et paiement", "BNK-03 — Lire les frais, tarifs et relevés bancaires", "BNK-04 — Comprendre le crédit et préparer sa capacité de remboursement", "BNK-05 — Droits du client, information et réclamation", "BNK-06 — Sécurité financière numérique et fraude", "BNK-07 — Découvrir la finance islamique bancaire", "BNK-08 — Inclusion financière et choix du canal adapté"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '["ETU", "LYC", "SAL"]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('5a2634ce-2149-5b54-822a-f4fba12f489d', 'cd7fb3bb-93fd-5bf7-8371-60c525fdcc16', 'BNK-01 — Comprendre le système financier algérien', 'Identifier les rôles de la Banque d’Algérie, des banques, établissements financiers, PSP et acteurs de marché.', NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b2bdb25b-9417-5f39-bb28-9780acf0e070', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Tous publics"], ["Niveau", "N1"], ["Objectif measurable", "Identifier les rôles de la Banque d’Algérie, des banques, établissements financiers, PSP et acteurs de marché."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a7cc1209-657a-5beb-b816-fce0ee829a58', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Banque centrale", "fonctions de stabilité monétaire, systèmes de paiement, change et supervision.", "[S33] [S34]"], ["Inclusion financière", "accès + usage + compréhension + protection.", "[S35] [S36]"], ["Marché financier", "Ensemble organisé de mécanismes, acteurs et infrastructures permettant l’émission, la négociation, la conservation et le règlement de titres financiers.", "[S38], [S40]"], ["Compte bancaire", "Relation de compte permettant d’enregistrer des opérations, de détenir un solde et d’utiliser des services de paiement selon les conditions de l’établissement.", "[S34], [S35]"], ["Action", "Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre.", "[S38], [S41]"], ["IOB", "Intermédiaire en Opérations de Bourse : personne morale agréée par la COSOB pour exercer une ou plusieurs activités autorisées, dont la négociation de valeurs mobilières et, selon agrément, le conseil ou la gestion.", "[S39]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1f459050-0aa5-592b-8838-558295e2f148', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Identifier les rôles de la Banque d’Algérie, des banques, établissements financiers, PSP et acteurs de marché. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('61bf2493-569c-5999-b9eb-2900a45aa71a', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Banque centrale — fonctions de stabilité monétaire, systèmes de paiement, change et supervision. [S33] [S34]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Inclusion financière — accès + usage + compréhension + protection. [S35] [S36]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Marché financier — Ensemble organisé de mécanismes, acteurs et infrastructures permettant l’émission, la négociation, la conservation et le règlement de titres financiers. [S38], [S40]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Compte bancaire — Relation de compte permettant d’enregistrer des opérations, de détenir un solde et d’utiliser des services de paiement selon les conditions de l’établissement. [S34], [S35]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Action — Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre. [S38], [S41]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>IOB — Intermédiaire en Opérations de Bourse : personne morale agréée par la COSOB pour exercer une ou plusieurs activités autorisées, dont la négociation de valeurs mobilières et, selon agrément, le conseil ou la gestion. [S39]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('30bc3429-3778-59dd-8b38-baf81b94794c', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Pourquoi une banque centrale n’est pas une banque commerciale. Une banque centrale poursuit des objectifs de stabilité monétaire et financière, organise ou surveille des infrastructures et encadre le système. Une banque commerciale fournit directement des comptes, crédits et services à ses clients ; leurs rôles, responsabilités et relations avec le public sont donc différents.</p><p>2. Rôle des banques et établissements financiers. Les banques collectent et gèrent des dépôts, exécutent des paiements et accordent des financements selon leur agrément. Les établissements financiers peuvent exercer certaines activités financières sans offrir exactement les mêmes services qu’une banque de dépôts.</p><p>3. Différence entre système bancaire, marché financier et prestataires de paiement. Le système bancaire organise principalement dépôts, crédit et paiements via les banques ; le marché financier met en relation émetteurs et investisseurs autour de titres ; les prestataires de paiement facilitent l’exécution de paiements. Un même utilisateur peut recourir aux trois sans que leurs fonctions se confondent.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7a8df29e-1048-5285-a131-419b9cd4cee1', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier le besoin réel avant le produit.</p><p>Étape 2. Lire les conditions, frais, délais et risques.</p><p>Étape 3. Vérifier l’acteur et le canal officiel.</p><p>Étape 4. Comparer au moins deux solutions sur le coût total et l’usage.</p><p>Étape 5. Conserver la preuve et savoir comment réclamer en cas d’anomalie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('72fa2858-3111-55cd-85b3-4d0532dc29f8', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Comprendre le système financier algérien », relevez les données disponibles, identifiez au moins quatre notions parmi Banque centrale, Inclusion financière, Marché financier, Compte bancaire, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e4f82a97-d9f2-5a77-acac-382e0409fc85', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une étudiante reçoit son salaire sur un compte bancaire, paie par carte et veut acheter une action : trois acteurs et cadres différents interviennent.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a44fbc69-2560-5dd4-8e90-cf44cfda5a1d', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Associer 10 opérations à l’acteur compétent : Banque d’Algérie, banque, PSP, IOB/COSOB.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3225771f-45e7-53db-b419-c5c9f629e1af', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>La réponse doit distinguer supervision, fourniture de services, paiement et intermédiation boursière.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cfc52631-404c-50f3-9315-1e2792b5b880', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0eeac6f2-e998-5424-8da3-7f7933a36c99', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b4937ccc-4761-5ca6-950d-0dcde3c1e77d', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
