INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0b0bcf95-92c5-5bf7-87c8-c7948bb74acd', '5a2634ce-2149-5b54-822a-f4fba12f489d', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Construire la carte des acteurs financiers"], ["Défi", "Identifier le bon interlocuteur dans 8 situations"], ["Outil lié", "Carte de l’écosystème"], ["Preuve Skills Passport", "Carte acteurs validée"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S33, S34, S36, S38"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
