INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'cd7fb3bb-93fd-5bf7-8371-60c525fdcc16', 'BNK-02 — Compte, CCP, carte, virement et paiement', 'Distinguer compte, solde, instrument de paiement, transfert et opération de consommation.', NULL, 2, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('020b23bb-e11e-5f71-80c5-16190f56c259', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Lycéens, étudiants, salariés, familles, professionnels"], ["Niveau", "N1"], ["Objectif measurable", "Distinguer compte, solde, instrument de paiement, transfert et opération de consommation."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b493b61e-ba71-5e64-86a9-a4e9f496d6b8', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Compte bancaire", "registre des opérations et du solde selon la convention.", "[S34] [S35]"], ["Moyen de paiement", "instrument permettant d’exécuter un paiement ou transfert.", "[S34] [S36]"], ["Transfert de fonds", "Mouvement d’argent entre personnes ou comptes ; FINCLUDIA distingue le déplacement de fonds d’un revenu nouvellement créé.", "[S20], [S32]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01], [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dc715971-b0cd-5dd6-9b76-96e6f57cc4fb', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Distinguer compte, solde, instrument de paiement, transfert et opération de consommation. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9303824a-21c4-57bf-ba0e-c86b448e2087', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Compte bancaire — registre des opérations et du solde selon la convention. [S34] [S35]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Moyen de paiement — instrument permettant d’exécuter un paiement ou transfert. [S34] [S36]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Transfert de fonds — Mouvement d’argent entre personnes ou comptes ; FINCLUDIA distingue le déplacement de fonds d’un revenu nouvellement créé. [S20], [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01], [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1df7eb77-d069-538e-a8b2-9cd720650340', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Compte ≠ carte. Pour compte ≠ carte, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p><p>2. Transfert entre ses comptes ≠ revenu ni dépense de consommation. Pour transfert entre ses comptes ≠ revenu ni dépense de consommation, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p><p>3. Vérifier bénéficiaire, montant, date et référence de chaque opération. Pour vérifier bénéficiaire, montant, date et référence de chaque opération, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d0dfb9e0-e99d-5f33-936b-3586a5272a6b', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier le besoin réel avant le produit.</p><p>Étape 2. Lire les conditions, frais, délais et risques.</p><p>Étape 3. Vérifier l’acteur et le canal officiel.</p><p>Étape 4. Comparer au moins deux solutions sur le coût total et l’usage.</p><p>Étape 5. Conserver la preuve et savoir comment réclamer en cas d’anomalie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('922c5553-4271-5f13-aa7d-0180c509a2f9', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('537efd51-115a-5620-8c1a-020ec72d3fbd', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Compte, CCP, carte, virement et paiement », relevez les données disponibles, identifiez au moins quatre notions parmi Compte bancaire, Moyen de paiement, Transfert de fonds, Dépense, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('71274485-ff34-5f4e-84bf-fb13a100295d', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 9, '{"html": "<h2>Approfondissement intégré — Compte, carte, paiement numérique et sécurité</h2><ul><li><strong>Publics</strong> : Lycéens, étudiants, salariés, tous publics</li><li><strong>Compétences renforcées</strong> : comprendre les fonctions d''un compte et d''une carte; distinguer paiement et crédit; adopter les réflexes de cybersécurité</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Compte bancaire</strong> : Relation de compte permettant d’enregistrer des opérations, de détenir un solde et d’utiliser des services de paiement selon les conditions de l’établissement. — [S34], [S35]</li><li><strong>Moyen de paiement</strong> : Instrument ou procédé permettant de transférer de la valeur ou d’exécuter un paiement : espèces, virement, carte, chèque ou solution de paiement autorisée. — [S34], [S36]</li><li><strong>OTP</strong> : Code d’authentification à usage unique utilisé pour confirmer une opération ou une connexion ; il doit rester secret. — [S35], [S32]</li><li><strong>Phishing</strong> : Technique de fraude visant à obtenir des informations sensibles ou provoquer une action en imitant un acteur de confiance. — [S35], [S32]</li><li><strong>Point de vigilance</strong></li><li><strong>Point pédagogique — Référence actuelle : le règlement Banque d''Algérie 25-03 du 14 avril 2025 place l''éducation financière et la transparence parmi les objectifs de protection de la clientèle.</strong></li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('05c70048-f0ff-5f6e-b091-0078bab94799', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 10, '{"html": "<h3>Les fonctions de base</h3><p>Un compte sert à recevoir, conserver et utiliser des fonds selon les services proposés. Une carte est un moyen d''accès ou de paiement ; elle n''est pas nécessairement un crédit. Les moyens numériques facilitent les opérations mais exigent une discipline de sécurité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8c4d411a-0f05-5388-b013-f89eba048243', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 11, '{"html": "<h3>Réflexes essentiels</h3><p>Ne jamais communiquer un mot de passe, code secret ou code reçu par SMS à un tiers ; vérifier l''adresse du service utilisé ; activer les protections disponibles ; se méfier de l''urgence artificielle et des liens reçus par message.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cdfb2169-cd97-5e7f-97a2-9b88a2a86602', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 12, '{"html": "<h3>Protection du client</h3><p>Le règlement 25-03 de la Banque d''Algérie vise notamment l''éducation financière, la transparence et la fourniture d''une information claire permettant au client de prendre des décisions éclairées.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('308c9858-4e03-5564-8d17-acb3223fc35a', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'callout', 13, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Un faux message prétend que votre compte sera bloqué si vous ne cliquez pas immédiatement sur un lien. Le bon réflexe est d''ouvrir l''application ou le site officiel par vos propres moyens et de contacter l''institution.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bd2aaacf-4d43-5b7c-a972-00db802d7c20', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 14, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Créez une checklist de sécurité de 8 points pour un étudiant qui reçoit sa première carte.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fe7902f7-98a9-5dc6-8f42-dd4eb5fdb4f9', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 15, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type attendu : 1) ne jamais partager PIN/OTP ; 2) utiliser l’application/site officiel ; 3) mot de passe unique et fort ; 4) activer les alertes/2FA ; 5) vérifier les opérations ; 6) savoir bloquer la carte ; 7) éviter liens urgents et appareils/réseaux non sûrs ; 8) contacter l’institution par un canal officiel en cas de doute.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7be27da9-beca-59cf-9830-5894883f1943', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 16, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f173a69d-da74-58bb-a4f2-e97e1ef8fff2', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 17, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Un code reçu par SMS doit être communiqué à un conseiller qui le demande ?</strong><br>A. Oui<br>B. Non<br>C. Seulement le week-end<br>D. Seulement par téléphone<br><em>B. Les codes d''authentification ne doivent pas être partagés.</em></li><li><strong>2. Une carte bancaire signifie automatiquement un crédit ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Seulement pour les étudiants<br><em>B. Une carte peut être un simple instrument de paiement.</em></li><li><strong>3. Une information financière doit être :</strong><br>A. Opaque<br>B. Claire et compréhensible<br>C. Uniquement juridique<br>D. Sans risques mentionnés<br><em>B. La compréhension est essentielle à une décision éclairée.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a07a54d0-2c47-5534-aeef-2806a6a5b7c6', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 18, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Amine transfère 20 000 DA de son compte courant vers un compte épargne : le patrimoine financier total ne change pas si les deux comptes sont inclus.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b72f728d-11a5-578d-8ac1-9044c5b90103', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 19, '{"html": "<h2>Exercice d’application</h2><p>Classer 12 opérations en revenu, dépense, transfert, retrait, paiement ou frais.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4fd83839-69f3-5d11-954b-11f3ad12ff97', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 20, '{"html": "<h2>Corrigé-type</h2><p>Chaque opération reçoit une nature unique et une explication.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fa892d43-2a77-5db3-8b01-341233ea80b4', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'table', 21, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d6bd7da8-5241-513a-a2e6-871d4f2390af', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 22, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8e5579f0-a56c-5a50-b111-b000c4b573c3', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 23, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('daa92e1c-5aa3-5599-adb4-f2dd61b3f882', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'text', 24, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('639e3951-b588-5824-b71f-a9b651950c89', '7ae0ca7b-7977-5d06-83dc-627ab1f2ce95', 'table', 25, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Réconcilier un mini-relevé bancaire"], ["Défi", "Zéro confusion transfert/dépense"], ["Outil lié", "Journal des transactions"], ["Preuve Skills Passport", "Relevé fictif classé"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S34, S35, S36"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
