INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('2626c907-b199-510f-bcdc-519a773bf862', 'cd7fb3bb-93fd-5bf7-8371-60c525fdcc16', 'BNK-03 — Lire les frais, tarifs et relevés bancaires', 'Comparer des services bancaires sur leur coût total et contrôler un relevé.', NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7d160cb1-76d2-5db5-aa79-82a09744323a', '2626c907-b199-510f-bcdc-519a773bf862', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Étudiants, salariés, familles, professionnels"], ["Niveau", "N2"], ["Objectif measurable", "Comparer des services bancaires sur leur coût total et contrôler un relevé."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b3d9d197-1416-532c-b16f-e27cad505251', '2626c907-b199-510f-bcdc-519a773bf862', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Frais bancaires", "commissions ou prix appliqués selon la grille tarifaire.", "[S35]"], ["Réclamation bancaire", "demande formalisée en cas de désaccord ou anomalie.", "[S35]"], ["Relevé bancaire", "Document retraçant, pour une période, les opérations portées sur un compte et son solde selon les informations de l’établissement.", "[S35], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dddcb2ee-3135-57f1-8333-42b55bda8af1', '2626c907-b199-510f-bcdc-519a773bf862', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comparer des services bancaires sur leur coût total et contrôler un relevé. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('efe17aca-776c-59a5-83d2-dc0d71c70364', '2626c907-b199-510f-bcdc-519a773bf862', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Frais bancaires — commissions ou prix appliqués selon la grille tarifaire. [S35]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Réclamation bancaire — demande formalisée en cas de désaccord ou anomalie. [S35]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Relevé bancaire — Document retraçant, pour une période, les opérations portées sur un compte et son solde selon les informations de l’établissement. [S35], [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7b5f6ca4-fd19-5a2a-89da-f3d28017417f', '2626c907-b199-510f-bcdc-519a773bf862', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Lire grille tarifaire, conditions et date de validité. Pour lire grille tarifaire, conditions et date de validité, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p><p>2. Distinguer frais récurrents, ponctuels et liés à une opération. Ce point demande de comparer des notions proches sans les confondre. Pour « Distinguer frais récurrents, ponctuels et liés à une opération », l''utilisateur doit identifier le critère qui change — nature du flux, horizon, risque, propriétaire, date ou base de calcul — puis appliquer ce critère à un exemple réel ou fictif.</p><p>3. Contrôler les débits inconnus et conserver les justificatifs. Pour « Contrôler les débits inconnus et conserver les justificatifs », la compétence est documentaire : savoir quelle information doit être conservée, qui l''émet, à quelle date et à quelle opération elle se rattache. Une trace exploitable doit permettre de reconstituer la décision.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6d889ca7-5d3f-5845-97e5-2448db2809fa', '2626c907-b199-510f-bcdc-519a773bf862', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier le besoin réel avant le produit.</p><p>Étape 2. Lire les conditions, frais, délais et risques.</p><p>Étape 3. Vérifier l’acteur et le canal officiel.</p><p>Étape 4. Comparer au moins deux solutions sur le coût total et l’usage.</p><p>Étape 5. Conserver la preuve et savoir comment réclamer en cas d’anomalie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('738c2bc9-ae4a-5675-97b0-1eae004fafbb', '2626c907-b199-510f-bcdc-519a773bf862', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Lire les frais, tarifs et relevés bancaires », relevez les données disponibles, identifiez au moins quatre notions parmi Frais bancaires, Réclamation bancaire, Relevé bancaire, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('36a8ff8d-905e-5686-b676-1927c411bf77', '2626c907-b199-510f-bcdc-519a773bf862', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Deux comptes affichent des frais de tenue, carte et virements différents : le compte le moins cher dépend de l’usage réel, pas d’un seul tarif.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4f9d8800-1068-5ae0-9ee7-5d2ca0bf3664', '2626c907-b199-510f-bcdc-519a773bf862', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Comparer deux grilles fictives pour un profil effectuant 12 virements et utilisant une carte.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7336ba40-07dc-5736-8d02-9b7ee410c668', '2626c907-b199-510f-bcdc-519a773bf862', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Additionner tous les coûts comparables sur la même période et expliquer les hypothèses.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('99d48aaa-aff0-5d02-a849-bb8df67475a7', '2626c907-b199-510f-bcdc-519a773bf862', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f421b1d9-42c4-5752-b58f-9dab4696402f', '2626c907-b199-510f-bcdc-519a773bf862', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2711d9aa-c778-5dd9-8924-834873c256ad', '2626c907-b199-510f-bcdc-519a773bf862', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a84816a0-ac7e-520f-b2ee-e4e823bd4099', '2626c907-b199-510f-bcdc-519a773bf862', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('99b05eff-afd2-5371-ae46-a9384094d89f', '2626c907-b199-510f-bcdc-519a773bf862', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un coût annuel bancaire"], ["Défi", "Repérer 3 coûts invisibles dans une offre"], ["Outil lié", "Comparateur de frais"], ["Preuve Skills Passport", "Comparatif daté"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S35"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
