INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6198c8a0-0389-58d8-b457-f058081a910e', '577b62d2-9110-51f7-a249-e6520d9ec374', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Particuliers, professionnels, entrepreneurs"], ["Niveau", "N2"], ["Objectif measurable", "Relier capital, durée, coût, mensualité, reste à vivre et scénario défavorable."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8cc25897-2b2a-533f-9b25-9dfa71bff40f', '577b62d2-9110-51f7-a249-e6520d9ec374', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Dette", "obligation de remboursement suivie par capital, échéance et coût.", "[S01] [S32]"], ["Taux d’effort", "indicateur pédagogique, non critère universel d’acceptation bancaire.", "[S32]"], ["Capacité de remboursement", "Montant qu’un budget peut consacrer durablement à une échéance sans compromettre les dépenses essentielles, la sécurité et les autres engagements.", "[S22], [S32]"], ["Reste à vivre", "Montant restant après déduction des catégories d’engagement retenues par le modèle ; la composition du calcul doit toujours être affichée.", "[S32]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('36a43d56-1730-5df9-a55d-09a7a391b0cc', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Relier capital, durée, coût, mensualité, reste à vivre et scénario défavorable. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('171770d9-4cc6-5a64-a07b-fa16031d4d3d', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Dette — obligation de remboursement suivie par capital, échéance et coût. [S01] [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Taux d’effort — indicateur pédagogique, non critère universel d’acceptation bancaire. [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Capacité de remboursement — Montant qu’un budget peut consacrer durablement à une échéance sans compromettre les dépenses essentielles, la sécurité et les autres engagements. [S22], [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Reste à vivre — Montant restant après déduction des catégories d’engagement retenues par le modèle ; la composition du calcul doit toujours être affichée. [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('255ae2e3-240b-5d6d-9c53-1d3915071b7e', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Comparer coût total et mensualité. Pour « Comparer coût total et mensualité », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>2. Tester une baisse de revenu ou une dépense imprévue. Pour tester une baisse de revenu ou une dépense imprévue, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p><p>3. Ne jamais présenter un seuil unique comme règle universelle. Pour ne jamais présenter un seuil unique comme règle universelle, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('37b6438f-302f-51b9-810d-65f7aac94f4b', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier le besoin réel avant le produit.</p><p>Étape 2. Lire les conditions, frais, délais et risques.</p><p>Étape 3. Vérifier l’acteur et le canal officiel.</p><p>Étape 4. Comparer au moins deux solutions sur le coût total et l’usage.</p><p>Étape 5. Conserver la preuve et savoir comment réclamer en cas d’anomalie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('84c274b6-a632-571e-bf5d-7a609ce1f43c', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('21c3bb28-2c52-5403-8899-ca2b1bff330c', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Comprendre le crédit et préparer sa capacité de remboursement », relevez les données disponibles, identifiez au moins quatre notions parmi Dette, Taux d’effort, Capacité de remboursement, Reste à vivre, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4d589059-e93c-542d-aa58-4ff2ea0db95d', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 9, '{"html": "<h2>Approfondissement intégré — Crédit, leasing et coût total</h2><ul><li><strong>Publics</strong> : Salariés, entreprises</li><li><strong>Compétences renforcées</strong> : comparer coût total et mensualité; comprendre leasing; analyser cash initial et garanties</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Dette</strong> : Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. — [S01], [S32]</li><li><strong>Leasing</strong> : Mode de financement de l’usage d’un actif selon un contrat de location financière dont les loyers, options, propriété finale et risques doivent être comparés au crédit et à l’achat comptant. — [S47]</li><li><strong>Capacité de remboursement</strong> : Montant qu’un budget peut consacrer durablement à une échéance sans compromettre les dépenses essentielles, la sécurité et les autres engagements. — [S22], [S32]</li><li><strong>Taux d’intérêt</strong> : Prix du temps et du crédit exprimé en pourcentage selon une convention et une période ; son interprétation exige de préciser base, durée, frais et capitalisation. — [S34], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('49d0f385-099a-5ad8-827e-ef71d6aac4c3', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 10, '{"html": "<h3>Crédit</h3><p>Le crédit met à disposition des fonds remboursés selon les conditions contractuelles. La décision doit tenir compte de la durée, du coût total, des frais, des garanties et de la capacité de remboursement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fde82db5-c8a8-53e9-91fa-fbfd96c1d619', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 11, '{"html": "<h3>Leasing</h3><p>Le leasing permet de financer l''usage d''un actif selon un contrat de location financière avec conditions spécifiques. Pour l''entreprise, il faut comparer cash initial, loyers, propriété finale éventuelle, fiscalité et flexibilité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('70df2029-48ba-5b10-99f0-53bd0939168e', '577b62d2-9110-51f7-a249-e6520d9ec374', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Deux solutions pour une machine de 8 M DA peuvent avoir un coût total et un impact initial sur la trésorerie différents. FINCLUDIA doit comparer les deux dimensions.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d60c51e5-e0fc-512f-a4a0-b29f0d6eb01e', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Construisez une grille de comparaison avec au moins 8 critères au-delà du taux.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d2a2acc4-fc18-51ad-a695-16aa2fac706e', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : la grille doit comparer au minimum coût total, mensualité/loyer, cash initial, durée, frais, garanties, flexibilité/remboursement anticipé, propriété finale de l’actif, traitement fiscal/comptable et impact sur la trésorerie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0c6cd2d2-21c4-5944-b677-2546f73e2970', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('971bddf9-1de5-51f9-ab12-06e5f749615f', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Comparer seulement la mensualité est suffisant ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Pour le leasing<br><em>B. Le coût total et les conditions comptent.</em></li><li><strong>2. Le leasing concerne généralement :</strong><br>A. L''usage/financement d''un actif<br>B. Un impôt<br>C. Un budget familial<br>D. Un indice boursier<br><em>A. Il s''agit d''un mécanisme de financement d''actifs.</em></li><li><strong>3. Le cash initial est :</strong><br>A. Sans importance<br>B. Un critère important<br>C. Toujours zéro<br>D. Toujours supérieur au prix<br><em>B. Il influence la liquidité.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('21942710-089f-5d5b-a4a1-c9e97311142c', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un salarié compare 36 et 60 mois : la mensualité baisse avec la durée, mais le coût total peut augmenter.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aa07dc6b-de53-5932-947d-c61c6b5dbcb6', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Comparer deux financements fictifs et tester -10 % de revenu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6e3b9e60-2793-5015-93f9-feb1eddbc86f', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>La conclusion doit intégrer coût total, reste à vivre et résilience.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8d73a459-cee4-5df0-b286-0fb4c89ac408', '577b62d2-9110-51f7-a249-e6520d9ec374', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fa7783eb-d8ce-5ebc-b012-585f51eb578a', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5a0f10c0-f2b1-5eb3-b620-fb281a2815a7', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6c6d08d4-4faf-5861-8b0b-d14d1e3bd18c', '577b62d2-9110-51f7-a249-e6520d9ec374', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('20b408bb-129e-5fab-b10f-8b52bb84841d', '577b62d2-9110-51f7-a249-e6520d9ec374', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Faire un stress test crédit"], ["Défi", "Expliquer pourquoi la mensualité seule ne suffit pas"], ["Outil lié", "Simulateur crédit"], ["Preuve Skills Passport", "Comparatif + stress test"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32, S35"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
