INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('05ba166b-4175-5a0c-87f1-c3466c95b285', 'cd7fb3bb-93fd-5bf7-8371-60c525fdcc16', 'BNK-05 — Droits du client, information et réclamation', 'Connaître les principes de protection de la clientèle et savoir documenter une réclamation.', NULL, 5, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d8ecec5e-a601-5485-bdcf-1c49bb454cca', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Tous publics"], ["Niveau", "N1-N2"], ["Objectif measurable", "Connaître les principes de protection de la clientèle et savoir documenter une réclamation."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dc76c984-9a0c-5970-a30e-b0d58558251a', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Éducation financière bancaire", "transparence et décision éclairée.", "[S22] [S35]"], ["Réclamation bancaire", "démarche documentée auprès de l’établissement selon le processus applicable.", "[S35]"], ["Demande", "Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions.", "[S32]"], ["Relevé bancaire", "Document retraçant, pour une période, les opérations portées sur un compte et son solde selon les informations de l’établissement.", "[S35], [S32]"], ["Action", "Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre.", "[S38], [S41]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0603011a-7034-5386-ad3b-9395f67a3d09', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Connaître les principes de protection de la clientèle et savoir documenter une réclamation. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('41d8ef51-cd0f-5e91-bd9e-9941a58d4cd7', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Éducation financière bancaire — transparence et décision éclairée. [S22] [S35]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Réclamation bancaire — démarche documentée auprès de l’établissement selon le processus applicable. [S35]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Demande — Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions. [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Relevé bancaire — Document retraçant, pour une période, les opérations portées sur un compte et son solde selon les informations de l’établissement. [S35], [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Action — Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre. [S38], [S41]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('36c455bb-fac8-55fb-896a-792fe40a6aa0', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Traitement équitable et information claire. Pour traitement équitable et information claire, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p><p>2. Compréhension de la nature d’une transaction avant conclusion. Pour compréhension de la nature d’une transaction avant conclusion, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p><p>3. Conserver date, faits, pièces et réponse dans une réclamation. Pour conserver date, faits, pièces et réponse dans une réclamation, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3157a225-862f-5fe4-877e-8117b7a737a7', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier le besoin réel avant le produit.</p><p>Étape 2. Lire les conditions, frais, délais et risques.</p><p>Étape 3. Vérifier l’acteur et le canal officiel.</p><p>Étape 4. Comparer au moins deux solutions sur le coût total et l’usage.</p><p>Étape 5. Conserver la preuve et savoir comment réclamer en cas d’anomalie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('70ac0482-2d70-5e76-b21b-ed3a8d5ee245', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Droits du client, information et réclamation », relevez les données disponibles, identifiez au moins quatre notions parmi Éducation financière bancaire, Réclamation bancaire, Demande, Relevé bancaire, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5292b810-b272-521c-a88a-c9c4747e7850', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un client constate un frais non compris sur son relevé : il documente l’opération, consulte les conditions puis utilise le canal officiel de réclamation.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e7fd8cd6-08d3-5adf-a39a-208984acdf49', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Rédiger une réclamation factuelle en 8 lignes à partir d’un cas fictif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fc469a18-a38b-54b7-a894-39bcc5a60284', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>La réclamation doit préciser opération, date, montant, question, pièce et demande sans accusation non étayée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('31f6d50a-4eb2-5faa-9707-7d8527a5a38c', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d2bb7d62-b2d2-5616-b6ee-47bed6b272aa', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('12c1a2a8-9776-5f84-8c34-51ad80898251', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dbfed41b-a2e6-5e61-9d26-a5f5bcebe32f', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6b58b47e-872d-5782-8abe-4611ab0cead3', '05ba166b-4175-5a0c-87f1-c3466c95b285', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Constituer un dossier de réclamation"], ["Défi", "Obtenir une chronologie complète"], ["Outil lié", "Centre de confiance"], ["Preuve Skills Passport", "Dossier fictif complet"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S22, S35"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
