INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'cd7fb3bb-93fd-5bf7-8371-60c525fdcc16', 'BNK-06 — Sécurité financière numérique et fraude', 'Adopter des réflexes de protection pour comptes, cartes, OTP et paiements.', NULL, 6, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f24a0903-8ebf-558a-a1eb-5066f7b3dce6', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Tous publics"], ["Niveau", "N1"], ["Objectif measurable", "Adopter des réflexes de protection pour comptes, cartes, OTP et paiements."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('00accd4f-ed03-5c60-bb1b-9ca569504d85', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Phishing", "tentative de tromper l’utilisateur afin d’obtenir un secret ou provoquer une opération.", "[S32]"], ["Authentification", "mécanisme de vérification de l’identité ou de l’autorisation d’un utilisateur.", "[S32]"], ["Demande", "Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions.", "[S32]"], ["OTP", "Code d’authentification à usage unique utilisé pour confirmer une opération ou une connexion ; il doit rester secret.", "[S35], [S32]"], ["ARR", "Annualisation pédagogique du revenu récurrent, souvent calculée à partir du MRR lorsque le modèle et la stabilité des revenus le permettent.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0b361a07-fa26-5bdc-8a94-48a5b7267ce2', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Adopter des réflexes de protection pour comptes, cartes, OTP et paiements. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5ad65caf-2dc7-57d2-9998-85a8bd4b1df6', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Phishing — tentative de tromper l’utilisateur afin d’obtenir un secret ou provoquer une opération. [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Authentification — mécanisme de vérification de l’identité ou de l’autorisation d’un utilisateur. [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Demande — Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions. [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>OTP — Code d’authentification à usage unique utilisé pour confirmer une opération ou une connexion ; il doit rester secret. [S35], [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>ARR — Annualisation pédagogique du revenu récurrent, souvent calculée à partir du MRR lorsque le modèle et la stabilité des revenus le permettent. [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('34418f5a-d6dc-5b73-a840-da419842c49f', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. PIN, mot de passe et OTP ne se partagent pas. Un OTP est un code d’authentification à usage limité. Il ne doit pas être communiqué à un tiers, même si celui-ci se présente comme un conseiller.</p><p>2. Vérifier domaine, bénéficiaire, montant et canal. Pour vérifier domaine, bénéficiaire, montant et canal, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p><p>3. En cas de doute : interrompre, contacter le canal officiel, conserver les preuves. Pour « En cas de doute : interrompre, contacter le canal officiel, conserver les preuves », la compétence est documentaire : savoir quelle information doit être conservée, qui l''émet, à quelle date et à quelle opération elle se rattache. Une trace exploitable doit permettre de reconstituer la décision.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('895b3de8-acd0-5dd3-bba0-1c204d918fcd', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier le besoin réel avant le produit.</p><p>Étape 2. Lire les conditions, frais, délais et risques.</p><p>Étape 3. Vérifier l’acteur et le canal officiel.</p><p>Étape 4. Comparer au moins deux solutions sur le coût total et l’usage.</p><p>Étape 5. Conserver la preuve et savoir comment réclamer en cas d’anomalie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a71ebd0b-132f-5e58-9385-ed26c0556417', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Sécurité financière numérique et fraude », relevez les données disponibles, identifiez au moins quatre notions parmi Phishing, Authentification, Demande, OTP, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0eabe474-ce16-571c-9a6c-2572b215d1e1', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un message prétend bloquer la carte dans 10 minutes et demande le code SMS : il faut arrêter et vérifier auprès de l’établissement.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('74f1ea3e-efd8-5264-8f36-dc52aaf94ed0', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Analyser cinq messages fictifs et signaler les indices de fraude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('170034e3-0ce3-5ec2-be4f-1bb4f3a875ab', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Toute demande de secret ou urgence artificielle doit déclencher une vérification indépendante.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1415c0d4-8e37-5a2e-86e7-aa43a103ad8b', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8b0dafbd-7b5a-5f13-97af-1945b29c8acd', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f26d4d8f-0bd2-55f7-8073-d1653b6c9b31', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d2519350-fe21-56fc-9f73-95b75623edd5', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f02345ab-ad40-543b-a350-b2b3908fdcad', '88f8ba0d-fdbd-5fa7-be92-ebdf47624229', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Passer le test anti-phishing"], ["Défi", "Aucune erreur critique sur OTP/PIN"], ["Outil lié", "Security Lab"], ["Preuve Skills Passport", "Checklist sécurité"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32, S35, S36"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
