INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('65043c79-9a91-5b3c-abf9-68f00d29f586', 'cd7fb3bb-93fd-5bf7-8371-60c525fdcc16', 'BNK-07 — Découvrir la finance islamique bancaire', 'Comprendre les principes et principaux contrats sans assimiler automatiquement tout produit à un crédit classique.', NULL, 7, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9afc9e65-5df0-57e9-9835-9c6f66b167ed', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Particuliers, entrepreneurs, publics intéressés par la finance islamique"], ["Niveau", "N2"], ["Objectif measurable", "Comprendre les principes et principaux contrats sans assimiler automatiquement tout produit à un crédit classique."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ee47c11b-29e3-542c-9f27-1be6c15ce2c2', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Finance islamique", "opérations bancaires ne donnant pas lieu à perception ou versement d’intérêts selon le cadre réglementaire applicable.", "[S37]"], ["Mourabaha", "vente avec marge connue selon les caractéristiques du produit autorisé.", "[S37]"], ["Obligation", "Titre de créance par lequel l’investisseur prête des fonds à un émetteur selon des conditions de rémunération et de remboursement prévues.", "[S38], [S41]"], ["Offre", "Quantité d’un bien ou service que les producteurs sont disposés à proposer selon les prix et autres conditions.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('12c742a0-862c-531d-9311-8448b326d1fb', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre les principes et principaux contrats sans assimiler automatiquement tout produit à un crédit classique. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('30e9881e-1ba3-5392-ad27-400e5d87f99d', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Finance islamique — opérations bancaires ne donnant pas lieu à perception ou versement d’intérêts selon le cadre réglementaire applicable. [S37]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Mourabaha — vente avec marge connue selon les caractéristiques du produit autorisé. [S37]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Obligation — Titre de créance par lequel l’investisseur prête des fonds à un émetteur selon des conditions de rémunération et de remboursement prévues. [S38], [S41]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Offre — Quantité d’un bien ou service que les producteurs sont disposés à proposer selon les prix et autres conditions. [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4e0a0550-a250-5241-bdf9-bbf8873c06d1', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Distinguer logique de vente, location ou participation. Ce point demande de comparer des notions proches sans les confondre. Pour « Distinguer logique de vente, location ou participation », l''utilisateur doit identifier le critère qui change — nature du flux, horizon, risque, propriétaire, date ou base de calcul — puis appliquer ce critère à un exemple réel ou fictif.</p><p>2. Comparer prix total, échéancier, frais, garanties et conditions. Pour « Comparer prix total, échéancier, frais, garanties et conditions », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>3. Vérifier l’autorisation et la documentation du produit auprès de l’établissement. Pour « Vérifier l’autorisation et la documentation du produit auprès de l’établissement », la compétence est documentaire : savoir quelle information doit être conservée, qui l''émet, à quelle date et à quelle opération elle se rattache. Une trace exploitable doit permettre de reconstituer la décision.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6aac4650-3084-5bc0-ba06-0853a34ff0bc', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier le besoin réel avant le produit.</p><p>Étape 2. Lire les conditions, frais, délais et risques.</p><p>Étape 3. Vérifier l’acteur et le canal officiel.</p><p>Étape 4. Comparer au moins deux solutions sur le coût total et l’usage.</p><p>Étape 5. Conserver la preuve et savoir comment réclamer en cas d’anomalie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f14bfdf6-9afd-55f2-b8e7-6b6779b121b3', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Découvrir la finance islamique bancaire », relevez les données disponibles, identifiez au moins quatre notions parmi Finance islamique, Mourabaha, Obligation, Offre, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('586c690e-611a-53b5-a672-68d0571a1fb6', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 8, '{"html": "<h2>Approfondissement intégré — Finance islamique : comprendre les principales structures</h2><ul><li><strong>Publics</strong> : Adultes, entreprises, étudiants</li><li><strong>Compétences renforcées</strong> : distinguer financement conventionnel et structures islamiques; connaître Murabaha, Ijara et Musharaka; comprendre que les contrats ont des risques et coûts</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Finance islamique</strong> : Opérations de banque relevant du cadre algérien de la finance islamique, définies comme ne donnant pas lieu à la perception ou au versement d’intérêts et soumises aux règles spécifiques applicables. — [S37]</li><li><strong>Mourabaha</strong> : Opération de vente à marge connue dans laquelle l’établissement acquiert un bien puis le revend au client selon les conditions du produit autorisé. — [S37]</li><li><strong>Ijara</strong> : Structure de finance islamique fondée sur une logique de location d’un actif selon les conditions contractuelles et réglementaires applicables. — [S47]</li><li><strong>Musharaka</strong> : Structure de finance islamique fondée sur une participation ou association au capital/au projet selon des modalités contractuelles définies. — [S47]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7f06f795-3c1f-5847-b161-0ff8f7372378', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 9, '{"html": "<h3>Cadre algérien</h3><p>La Banque d''Algérie dispose d''un cadre spécifique pour les opérations relevant de la finance islamique. Des règlements de 2025 ont notamment précisé les règles comptables et le marché monétaire interbancaire de finance islamique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('18b1c9a6-4e25-567f-8845-00e1efea13e8', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 10, '{"html": "<h3>Structures</h3><p>Murabaha : vente avec marge connue selon la structure applicable. Ijara : logique de location. Musharaka : participation/association selon les modalités contractuelles. Ces notions doivent être enseignées sans les réduire à une simple traduction du crédit conventionnel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f04b4cc6-38e6-523a-9406-b906e47fa8fc', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'callout', 11, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Pour un équipement, FINCLUDIA peut comparer une offre de crédit, une offre de leasing et une Ijara en affichant cash initial, paiements, propriété de l''actif, coût total et risques.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5eea49bb-fe79-5128-a332-33590f46ac92', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 12, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Créez un tableau comparatif pédagogique Crédit / Leasing / Ijara avec 6 critères.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8ce60c85-e336-5ca3-94bb-75ddcfe07d44', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 13, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : comparer Crédit / Leasing / Ijara sur au moins six critères : nature juridique, propriété de l’actif, cash initial, calendrier des paiements, coût total/marge/loyers, garanties/risques, fin de contrat et flexibilité. Ne pas réduire l’Ijara à une simple traduction du crédit.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3c13ee9d-8dcd-5654-bd7e-17f02ee25a61', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 14, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7db3e757-a055-5eb7-abe5-e623b5e53cd3', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 15, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. La finance islamique en Algérie dispose-t-elle d''un cadre réglementaire ?</strong><br>A. Oui<br>B. Non<br>C. Seulement à l''étranger<br>D. Uniquement pour les ménages<br><em>A. La Banque d''Algérie publie plusieurs règlements dédiés.</em></li><li><strong>2. Ijara correspond principalement à une logique de :</strong><br>A. Location<br>B. Action ordinaire<br>C. Impôt<br>D. Salaire<br><em>A. Il s''agit d''une structure de location.</em></li><li><strong>3. Une structure islamique signifie automatiquement absence de risque ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Seulement en banque<br><em>B. Toute décision financière comporte des risques et conditions.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('73bff5e1-2fa7-55bd-af9f-fd1be33b0fd8', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 16, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un ménage compare un financement classique et une Mourabaha immobilière : il compare coût total et obligations contractuelles sans réduire la comparaison au seul vocabulaire.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('347401c9-edbc-5aff-a5bd-e561340e8096', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 17, '{"html": "<h2>Exercice d’application</h2><p>Créer une grille de comparaison neutre pour deux offres fictives.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ee1f7c97-b454-5f65-86ba-19e0dc1259e1', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 18, '{"html": "<h2>Corrigé-type</h2><p>Comparer même objet, durée, apports, coûts, garanties et clauses ; aucune conclusion religieuse personnalisée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b4ec235c-f287-53b4-9cc8-a4973dd7c42f', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'table', 19, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('222824c3-f074-5079-a8b7-7bee7037f03e', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 20, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f2133539-406a-5aa0-a31f-45e7dfdc433b', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 21, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('503106a3-aa7f-578a-a468-eec8a5273599', '65043c79-9a91-5b3c-abf9-68f00d29f586', 'text', 22, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
