INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'cd7fb3bb-93fd-5bf7-8371-60c525fdcc16', 'BNK-08 — Inclusion financière et choix du canal adapté', 'Identifier les barrières d’accès et choisir un canal formel adapté aux besoins.', NULL, 8, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1a4b4317-c588-5d33-8c7a-11fdfe5e57cf', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Jeunes, non-bancarisés, zones éloignées, familles, entrepreneurs"], ["Niveau", "N1-N2"], ["Objectif measurable", "Identifier les barrières d’accès et choisir un canal formel adapté aux besoins."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8205aa9c-dcce-5c57-9413-986ac5b4ab7e', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Inclusion financière", "accès et usage de services formels adaptés, associés à compréhension et protection.", "[S01] [S35] [S36]"], ["Besoin", "Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer.", "[S01], [S32]"], ["ARR", "Annualisation pédagogique du revenu récurrent, souvent calculée à partir du MRR lorsque le modèle et la stabilité des revenus le permettent.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eac995fd-a5cc-5477-9cf0-b29b3fb79f87', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Identifier les barrières d’accès et choisir un canal formel adapté aux besoins. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('097c3241-c265-549b-9b5b-f8fb8cda3b54', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Inclusion financière — accès et usage de services formels adaptés, associés à compréhension et protection. [S01] [S35] [S36]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>Besoin — Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer. [S01], [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p><p>ARR — Annualisation pédagogique du revenu récurrent, souvent calculée à partir du MRR lorsque le modèle et la stabilité des revenus le permettent. [S32]</p><p>Application dans ce module. L’utilisateur doit savoir reconnaître le service ou l’acteur concerné, lire les conditions essentielles, vérifier le coût et la sécurité, puis conserver une preuve de l’opération ou de la demande.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1d0d6de5-ccf3-580b-a742-6a998b0e79b1', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Barrières possibles : distance, coût, confiance, documents, compétences numériques. Pour « Barrières possibles : distance, coût, confiance, documents, compétences numériques », la compétence est documentaire : savoir quelle information doit être conservée, qui l''émet, à quelle date et à quelle opération elle se rattache. Une trace exploitable doit permettre de reconstituer la décision.</p><p>2. Comparer agence, paiement numérique, compte, produits et accompagnement. Pour comparer agence, paiement numérique, compte, produits et accompagnement, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p><p>3. L’inclusion ne signifie pas souscrire un produit inutile. Pour l’inclusion ne signifie pas souscrire un produit inutile, l''utilisateur identifie l''acteur qui fournit le service, les conditions d''utilisation, les frais éventuels, les risques et la preuve disponible. La compétence consiste ensuite à comparer une alternative et à savoir quel canal officiel utiliser en cas de doute.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('83c2865e-c016-5bdc-a4d4-a08f4a8a2029', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier le besoin réel avant le produit.</p><p>Étape 2. Lire les conditions, frais, délais et risques.</p><p>Étape 3. Vérifier l’acteur et le canal officiel.</p><p>Étape 4. Comparer au moins deux solutions sur le coût total et l’usage.</p><p>Étape 5. Conserver la preuve et savoir comment réclamer en cas d’anomalie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cdf7f21c-ca11-5fbc-a31c-903dc22f56e9', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Inclusion financière et choix du canal adapté », relevez les données disponibles, identifiez au moins quatre notions parmi Inclusion financière, Besoin, ARR, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('98558850-fde9-507b-9924-12031657a52a', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un artisan veut encaisser de façon traçable et séparer son activité : le parcours commence par le besoin, puis compare les solutions disponibles et leur coût.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('88e2826b-92b8-55a1-bdc1-a9294680d63c', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Pour quatre profils fictifs, définir besoin, obstacle, canal possible et point de vigilance.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d809878e-b361-5934-a1c9-70105c78be6a', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Une solution est adaptée si elle répond au besoin et si l’utilisateur comprend coût, risques et recours.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3ce55e70-589d-594f-ae45-a70b5a2123e8', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fd1d3b7a-f70d-53f0-8dfd-7433aca5cf41', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('795e2de5-59e8-5360-9a61-74ea340cfd8c', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ff0aae7e-4198-5919-b527-57c6f2dc1d0d', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('da45c21e-bc7a-519a-9370-7781fd2bd137', 'eb83f4d4-50f9-52c3-95e5-79490ee008aa', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Construire un plan d’accès financier"], ["Défi", "Trouver une solution sans vente forcée"], ["Outil lié", "Guide inclusion"], ["Preuve Skills Passport", "Plan d’accès"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S35, S36"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
