INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('5c9a9f3a-77b2-503c-a5ac-8fb2280ce3c5', 'cd7fb3bb-93fd-5bf7-8371-60c525fdcc16', 'Cas intégrateur corrigé — Banque & inclusion', NULL, NULL, 9, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('66c35078-4a38-5188-8dae-3ef14045043a', '5c9a9f3a-77b2-503c-a5ac-8fb2280ce3c5', 'text', 1, '{"html": "<h3>Scénario\\nNadia compare deux comptes fictifs. Offre A : tenue de compte 300 DA/mois, carte 1 200 DA/an, 2 retraits hors réseau gratuits puis 100 DA chacun. Offre B : tenue 450 DA/mois, carte incluse, retraits hors réseau gratuits. Nadia effectue 3 retraits hors réseau par mois et souhaite ensuite simuler un crédit de 360 000 DA sur 24 mois sans conclure automatiquement.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fe4aff78-25af-54c3-af4e-e6c54cb0e7e4', '5c9a9f3a-77b2-503c-a5ac-8fb2280ce3c5', 'text', 2, '{"html": "<h2>Travail demandé</h2><p>1. Calculer le coût annuel visible des deux offres pour le comportement décrit.</p><p>2. Identifier les éléments à vérifier dans la brochure tarifaire.</p><p>3. Expliquer pourquoi la carte, le compte et le budget sont trois notions différentes.</p><p>4. Indiquer les contrôles de sécurité avant une opération en ligne.</p><p>5. Expliquer ce qu’une simulation de crédit peut et ne peut pas valider.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a67e852b-f4b1-5fa6-9533-69a3127d47a7', '5c9a9f3a-77b2-503c-a5ac-8fb2280ce3c5', 'text', 3, '{"html": "<h2>Corrigé-type</h2><p>A : tenue 3 600 + carte 1 200 + 12 retraits payants environ (un par mois après les deux gratuits mensuels, donc ici 1 payant/mois) = 1 200 DA, soit 6 000 DA/an. B : 5 400 DA/an. Sur ces seules hypothèses, B est moins chère de 600 DA, mais il faut vérifier tous les autres frais et conditions. La simulation de crédit estime mensualité/coût selon hypothèses ; elle ne vaut ni accord bancaire ni conseil personnalisé.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a2d0bc79-04c5-5b7d-a0b1-d2c98ac72994', '5c9a9f3a-77b2-503c-a5ac-8fb2280ce3c5', 'table', 4, '{"headers": ["Critère", "Poids"], "rows": [["Exactitude technique / calculs", "35 %"], ["Interprétation et décision", "25 %"], ["Gestion du risque / conformité", "20 %"], ["Traçabilité et sources", "10 %"], ["Clarté de l’explication", "10 %"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fd1b111e-de0e-5323-82e5-f5dbc762d0ad', '5c9a9f3a-77b2-503c-a5ac-8fb2280ce3c5', 'text', 5, '{"html": "<h3>Validation du cas intégrateur\\nSeuil : 75 %. Une erreur critique de sécurité, conformité, fraude, règle réglementaire active ou confusion réel/fictif doit être corrigée avant validation, même si le score global atteint 75 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'academy-finance-collective-familiale', 'FINCLUDIA Academy — Finance collective & familiale', 'Colocation, couple et foyer : règles, répartition, budget, remboursements, objectifs, réserve et gouvernance.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Finance collective & familiale', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'beginner', '["COL-01 — Mes finances, nos finances, les finances du foyer", "COL-02 — Répartir équitablement les dépenses", "COL-03 — Construire un budget collectif", "COL-04 — Avances, remboursements et soldes", "COL-05 — Objectifs communs", "COL-06 — Réserve et résilience du foyer", "COL-07 — Gouvernance financière du foyer"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '[]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('577454b8-f422-5897-86f4-233f3d6208e3', 'ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'COL-01 — Mes finances, nos finances, les finances du foyer', 'Séparer les données personnelles, partagées et communes.', NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d323ae19-655c-533e-aec5-0d0c72861658', '577454b8-f422-5897-86f4-233f3d6208e3', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Colocataires, couples, familles"], ["Niveau", "N1-N2"], ["Objectif measurable", "Séparer les données personnelles, partagées et communes."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f7e2c3c0-9e56-5980-956f-ede716ac8b23', '577454b8-f422-5897-86f4-233f3d6208e3', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01] [S32]"], ["Patrimoine net", "Valeur des actifs détenus diminuée des dettes et autres passifs retenus.", "[S32]"], ["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01] [S32]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e915c08c-ac79-579d-aa73-278f389c37dd', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Séparer les données personnelles, partagées et communes. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('19ccb18f-ba29-5fdc-8f74-5f52cbf52ff8', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01] [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Patrimoine net — Valeur des actifs détenus diminuée des dettes et autres passifs retenus. [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Dette — Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. [S01] [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01], [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eff69ae4-72ca-58df-9ba2-54190757fd78', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Trois espaces : personnel, partagé, foyer. Dans un foyer, trois espaces : personnel, partagé, foyer doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p><p>2. Permissions et confidentialité. Dans un foyer, permissions et confidentialité doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p><p>3. Dette personnelle vs dette commune. Ce point demande de comparer des notions proches sans les confondre. Pour « Dette personnelle vs dette commune », l''utilisateur doit identifier le critère qui change — nature du flux, horizon, risque, propriétaire, date ou base de calcul — puis appliquer ce critère à un exemple réel ou fictif.</p><p>Repère de calcul. Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7e80e3b1-9fb2-52f4-bc0f-a5fa094a89bc', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir ce qui est personnel et ce qui est commun.</p><p>Étape 2. Choisir une règle de partage comprise par tous.</p><p>Étape 3. Calculer les contributions et soldes sans double compte.</p><p>Étape 4. Prévoir une réserve et des objectifs communs.</p><p>Étape 5. Documenter les décisions importantes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('30fcc930-15d6-5735-9bf1-334adb0ca274', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f7641bc7-49bd-5ec5-a49f-4aba1ea9135e', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Mes finances, nos finances, les finances du foyer », relevez les données disponibles, identifiez au moins quatre notions parmi Budget, Patrimoine net, Dette, Épargne, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ce4564aa-f6e0-52ae-b6d6-d42a98e019dd', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Dans un couple, un crédit automobile personnel peut rester privé tandis que le loyer, les courses et l’épargne vacances sont partagés. FINCLUDIA doit respecter le niveau de partage choisi.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('366b33ae-6e7e-5e65-be3f-b891bad40dce', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Classer 15 éléments entre Personnel / Partagé / Foyer.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('419631e2-46ce-5bfc-9b0d-a19c7d34267c', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Le classement dépend des règles décidées par les membres ; la confidentialité doit rester explicite.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('89679f72-c5ab-5ae5-919b-0b2bcf70a8db', '577454b8-f422-5897-86f4-233f3d6208e3', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0a75ad00-16bd-50ce-b79c-4f6696523ad5', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b3cdb04c-72cd-59b7-9d5c-3b4c54b155a7', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aa8fec33-6101-5e13-bfe7-06cbf497a969', '577454b8-f422-5897-86f4-233f3d6208e3', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('00442e5e-45e7-57fe-915c-df1fa6b11214', '577454b8-f422-5897-86f4-233f3d6208e3', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Configurer les permissions d’un foyer."], ["Défi", "Faire une revue des données partagées après 30 jours."], ["Outil lié", "Household Engine"], ["Preuve Skills Passport", "Matrice de permissions."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('65805362-fb47-54eb-a0a2-7b226dbda598', 'ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'course', '577454b8-f422-5897-86f4-233f3d6208e3', 'QCM — COL-01', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
