INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('19b6f479-6340-5ef4-8891-d46badcb6d7e', 'ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'COL-03 — Construire un budget collectif', 'Créer des enveloppes communes et suivre les écarts.', NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('034aee23-3451-5a03-bacc-f14983123acd', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Colocataires, couples, familles"], ["Niveau", "N1-N2"], ["Objectif measurable", "Créer des enveloppes communes et suivre les écarts."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('532f8044-cb88-5510-ae8a-465997e37aa8', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01] [S32]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Fonds de sécurité", "Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles.", "[S03] [S32]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01], [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('05cd7f9f-cf29-5651-99dd-60eae4227865', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Créer des enveloppes communes et suivre les écarts. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('17f28381-fc78-50f1-8b4d-65b19b556920', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01] [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Fonds de sécurité — Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles. [S03] [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01], [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6964e085-3ed5-5112-84b2-2c2c66722786', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Logement, charges, alimentation, transport commun, enfants, santé, loisirs, réserve et objectifs. Dans un foyer, logement, charges, alimentation, transport commun, enfants, santé, loisirs, réserve et objectifs doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p><p>Repère de calcul. Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p><p>2. Budget individuel vs budget collectif. Ce point demande de comparer des notions proches sans les confondre. Pour « Budget individuel vs budget collectif », l''utilisateur doit identifier le critère qui change — nature du flux, horizon, risque, propriétaire, date ou base de calcul — puis appliquer ce critère à un exemple réel ou fictif.</p><p>Repère de calcul. Solde budgétaire = revenus de la période − dépenses de la période.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cba551bf-d47c-5fed-ba08-b8b961d2c98f', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir ce qui est personnel et ce qui est commun.</p><p>Étape 2. Choisir une règle de partage comprise par tous.</p><p>Étape 3. Calculer les contributions et soldes sans double compte.</p><p>Étape 4. Prévoir une réserve et des objectifs communs.</p><p>Étape 5. Documenter les décisions importantes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('17463fa5-89c4-5843-a3e4-d124167f1aa3', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('db2755ed-9266-59c1-9c1e-e1637d4f8820', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Construire un budget collectif », relevez les données disponibles, identifiez au moins quatre notions parmi Budget, Dépense, Fonds de sécurité, Épargne, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8ee41222-bbe9-5add-8224-1ae2272b0a37', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une famille à Sétif crée un budget de 180 000 DA dont 65 000 logement, 45 000 alimentation, 20 000 transport, 10 000 santé, 20 000 enfants et 20 000 épargne/réserve.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3274c15a-8857-510a-9e8d-b8eb84122efe', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Calculer le reste si le revenu foyer est 210 000 DA et le budget commun 180 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('65795ca0-ad2b-5823-a7ee-53971b1ae734', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>30 000 DA avant autres dépenses personnelles.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('456ba41d-473c-57fc-9541-d00b3ab73593', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d76281f4-fbe1-573a-a1a7-108b768ffced', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('62507a64-86fe-5730-97c2-8b81ca5ecb92', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1e1df1a4-dbb0-5fcc-bca7-deb64a7f0f06', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3719e17a-6d1b-59db-914c-f443fc40b759', '19b6f479-6340-5ef4-8891-d46badcb6d7e', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un budget collectif mensuel."], ["Défi", "Tenir 3 réunions budget mensuelles."], ["Outil lié", "Budget foyer"], ["Preuve Skills Passport", "Budget collectif complété."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S03, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
