INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('e02e8634-dd2c-504b-95a4-b591ce663b28', 'ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'COL-04 — Avances, remboursements et soldes', 'Calculer qui doit combien à qui sans mélanger les comptes personnels.', NULL, 4, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('faa8d128-3b1c-5d31-a5e8-9916968c69a8', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Colocataires"], ["Niveau", "N1-N2"], ["Objectif measurable", "Calculer qui doit combien à qui sans mélanger les comptes personnels."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('994e8ffd-25f7-56d6-be85-1b510a20d4b1', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Cash-flow personnel", "Différence entre ressources encaissées et sorties d’argent sur une période, après prise en compte des engagements suivis.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7c1fea75-77b2-529e-aea7-1337a1a23893', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Calculer qui doit combien à qui sans mélanger les comptes personnels. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c0bdee22-ad97-5200-8e84-c18c6435c764', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Cash-flow personnel — Différence entre ressources encaissées et sorties d’argent sur une période, après prise en compte des engagements suivis. [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4a3789dc-5c5a-5f21-b6ec-cab288b26962', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Payeur, participants concernés, clé de répartition. Dans un foyer, payeur, participants concernés, clé de répartition doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p><p>2. Solde net. Dans un foyer, solde net doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p><p>Repère de calcul. Solde budgétaire = revenus de la période − dépenses de la période.</p><p>3. Remboursement et preuve. Pour « Remboursement et preuve », la compétence est documentaire : savoir quelle information doit être conservée, qui l''émet, à quelle date et à quelle opération elle se rattache. Une trace exploitable doit permettre de reconstituer la décision.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1f171210-1d60-543d-99b9-796145500eb1', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir ce qui est personnel et ce qui est commun.</p><p>Étape 2. Choisir une règle de partage comprise par tous.</p><p>Étape 3. Calculer les contributions et soldes sans double compte.</p><p>Étape 4. Prévoir une réserve et des objectifs communs.</p><p>Étape 5. Documenter les décisions importantes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3b7a8e36-5145-51a4-8373-33c475c1dba5', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('309544cd-62cc-518b-b37e-e0030b34aa48', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Avances, remboursements et soldes », relevez les données disponibles, identifiez au moins quatre notions parmi Dépense, Cash-flow personnel, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('32658cf6-00e7-5d8a-9e3e-4a0f4cf502c1', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Dans une colocation, A paie 12 000 DA d’internet/charges pour A, B et C à parts égales. Chaque personne supporte 4 000 DA ; B et C doivent chacun 4 000 DA à A.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4dca67e8-db44-54af-8158-72f9e3d9cfb8', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>A avance 18 000 DA pour 3 personnes à parts égales ; B a déjà remboursé 2 000 DA. Quel solde reste dû par B ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8321233b-a030-5d59-a2e5-7dd6790416ef', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Part B = 6 000 DA ; après 2 000 DA, il reste 4 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('93ac22f0-0ea4-5d2b-8eca-c87c5ad3d993', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c215889a-c459-5a8b-8051-6908f20d88a0', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('51a04df1-4581-58c9-b52a-5122a2423cc4', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9b39d3f2-6113-5c3f-9e25-2ac45904d3d1', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('73ddb19c-75b5-5074-a2be-1fe9853216ba', 'e02e8634-dd2c-504b-95a4-b591ce663b28', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Enregistrer 10 dépenses communes."], ["Défi", "Clôturer un mois avec tous les soldes expliqués."], ["Outil lié", "Coloc"], ["Preuve Skills Passport", "Journal de soldes."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
