INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('1e86c2fe-65df-5560-8000-eeb4b8726482', 'ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'COL-05 — Objectifs communs', 'Financer un projet collectif avec contributions explicites.', NULL, 5, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d5c1a4d7-d525-526d-9285-61f50ba8186f', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Couples, familles, colocataires"], ["Niveau", "N1-N2"], ["Objectif measurable", "Financer un projet collectif avec contributions explicites."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9b8f0b42-4ff6-510e-9d48-9d6d6efc9a30', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Objectif financier", "Projet défini par un montant, un horizon, une priorité et une contribution à fournir.", "[S01] [S32]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01] [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"], ["Rendement", "Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon.", "[S01], [S41]"], ["Horizon d’investissement", "Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné.", "[S02], [S41]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d83a9b56-806d-5906-b325-7b03735b2cb5', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Financer un projet collectif avec contributions explicites. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e2f544d1-451a-5465-bd36-bceb1f1f82e5', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Objectif financier — Projet défini par un montant, un horizon, une priorité et une contribution à fournir. [S01] [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01] [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Rendement — Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon. [S01], [S41]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Horizon d’investissement — Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné. [S02], [S41]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6893480b-14f9-5df2-886a-e3812de8bf02', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Objectif, capital, horizon. L’horizon est la durée pendant laquelle l’argent peut rester mobilisé avant d’être nécessaire. Il détermine la capacité à accepter fluctuation, immobilisation ou durée de financement.</p><p>2. Contribution par membre. Dans un foyer, contribution par membre doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p><p>3. Règles de retrait. Dans un foyer, règles de retrait doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ba057da7-8949-5879-ad65-4e04c54d3c3d', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir ce qui est personnel et ce qui est commun.</p><p>Étape 2. Choisir une règle de partage comprise par tous.</p><p>Étape 3. Calculer les contributions et soldes sans double compte.</p><p>Étape 4. Prévoir une réserve et des objectifs communs.</p><p>Étape 5. Documenter les décisions importantes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bd8741bf-516b-5046-bb14-d56ec75ce6aa', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7eeecf30-2c80-5d65-b661-ff1e99a00fb3', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Objectifs communs », relevez les données disponibles, identifiez au moins quatre notions parmi Objectif financier, Épargne, Revenu, Rendement, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d2ba5fdc-27fe-5c3b-8f65-cf13f77c0c7c', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un couple vise 480 000 DA pour des travaux en 24 mois. A contribue 8 000 DA et B 12 000 DA par mois : 20 000 × 24 = 480 000 DA, hors capital initial et rendement.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9881e43e-8488-5355-9271-a01b14611187', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Objectif 300 000 DA en 15 mois à deux personnes, parts égales : contribution mensuelle par personne ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a3d4919a-ea47-5a84-ac9c-2f4eaace3467', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>300 000 / 15 / 2 = 10 000 DA par personne.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a02a52a6-9e16-5e94-a371-bb2f676de747', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b6807f56-52f7-5ae4-b1b0-719b3d4b1774', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('90116f82-c4b9-531e-8a12-aba7d64d386e', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c33b8589-9802-5ecb-89db-1bec125b0fda', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('29460191-f14d-5785-9683-8008ffd35315', '1e86c2fe-65df-5560-8000-eeb4b8726482', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un objectif commun."], ["Défi", "Atteindre 10 % du projet ou simuler trois scénarios."], ["Outil lié", "Objectifs foyer"], ["Preuve Skills Passport", "Trajectoire commune."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S08, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
