INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('da0118f3-569a-50a5-8735-4ffabb395567', 'ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'COL-06 — Réserve et résilience du foyer', 'Mesurer la dépendance aux revenus et la capacité à absorber un choc.', NULL, 6, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6ef1c94d-ae26-5945-be78-2f37dd8ae9f4', 'da0118f3-569a-50a5-8735-4ffabb395567', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Couples, familles"], ["Niveau", "N1-N2"], ["Objectif measurable", "Mesurer la dépendance aux revenus et la capacité à absorber un choc."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8e8b78bc-58ac-5879-9935-36aabc5a847f', 'da0118f3-569a-50a5-8735-4ffabb395567', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Fonds de sécurité", "Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles.", "[S03] [S32]"], ["Bien-être financier", "État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière.", "[S03]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d6d7891e-d03d-51b8-abc8-c207a8c4d7ce', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Mesurer la dépendance aux revenus et la capacité à absorber un choc. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2c55ee8c-1176-5d01-97e6-3f085533f55b', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Fonds de sécurité — Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles. [S03] [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Bien-être financier — État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière. [S03]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5ee702cf-af4e-5165-9cdc-3dc02b2aa7ca', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Réserve commune vs personnelle. Ce point demande de comparer des notions proches sans les confondre. Pour « Réserve commune vs personnelle », l''utilisateur doit identifier le critère qui change — nature du flux, horizon, risque, propriétaire, date ou base de calcul — puis appliquer ce critère à un exemple réel ou fictif.</p><p>Repère de calcul. Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p><p>2. Dépendance au revenu principal. Dans un foyer, dépendance au revenu principal doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p><p>3. Perte d’un revenu. Dans un foyer, perte d’un revenu doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p><p>4. Dépense familiale exceptionnelle. Dans un foyer, dépense familiale exceptionnelle doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b4916176-bbba-52c1-8e2d-12451d2c8582', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir ce qui est personnel et ce qui est commun.</p><p>Étape 2. Choisir une règle de partage comprise par tous.</p><p>Étape 3. Calculer les contributions et soldes sans double compte.</p><p>Étape 4. Prévoir une réserve et des objectifs communs.</p><p>Étape 5. Documenter les décisions importantes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8ed34ff1-9e8c-57d1-be5c-837f57deb02e', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('28e2e1b1-b260-5e2d-9812-8c9e452bc58c', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Réserve et résilience du foyer », relevez les données disponibles, identifiez au moins quatre notions parmi Fonds de sécurité, Bien-être financier, Risque financier, Dépense, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('33448cb2-e07f-52f4-9c49-3c8a895bfa68', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un foyer gagne 220 000 DA, dont 160 000 DA viennent d’un seul conjoint. FINCLUDIA signale une forte dépendance à cette source sans la qualifier comme faute : le foyer peut tester un scénario de perte temporaire.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('28e8f673-9304-575d-9111-bf765cfe9853', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Revenus 220 000 DA, revenu principal 160 000 DA. Calculer sa part.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b3018bb8-4432-5899-9960-44ca6a34866c', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>160 000 / 220 000 = 72,7 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ae7bfaba-ca83-537c-961f-58dc6eaa2303', 'da0118f3-569a-50a5-8735-4ffabb395567', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e0eeac00-35ae-5ba6-880d-6011c6144199', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ae0bfa31-27f4-57e1-b6a1-d1a11a479b06', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4f4ef76c-67e4-51d3-bd22-28848ef653ba', 'da0118f3-569a-50a5-8735-4ffabb395567', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f89e74f8-8b8e-550a-9b86-19441d5cba36', 'da0118f3-569a-50a5-8735-4ffabb395567', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Tester la perte de chaque revenu séparément."], ["Défi", "Définir 3 mesures de résilience."], ["Outil lié", "Stress test foyer"], ["Preuve Skills Passport", "Plan de résilience familiale."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S03, S22, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('6398ed58-2e8d-52ae-b04c-6cf2297a7a66', 'ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'course', 'da0118f3-569a-50a5-8735-4ffabb395567', 'QCM — COL-06', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
