INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('5cb4d0a1-0b49-5262-9ab0-999aa8f986e6', '6f08691f-53e7-5375-b922-7baa619122f4', 1, 'État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('0f19d32d-5a2d-5c96-894b-a78d37f1b2dc', '6f08691f-53e7-5375-b922-7baa619122f4', 2, 'Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles.', 1);
