INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('241d8453-7828-579d-b44c-101caa7a35a9', '6398ed58-2e8d-52ae-b04c-6cf2297a7a66', 'single', 4, 'Lorsqu’une donnée réglementaire, bancaire, fiscale ou de marché est utilisée, quel réflexe FINCLUDIA est correct ?', 'FINCLUDIA versionne les règles évolutives et sépare toujours simulation, information et décision.', 1, '[]');
