INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'COL-07 — Gouvernance financière du foyer', 'Mettre en place des règles de décision et une routine financière.', NULL, 7, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('73d07d35-fedc-5a3b-9dba-1a9ab39e907b', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Couples, familles, colocataires"], ["Niveau", "N1-N2"], ["Objectif measurable", "Mettre en place des règles de décision et une routine financière."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7ecd6e7b-0769-5475-96a8-b8ac6e643d5f', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01] [S32]"], ["Objectif financier", "Projet défini par un montant, un horizon, une priorité et une contribution à fournir.", "[S01] [S32]"], ["Bien-être financier", "État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière.", "[S03]"], ["Dépense commune", "Dépense bénéficiant à plusieurs membres d’un groupe ou d’un foyer et répartie selon une règle acceptée.", "[S32]"], ["Enveloppe budgétaire", "Montant affecté à une catégorie ou un objectif pendant une période afin de suivre ce qui est prévu, consommé et restant.", "[S32]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('46b07210-5856-5585-8a60-b88f36659969', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Mettre en place des règles de décision et une routine financière. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dbdfce7e-50d7-5a9e-99b6-7a67358edecf', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01] [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Objectif financier — Projet défini par un montant, un horizon, une priorité et une contribution à fournir. [S01] [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Bien-être financier — État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière. [S03]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Dépense commune — Dépense bénéficiant à plusieurs membres d’un groupe ou d’un foyer et répartie selon une règle acceptée. [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Enveloppe budgétaire — Montant affecté à une catégorie ou un objectif pendant une période afin de suivre ce qui est prévu, consommé et restant. [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La notion doit être appliquée avec une règle explicite de partage, des responsabilités claires et une traçabilité permettant d’éviter les conflits ou les doubles comptes entre membres.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('73622679-3efc-58f5-8b66-fa9214a8e70b', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Réunion financière mensuelle. Dans un foyer, réunion financière mensuelle doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p><p>2. Seuil de dépense nécessitant concertation. Dans un foyer, seuil de dépense nécessitant concertation doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p><p>3. Règle de contribution. Dans un foyer, règle de contribution doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p><p>4. Gestion des désaccords et confidentialité. Dans un foyer, gestion des désaccords et confidentialité doit être associé à une règle comprise par les membres : qui paie, qui bénéficie, comment la dépense est répartie et comment le solde est régularisé. La transparence de la règle est aussi importante que le calcul.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5e679153-a67e-50a8-a139-719ca0ce7a20', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir ce qui est personnel et ce qui est commun.</p><p>Étape 2. Choisir une règle de partage comprise par tous.</p><p>Étape 3. Calculer les contributions et soldes sans double compte.</p><p>Étape 4. Prévoir une réserve et des objectifs communs.</p><p>Étape 5. Documenter les décisions importantes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3b019fa1-4cf0-5a48-a757-68df76a9617c', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('830d3bcb-e873-5382-b8b9-857e8e3e9d9c', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Gouvernance financière du foyer », relevez les données disponibles, identifiez au moins quatre notions parmi Budget, Objectif financier, Bien-être financier, Dépense commune, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('588b7a85-b40e-52db-bd13-77968bdcf7e7', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un couple décide que toute dépense commune supérieure à 25 000 DA nécessite une validation des deux membres, tandis que les enveloppes personnelles restent libres.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e75f04cb-8a3c-58cd-a787-1c19c5ec656d', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Rédiger 5 règles simples de gouvernance financière pour un foyer fictif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8606e5fc-fd01-55e3-bfa7-0150a59175f1', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Les règles doivent couvrir budget, dépenses exceptionnelles, objectifs, confidentialité et revue périodique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('15194f35-b924-55b9-84f2-e8619af2b12a', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6be985c3-83fd-5f89-a7a5-1f998885d5df', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9f76f750-9da6-5762-a06d-415d24f1edb4', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('08858d44-4b0a-5563-bfdc-ed4d0c6cfc1b', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('136aae00-5420-5185-814d-f7273dc25536', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer une charte de foyer."], ["Défi", "Tenir 3 revues mensuelles successives."], ["Outil lié", "Household Engine"], ["Preuve Skills Passport", "Charte financière du foyer."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S03, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('f24f9f36-e989-5250-b592-fd2b0b16ba84', 'ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'course', '10b90230-28b1-51e7-b92a-1a6b10ecf94b', 'QCM — COL-07', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
