INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('df3e23c1-0b11-5fc8-872d-70e5b7f992d8', 'ced82e6b-87d9-5ac4-a35b-0f8deb0c378e', 'Cas intégrateur corrigé — Finance collective & familiale', NULL, NULL, 8, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dee33f7c-cac0-536d-89ef-44f2ea39a82e', 'df3e23c1-0b11-5fc8-872d-70e5b7f992d8', 'text', 1, '{"html": "<h3>Scénario\\nUn couple dispose de 210 000 DA de revenus mensuels (130 000 et 80 000). Les dépenses communes sont de 120 000 DA. Ils veulent partager proportionnellement aux revenus, constituer une réserve commune de 15 000 DA/mois et financer un projet de 360 000 DA en 18 mois.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('53ae30d5-d35b-5848-912f-c06b4949eb13', 'df3e23c1-0b11-5fc8-872d-70e5b7f992d8', 'text', 2, '{"html": "<h2>Travail demandé</h2><p>1. Calculer la clé de partage proportionnelle.</p><p>2. Calculer la quote-part de chacun sur les 120 000 DA.</p><p>3. Ajouter la réserve commune et vérifier la capacité du foyer.</p><p>4. Calculer la contribution mensuelle nécessaire pour le projet.</p><p>5. Proposer une règle de gouvernance en cas de dépense exceptionnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('45aa77ec-f6e1-59e6-984a-3922df3d00af', 'df3e23c1-0b11-5fc8-872d-70e5b7f992d8', 'text', 3, '{"html": "<h2>Corrigé-type</h2><p>Part revenus : 130/210 ≈ 61,9 %, 80/210 ≈ 38,1 %. Dépenses communes : environ 74 286 DA et 45 714 DA. Projet : 360 000/18 = 20 000 DA/mois. Avec réserve 15 000 + projet 20 000, effort commun additionnel 35 000 DA. Une règle de gouvernance peut imposer accord des deux au-delà d’un seuil et justification enregistrée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a745421c-1934-539e-bc8c-785896a36ca9', 'df3e23c1-0b11-5fc8-872d-70e5b7f992d8', 'table', 4, '{"headers": ["Critère", "Poids"], "rows": [["Exactitude technique / calculs", "35 %"], ["Interprétation et décision", "25 %"], ["Gestion du risque / conformité", "20 %"], ["Traçabilité et sources", "10 %"], ["Clarté de l’explication", "10 %"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('24a1f6b5-1796-5b37-affe-0c0b7eb1def8', 'df3e23c1-0b11-5fc8-872d-70e5b7f992d8', 'text', 5, '{"html": "<h3>Validation du cas intégrateur\\nSeuil : 75 %. Une erreur critique de sécurité, conformité, fraude, règle réglementaire active ou confusion réel/fictif doit être corrigée avant validation, même si le score global atteint 75 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('222eb4b1-9a02-5348-b68d-b917a008e63d', 'academy-investissement-marchs', 'FINCLUDIA Academy — Investissement & marchés', 'Épargne, investissement, risque, horizon, diversification, Bourse d’Alger, instruments, IOB, portefeuille fictif et biais.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Investissement & marchés', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'intermediate', '["INV-01 — Épargne ou investissement ?", "INV-02 — Objectif, horizon, liquidité et tolérance à la perte", "INV-03 — Risque, rendement, inflation et rendement réel", "INV-04 — Intérêts simples et composés", "INV-05 — Classes d’actifs et sources de rendement", "INV-06 — Diversification et concentration", "INV-07 — Comprendre la Bourse d’Alger et ses acteurs", "INV-08 — Actions, obligations, OPC et financement de l’économie", "INV-09 — Ordres de bourse et rôle de l’IOB", "INV-10 — Construire un portefeuille fictif", "INV-11 — Frais, fiscalité et performance nette", "INV-12 — Biais, FOMO et discipline de décision"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '["EPG", "ETU", "SAL"]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('388e2677-3ec5-53cb-a2c2-220882f2fae7', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'INV-01 — Épargne ou investissement ?', 'Distinguer sécurité, disponibilité, horizon et recherche de rendement.', NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c7c9de9b-a4ae-53fa-864f-6564b643bb31', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Étudiants, salariés, familles, épargnants, entrepreneurs"], ["Niveau", "N1"], ["Objectif measurable", "Distinguer sécurité, disponibilité, horizon et recherche de rendement."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('38256eac-c188-557a-aa7a-d612b3e8ab64', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Épargne", "ressources non consommées mises de côté.", "[S01] [S32]"], ["Investissement", "engagement de ressources dans l’espoir d’un avantage futur avec incertitude et risque.", "[S01] [S41]"], ["Liquidité", "Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur.", "[S14], [S32]"], ["Rendement", "Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon.", "[S01], [S41]"], ["Horizon d’investissement", "Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné.", "[S02], [S41]"], ["Besoin", "Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('64020274-b359-5ded-b29d-a64c768725a6', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Distinguer sécurité, disponibilité, horizon et recherche de rendement. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('739946b4-3a34-5f9a-96fc-70ad12c0299e', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Épargne — ressources non consommées mises de côté. [S01] [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Investissement — engagement de ressources dans l’espoir d’un avantage futur avec incertitude et risque. [S01] [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Liquidité — Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur. [S14], [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Rendement — Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon. [S01], [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Horizon d’investissement — Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné. [S02], [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Besoin — Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer. [S01], [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c19ae96c-0010-558b-9c01-1ac9cc9e4382', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Épargne de sécurité avant prise de risque non nécessaire. Le risque lié à « Épargne de sécurité avant prise de risque non nécessaire » doit être décrit par sa cause, sa probabilité, son impact et les mesures de réduction possibles. FINCLUDIA ne cherche pas à supprimer toute incertitude, mais à rendre le risque visible et documenté.</p><p>Repère de calcul. Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>2. L’investissement dépend de l’objectif et de l’horizon. L’horizon est la durée pendant laquelle l’argent peut rester mobilisé avant d’être nécessaire. Il détermine la capacité à accepter fluctuation, immobilisation ou durée de financement.</p><p>3. Rendement potentiel n’est jamais garanti. Pour rendement potentiel n’est jamais garanti, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ac209da-d0a6-5c6f-8fea-b11620898768', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir l’objectif et l’horizon.</p><p>Étape 2. Vérifier le besoin de liquidité.</p><p>Étape 3. Identifier les sources de rendement et de risque.</p><p>Étape 4. Comparer scénarios, frais et pertes possibles.</p><p>Étape 5. Décider uniquement dans le cadre fictif/pédagogique lorsque FINCLUDIA n’exécute pas l’investissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('720b9005-6930-5640-8992-a862c67dc794', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('60f11962-8eb7-5d9f-b783-6a50825d2ad8', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Épargne ou investissement ? », relevez les données disponibles, identifiez au moins quatre notions parmi Épargne, Investissement, Liquidité, Rendement, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b578e9d9-00c4-59e0-8314-9763a30135d5', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une salariée a un projet de frais universitaires dans 6 mois et un objectif retraite à 20 ans : les contraintes de liquidité ne sont pas les mêmes.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fac7b23f-e99c-5664-82fe-9f804a4db594', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Classer cinq objectifs selon horizon et besoin de liquidité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7a977b63-1b60-502d-bd0c-70f264b53cdd', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Justifier chaque classement ; aucune classe d’actif n’est automatiquement recommandée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0a34e350-0f49-5f2f-8983-85c0ff56675c', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bc40ae39-7d66-5f02-a685-6b86b6b23fed', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1c08d93d-4426-5bc3-be65-9466511c99fe', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e12aab8c-c5ee-52db-b5df-49a5cd0f11e1', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6cb4c30d-ee20-570d-9dd4-6a914298fdc3', '388e2677-3ec5-53cb-a2c2-220882f2fae7', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer la carte de mes objectifs"], ["Défi", "Séparer court terme et long terme"], ["Outil lié", "Goal Planner"], ["Preuve Skills Passport", "Carte objectifs"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S02, S41"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
