INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('836d6c3c-8704-540b-8038-67a127e30406', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'INV-02 — Objectif, horizon, liquidité et tolérance à la perte', 'Définir les contraintes avant de sélectionner un placement.', NULL, 2, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c802afc3-62f9-5baf-a6a0-122b22745874', '836d6c3c-8704-540b-8038-67a127e30406', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Épargnants et investisseurs débutants"], ["Niveau", "N2"], ["Objectif measurable", "Définir les contraintes avant de sélectionner un placement."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('46955f10-3bae-5e49-ab76-03802c5d016e', '836d6c3c-8704-540b-8038-67a127e30406', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Liquidité financière", "possibilité de convertir rapidement un actif avec coût/perte limités.", "[S01] [S41]"], ["Risque financier", "possibilité d’un résultat défavorable par rapport à l’attendu.", "[S02] [S32]"], ["Tolérance à la perte", "Capacité financière et psychologique à supporter une baisse de valeur sans compromettre un objectif ou une dépense essentielle.", "[S02], [S41]"], ["Liquidité", "Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur.", "[S14], [S32]"], ["Horizon d’investissement", "Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné.", "[S02], [S41]"], ["Besoin", "Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('74b5b430-4112-5c62-ae50-01592a795aa1', '836d6c3c-8704-540b-8038-67a127e30406', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Définir les contraintes avant de sélectionner un placement. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('68b69f52-aebf-5408-a038-bdcd90c1f66a', '836d6c3c-8704-540b-8038-67a127e30406', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Liquidité financière — possibilité de convertir rapidement un actif avec coût/perte limités. [S01] [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Risque financier — possibilité d’un résultat défavorable par rapport à l’attendu. [S02] [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Tolérance à la perte — Capacité financière et psychologique à supporter une baisse de valeur sans compromettre un objectif ou une dépense essentielle. [S02], [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Liquidité — Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur. [S14], [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Horizon d’investissement — Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné. [S02], [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Besoin — Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer. [S01], [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('521eada5-8436-57eb-9055-f2c289b0377a', '836d6c3c-8704-540b-8038-67a127e30406', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Liquidité financière. La liquidité décrit la facilité avec laquelle une ressource peut être mobilisée rapidement sans forte perte de valeur. Un actif peut avoir de la valeur tout en étant peu utile pour régler une échéance immédiate.</p><p>2. Risque financier. Le risque lié à « Risque financier » doit être décrit par sa cause, sa probabilité, son impact et les mesures de réduction possibles. FINCLUDIA ne cherche pas à supprimer toute incertitude, mais à rendre le risque visible et documenté.</p><p>3. Tolérance à la perte. Pour tolérance à la perte, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>4. Liquidité. La liquidité décrit la facilité avec laquelle une ressource peut être mobilisée rapidement sans forte perte de valeur. Un actif peut avoir de la valeur tout en étant peu utile pour régler une échéance immédiate.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1167d2e9-3a31-5778-becd-63149f064107', '836d6c3c-8704-540b-8038-67a127e30406', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir l’objectif et l’horizon.</p><p>Étape 2. Vérifier le besoin de liquidité.</p><p>Étape 3. Identifier les sources de rendement et de risque.</p><p>Étape 4. Comparer scénarios, frais et pertes possibles.</p><p>Étape 5. Décider uniquement dans le cadre fictif/pédagogique lorsque FINCLUDIA n’exécute pas l’investissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('981a1c09-b441-5008-8333-358f579e9ed3', '836d6c3c-8704-540b-8038-67a127e30406', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Objectif, horizon, liquidité et tolérance à la perte », relevez les données disponibles, identifiez au moins quatre notions parmi Liquidité financière, Risque financier, Tolérance à la perte, Liquidité, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('723b3ef6-29e7-524f-9928-1a02e09d6adc', '836d6c3c-8704-540b-8038-67a127e30406', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Objectif logement dans 18 mois : une forte volatilité peut être incompatible avec la date si le capital doit être disponible.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2ede454e-32a5-581e-adce-d4d3a511b435', '836d6c3c-8704-540b-8038-67a127e30406', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Écrire une fiche objectif avec montant, horizon, liquidité et perte maximale supportable fictive.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9c5917eb-d3c8-56e9-b9cd-f49e45159d68', '836d6c3c-8704-540b-8038-67a127e30406', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>La fiche doit expliciter les contraintes avant toute comparaison de produit.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5d25e7c4-5315-51a4-8a79-85bb84831e01', '836d6c3c-8704-540b-8038-67a127e30406', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b08f8ba5-b34a-590c-ace8-bc37a55cf148', '836d6c3c-8704-540b-8038-67a127e30406', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b6830edc-75ce-5095-8a85-619ccf8e5ec2', '836d6c3c-8704-540b-8038-67a127e30406', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('64657c39-8c84-5c3e-a7d2-b1bddca54ae3', '836d6c3c-8704-540b-8038-67a127e30406', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ae357ddc-a140-554d-82b1-1ea6455fa258', '836d6c3c-8704-540b-8038-67a127e30406', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer mon profil d’objectif"], ["Défi", "Refuser une simulation sans horizon"], ["Outil lié", "Investor Readiness"], ["Preuve Skills Passport", "Fiche objectif"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S41"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
