INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('7e873759-4d40-5c4c-aa4b-482c8f7fed0c', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'INV-03 — Risque, rendement, inflation et rendement réel', 'Comprendre qu’un rendement nominal ne suffit pas à mesurer le pouvoir d’achat.', NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cee97297-a7f0-5afb-9d9e-b5a9c001d0bb', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Épargnants, salariés, familles"], ["Niveau", "N2"], ["Objectif measurable", "Comprendre qu’un rendement nominal ne suffit pas à mesurer le pouvoir d’achat."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('75370fed-c3d0-504c-a05b-a1f21013aec1', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Rendement", "variation/revenu d’un placement sur une période.", "[S01] [S41]"], ["Inflation", "hausse générale et durable des prix, suivie notamment via l’IPC.", "[S43]"], ["Écart budgétaire", "Différence entre une valeur réelle et une valeur budgétée ; son analyse vise à expliquer la cause avant de décider d’une action.", "[S30], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('466279c0-03b1-5b9b-ba75-0a482de887d4', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre qu’un rendement nominal ne suffit pas à mesurer le pouvoir d’achat. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('abc7d670-ee01-5938-a0fb-eedfa859fae0', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Rendement — variation/revenu d’un placement sur une période. [S01] [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Inflation — hausse générale et durable des prix, suivie notamment via l’IPC. [S43]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Écart budgétaire — Différence entre une valeur réelle et une valeur budgétée ; son analyse vise à expliquer la cause avant de décider d’une action. [S30], [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2042e56f-6994-5cee-a3a8-9f155237b63c', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Rendement potentiel et risque doivent être affichés ensemble. Le risque lié à « Rendement potentiel et risque doivent être affichés ensemble » doit être décrit par sa cause, sa probabilité, son impact et les mesures de réduction possibles. FINCLUDIA ne cherche pas à supprimer toute incertitude, mais à rendre le risque visible et documenté.</p><p>2. Comparer nominal et réel. Pour comparer nominal et réel, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>3. Les données d’inflation sont datées, pas figées dans les vidéos. L’inflation est une hausse générale et durable du niveau des prix. Son effet concret dépend de la structure de consommation de chaque ménage et de l’évolution de ses revenus.</p><p>Repère de calcul. Rendement réel exact = (1 + rendement nominal) ÷ (1 + inflation) − 1.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2247d723-619b-51d9-8912-714fb7761bec', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir l’objectif et l’horizon.</p><p>Étape 2. Vérifier le besoin de liquidité.</p><p>Étape 3. Identifier les sources de rendement et de risque.</p><p>Étape 4. Comparer scénarios, frais et pertes possibles.</p><p>Étape 5. Décider uniquement dans le cadre fictif/pédagogique lorsque FINCLUDIA n’exécute pas l’investissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dfdb0770-e467-566b-a4f1-271196537b93', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Rendement réel exact = (1 + rendement nominal) ÷ (1 + inflation) − 1.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('502dd3f5-3af5-5cff-abff-1ea649ee8cdf', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Risque, rendement, inflation et rendement réel », relevez les données disponibles, identifiez au moins quatre notions parmi Rendement, Inflation, Écart budgétaire, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('46ffc8a9-1350-57d2-bd78-0dea10360fb2', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 9, '{"html": "<h2>Approfondissement intégré — Rendement, risque, liquidité et horizon</h2><ul><li><strong>Publics</strong> : Salariés, familles, investisseurs débutants</li><li><strong>Compétences renforcées</strong> : comprendre le couple rendement-risque; définir un horizon; distinguer volatilité et perte définitive</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Rendement</strong> : Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon. — [S01], [S41]</li><li><strong>Risque financier</strong> : Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. — [S02], [S22]</li><li><strong>Liquidité</strong> : Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur. — [S14], [S32]</li><li><strong>Horizon d’investissement</strong> : Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné. — [S02], [S41]</li><li><strong>Tolérance à la perte</strong> : Capacité financière et psychologique à supporter une baisse de valeur sans compromettre un objectif ou une dépense essentielle. — [S02], [S41]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('32c7c72d-915d-513e-8c9d-1e0b3d37f9fb', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 10, '{"html": "<h3>Quatre dimensions</h3><p>Rendement : gain ou perte. Risque : incertitude des résultats. Liquidité : facilité à transformer un actif en cash sans forte décote. Horizon : durée pendant laquelle l''argent peut rester investi.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3aadb52c-e7fb-5161-9cc2-db86075885cb', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 11, '{"html": "<h3>Pas de meilleur placement universel</h3><p>Un produit liquide et prudent peut être adapté à un fonds d''urgence, tandis qu''un objectif de 15 ans peut accepter davantage de fluctuations. Le choix dépend de l''objectif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('81e954df-ee17-5774-ad99-fe296b5277ef', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>L''argent destiné au loyer du mois prochain n''a pas le même horizon que l''épargne retraite. Les deux ne devraient pas être gérés de la même manière.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fd8e45b4-8c70-5da5-9d92-84a708008b5b', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Classez cinq objectifs selon horizon et besoin de liquidité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aa56cf76-a4da-5e3e-ba9b-048b015ff847', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : classer chaque objectif par date d’utilisation et besoin de disponibilité. Dépense dans quelques semaines : liquidité très élevée ; projet à 2-3 ans : horizon court/moyen ; retraite à 15 ans : horizon long. Le risque acceptable dépend aussi de la tolérance à la perte.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1f632e2c-ec48-5e54-8006-c96c1175e1c1', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a0fe0367-c011-5ee9-a730-0b9e52e67013', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Plus de rendement potentiel signifie généralement :</strong><br>A. Moins d''incertitude garantie<br>B. Un risque à analyser<br>C. Aucun risque<br>D. Plus de liquidité toujours<br><em>B. Le rendement ne se juge pas sans risque.</em></li><li><strong>2. Le fonds d''urgence nécessite surtout :</strong><br>A. Liquidité<br>B. Volatilité élevée<br>C. Blocage long obligatoire<br>D. Effet de levier<br><em>A. Il doit rester accessible.</em></li><li><strong>3. Le meilleur placement est :</strong><br>A. Le même pour tous<br>B. Celui adapté à l''objectif et au risque<br>C. Toujours une action<br>D. Toujours l''or<br><em>B. Il n''existe pas de classement universel.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1e835843-1c3b-5484-9ad4-badc2404fd8e', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Placement hypothétique +6 %, inflation hypothétique +4 % : l’écart simple est proche de 2 points, mais le calcul exact dépend des conventions.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c8d4a302-df1d-5f1b-9749-0dafa53197e2', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Calculer une valeur réelle simplifiée pour trois scénarios.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ef4df0e-d0f5-5533-ae3b-41db1a7e7e96', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>Montrer hypothèses et ne pas appeler le résultat « prévision ».</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bba47748-070d-5fe2-addd-520d390f6c21', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c0d02aa7-5477-56da-b083-0991e903a94b', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('320d99a1-94f4-51ec-b575-1118b191a1e2', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5e65579a-b371-516e-aaed-57ed39efe8a4', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('92eb8506-ddb4-5307-b659-014459a9c2f2', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Tester trois scénarios rendement/inflation"], ["Défi", "Identifier le scénario qui protège le mieux le pouvoir d’achat sans nier le risque"], ["Outil lié", "Simulateur inflation"], ["Preuve Skills Passport", "Tableau scénarios"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32, S41, S43"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('b3a668c3-3495-521c-854d-80ad8394d77f', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'course', '7e873759-4d40-5c4c-aa4b-482c8f7fed0c', 'QCM — INV-03', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
