INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('d430dfbb-0e73-5b45-a41c-3279c7bab3e7', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'INV-04 — Intérêts simples et composés', 'Comprendre l’effet du temps, du taux et des versements réguliers.', NULL, 4, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('33c8b041-1f06-52b2-a218-f03cfc58b43d', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Étudiants, salariés, épargnants"], ["Niveau", "N2"], ["Objectif measurable", "Comprendre l’effet du temps, du taux et des versements réguliers."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('28caeed8-8861-53c8-b207-040958cb2667', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Intérêt compose", "mécanisme où les gains ajoutés au capital peuvent eux-mêmes produire des gains futurs selon la convention retenue.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8613d90f-8d35-52ab-895f-6093f77da5eb', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre l’effet du temps, du taux et des versements réguliers. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b495cdc3-c123-5cfb-b9da-9cd3ac03f854', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Intérêt composé — mécanisme où les gains ajoutés au capital peuvent eux-mêmes produire des gains futurs selon la convention retenue. [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('df45006d-5405-58e4-a7a7-4164d4ff85a0', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Capital initial, versements, durée, taux hypothétique. Pour capital initial, versements, durée, taux hypothétique, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>2. Différence entre croissance linéaire et capitalisation. Ce point demande de comparer des notions proches sans les confondre. Pour « Différence entre croissance linéaire et capitalisation », l''utilisateur doit identifier le critère qui change — nature du flux, horizon, risque, propriétaire, date ou base de calcul — puis appliquer ce critère à un exemple réel ou fictif.</p><p>Repère de calcul. Capitalisation composée : valeur future = capital initial × (1 + taux)^nombre de périodes, lorsque cette hypothèse est pertinente.</p><p>3. Un taux simulé n’est pas une promesse. Pour un taux simulé n’est pas une promesse, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0a864348-261a-5548-a011-5bf827031fa7', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir l’objectif et l’horizon.</p><p>Étape 2. Vérifier le besoin de liquidité.</p><p>Étape 3. Identifier les sources de rendement et de risque.</p><p>Étape 4. Comparer scénarios, frais et pertes possibles.</p><p>Étape 5. Décider uniquement dans le cadre fictif/pédagogique lorsque FINCLUDIA n’exécute pas l’investissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0a61fed3-8fc0-5b9c-844f-96e92519da5e', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Capitalisation composée : valeur future = capital initial × (1 + taux)^nombre de périodes, lorsque cette hypothèse est pertinente.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5bcc2c87-40ed-505f-8d79-0b2ad14b994e', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Intérêts simples et composés », relevez les données disponibles, identifiez au moins quatre notions parmi Intérêt composé, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('08ce90c4-0029-5355-ad1f-4735d46a08be', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : 100 000 DA à 5 % hypothétiques pendant deux ans : la deuxième année peut s’appliquer sur le capital augmenté si la capitalisation est annuelle.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7abbdfa1-f706-51d5-9f6a-deccebed3287', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Comparer intérêt simple et composé sur 3 ans avec un taux fictif de 5 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ea340a4a-8447-5f5d-aac3-6de876f75a23', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Afficher formule, période et résultat ; étiqueter le taux comme hypothèse.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d851df4c-a248-5cf6-bea6-7bc5a84ed4c1', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2f3fb0b5-86c6-5596-a012-8e73391b7f20', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('be5cb823-89c8-5b82-9173-7dd37871f02b', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ae92b691-f409-5aad-8b00-788ddef7cb06', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a4e1166f-cc39-50c8-a8da-fe0af2bd00d9', 'd430dfbb-0e73-5b45-a41c-3279c7bab3e7', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Utiliser le simulateur de capitalisation"], ["Défi", "Expliquer l’effet du temps en 3 phrases"], ["Outil lié", "Simulateur intérêts composés"], ["Preuve Skills Passport", "Simulation enregistrée"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
