INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('b229701b-ada0-5a50-812e-87bc73efe1fe', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'INV-06 — Diversification et concentration', 'Mesurer la concentration et comprendre les limites de la diversification.', NULL, 6, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d90dffa3-999c-507d-b2f4-0ab4c6ffb05d', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Épargnants, investisseurs débutants"], ["Niveau", "N2"], ["Objectif measurable", "Mesurer la concentration et comprendre les limites de la diversification."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8e598d4a-cff3-58d2-b48c-6a20fb2ea2e3', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Diversification", "répartition des expositions pour réduire la dépendance à une source de risque.", "[S01] [S41]"], ["Concentration", "part importante du portefeuille exposée à un seul actif, émetteur ou risque.", "[S32]"], ["Portefeuille fictive", "Ensemble d’actifs simulés utilisé à des fins pédagogiques sans exécution réelle ni modification du patrimoine de l’utilisateur.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cdfdf302-ca99-5a5e-a0d6-195dd7bc39af', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Mesurer la concentration et comprendre les limites de la diversification. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a73728dd-2d85-5516-8b2a-eee7f84212fb', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Diversification — répartition des expositions pour réduire la dépendance à une source de risque. [S01] [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Concentration — part importante du portefeuille exposée à un seul actif, émetteur ou risque. [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Portefeuille fictif — Ensemble d’actifs simulés utilisé à des fins pédagogiques sans exécution réelle ni modification du patrimoine de l’utilisateur. [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('762e7dbd-648f-55f0-8a8a-8bc2290c8e1f', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Diversifier ≠ garantir. Pour diversifier ≠ garantir, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>2. Regarder poids du plus gros actif, secteurs et facteurs communs. Pour regarder poids du plus gros actif, secteurs et facteurs communs, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>3. Un portefeuille de plusieurs actifs peut rester concentré si les risques sont similaires. Le risque lié à « Un portefeuille de plusieurs actifs peut rester concentré si les risques sont similaires » doit être décrit par sa cause, sa probabilité, son impact et les mesures de réduction possibles. FINCLUDIA ne cherche pas à supprimer toute incertitude, mais à rendre le risque visible et documenté.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f4c128ff-480f-5b1d-aba6-cf67a2937829', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir l’objectif et l’horizon.</p><p>Étape 2. Vérifier le besoin de liquidité.</p><p>Étape 3. Identifier les sources de rendement et de risque.</p><p>Étape 4. Comparer scénarios, frais et pertes possibles.</p><p>Étape 5. Décider uniquement dans le cadre fictif/pédagogique lorsque FINCLUDIA n’exécute pas l’investissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a0c3c671-4710-53d5-823b-2f035b74daaa', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Diversification et concentration », relevez les données disponibles, identifiez au moins quatre notions parmi Diversification, Concentration, Portefeuille fictif, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('66c23d3b-2ff4-558a-93b0-ff114d1d31be', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Portefeuille fictif 1 000 000 DA dont 700 000 DA sur un seul actif : concentration principale = 70 %.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b33a799f-183d-50f1-a710-6ec3b63435f8', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Calculer la concentration de trois portefeuilles fictifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('40d24dd7-2396-5566-a2a3-2d368c87991c', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Concentration = valeur exposition principale / valeur portefeuille, selon périmètre explicite.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('61ee7066-71b0-56bb-99cf-702b1d093cc0', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dae9d28f-fa35-5053-a1f5-f5ec8f43db72', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('35e27559-5853-5473-8f9e-bcd11ac71b7f', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('906c1447-950f-57d9-a747-d760ab330d26', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e1967ed2-2edb-599b-abcf-816a2c9aa95f', 'b229701b-ada0-5a50-812e-87bc73efe1fe', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Réduire une concentration fictive"], ["Défi", "Passer sous un seuil choisi par l’apprenant et justifier"], ["Outil lié", "Portfolio Lab"], ["Preuve Skills Passport", "Avant/après"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32, S41"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
