INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ce96507-f423-5eaa-9c5b-71d9305d5eb1', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Étudiants, épargnants, entrepreneurs, dirigeants"], ["Niveau", "N2-N3"], ["Objectif measurable", "Identifier COSOB, SGBV, IOB, dépositaire et principaux compartiments."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('25279642-fe75-533e-a5dd-0ab131478f95', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Bourse d’Alger", "marché organisé opéré par la SGBV sous contrôle de la COSOB.", "[S38] [S40] [S46]"], ["IOB", "intermédiaire agréé pour la négociation et autres activités autorisées.", "[S39]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01], [S32]"], ["Ordre de bourse", "Instruction transmise à un intermédiaire habilité pour acheter ou vendre un instrument financier selon des conditions définies.", "[S39], [S40]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a4303077-5470-5733-a0b6-93673cff619b', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Identifier COSOB, SGBV, IOB, dépositaire et principaux compartiments. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('83ebbf06-c76f-575b-9923-79fcb47955fe', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Bourse d’Alger — marché organisé opéré par la SGBV sous contrôle de la COSOB. [S38] [S40] [S46]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>IOB — intermédiaire agréé pour la négociation et autres activités autorisées. [S39]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01], [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Ordre de bourse — Instruction transmise à un intermédiaire habilité pour acheter ou vendre un instrument financier selon des conditions définies. [S39], [S40]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dc24ca1b-e43e-5800-9f1f-1f7fe52d7c04', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. COSOB : régulation, protection de l’épargne investie et transparence. Pour cosob : régulation, protection de l’épargne investie et transparence, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>Repère de calcul. Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>2. SGBV : organisation des négociations et cotation. Pour sgbv : organisation des négociations et cotation, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>3. IOB : accès professionnel à la négociation ; FINCLUDIA ne transmet pas d’ordres dans ce parcours. Pour iob : accès professionnel à la négociation ; fincludia ne transmet pas d’ordres dans ce parcours, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ddeefa54-d29d-5024-8211-6eb7fa5e0070', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir l’objectif et l’horizon.</p><p>Étape 2. Vérifier le besoin de liquidité.</p><p>Étape 3. Identifier les sources de rendement et de risque.</p><p>Étape 4. Comparer scénarios, frais et pertes possibles.</p><p>Étape 5. Décider uniquement dans le cadre fictif/pédagogique lorsque FINCLUDIA n’exécute pas l’investissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bde84644-25b0-5087-bbd4-5cb75e2578fe', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('96645e6d-5acb-599b-80ba-eb29db98555a', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Comprendre la Bourse d’Alger et ses acteurs », relevez les données disponibles, identifiez au moins quatre notions parmi Bourse d’Alger, IOB, Épargne, Ordre de bourse, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2eae3baf-04bf-5841-bd84-9a0aba1d66c2', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 9, '{"html": "<h2>Approfondissement intégré — Bourse d''Alger : comprendre un marché local</h2><ul><li><strong>Publics</strong> : Étudiants, épargnants, entrepreneurs</li><li><strong>Compétences renforcées</strong> : identifier une société cotée; lire un cours et une séance; comprendre liquidité et profondeur</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Bourse d’Alger</strong> : Marché organisé des valeurs mobilières opéré par la SGBV sous le contrôle de la COSOB, avec des compartiments de titres de capital et de titres de créance. — [S38], [S40], [S46]</li><li><strong>Marché financier</strong> : Ensemble organisé de mécanismes, acteurs et infrastructures permettant l’émission, la négociation, la conservation et le règlement de titres financiers. — [S38], [S40]</li><li><strong>IOB</strong> : Intermédiaire en Opérations de Bourse : personne morale agréée par la COSOB pour exercer une ou plusieurs activités autorisées, dont la négociation de valeurs mobilières et, selon agrément, le conseil ou la gestion. — [S39]</li><li><strong>Liquidité</strong> : Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur. — [S14], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ddab133-3073-5e49-96e4-422faa7b75ae', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 10, '{"html": "<h3>Marché actuel</h3><p>Au 22 septembre 2026, la SGBV affiche sept titres de capital sur le marché officiel : Alliance Assurances, El Aurassi, Saidal, Biopharm, CPA, BDL et Ayrade. Le marché PME comporte notamment AOM Invest, Moustachir et CRAPC Expertise.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('15efb906-0df7-5282-bbd7-eaac1b9d8093', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 11, '{"html": "<h3>Liquidité</h3><p>Un marché peu profond peut connaître des séances avec peu ou pas de transactions sur certains titres. La liquidité doit donc faire partie de l''éducation financière au même titre que le rendement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c9bfaa61-4548-548f-b024-e59da6a2d2e5', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Un titre peut afficher un cours mais enregistrer peu de transactions. L''investisseur doit comprendre qu''un prix affiché ne garantit pas qu''il pourra acheter ou vendre immédiatement la quantité souhaitée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d3bc3008-d8f1-5e84-a540-758b553152fe', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Choisissez un titre coté sur le site SGBV et notez : secteur, valeur nominale, dernier cours, volume de la séance et nombre de transactions.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('989e3b8a-21fe-5085-b031-ca824c01eebe', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : utiliser une page SGBV datée et relever les cinq champs demandés. La réponse n’est valide que si la source/date sont conservées ; un cours affiché avec faible volume doit être interprété avec prudence en raison de la liquidité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f3ba4f26-e946-5abe-9db2-ca9a36a8281d', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4234c3cd-cd41-566f-a4b7-e7f005a6fd99', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. La liquidité d''une action désigne :</strong><br>A. La facilité d''achat/vente sans forte décote<br>B. Son dividende garanti<br>C. Son impôt<br>D. Son capital social<br><em>A. Elle mesure la facilité de transaction.</em></li><li><strong>2. Un cours affiché garantit-il une transaction immédiate ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Seulement pour une banque<br><em>B. Il faut qu''une contrepartie existe.</em></li><li><strong>3. Le marché officiel SGBV compte actuellement sept titres de capital ?</strong><br>A. Oui au 22 septembre 2026<br>B. Non, 100<br>C. Aucun<br>D. Toujours 7 pour toujours<br><em>A. C''est l''état consulté à cette date et il peut évoluer.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8d96c31d-e14b-5b1b-ab43-fd823c02d793', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un utilisateur veut acheter une valeur cotée : FINCLUDIA explique le marché et l’oriente vers un IOB agréé pour l’exécution réelle.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('585aaebd-4f1a-57ba-9246-011a10885356', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Associer cinq fonctions à COSOB, SGBV, IOB ou dépositaire central.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3016251e-9c7e-56c4-ae1e-568b4adaa11e', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>Aucune fonction d’exécution réelle ne doit être attribuée à FINCLUDIA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5dc8e8a2-8dc9-5ec0-8afe-a695ef13ed3a', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5a58320a-7f1f-5f17-aafd-fa03268f08f2', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1fefac96-ccc9-5f70-8143-ee7880e881f3', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('349d5577-30aa-5948-af71-2b1ea86bd9cb', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4699c30f-7049-563b-9796-f6ef9106e932', '9b63323a-bd7e-52e1-b910-2193e21b54bf', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Cartographier le parcours d’un ordre fictif"], ["Défi", "Aucune confusion régulateur/intermédiaire"], ["Outil lié", "Market Map"], ["Preuve Skills Passport", "Schéma validé"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S38, S39, S40, S46"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
