INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('80a72cb6-4fc2-5d1d-b78d-bde21b05bd4a', 'c064c0e2-c354-570f-9fab-7a416bb3559e', 1, 'Choisir une réponse sans calcul ni justification, puis modifier les données pour obtenir le résultat souhaité.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('94fb7888-4442-598f-bedc-310713b80bd9', 'c064c0e2-c354-570f-9fab-7a416bb3559e', 2, 'Confondre une hypothèse pédagogique avec une règle réglementaire applicable à tous.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('b6def01a-9d47-52b1-ba6d-759a7052bd1d', 'c064c0e2-c354-570f-9fab-7a416bb3559e', 3, 'Supprimer les données qui ne confirment pas la première intuition.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('4c8187ad-8ed3-534c-a0a4-f16ba9cb93ac', 'c064c0e2-c354-570f-9fab-7a416bb3559e', 4, 'Aucune fonction d’exécution réelle ne doit être attribuée à FINCLUDIA.', 1);
INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('ee712abf-c63c-5b64-8fd3-bd15e63a22ca', '848d2481-a32c-5f19-908f-68ff65e7cd2a', 'single', 4, 'Lorsqu’une donnée réglementaire, bancaire, fiscale ou de marché est utilisée, quel réflexe FINCLUDIA est correct ?', 'FINCLUDIA versionne les règles évolutives et sépare toujours simulation, information et décision.', 1, '[]');
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('fa5d9c41-96ab-50fb-a8fc-e87419f0b93e', 'ee712abf-c63c-5b64-8fd3-bd15e63a22ca', 1, 'Vérifier la source, la date d’effet, le périmètre et le statut de fraîcheur avant de conclure.', 1);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('fa880c82-09c7-5189-9ab9-a3a3230832e1', 'ee712abf-c63c-5b64-8fd3-bd15e63a22ca', 2, 'Conserver indéfiniment la première valeur trouvée, même si la règle change.', 0);
