INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('077be1a2-e783-54f3-a4c2-cd7298620fb9', '848d2481-a32c-5f19-908f-68ff65e7cd2a', 'single', 5, 'Quelle preuve doit permettre au site de confirmer l’application de la compétence ?', 'La progression repose sur une preuve d’application, pas seulement sur la consultation du contenu.', 1, '[]');
