INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('71fa48ef-2678-5cf9-9871-fd7a305b6ebb', '077be1a2-e783-54f3-a4c2-cd7298620fb9', 2, 'Schéma validé', 1);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('de7e54ff-22c3-589b-b7fa-b4e7fb1ba447', '077be1a2-e783-54f3-a4c2-cd7298620fb9', 3, 'Le temps passé sur l’écran, sans action de l’utilisateur.', 0);
