INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('c1b99aaa-c609-540f-9b61-4bebeac0c790', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'INV-08 — Actions, obligations, OPC et financement de l’économie', 'Comparer la nature économique des principaux instruments sans recommandation personnalisée.', NULL, 8, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2d4044cb-2b41-5aec-b60f-d946616cb39c', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Épargnants, étudiants, dirigeants"], ["Niveau", "N3"], ["Objectif measurable", "Comparer la nature économique des principaux instruments sans recommandation personnalisée."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b09f2ab3-f0c4-5d24-ae9d-96384483a9ee', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Action", "titre de capital.", "[S38] [S41]"], ["Obligation", "titre de créance.", "[S38] [S41]"], ["OPCVM", "véhicule de placement collectif régi par le cadre applicable.", "[S38] [S41]"], ["Concentration", "Exposition excessive à un nombre limité d’actifs, d’émetteurs, de secteurs, de clients ou de risques.", "[S38], [S41]"], ["Liquidité", "Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur.", "[S14], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7de4a631-7fbf-5d35-b0f3-ededb9670b8f', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comparer la nature économique des principaux instruments sans recommandation personnalisée. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d603ae0a-2a8c-58a2-8ee7-2d7e993c1c0f', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Action — titre de capital. [S38] [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Obligation — titre de créance. [S38] [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>OPCVM — véhicule de placement collectif régi par le cadre applicable. [S38] [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Concentration — Exposition excessive à un nombre limité d’actifs, d’émetteurs, de secteurs, de clients ou de risques. [S38], [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Liquidité — Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur. [S14], [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('07cdc076-f1c1-5d81-8478-5ead43e41072', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Actionnaire vs créancier. L’actionnaire détient une part du capital et supporte le risque résiduel de l’entreprise ; le créancier détient une créance avec des droits contractuels de remboursement. Leurs flux, priorité et risque ne sont pas identiques.</p><p>2. Flux possibles : dividende, coupon, remboursement, variation de prix. Pour « Flux possibles : dividende, coupon, remboursement, variation de prix », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>Repère de calcul. Performance totale simple = (valeur finale − valeur initiale + revenus encaissés) ÷ valeur initiale.</p><p>3. Risque de crédit, marché, liquidité et concentration. La concentration mesure la dépendance à un petit nombre d’actifs, clients, fournisseurs ou sources de revenu. Plus cette dépendance est forte, plus un choc ciblé peut affecter l’ensemble.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1baebb63-de89-5329-9d0e-e4e0e7ccb60a', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir l’objectif et l’horizon.</p><p>Étape 2. Vérifier le besoin de liquidité.</p><p>Étape 3. Identifier les sources de rendement et de risque.</p><p>Étape 4. Comparer scénarios, frais et pertes possibles.</p><p>Étape 5. Décider uniquement dans le cadre fictif/pédagogique lorsque FINCLUDIA n’exécute pas l’investissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9932bc8b-964d-5cd4-bd2b-54e1337c2700', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Performance totale simple = (valeur finale − valeur initiale + revenus encaissés) ÷ valeur initiale.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aa17c1ef-799d-5b2a-9239-412e11377148', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Actions, obligations, OPC et financement de l’économie », relevez les données disponibles, identifiez au moins quatre notions parmi Action, Obligation, OPCVM, Concentration, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dbeda375-2d5f-53f4-b793-0a4bf1dc6f24', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 9, '{"html": "<h2>Approfondissement intégré — Actions et dividendes</h2><ul><li><strong>Publics</strong> : Investisseurs débutants, étudiants</li><li><strong>Compétences renforcées</strong> : comprendre une action; distinguer cours et valeur économique; comprendre dividende</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Action</strong> : Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre. — [S38], [S41]</li><li><strong>Dividende</strong> : Distribution décidée par une société au profit des détenteurs de titres éligibles ; elle peut varier, être différée ou ne pas être versée. — [S47]</li><li><strong>Rendement</strong> : Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon. — [S01], [S41]</li><li><strong>Marché financier</strong> : Ensemble organisé de mécanismes, acteurs et infrastructures permettant l’émission, la négociation, la conservation et le règlement de titres financiers. — [S38], [S40]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('78248a30-2e30-5547-9801-13bc6ca9de4a', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 10, '{"html": "<h3>Action</h3><p>Une action représente une participation au capital d''une société selon les droits attachés au titre. Son prix de marché peut varier en fonction des attentes, résultats, liquidité et conditions de marché.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a591a79f-08a6-517f-94ec-20c9c1267fbe', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 11, '{"html": "<h3>Dividende</h3><p>Un dividende est une distribution décidée selon les règles de la société. Il n''est ni automatique ni garanti et peut varier ou être supprimé.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dfcce7de-dfe0-57ab-b16a-82ba8ef63e71', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Une action achetée 1 000 DA peut valoir 900 ou 1 100 DA plus tard. Un dividende éventuel doit être ajouté à la performance totale, mais il ne protège pas contre une baisse du cours.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d658874c-1485-5e90-9cee-4441e3fa47e8', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Calculez la performance totale d''une action fictive : prix initial, prix final et dividende.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eaaf2e52-ea7c-5343-8db1-acbc59ee1052', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : performance totale = (prix final - prix initial + dividende encaissé) / prix initial x 100, avant frais et fiscalité. Un dividende ne compense pas automatiquement une baisse du cours.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('024b2796-c443-5ab3-8186-b5b999ad1012', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('84caf96a-77c2-59bc-a527-294c83deceda', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Une action est :</strong><br>A. Une participation au capital<br>B. Un compte courant<br>C. Une taxe<br>D. Une mensualité<br><em>A. Elle représente une part du capital.</em></li><li><strong>2. Un dividende est garanti ?</strong><br>A. Oui<br>B. Non<br>C. Toujours pour les banques<br>D. Seulement chaque mois<br><em>B. Il dépend des décisions et résultats.</em></li><li><strong>3. Le cours de Bourse peut :</strong><br>A. Seulement monter<br>B. Monter ou baisser<br>C. Rester obligatoire<br>D. Égaler toujours la valeur nominale<br><em>B. Il fluctue.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e6580fc8-b62e-5f5b-b039-acf8ffcae3d0', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 17, '{"html": "<h2>Approfondissement intégré — Obligations et sukuk</h2><ul><li><strong>Publics</strong> : Investisseurs, entreprises, étudiants</li><li><strong>Compétences renforcées</strong> : comprendre dette obligataire; comprendre coupon et échéance; distinguer sukuk et obligation conventionnelle</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Obligation</strong> : Titre de créance par lequel l’investisseur prête des fonds à un émetteur selon des conditions de rémunération et de remboursement prévues. — [S38], [S41]</li><li><strong>Sukuk</strong> : Instrument de finance islamique structuré autour d’actifs, droits ou flux selon la structure retenue ; il ne doit pas être réduit à une simple obligation conventionnelle renommée. — [S47]</li><li><strong>Taux d’intérêt</strong> : Prix du temps et du crédit exprimé en pourcentage selon une convention et une période ; son interprétation exige de préciser base, durée, frais et capitalisation. — [S34], [S32]</li><li><strong>Risque financier</strong> : Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. — [S02], [S22]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7c856646-ff4c-5f6a-ae4f-df457b2a9e14', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 18, '{"html": "<h3>Obligation</h3><p>Une obligation est un titre de dette : l''investisseur prête selon les conditions de l''émission et reçoit des flux prévus, sous réserve du risque de l''émetteur et des modalités contractuelles.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7cf3b6a6-912c-5d7a-97f4-c82efa738c7a', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 19, '{"html": "<h3>Risque de taux et crédit</h3><p>La valeur de marché d''une obligation peut varier quand les taux évoluent. Il existe aussi un risque de défaut de l''émetteur.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('32e56ecc-fd51-5e39-9bcc-8f5a463b483b', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 20, '{"html": "<h3>Sukuk</h3><p>Les sukuk sont des instruments de finance islamique structurés autour d''actifs, droits ou flux selon la structure juridique et charaïque retenue ; ils ne doivent pas être présentés comme de simples obligations renommées.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5ce79f18-22b8-57aa-8527-0653682c4328', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'callout', 21, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Une obligation à 5 ans n''a pas le même risque qu''un dépôt liquide. FINCLUDIA doit montrer échéance, flux, risque émetteur et sensibilité aux taux.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2ed3e05a-cdb9-5097-b507-6fec4ef18538', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 22, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Comparez une action, une obligation et un sukuk fictifs selon risque, revenu attendu, horizon et liquidité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('441dd3de-ee11-51a8-b538-c420d60639f4', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 23, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : action = participation au capital, rendement variable et pas d’échéance fixe ; obligation = créance avec flux/échéance contractuels et risque de taux/crédit ; sukuk = instrument islamique structuré selon actifs/droits/flux. Comparer risque, revenu, horizon, liquidité et structure juridique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9e791b4e-b9a8-5f7a-879d-f58377074278', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 24, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ca13f763-7165-563b-abe8-bdd2d8028044', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 25, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Une obligation représente généralement :</strong><br>A. Une dette de l''émetteur<br>B. Un salaire<br>C. Une taxe<br>D. Un stock<br><em>A. Le détenteur est créancier selon les termes du titre.</em></li><li><strong>2. Le prix d''une obligation peut varier avant échéance ?</strong><br>A. Oui<br>B. Non<br>C. Jamais<br>D. Seulement en Algérie<br><em>A. Les taux et le risque influencent le prix.</em></li><li><strong>3. Un sukuk doit être compris selon :</strong><br>A. Sa structure spécifique<br>B. Uniquement son nom<br>C. Toujours comme une action<br>D. Aucune règle<br><em>A. La structure contractuelle est essentielle.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('83924e8b-abc3-567d-9a5a-4b8314555629', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 26, '{"html": "<p>Traçabilité : contenu intégré depuis [S47] et relié aux définitions maîtres. Les valeurs réglementaires actives restent versionnées dans le Centre de confiance.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c13e809c-4a87-5669-b65f-8d07f3402d29', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 27, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Deux instruments fictifs financent la même entreprise : l’action donne une exposition au capital ; l’obligation représente une créance selon ses termes.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c5a162b8-becb-5fd3-8d1e-d5a00c69e559', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 28, '{"html": "<h2>Exercice d’application</h2><p>Compléter un tableau propriétaire/créancier, flux, échéance, risque pour action et obligation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('128861a9-1a7b-5827-afea-22881ad52cf3', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 29, '{"html": "<h2>Corrigé-type</h2><p>L’élève doit distinguer droits économiques et promesses contractuelles.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3357e10b-af36-5cbc-a59a-998420fe171b', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'table', 30, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b11f431c-288d-5997-9cba-71b6943c7f06', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 31, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2b1cef6f-79e5-5222-b7ec-950c53cc567a', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 32, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d2dd64b0-af50-5e69-a90b-988866345775', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'text', 33, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e260f5da-387a-54fd-80c5-6c26e6167b9e', 'c1b99aaa-c609-540f-9b61-4bebeac0c790', 'table', 34, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Comparer trois instruments fictifs"], ["Défi", "Zéro confusion action/obligation"], ["Outil lié", "Instrument Lab"], ["Preuve Skills Passport", "Tableau comparatif"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S38, S41"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
