INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('dc2f8f00-f8ef-5164-8348-40465e1d9f47', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'INV-09 — Ordres de bourse et rôle de l’IOB', 'Comprendre le chemin d’un ordre et les paramètres essentiels sans exécuter de transaction.', NULL, 9, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3e8ff1b5-4008-5b89-a416-09be533ee047', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Investisseurs débutants"], ["Niveau", "N3"], ["Objectif measurable", "Comprendre le chemin d’un ordre et les paramètres essentiels sans exécuter de transaction."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8c610cd3-9e02-51d8-a6d5-3011aa7e6de9', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["IOB", "personne morale agréée par la COSOB pour des activités autorisées dont la négociation.", "[S39]"], ["Ordre de bourse", "instruction de négociation comportant notamment sens, titre, quantité et conditions de prix/durée selon règles du marché.", "[S39] [S40]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('484070f0-1bf8-59dc-8603-6c1d0c0865c6', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre le chemin d’un ordre et les paramètres essentiels sans exécuter de transaction. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('032b6bde-7592-5194-a0a2-9b6800d17b89', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>IOB — personne morale agréée par la COSOB pour des activités autorisées dont la négociation. [S39]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Ordre de bourse — instruction de négociation comportant notamment sens, titre, quantité et conditions de prix/durée selon règles du marché. [S39] [S40]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f61e53ff-30aa-54ba-9304-f03c9b6bcc5a', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Compte-titres et conservation. Pour compte-titres et conservation, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>2. Ordre au marché/limité selon cadre et disponibilité. Un ordre au marché privilégie l’exécution disponible sans garantir un prix précis ; un ordre limité fixe une condition de prix mais peut rester non exécuté. FINCLUDIA enseigne la mécanique sans transmettre d’ordres réels.</p><p>3. Exécution dépend du marché ; un ordre n’est pas une garantie de prix ou d’exécution. Pour « Exécution dépend du marché ; un ordre n’est pas une garantie de prix ou d’exécution », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cfde8dfc-2c35-5f8d-a90b-cd267917bd18', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir l’objectif et l’horizon.</p><p>Étape 2. Vérifier le besoin de liquidité.</p><p>Étape 3. Identifier les sources de rendement et de risque.</p><p>Étape 4. Comparer scénarios, frais et pertes possibles.</p><p>Étape 5. Décider uniquement dans le cadre fictif/pédagogique lorsque FINCLUDIA n’exécute pas l’investissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('37a1d11d-0b21-5f20-b40d-53f2d7377775', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Ordres de bourse et rôle de l’IOB », relevez les données disponibles, identifiez au moins quatre notions parmi IOB, Ordre de bourse, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f02af442-deb4-50d7-a11e-6300ea0a9c7c', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un ordre fictif à cours limité ne s’exécute pas si aucune contrepartie compatible n’est disponible.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('91292c22-c0fa-5181-8ee2-448fa7a2e014', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Lire cinq ordres fictifs et identifier paramètres manquants.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('509bb819-458e-58ed-b59f-68ca79a3d8e3', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Chaque ordre doit préciser les éléments requis dans le cas pédagogique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('16f489d0-9b73-5681-9d42-0b4b778d8992', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9438956a-d0b1-58cb-b201-a5bc73d62a3a', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3ff7019d-ab82-525c-91b0-9102488ca2e7', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cf105917-6b67-5f54-abb6-a9e8c322bbd4', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b7f5b8b1-c0fd-5a97-be98-8104f9c4a56e', 'dc2f8f00-f8ef-5164-8348-40465e1d9f47', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Simuler le cycle d’un ordre"], ["Défi", "Identifier une situation de non-exécution"], ["Outil lié", "Order Simulator"], ["Preuve Skills Passport", "Journal d’ordre fictif"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S39, S40"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
