INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('85b13149-febd-56f6-858c-b8f6ff83967a', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'INV-10 — Construire un portefeuille fictif', 'Appliquer objectif, horizon, diversification et scénarios sans argent réel.', NULL, 10, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4ff0f1c1-ea04-5b49-af14-331c4ae54dd1', '85b13149-febd-56f6-858c-b8f6ff83967a', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Épargnants, étudiants, salariés"], ["Niveau", "N2-N3"], ["Objectif measurable", "Appliquer objectif, horizon, diversification et scénarios sans argent réel."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7f23a62f-6cdd-5ee7-bba5-285b667510bd', '85b13149-febd-56f6-858c-b8f6ff83967a', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Portefeuille fictive", "allocation pédagogique sans lien avec le patrimoine réel.", "[S32]"], ["Diversification", "répartition des expositions.", "[S41]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c7ecf337-06c7-5186-8e10-a5ddc34335d8', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Appliquer objectif, horizon, diversification et scénarios sans argent réel. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6d0c85ee-51c4-5939-87b8-1767730a8365', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Portefeuille fictif — allocation pédagogique sans lien avec le patrimoine réel. [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Diversification — répartition des expositions. [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3c0aee78-ce46-555f-a14c-a8c423a87ca1', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Séparation stricte réel/fictif. Pour séparation stricte réel/fictif, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>2. Allocation par poches et poids. L’allocation répartit le portefeuille entre plusieurs poches selon l’objectif, l’horizon et le risque. Les poids doivent totaliser 100 % et être examinés avec les corrélations et concentrations réelles, pas seulement le nombre de lignes.</p><p>3. Scénarios prudent/central/favorable et baisse défavorable. « Scénarios prudent/central/favorable et baisse défavorable » se travaille par scénarios. L''utilisateur fixe une hypothèse de base, une hypothèse défavorable et, si utile, une hypothèse favorable ; il compare ensuite les effets sur le budget, le cash, la marge ou le risque.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8e3bec08-b509-5460-ae1d-0fc0d8d0365f', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir l’objectif et l’horizon.</p><p>Étape 2. Vérifier le besoin de liquidité.</p><p>Étape 3. Identifier les sources de rendement et de risque.</p><p>Étape 4. Comparer scénarios, frais et pertes possibles.</p><p>Étape 5. Décider uniquement dans le cadre fictif/pédagogique lorsque FINCLUDIA n’exécute pas l’investissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('165c29b6-ff18-5187-a50a-53155c698f3d', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Construire un portefeuille fictif », relevez les données disponibles, identifiez au moins quatre notions parmi Portefeuille fictif, Diversification, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d0d66d82-4bff-5643-bbce-a64688b38c4b', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 8, '{"html": "<h2>Approfondissement intégré — Portefeuille, diversification et allocation</h2><ul><li><strong>Publics</strong> : Investisseurs débutants à intermédiaires</li><li><strong>Compétences renforcées</strong> : comprendre diversification; construire une allocation; mesurer concentration</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Diversification</strong> : Répartition d’une exposition entre plusieurs actifs, émetteurs, secteurs ou catégories afin de réduire la dépendance à une seule source de risque ; elle ne supprime pas le risque de perte. — [S01], [S41]</li><li><strong>Concentration</strong> : Exposition excessive à un nombre limité d’actifs, d’émetteurs, de secteurs, de clients ou de risques. — [S38], [S41]</li><li><strong>Allocation</strong> : Répartition d’un budget ou d’un portefeuille entre plusieurs usages, actifs ou risques selon les objectifs, contraintes, horizon et besoin de liquidité. — [S47]</li><li><strong>Classe d’actifs</strong> : Catégorie d’investissements partageant des caractéristiques économiques et des profils de risque proches, par exemple actions ou obligations. — [S38], [S41]</li><li><strong>Portefeuille fictive</strong> : Ensemble d’actifs simulés utilisé à des fins pédagogiques sans exécution réelle ni modification du patrimoine de l’utilisateur. — [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('414496ef-06cd-5352-8e14-2723256eaebe', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 9, '{"html": "<h3>Diversification</h3><p>Diversifier consiste à ne pas dépendre d''un seul actif, secteur, devise ou risque. Elle ne supprime pas les pertes, mais peut réduire certains risques spécifiques.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a4064aff-db61-5932-8d8c-4f151703d769', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 10, '{"html": "<h3>Allocation</h3><p>L''allocation répartit le patrimoine entre différentes classes d''actifs selon objectif, horizon, liquidité et tolérance au risque.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a2b3154e-c333-59ee-a81d-9d34b96dff87', '85b13149-febd-56f6-858c-b8f6ff83967a', 'callout', 11, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Un portefeuille de 10 titres tous exposés au même secteur peut être moins diversifié qu''un portefeuille plus simple couvrant plusieurs risques distincts.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1a1806a0-678f-5231-8468-0f1adc3f696d', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 12, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Construisez une allocation fictive pour un objectif à 10 ans puis identifiez trois concentrations.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8a46f4be-be5c-5aa3-99f1-f245229601a3', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 13, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : construire des pondérations totalisant 100 %, puis mesurer au moins trois concentrations : par émetteur, secteur, classe d’actifs, devise ou zone géographique. Proposer une diversification cohérente avec l’objectif sans prétendre supprimer le risque.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('080fb30f-3cec-599d-93e2-a5edfaacae67', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 14, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d4a81b4e-9a63-5417-9bc1-2bf76d5bd8bf', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 15, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Diversification signifie :</strong><br>A. Multiplier les noms sans regarder les risques<br>B. Répartir entre risques différents<br>C. Éviter toute perte<br>D. Acheter uniquement à l''étranger<br><em>B. La diversification concerne les sources de risque.</em></li><li><strong>2. Une allocation dépend notamment de :</strong><br>A. L''horizon<br>B. La couleur du logo<br>C. Le jour de la semaine<br>D. Le nombre de banques uniquement<br><em>A. L''horizon est une variable clé.</em></li><li><strong>3. Diversification = garantie de profit ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Seulement avec obligations<br><em>B. Elle réduit certains risques sans garantir un rendement.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3352d289-832f-5ac2-b3a6-49924ee17809', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 16, '{"html": "<p>Traçabilité : contenu intégré depuis [S47] et relié aux définitions maîtres. Les valeurs réglementaires actives restent versionnées dans le Centre de confiance.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('84c5fb42-4f3d-5c7b-8ee0-188ecc1a25a6', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Portefeuille fictif de 100 000 DA réparti 40/30/30 ; une baisse d’un actif affecte le portefeuille selon son poids.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('128d394d-d72f-56d0-b5ce-31bda24564c0', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Construire un portefeuille fictif de quatre poches et tester -20 % sur la plus grande.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6191d4bf-b6e2-5118-89b8-642cf9e56c63', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>Calculer la nouvelle valeur et expliquer le rôle du poids.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('35ddb4dd-d609-5fb7-ab03-ec5b81ad8004', '85b13149-febd-56f6-858c-b8f6ff83967a', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('195b2f96-74ff-5c3e-81d2-1318c2bf8880', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('07396ee2-2fd1-5416-98cd-d1b94022a6eb', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4e6cec95-904a-51d6-968e-eb79b0cf1257', '85b13149-febd-56f6-858c-b8f6ff83967a', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('166d0feb-cbc6-5b47-bc1f-9d4b5fc958d3', '85b13149-febd-56f6-858c-b8f6ff83967a', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un portefeuille pédagogique"], ["Défi", "Passer un stress test"], ["Outil lié", "Portfolio Simulator"], ["Preuve Skills Passport", "Allocation + stress test"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32, S41"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
