INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('67c788fe-8be5-575f-aa43-0b19baf21e89', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'INV-11 — Frais, fiscalité et performance nette', 'Distinguer performance brute et nette de coûts, en versionnant la fiscalité.', NULL, 11, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('084e1e25-0869-59a7-beff-144e98f0baa7', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Épargnants, investisseurs débutants"], ["Niveau", "N3"], ["Objectif measurable", "Distinguer performance brute et nette de coûts, en versionnant la fiscalité."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('098fabe3-2a72-5f59-8922-764bb57d2cc1', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Rendement", "résultat sur une période avant ou après coûts selon convention.", "[S41]"], ["Frais", "commissions explicites ou autres coûts à intégrer dans le calcul net.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c0497f56-68e5-5153-b187-b7d6f991afac', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Distinguer performance brute et nette de coûts, en versionnant la fiscalité. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('337908a5-944f-5b52-8eec-156a71329e3f', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Rendement — résultat sur une période avant ou après coûts selon convention. [S41]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Frais — commissions explicites ou autres coûts à intégrer dans le calcul net. [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2b6adb88-4a60-5270-a1cc-7a272c98a181', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Comparer des produits sur le même périmètre. Pour comparer des produits sur le même périmètre, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>2. Afficher frais ponctuels et récurrents. Pour afficher frais ponctuels et récurrents, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>3. Fiscalité = capsule dynamique selon instrument, statut et date. Pour fiscalité = capsule dynamique selon instrument, statut et date, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7188c1fc-4ed4-5dbc-8014-46708f54189b', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir l’objectif et l’horizon.</p><p>Étape 2. Vérifier le besoin de liquidité.</p><p>Étape 3. Identifier les sources de rendement et de risque.</p><p>Étape 4. Comparer scénarios, frais et pertes possibles.</p><p>Étape 5. Décider uniquement dans le cadre fictif/pédagogique lorsque FINCLUDIA n’exécute pas l’investissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bdf60617-66f0-59dd-af3a-8bd10127f212', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Frais, fiscalité et performance nette », relevez les données disponibles, identifiez au moins quatre notions parmi Rendement, Frais, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5d57c920-af2e-5518-8939-0c0705b9503b', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un rendement brut fictif de 7 % avec 1 % de frais n’est pas équivalent à 7 % net ; la fiscalité éventuelle est traitée séparément.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c3a230cc-e815-5879-8405-f5c79bd96d80', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Comparer deux placements fictifs avec structures de frais différentes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bc53dc63-180c-5ed5-ba34-762742aadcbb', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Présenter rendement brut, coûts et résultat net pédagogique sur une même période.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('13d05de4-9e73-50e1-a5bc-43b8119de0e6', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fefbfb13-ef11-5546-bbfa-8ec8bbe6ac48', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c2538ced-89ef-5e07-bcf9-e5ef65af9f22', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('710790f3-1e8d-5d15-b547-aa2a26e23ef2', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8c263115-37cf-57d9-a04f-faf6ae01a0f6', '67c788fe-8be5-575f-aa43-0b19baf21e89', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Construire une fiche performance nette"], ["Défi", "Détecter un frais omis"], ["Outil lié", "Fee Analyzer"], ["Preuve Skills Passport", "Comparatif"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32, S41"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
