INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aa0ef0d7-9509-541c-986f-b8bedda8331c', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Tous épargnants/investisseurs"], ["Niveau", "N2"], ["Objectif measurable", "Reconnaître les biais qui peuvent dégrader une décision financière."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('892c088f-8abc-5174-af03-9e06dd24e917', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Biais de confirmation", "tendance à privilégier les informations compatibles avec une croyance existante.", "[S32]"], ["FOMO", "peur de manquer une opportunité pouvant pousser à une action précipitée.", "[S32]"], ["Envie", "Dépense souhaitée pour le confort, le plaisir ou la préférence, généralement plus facilement différable qu’un besoin.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6a1caed1-0580-5d5d-99ff-4d83b64f8387', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Reconnaître les biais qui peuvent dégrader une décision financière. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('388b5016-5315-58bc-9f4e-2560fd3b7e1c', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Biais de confirmation — tendance à privilégier les informations compatibles avec une croyance existante. [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>FOMO — peur de manquer une opportunité pouvant pousser à une action précipitée. [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p><p>Envie — Dépense souhaitée pour le confort, le plaisir ou la préférence, généralement plus facilement différable qu’un besoin. [S01], [S32]</p><p>Application dans ce module. L’utilisateur doit relier la notion à un objectif, un horizon, un besoin de liquidité et une capacité à supporter une perte ; aucun rendement hypothétique n’est traité comme garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7fad4439-3cc6-56de-81a3-cba073cdd810', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Séparer thèse, faits et émotion. Pour séparer thèse, faits et émotion, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>2. Journaliser la raison d’une décision avant le résultat. Pour journaliser la raison d’une décision avant le résultat, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p><p>3. Chercher volontairement une information contradictoire. Pour chercher volontairement une information contradictoire, FINCLUDIA relie systématiquement rendement potentiel, risque de perte, horizon, liquidité et frais. L''utilisateur doit être capable d''expliquer dans quel objectif cette notion devient pertinente et dans quel cas elle serait inadaptée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('92ee8ab8-a2cf-54a8-83e5-8a9dd51766dc', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Définir l’objectif et l’horizon.</p><p>Étape 2. Vérifier le besoin de liquidité.</p><p>Étape 3. Identifier les sources de rendement et de risque.</p><p>Étape 4. Comparer scénarios, frais et pertes possibles.</p><p>Étape 5. Décider uniquement dans le cadre fictif/pédagogique lorsque FINCLUDIA n’exécute pas l’investissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aad1a028-bff9-57ce-bdc4-6c2c4a8fe6b7', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Biais, FOMO et discipline de décision », relevez les données disponibles, identifiez au moins quatre notions parmi Biais de confirmation, FOMO, Envie, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5ba7d1e1-28ec-5502-956e-8516e5460a61', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 8, '{"html": "<h2>Approfondissement intégré — Psychologie de l''argent, biais et arnaques</h2><ul><li><strong>Publics</strong> : Tous publics</li><li><strong>Compétences renforcées</strong> : identifier biais comportementaux; résister à FOMO et surconfiance; repérer promesses irréalistes</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Biais comportemental</strong> : Tendance cognitive ou émotionnelle pouvant déformer l’analyse et la décision financière, par exemple surconfiance, ancrage, aversion aux pertes ou effet de foule. — [S47]</li><li><strong>FOMO</strong> : Biais comportemental lié à la peur de manquer une opportunité, pouvant conduire à décider sous pression sans analyse suffisante. — [S02], [S32]</li><li><strong>Phishing</strong> : Technique de fraude visant à obtenir des informations sensibles ou provoquer une action en imitant un acteur de confiance. — [S35], [S32]</li><li><strong>Risque financier</strong> : Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. — [S02], [S22]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3f9b6f67-ec0f-5d17-a547-6038e27ee195', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 9, '{"html": "<h3>Biais fréquents</h3><p>Biais de confirmation, aversion aux pertes, ancrage, surconfiance et effet de foule peuvent influencer les décisions financières.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3a5e8027-60f0-58b5-8de7-01d0b66136b7', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 10, '{"html": "<h3>Signaux d''alerte</h3><p>Promesse de rendement élevé sans risque, pression pour agir immédiatement, opacité sur le produit, refus d''expliquer les pertes possibles et demande de données sensibles sont des signaux de prudence.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3b0ccfbd-ff71-526f-8dc2-8d626a18655a', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'callout', 11, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Un investissement présenté comme « garanti, 5 % par semaine, offre valable aujourd''hui » cumule plusieurs drapeaux rouges : rendement extrême, urgence et promesse de sécurité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bc2659a4-2e02-5886-8cfc-89604d60af19', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 12, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Analysez trois publicités fictives et identifiez les biais ou signaux de risque.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('983da3c7-cf96-57a2-9f2e-a06b102594be', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 13, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : rechercher promesse de rendement élevé/garanti, urgence artificielle, opacité, pression sociale, demande d’informations sensibles, absence de scénario de perte. Identifier aussi les biais mobilisés : FOMO, surconfiance, ancrage, confirmation ou effet de foule.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7299a092-040b-5e3e-a712-ee5fd6662599', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 14, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8c511971-8882-5020-a4cb-24f598eac478', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 15, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. FOMO signifie notamment :</strong><br>A. Peur de manquer une opportunité<br>B. Une taxe<br>C. Une méthode comptable<br>D. Un prêt<br><em>A. Elle pousse à agir sans analyse.</em></li><li><strong>2. Rendement élevé garanti sans risque est :</strong><br>A. Un signal de prudence<br>B. Une preuve de sécurité<br>C. Toujours légal<br>D. Sans intérêt<br><em>A. Le risque doit être examiné.</em></li><li><strong>3. La surconfiance peut conduire à :</strong><br>A. Sous-estimer les risques<br>B. Toujours mieux épargner<br>C. Éliminer la volatilité<br>D. Réduire le CA<br><em>A. Elle fausse l''évaluation.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('014d4762-31cb-5031-9673-d834040b54c2', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 16, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une hausse rapide d’un actif fictif crée une envie d’achat immédiat : le protocole impose objectif, risque, source et délai de réflexion.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a7c457bb-bf3e-51aa-a5d1-37307cac437c', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 17, '{"html": "<h2>Exercice d’application</h2><p>Analyser quatre décisions fictives et identifier le biais dominant.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('60ab5efd-9beb-5384-9285-e1695d07e360', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 18, '{"html": "<h2>Corrigé-type</h2><p>La réponse doit relier comportement observé et biais sans diagnostic psychologique personnel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f7f70a87-dc89-5ece-aa84-ffd0761bcb74', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'table', 19, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5f3585d8-1376-5ee9-bbe2-d1ac53da008b', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 20, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('52a08a2a-3767-5483-8708-d17cfdbe8195', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 21, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d80b523d-c6e4-5240-9241-490b4f9444ac', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'text', 22, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e5b2ac4a-ecd4-56d7-b05f-ec3fac70a4f1', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'table', 23, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Tenir un journal de décision"], ["Défi", "Réécrire une décision impulsive en décision documentée"], ["Outil lié", "Decision Journal"], ["Preuve Skills Passport", "Journal fictif"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('0bb3a845-29a2-5268-a317-a22eba6c5b7f', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'course', 'c02cccaa-89b3-548d-8b42-16046e32dd6b', 'QCM — INV-12', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
