INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('401d2459-c20c-573a-8cd1-9fdee83207e9', 'a3e89c96-cf07-5cf7-975e-471918e2c5e4', 1, 'Prendre une décision uniquement à partir du solde du compte sans examiner le budget.', 0);
