INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('783f8d6b-8679-507a-86f3-09baf6c7b5b8', '0bb3a845-29a2-5268-a317-a22eba6c5b7f', 'single', 3, 'Dans le cas pratique du module, quelle démarche est la plus correcte ?', 'Le corrigé-type exige un raisonnement explicite, traçable et cohérent avec les données du cas.', 1, '[]');
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('e803afac-b988-557e-bb30-e7091dea5586', '783f8d6b-8679-507a-86f3-09baf6c7b5b8', 1, 'La réponse doit relier comportement observé et biais sans diagnostic psychologique personnel.', 1);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('0896ff70-d354-59af-beee-897ac320bab6', '783f8d6b-8679-507a-86f3-09baf6c7b5b8', 2, 'Choisir une réponse sans calcul ni justification, puis modifier les données pour obtenir le résultat souhaité.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('935dcd32-fc9b-57a4-8fa4-da0d159a9862', '783f8d6b-8679-507a-86f3-09baf6c7b5b8', 3, 'Confondre une hypothèse pédagogique avec une règle réglementaire applicable à tous.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('c41acc4e-d74a-5d15-a2d4-2f029b26e89a', '783f8d6b-8679-507a-86f3-09baf6c7b5b8', 4, 'Supprimer les données qui ne confirment pas la première intuition.', 0);
INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('a13e437b-5978-5576-95c0-5400d476eaf7', '0bb3a845-29a2-5268-a317-a22eba6c5b7f', 'single', 4, 'Lorsqu’une donnée réglementaire, bancaire, fiscale ou de marché est utilisée, quel réflexe FINCLUDIA est correct ?', 'FINCLUDIA versionne les règles évolutives et sépare toujours simulation, information et décision.', 1, '[]');
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('09ea9ff5-6771-5c23-b53b-8f70eb3a3adf', 'a13e437b-5978-5576-95c0-5400d476eaf7', 1, 'Conserver indéfiniment la première valeur trouvée, même si la règle change.', 0);
