INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('42f119c9-1832-58fe-985e-beb34bfaf582', '222eb4b1-9a02-5348-b68d-b917a008e63d', 'Cas intégrateur corrigé — Investissement & marchés', NULL, NULL, 13, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('18776fcb-745a-5356-9fd7-986a62b21bb5', '42f119c9-1832-58fe-985e-beb34bfaf582', 'text', 1, '{"html": "<h3>Scénario\\nLeila dispose fictivement de 600 000 DA qu’elle n’utilisera pas pendant 5 ans. Elle garde séparément son fonds d’urgence. Elle construit un portefeuille pédagogique : 300 000 DA en obligations fictives, 240 000 DA en actions fictives et 60 000 DA en liquidités. Un scénario fait baisser les actions de 25 % et les obligations de 5 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('43af30ee-ef28-5182-9f26-561fc88e4410', '42f119c9-1832-58fe-985e-beb34bfaf582', 'text', 2, '{"html": "<h2>Travail demandé</h2><p>1. Calculer les poids du portefeuille.</p><p>2. Calculer la valeur après le scénario adverse.</p><p>3. Mesurer la perte totale en DA et en %.</p><p>4. Expliquer le rôle de la diversification et ses limites.</p><p>5. Identifier les acteurs à consulter pour une exécution réelle en Bourse d’Alger.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d1f7b97a-a000-51a2-8694-a51008557d6b', '42f119c9-1832-58fe-985e-beb34bfaf582', 'text', 3, '{"html": "<h2>Corrigé-type</h2><p>Poids : obligations 50 %, actions 40 %, liquidités 10 %. Valeur après choc : obligations 285 000 ; actions 180 000 ; liquidités 60 000 = 525 000 DA. Perte = 75 000 DA, soit 12,5 %. La diversification réduit la concentration mais ne supprime pas le risque. Pour une opération réelle, l’utilisateur doit passer par les acteurs/intermédiaires habilités selon le cadre du marché ; FINCLUDIA reste pédagogique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fa9742bc-0152-51fc-b750-51ff2e455607', '42f119c9-1832-58fe-985e-beb34bfaf582', 'table', 4, '{"headers": ["Critère", "Poids"], "rows": [["Exactitude technique / calculs", "35 %"], ["Interprétation et décision", "25 %"], ["Gestion du risque / conformité", "20 %"], ["Traçabilité et sources", "10 %"], ["Clarté de l’explication", "10 %"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('34d6f361-cc33-57f2-a60a-be1c7945ff99', '42f119c9-1832-58fe-985e-beb34bfaf582', 'text', 5, '{"html": "<h3>Validation du cas intégrateur\\nSeuil : 75 %. Une erreur critique de sécurité, conformité, fraude, règle réglementaire active ou confusion réel/fictif doit être corrigée avant validation, même si le score global atteint 75 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'academy-professionnels-indpendants', 'FINCLUDIA Academy — Professionnels indépendants', 'Séparation perso/pro, facturation, coûts, marge, seuil, trésorerie, BFR, fiscalité, financement, profession libérale et auto-entrepreneur.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Professionnels indépendants', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'intermediate', '["PRO-01 — Séparer finances personnelles et professionnelles", "PRO-02 — Facturé, encaissé, à recevoir", "PRO-03 — Coûts, prix de revient et marge", "PRO-04 — Seuil de rentabilité et point mort", "PRO-05 — Piloter sa trésorerie", "PRO-06 — Gérer les créances clients et le DSO", "PRO-07 — Comprendre et piloter le BFR", "PRO-08 — Budget et prévision de l’activité", "PRO-09 — Fiscalité et obligations : savoir chercher la règle", "PRO-10 — Préparer un financement professionnel", "PRO-11 — Construire son Passeport financier", "LIB-01 — Économie d’une profession libérale"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '[]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'PRO-01 — Séparer finances personnelles et professionnelles', 'Créer une frontière claire entre l’argent de l’activité et l’argent personnel.', NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c24c1f3d-7078-5ac8-a674-5a2304a4e22d', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Libéraux, freelances, auto-entrepreneurs"], ["Niveau", "N2-N4"], ["Objectif measurable", "Créer une frontière claire entre l’argent de l’activité et l’argent personnel."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('53b3a510-799b-5d1c-9bcf-3de16ca12b50', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Cash-flow personnel", "Différence entre ressources encaissées et sorties d’argent sur une période, après prise en compte des engagements suivis.", "[S32]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Comptabilité financière", "Système d’organisation de l’information financière permettant de saisir, classer, évaluer et présenter des données donnant une image fidèle de la situation, de la performance et de la trésorerie.", "[S13]"], ["Provision", "Somme mise progressivement de côté pour une dépense future prévisible, même si elle n’est pas encore exigible.", "[S32]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b77a5e12-2a60-5fb6-8190-fcef2ab555ad', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Créer une frontière claire entre l’argent de l’activité et l’argent personnel. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f14b5d4e-e08e-598e-b25d-9e0670bd61cb', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Cash-flow personnel — Différence entre ressources encaissées et sorties d’argent sur une période, après prise en compte des engagements suivis. [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Comptabilité financière — Système d’organisation de l’information financière permettant de saisir, classer, évaluer et présenter des données donnant une image fidèle de la situation, de la performance et de la trésorerie. [S13]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Provision — Somme mise progressivement de côté pour une dépense future prévisible, même si elle n’est pas encore exigible. [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('045ad0f6-a72a-5b75-95a2-53afcd1d3d2f', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Compte et caisse de l’activité. Dans une activité indépendante, compte et caisse de l’activité doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>2. Prélèvements personnels identifiés. Dans une activité indépendante, prélèvements personnels identifiés doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>3. Dépenses professionnelles documentées. Pour « Dépenses professionnelles documentées », la compétence est documentaire : savoir quelle information doit être conservée, qui l''émet, à quelle date et à quelle opération elle se rattache. Une trace exploitable doit permettre de reconstituer la décision.</p><p>4. Provision fiscale/sociale séparée. Provisionner consiste à mettre de côté progressivement pour une dépense future prévisible. Une dépense annuelle de 120 000 DA peut ainsi être préparée par une provision de 10 000 DA par mois.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a34720b0-9954-5dfb-9c9e-eda7dad3a111', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Séparer finances personnelles et professionnelles.</p><p>Étape 2. Identifier le chiffre d’affaires, les coûts et les encaissements réels.</p><p>Étape 3. Prévoir les obligations et besoins de trésorerie.</p><p>Étape 4. Calculer marge, BFR ou seuil lorsque pertinent.</p><p>Étape 5. Conserver les pièces qui prouvent l’activité et les revenus.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6aa47fd2-2de9-5c73-baeb-ea56acc21f08', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Séparer finances personnelles et professionnelles », relevez les données disponibles, identifiez au moins quatre notions parmi Cash-flow personnel, Trésorerie, Comptabilité financière, Provision, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d7d9509a-484b-5757-a31c-bd55b0d5ceb7', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une consultante indépendante à Alger encaisse 250 000 DA. Elle ne considère pas tout comme argent disponible : une partie finance les charges, une partie est provisionnée et le reste peut devenir rémunération/prélèvement.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6b7a1b16-dc76-53a9-a657-3d073f996b9a', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Reclasser 12 opérations mixtes en personnel, professionnel ou à clarifier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('be975cbf-6bdd-5e35-8fb0-a44d370eff51', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Le classement doit s’appuyer sur la finalité économique et les justificatifs ; les cas ambigus sont à confirmer.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('51a3d745-0774-5ea4-ad8e-3da7f12f72e1', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('04d26a73-b3f4-5a64-a436-185f0b522034', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7d40fec1-c3a9-5492-9d5b-24145e29b400', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5f72fe45-6c65-55c2-a798-60b13a708a71', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('34762a0a-f64d-5fc3-8c2e-ffc80c045271', '6bdcbffa-0029-5e2d-813f-c51e94eb1e5f', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer deux univers de flux dans FINCLUDIA."], ["Défi", "30 jours sans mélange non identifié."], ["Outil lié", "Pro & Cash"], ["Preuve Skills Passport", "Journal perso/pro propre."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S13, S14, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
