INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('911219d6-2dd9-536a-a172-77de29ee0ad8', '70c3f299-6aa1-581e-bf1f-124a7a9f3b6c', 'single', 1, 'Quelle proposition définit le mieux « Cash-flow personnel » ?', 'La bonne réponse reprend la définition maître du concept « Cash-flow personnel ».', 1, '[]');
