INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('87cd0734-972a-5926-9eb6-cb90d9a770de', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'PRO-03 — Coûts, prix de revient et marge', 'Calculer le coût réel d’une prestation ou d’un produit et fixer un prix soutenable.', NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ca1fd130-359e-5a51-9666-89fd09c73e9b', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Libéraux, AE, microentreprises"], ["Niveau", "N2-N4"], ["Objectif measurable", "Calculer le coût réel d’une prestation ou d’un produit et fixer un prix soutenable."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0517b835-0084-5211-b998-50349f4df31b', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Prix de revient", "Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service.", "[S16] [S30]"], ["Charge fixe", "Charge qui ne varie pas directement avec le volume d’activité à court terme, par exemple certains loyers ou abonnements.", "[S16]"], ["Charge variable", "Charge qui évolue avec le volume d’activité, par exemple certains achats de marchandises ou matières.", "[S16]"], ["Marge sur coûts variables", "Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité.", "[S16]"], ["Dépense variable", "Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport.", "[S32]"], ["Facture", "Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables.", "[S04], [S05], [S32]"], ["Dépense fixe", "Dépense récurrente dont le montant varie peu à court terme, par exemple un loyer ou un abonnement.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('50b855d3-bd27-5c78-b144-95c6398d141b', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Calculer le coût réel d’une prestation ou d’un produit et fixer un prix soutenable. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('178142de-68fa-5759-b90a-821c07b0b429', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Prix de revient — Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service. [S16] [S30]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Charge fixe — Charge qui ne varie pas directement avec le volume d’activité à court terme, par exemple certains loyers ou abonnements. [S16]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Charge variable — Charge qui évolue avec le volume d’activité, par exemple certains achats de marchandises ou matières. [S16]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Marge sur coûts variables — Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité. [S16]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Dépense variable — Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport. [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Facture — Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables. [S04], [S05], [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Dépense fixe — Dépense récurrente dont le montant varie peu à court terme, par exemple un loyer ou un abonnement. [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('741bc74a-8f66-5925-9e32-1594a7fec47b', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Coûts directs et indirects. Pour « Coûts directs et indirects », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>2. Charges fixes et variables. Dans une activité indépendante, charges fixes et variables doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>3. Marge unitaire. La marge mesure ce qui reste après certains coûts, selon la convention choisie. Il faut toujours préciser de quelle marge on parle et quels coûts ont été déduits.</p><p>4. Marge sur coûts variables. La marge mesure ce qui reste après certains coûts, selon la convention choisie. Il faut toujours préciser de quelle marge on parle et quels coûts ont été déduits.</p><p>Repère de calcul. Marge sur coûts variables = chiffre d’affaires − charges variables.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b08f67cf-8bf0-5240-a455-604d0bdad473', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Séparer finances personnelles et professionnelles.</p><p>Étape 2. Identifier le chiffre d’affaires, les coûts et les encaissements réels.</p><p>Étape 3. Prévoir les obligations et besoins de trésorerie.</p><p>Étape 4. Calculer marge, BFR ou seuil lorsque pertinent.</p><p>Étape 5. Conserver les pièces qui prouvent l’activité et les revenus.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5f886c94-4ae6-5fea-b862-9d9d301642dc', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Marge sur coûts variables = chiffre d’affaires − charges variables.</p><p>Prix de revient = coûts directs + quote-part des coûts indirects affectés selon une méthode explicite.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a2a37d88-5c68-531d-a158-7144fff875e6', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Coûts, prix de revient et marge », relevez les données disponibles, identifiez au moins quatre notions parmi Prix de revient, Charge fixe, Charge variable, Marge sur coûts variables, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('46aaef93-f05d-58c9-af83-1b74fed85b31', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 9, '{"html": "<h2>Approfondissement intégré — Chiffre d''affaires, coûts, marge et résultat</h2><ul><li><strong>Publics</strong> : Auto-entrepreneurs, professionnels, entrepreneurs, PME/PMI</li><li><strong>Compétences renforcées</strong> : distinguer CA et bénéfice; calculer marge brute; identifier coûts directs et indirects</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Chiffre d’affaires</strong> : Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable. — [S04], [S05]</li><li><strong>Marge</strong> : Écart entre un revenu ou chiffre d’affaires et une catégorie de coûts définie. Une marge doit toujours préciser son périmètre : marge brute, marge sur coûts variables, marge nette, etc. — [S47]</li><li><strong>Prix de revient</strong> : Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service. — [S16], [S30]</li><li><strong>Résultat / benefice</strong> : Excédent des produits sur les charges sur une période ; pour les BNC, la DGI définit le bénéfice comme l’excédent des recettes sur les dépenses nécessaires à l’exercice. — [S06], [S13]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eb256223-75f3-5c80-a6b7-b9a8ce2b5cd7', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 10, '{"html": "<h3>CA n''est pas bénéfice</h3><p>Le chiffre d''affaires correspond aux ventes ou prestations facturées/encaissées selon l''indicateur suivi. Il ne mesure pas à lui seul ce que l''entreprise gagne. Il faut retrancher les coûts nécessaires à l''activité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0471b8a2-afc4-5c11-8659-d4113718b5fd', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 11, '{"html": "<h3>Marge</h3><p>Marge brute = ventes - coûts directement liés aux biens/services vendus. La marge permet d''absorber ensuite les frais généraux, les charges financières, les impôts et de dégager un résultat.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9b83cae0-4454-59e7-a66d-8eb6025f9ab8', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Un artisan vend pour 500 000 DA dans le mois. Ses matières et coûts directs représentent 300 000 DA. Marge brute : 200 000 DA, soit 40 % du CA avant les autres charges.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fe3cccce-370a-5a81-9c7c-20b7b84670cb', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Pour une activité fictive, calculez CA, coûts directs, marge brute et marge en pourcentage.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ffef5e9f-5bb0-5267-91f7-1b1b8a479ac2', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : CA = total des ventes/prestations du périmètre. Marge brute = CA - coûts directs. Taux de marge sur CA = marge brute / CA x 100. Le bénéfice final ne peut être déduit sans intégrer les autres charges.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e0baba22-a7ed-5ad3-be35-dacbbbb2aff8', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7bcf79fb-5e8e-5a70-84d8-43030596bccf', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Le CA est égal au bénéfice ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Pour une startup seulement<br><em>B. Les coûts doivent être déduits.</em></li><li><strong>2. Marge brute = :</strong><br>A. Ventes - coûts directs<br>B. Cash - banque<br>C. Dette - épargne<br>D. Actifs - passifs<br><em>A. C''est une mesure de rentabilité commerciale.</em></li><li><strong>3. Une marge positive garantit-elle un résultat net positif ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Seulement en industrie<br><em>B. Les autres charges peuvent absorber la marge.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('82f14054-38b8-5f9a-88e5-c59b80b721bb', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un photographe facture une mission 45 000 DA. Transport 4 000, location matériel 8 000 et sous-traitance 6 000 sont variables. Sa marge avant charges fixes est 27 000 DA.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('79c2efa7-858e-55c5-a063-d0fa8ebecb94', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Prix = 50 000 DA ; coûts variables = 20 000 DA. Calculer la marge sur coûts variables et son taux.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('963c98d5-26df-568e-be9d-2794b1ea842b', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>Marge = 30 000 DA ; taux = 60 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('24c7bf07-aa88-5f93-8c54-fd8c6e105bc8', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1b63e59b-0509-5990-b6de-83fdfe7e4204', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('31c3a80a-943d-58c2-99bc-8c998aecefd7', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f8c868c1-56c4-5793-a3ab-27fb470ee4a8', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8d8820f6-4b14-5b99-b341-40356e2d5cf9', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Calculer le coût de revient d’une vraie offre."], ["Défi", "Modifier trois hypothèses de coût et maintenir une marge cible."], ["Outil lié", "Prix & Marge"], ["Preuve Skills Passport", "Fiche coût/prix."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S16, S30"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('942ba83e-7a5e-58a4-b6ca-83b66a0e9b25', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'course', '87cd0734-972a-5926-9eb6-cb90d9a770de', 'QCM — PRO-03', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
