INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('8e817be2-b013-5907-9052-1130aaee08fc', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'PRO-04 — Seuil de rentabilité et point mort', 'Traduire les charges fixes en chiffre d’affaires minimal.', NULL, 4, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('607bf168-256d-5065-a586-f4e85bbccf56', '8e817be2-b013-5907-9052-1130aaee08fc', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Libéraux, AE, microentreprises"], ["Niveau", "N2-N4"], ["Objectif measurable", "Traduire les charges fixes en chiffre d’affaires minimal."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3cf05a9e-ca0d-5573-bfd6-a5784ea6f5e5', '8e817be2-b013-5907-9052-1130aaee08fc', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Seuil de rentabilité", "Niveau de chiffre d’affaires à partir duquel l’entreprise couvre ses charges fixes et variables sans perte ni bénéfice.", "[S16]"], ["Point mort", "Temps nécessaire pour atteindre le seuil de rentabilité au cours d’une période.", "[S16]"], ["Charge fixe", "Charge qui ne varie pas directement avec le volume d’activité à court terme, par exemple certains loyers ou abonnements.", "[S16]"], ["Marge sur coûts variables", "Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité.", "[S16]"], ["Dépense variable", "Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport.", "[S32]"], ["Dépense fixe", "Dépense récurrente dont le montant varie peu à court terme, par exemple un loyer ou un abonnement.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3f33f967-c939-5e5f-b23c-ec4b603947dc', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Traduire les charges fixes en chiffre d’affaires minimal. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eeb53de9-ef5c-596f-9995-a53aec5d52cc', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Seuil de rentabilité — Niveau de chiffre d’affaires à partir duquel l’entreprise couvre ses charges fixes et variables sans perte ni bénéfice. [S16]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Point mort — Temps nécessaire pour atteindre le seuil de rentabilité au cours d’une période. [S16]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Charge fixe — Charge qui ne varie pas directement avec le volume d’activité à court terme, par exemple certains loyers ou abonnements. [S16]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Marge sur coûts variables — Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité. [S16]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Dépense variable — Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport. [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Dépense fixe — Dépense récurrente dont le montant varie peu à court terme, par exemple un loyer ou un abonnement. [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3b373099-44d5-57a6-b156-f99f9bd577d3', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Calcul du seuil. Dans une activité indépendante, calcul du seuil doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>2. Conversion en ventes/heures/jours. Dans une activité indépendante, conversion en ventes/heures/jours doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>3. Marge de sécurité. La marge mesure ce qui reste après certains coûts, selon la convention choisie. Il faut toujours préciser de quelle marge on parle et quels coûts ont été déduits.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6e0077fe-2cb8-58c1-85bc-3e4470c48a31', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Séparer finances personnelles et professionnelles.</p><p>Étape 2. Identifier le chiffre d’affaires, les coûts et les encaissements réels.</p><p>Étape 3. Prévoir les obligations et besoins de trésorerie.</p><p>Étape 4. Calculer marge, BFR ou seuil lorsque pertinent.</p><p>Étape 5. Conserver les pièces qui prouvent l’activité et les revenus.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5c96865b-086a-5321-9b99-9fd350905d2c', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Seuil de rentabilité = charges fixes ÷ taux de marge sur coûts variables.</p><p>Marge sur coûts variables = chiffre d’affaires − charges variables.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('165b7cf9-2109-5caf-a162-dd67ecac2798', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Seuil de rentabilité et point mort », relevez les données disponibles, identifiez au moins quatre notions parmi Seuil de rentabilité, Point mort, Charge fixe, Marge sur coûts variables, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3a5f1c75-7085-5a00-aeef-f34e56b3244f', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 9, '{"html": "<h2>Approfondissement intégré — Prix de revient, marge et seuil de rentabilité</h2><ul><li><strong>Publics</strong> : Entrepreneurs, auto-entrepreneurs, dirigeants PME/PMI</li><li><strong>Compétences renforcées</strong> : calculer un coût de revient; distinguer coûts fixes et variables; calculer un seuil de rentabilité</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Charge fixe</strong> : Charge qui ne varie pas directement avec le volume d’activité à court terme, par exemple certains loyers ou abonnements. — [S16]</li><li><strong>Charge variable</strong> : Charge qui évolue avec le volume d’activité, par exemple certains achats de marchandises ou matières. — [S16]</li><li><strong>Marge sur coûts variables</strong> : Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité. — [S16]</li><li><strong>Seuil de rentabilité</strong> : Niveau de chiffre d’affaires à partir duquel l’entreprise couvre ses charges fixes et variables sans perte ni bénéfice. — [S16]</li><li><strong>Point mort</strong> : Temps nécessaire pour atteindre le seuil de rentabilité au cours d’une période. — [S16]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('939d083f-1cac-554e-a1b0-8bf3c33672ab', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 10, '{"html": "<h3>Coûts fixes et variables</h3><p>Les coûts fixes évoluent peu avec le volume à court terme : loyer, certains abonnements, une partie des salaires. Les coûts variables augmentent avec les unités vendues : matières, commissions ou transport par unité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('86b4a9a8-e3aa-5ed5-81a4-c6b9e1020d0c', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 11, '{"html": "<h3>Seuil de rentabilité</h3><p>Le seuil de rentabilité est le niveau d''activité à partir duquel la marge sur coûts variables couvre les coûts fixes. Forme simple en valeur : coûts fixes / taux de marge sur coûts variables.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d8227c5d-6e79-5497-aa06-dd8a49a790ef', '8e817be2-b013-5907-9052-1130aaee08fc', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Coûts fixes mensuels : 300 000 DA. Taux de marge sur coûts variables : 40 %. Seuil de rentabilité = 300 000 / 0,40 = 750 000 DA de CA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6ba624e8-2e4c-555d-84c5-03aef55e44cf', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Une activité a 420 000 DA de coûts fixes et un taux de marge sur coûts variables de 35 %. Calculez le seuil de rentabilité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aa766cee-6e26-5f1b-9f9c-b907a4d074d2', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : seuil de rentabilité = 420 000 / 0,35 = 1 200 000 DA de chiffre d’affaires. En dessous, la marge sur coûts variables ne couvre pas les coûts fixes ; au-dessus, elle commence à contribuer au résultat.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('89ecc752-361a-587e-9aa2-4c3756a7268a', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('70f2158f-4c7f-5f42-9e1f-6a7691aca959', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Le seuil de rentabilité indique :</strong><br>A. Le niveau où la marge couvre les coûts fixes<br>B. La valeur de l''entreprise<br>C. Le montant du capital social<br>D. Le cours de Bourse<br><em>A. C''est le point d''équilibre économique.</em></li><li><strong>2. 420 000 / 35 % vaut environ :</strong><br>A. 120 000<br>B. 1 200 000<br>C. 14 700<br>D. 4 200 000<br><em>B. 420 000 / 0,35 = 1 200 000.</em></li><li><strong>3. Une hausse du prix sans perte de volume peut :</strong><br>A. Réduire automatiquement la marge<br>B. Améliorer la marge unitaire<br>C. Supprimer les coûts fixes<br>D. Annuler le BFR<br><em>B. Le prix influence la contribution par unité.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d6d0780a-34b1-51c4-8c13-682a3cec5037', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un consultant a 1 200 000 DA de charges fixes annuelles et un taux de marge sur coûts variables de 80 %. Son seuil de rentabilité pédagogique est 1 500 000 DA de CA.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('17968985-1066-5fa5-b3f0-141d222c81e1', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Charges fixes 900 000 DA, taux de marge 60 %. Calculer le seuil.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bac2ab96-3290-5059-b1ee-063f040b46e1', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>900 000 / 0,60 = 1 500 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f9304da4-c6da-5f7e-b274-55d4374e75f9', '8e817be2-b013-5907-9052-1130aaee08fc', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ffb23824-016d-53e4-a53b-a428e189387c', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7ff5f02c-e403-5a91-b235-f3982f2a70f6', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('26febcd7-690d-56a0-95a5-d60371d3cd2c', '8e817be2-b013-5907-9052-1130aaee08fc', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5a02a95b-67f1-5ffa-ad67-71a4cabba560', '8e817be2-b013-5907-9052-1130aaee08fc', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Calculer son seuil annuel et mensuel."], ["Défi", "Traduire le seuil en nombre de missions ou produits."], ["Outil lié", "Seuil de rentabilité"], ["Preuve Skills Passport", "Seuil + point mort."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S16"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
