INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'PRO-05 — Piloter sa trésorerie', 'Prévoir les encaissements et décaissements afin d’éviter une rupture de cash.', NULL, 5, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e40a789c-7e61-5829-a4b5-31dfdbfc3c50', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Libéraux, AE, microentreprises"], ["Niveau", "N2-N4"], ["Objectif measurable", "Prévoir les encaissements et décaissements afin d’éviter une rupture de cash."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7e224cd4-0580-5edb-acb7-4c3a232ca486', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Encaissement", "Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés.", "[S14] [S32]"], ["Flux de trésorerie d’exploitation", "Flux de trésorerie issus principalement des activités génératrices de revenus et des activités qui ne sont ni d’investissement ni de financement.", "[S14]"], ["Décaissement", "Sortie effective de trésorerie ; il se distingue d’une charge comptable qui peut être constatée à une autre date.", "[S14], [S42]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('65d4cf81-615e-5d11-b680-59a21fbf2501', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Prévoir les encaissements et décaissements afin d’éviter une rupture de cash. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('11b34e7a-5dd1-539e-969c-838d674dac6f', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Encaissement — Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés. [S14] [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Flux de trésorerie d’exploitation — Flux de trésorerie issus principalement des activités génératrices de revenus et des activités qui ne sont ni d’investissement ni de financement. [S14]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Décaissement — Sortie effective de trésorerie ; il se distingue d’une charge comptable qui peut être constatée à une autre date. [S14], [S42]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1c54bf97-8eba-5ec4-bedc-90115557a950', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Solde initial. Dans une activité indépendante, solde initial doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>Repère de calcul. Solde budgétaire = revenus de la période − dépenses de la période.</p><p>2. Encaissements prévus. Une vente n’est pas un encaissement tant que l’argent n’est pas effectivement reçu. Cette distinction est fondamentale pour la trésorerie et le BFR.</p><p>3. Décaissements prévus. Dans une activité indépendante, décaissements prévus doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>4. Solde de fin. Dans une activité indépendante, solde de fin doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>Repère de calcul. Solde budgétaire = revenus de la période − dépenses de la période.</p><p>5. Scénarios de retard. « Scénarios de retard » se travaille par scénarios. L''utilisateur fixe une hypothèse de base, une hypothèse défavorable et, si utile, une hypothèse favorable ; il compare ensuite les effets sur le budget, le cash, la marge ou le risque.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d7b14a82-d970-58f4-ab34-a664ce050a67', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Séparer finances personnelles et professionnelles.</p><p>Étape 2. Identifier le chiffre d’affaires, les coûts et les encaissements réels.</p><p>Étape 3. Prévoir les obligations et besoins de trésorerie.</p><p>Étape 4. Calculer marge, BFR ou seuil lorsque pertinent.</p><p>Étape 5. Conserver les pièces qui prouvent l’activité et les revenus.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3a11a23d-36b7-5742-8120-f29325a57f38', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('255361ee-5c5a-5395-a7c2-6f28c5b035db', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Piloter sa trésorerie », relevez les données disponibles, identifiez au moins quatre notions parmi Trésorerie, Encaissement, Flux de trésorerie d’exploitation, Décaissement, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fa4ed61b-6b4d-5866-8503-8c563fd2b983', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une agence de communication possède 300 000 DA de cash, attend 500 000 DA d’encaissements et prévoit 620 000 DA de décaissements : solde final prévu 180 000 DA.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b1d09174-1c6c-55a3-a97e-0c088afdf96c', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Solde initial 150 000, encaissements 400 000, décaissements 470 000. Calculer le solde final.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('168fa916-ea8a-5ab5-a406-0c30cb4f174e', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>80 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ddd99c7d-de9d-5a8b-8aa0-f32971abb08a', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1bd2808e-e6b7-552a-b0dc-d8c8652c0b75', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f2abe77a-886d-5e90-9523-7c23651b51d6', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cdeb3183-9844-567d-83dc-be618c51b616', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a0f46645-1009-500f-945f-5865e71d8c20', '2db8a46b-7f3f-5f0b-a79e-1d2ffd6f4379', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Construire une prévision 13 semaines."], ["Défi", "Simuler un retard de 30 jours du plus gros client."], ["Outil lié", "Cash Forecast"], ["Preuve Skills Passport", "Prévision 13 semaines."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S14, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
