INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('3dc6a393-3337-5dee-8cfd-c4979b810055', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'PRO-06 — Gérer les créances clients et le DSO', 'Suivre les retards et réduire le cash immobilisé chez les clients.', NULL, 6, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6437e61a-ac0a-5b05-be9c-e5148b5a8253', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Libéraux, AE, microentreprises"], ["Niveau", "N2-N4"], ["Objectif measurable", "Suivre les retards et réduire le cash immobilisé chez les clients."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ddd0d4bc-ddd0-58e6-9d2b-3b6126d5c7dc', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Créance client", "Montant facturé à un client mais non encore encaissé.", "[S15] [S32]"], ["DSO", "Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période.", "[S30] [S32]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('888f207f-4401-5e0b-a027-860b30b60edb', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Suivre les retards et réduire le cash immobilisé chez les clients. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a89f2fe9-5e9c-5a17-bcb6-460aae3056ba', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Créance client — Montant facturé à un client mais non encore encaissé. [S15] [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>DSO — Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période. [S30] [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b47af9c0-2dfd-5840-b582-53eccfbdad1e', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Aging des créances. Dans une activité indépendante, aging des créances doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>2. Échéances. Dans une activité indépendante, échéances doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>3. Relances. Dans une activité indépendante, relances doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>4. DSO pédagogique. Dans une activité indépendante, dso pédagogique doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>Repère de calcul. DSO pédagogique ≈ créances clients ÷ chiffre d’affaires à crédit × nombre de jours de la période.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7062e905-b916-5028-84fe-5655e4786d77', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Séparer finances personnelles et professionnelles.</p><p>Étape 2. Identifier le chiffre d’affaires, les coûts et les encaissements réels.</p><p>Étape 3. Prévoir les obligations et besoins de trésorerie.</p><p>Étape 4. Calculer marge, BFR ou seuil lorsque pertinent.</p><p>Étape 5. Conserver les pièces qui prouvent l’activité et les revenus.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f6d1e17c-9439-5ece-969a-b6a2d7019de6', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>DSO pédagogique ≈ créances clients ÷ chiffre d’affaires à crédit × nombre de jours de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2f2b84ed-6939-5475-9b91-470e53bb89fc', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Gérer les créances clients et le DSO », relevez les données disponibles, identifiez au moins quatre notions parmi Créance client, DSO, Trésorerie, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('563ce516-4b18-548e-b839-fe57212c2c6e', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une petite agence a 900 000 DA de créances dont 400 000 DA dépassent l’échéance. FINCLUDIA sépare les montants 0-30, 31-60, 61-90 et &gt;90 jours.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d80f8bb1-0cb1-53e4-9cf3-4a460a4546ee', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Créances moyennes 600 000 DA, ventes à crédit annuelles 7 200 000 DA. Estimer DSO sur 365 jours.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8dac5cb3-17b5-5b5b-8508-acac8d3006fb', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>600 000 / 7 200 000 × 365 ≈ 30,4 jours.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e6018b5a-17a2-557b-8216-1e3e10123999', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('624712b7-4d28-5f28-9fe3-e7d6779d340a', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3a3ab7ab-869e-5f1f-bdaf-6cf210a8d736', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a1175f75-92f0-52f5-a690-1f7930a2058c', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c9a37c8f-2cc2-575e-b2d0-fe486bc8ddc3', '3dc6a393-3337-5dee-8cfd-c4979b810055', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Construire l’aging client."], ["Défi", "Réduire le DSO simulé de 10 jours et mesurer le cash libéré."], ["Outil lié", "Créances"], ["Preuve Skills Passport", "Aging + DSO."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S14, S15, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
