INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('109d2395-dfb6-5e7d-8322-8c5780663a42', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'PRO-07 — Comprendre et piloter le BFR', 'Mesurer l’argent immobilisé dans le cycle d’exploitation.', NULL, 7, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9abfb27d-8ff3-57ca-b213-eaa67d2b5934', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Libéraux, microentreprises, PME"], ["Niveau", "N2-N4"], ["Objectif measurable", "Mesurer l’argent immobilisé dans le cycle d’exploitation."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('72b3aa15-17c8-58ae-b07e-ac86d995d75b', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Besoin en fonds de roulement", "Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation.", "[S15]"], ["Créance client", "Montant facturé à un client mais non encore encaissé.", "[S15] [S32]"], ["Dette fournisseur", "Montant dû à un fournisseur au titre d’achats ou services reçus et non encore réglés.", "[S15]"], ["DIO", "Indicateur pédagogique du nombre moyen de jours pendant lesquels le stock reste immobilisé avant sa vente ou consommation.", "[S32]"], ["DSO", "Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période.", "[S30] [S32]"], ["DPO", "Indicateur pédagogique du délai moyen de règlement des fournisseurs, à rapprocher des achats à crédit.", "[S32]"], ["Stock", "Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés.", "[S13], [S42]"], ["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f6669b3c-c19c-5129-b443-4cfc7c53d86e', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Mesurer l’argent immobilisé dans le cycle d’exploitation. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6eff76e5-dae2-50f8-94f7-ead1d06933f0', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Besoin en fonds de roulement — Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation. [S15]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Créance client — Montant facturé à un client mais non encore encaissé. [S15] [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Dette fournisseur — Montant dû à un fournisseur au titre d’achats ou services reçus et non encore réglés. [S15]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>DIO — Indicateur pédagogique du nombre moyen de jours pendant lesquels le stock reste immobilisé avant sa vente ou consommation. [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>DSO — Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période. [S30] [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>DPO — Indicateur pédagogique du délai moyen de règlement des fournisseurs, à rapprocher des achats à crédit. [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Stock — Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés. [S13], [S42]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Dette — Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. [S01], [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('11d3422a-c906-5ff9-96d4-386b108c9a09', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Stocks et travaux en cours. « Stocks et travaux en cours » mobilise de la trésorerie tant que les biens ne sont pas vendus ou consommés. Le suivi doit combiner valeur du stock, vitesse de rotation, risque d''invendu et conséquences sur le BFR.</p><p>2. Créances clients. « Créances clients » doit être analysé à partir de la dépendance, du délai d''encaissement, de la qualité documentaire et du risque d''impayé. Une croissance du chiffre d''affaires peut dégrader le cash si les créances augmentent trop vite.</p><p>3. Dettes fournisseurs. « Dettes fournisseurs » se traite par vérification de l''identité, des références, des conditions, de la qualité attendue et des documents. Le prix le plus bas ne compense pas un risque élevé de non-conformité ou de défaut.</p><p>Repère de calcul. Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>4. BFR et cycle de conversion du cash. Le BFR apparaît lorsque l’entreprise paie des stocks ou charges avant d’encaisser ses clients. Il se pilote en agissant sur le stock, les délais clients, les délais fournisseurs et l’organisation du cycle d’exploitation.</p><p>Repère de calcul. BFR simplifié = stocks + créances d’exploitation − dettes d’exploitation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3c04f47d-66ba-5f39-9c9b-6213eb4f4bac', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Séparer finances personnelles et professionnelles.</p><p>Étape 2. Identifier le chiffre d’affaires, les coûts et les encaissements réels.</p><p>Étape 3. Prévoir les obligations et besoins de trésorerie.</p><p>Étape 4. Calculer marge, BFR ou seuil lorsque pertinent.</p><p>Étape 5. Conserver les pièces qui prouvent l’activité et les revenus.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8b88390e-530f-5751-abf5-d4a956d2bb75', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>BFR simplifié = stocks + créances d’exploitation − dettes d’exploitation.</p><p>DSO pédagogique ≈ créances clients ÷ chiffre d’affaires à crédit × nombre de jours de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b2c42c73-fe8e-5ee1-8c22-8fbfff78fd6f', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Comprendre et piloter le BFR », relevez les données disponibles, identifiez au moins quatre notions parmi Besoin en fonds de roulement, Créance client, Dette fournisseur, DIO, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c9930aba-34ea-551e-b1fe-b5b333d4efc3', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 9, '{"html": "<h2>Approfondissement intégré — Trésorerie, BFR, DSO, DPO et stock</h2><ul><li><strong>Publics</strong> : Startups, PME/PMI, professions libérales</li><li><strong>Compétences renforcées</strong> : comprendre pourquoi une entreprise rentable peut manquer de cash; calculer un BFR simplifié; interpréter DSO/DPO/DIO</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Trésorerie</strong> : Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. — [S14], [S30]</li><li><strong>Besoin en fonds de roulement</strong> : Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation. — [S15]</li><li><strong>DSO</strong> : Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période. — [S30], [S32]</li><li><strong>DPO</strong> : Indicateur pédagogique du délai moyen de règlement des fournisseurs, à rapprocher des achats à crédit. — [S32]</li><li><strong>DIO</strong> : Indicateur pédagogique du nombre moyen de jours pendant lesquels le stock reste immobilisé avant sa vente ou consommation. — [S32]</li><li><strong>Cash Conversion Cycle</strong> : Cycle de conversion du cash, généralement présenté comme DSO + DIO - DPO, pour visualiser la durée d’immobilisation du cash d’exploitation. — [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c2df4a92-0581-5158-8c29-30ba9bf0a728', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 10, '{"html": "<h3>Rentabilité ≠ trésorerie</h3><p>Une vente peut générer du bénéfice mais ne pas être encaissée immédiatement. Le stock immobilise aussi du cash. À l''inverse, un délai fournisseur finance temporairement l''activité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fb27e25e-d2a2-53b4-ae4f-0367fe9740c3', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 11, '{"html": "<h3>Formule de base</h3><p>BFR simplifié = stocks + créances clients - dettes fournisseurs. DSO mesure le délai client, DPO le délai fournisseur et DIO la durée moyenne du stock.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('63d4f86d-e010-5705-b954-40e0229006b3', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 12, '{"html": "<h3>Cycle de conversion du cash</h3><p>CCC = DSO + DIO - DPO. Plus le cycle est long, plus le cash reste immobilisé, toutes choses égales par ailleurs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6476c9df-1fa2-5ea1-945d-6a77344e720e', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'callout', 13, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Stocks 2 M DA + créances 3 M - fournisseurs 1,2 M = BFR de 3,8 M DA. Même une entreprise rentable peut avoir besoin de financer ce montant.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e7b11090-5767-57e7-880f-142541ed4c20', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 14, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Calculez le BFR d''une PME fictive puis simulez une baisse du DSO de 15 jours. Expliquez l''effet attendu sur le cash.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6525a0d8-8477-5a8b-820b-81c86f9f2ea2', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 15, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : BFR = stocks + créances clients - dettes fournisseurs. Une baisse du DSO réduit, toutes choses égales, le montant moyen des créances et libère du cash. L’effet exact d’une baisse de 15 jours dépend du niveau de ventes à crédit.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('98e04b1f-0083-5bf6-9920-9b75f0b37071', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 16, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('08e58802-b63f-5bb5-82f9-00d8e9e29975', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 17, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Une entreprise rentable peut-elle manquer de trésorerie ?</strong><br>A. Non<br>B. Oui<br>C. Jamais<br>D. Seulement si elle est cotée<br><em>B. Décalages et stocks peuvent absorber le cash.</em></li><li><strong>2. BFR simplifié =</strong><br>A. Stocks + créances - fournisseurs<br>B. CA - résultat<br>C. Actifs - capital<br>D. Cash + dette<br><em>A. C''est une approximation du besoin opérationnel.</em></li><li><strong>3. Le DSO concerne :</strong><br>A. Les clients<br>B. Les fournisseurs<br>C. Les salariés<br>D. Les banques<br><em>A. Il mesure le délai moyen de recouvrement.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('509f8880-e74f-5258-aaad-a98b4a36e92e', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 18, '{"html": "<p>Traçabilité : contenu intégré depuis [S47] et relié aux définitions maîtres. Les valeurs réglementaires actives restent versionnées dans le Centre de confiance.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('da548795-8bdc-5a1a-acf9-37d20715a5c5', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 19, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une microentreprise a 700 000 DA de stock, 900 000 DA de créances et 500 000 DA de dettes fournisseurs : BFR simplifié = 1 100 000 DA.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d33ad1c0-7352-5323-94e0-097524c0b8a7', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 20, '{"html": "<h2>Exercice d’application</h2><p>Stock 300 000, créances 450 000, fournisseurs 250 000. Calculer BFR.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7cc2cb62-06d8-5379-aa49-b0187e382093', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 21, '{"html": "<h2>Corrigé-type</h2><p>500 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('28707edc-ab30-5645-a06b-9087a93613e9', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'table', 22, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('16e85942-1404-5b14-a1dd-c44e4ad872a6', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 23, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3a91264a-7c50-5306-96ae-3fd9e58e81dc', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 24, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('601d4b3f-495d-59d6-868f-7b328ab18942', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'text', 25, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('285fa5ba-33d7-5e1d-9a82-7553ed7429ae', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'table', 26, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Calculer le BFR du cas réel ou d’un cas pédagogique."], ["Défi", "Tester trois leviers : stock -10 %, DSO -10 jours, DPO +5 jours."], ["Outil lié", "BFR"], ["Preuve Skills Passport", "BFR avant/après."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S15, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('15bacf8a-e062-5217-8736-95baaf3a64bf', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'course', '109d2395-dfb6-5e7d-8322-8c5780663a42', 'QCM — PRO-07', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
