INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('200e9d55-9c45-5a36-a72c-10938499430e', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'PRO-09 — Fiscalité et obligations : savoir chercher la règle', 'Comprendre son régime sans figer les taux dans les cours.', NULL, 9, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('28d2d380-db7e-5194-bcc5-e73f8c45ec3e', '200e9d55-9c45-5a36-a72c-10938499430e', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Libéraux, AE, microentreprises"], ["Niveau", "N2-N4"], ["Objectif measurable", "Comprendre son régime sans figer les taux dans les cours."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ea409788-427e-5b39-82d8-ed8a5bddde49', '200e9d55-9c45-5a36-a72c-10938499430e', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["IFU", "Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur.", "[S04]"], ["TVA", "Impôt calculé sur le chiffre d’affaires hors taxe pour les opérations et contribuables relevant des régimes concernés ; les taux et exonérations sont fixés par les textes en vigueur.", "[S05]"], ["BNC", "Bénéfices des professions non commerciales ; le régime simplifié BNC concerne notamment certaines professions libérales et détermine le bénéfice à partir des recettes et dépenses nécessaires.", "[S06]"], ["IBS", "Impôt sur les bénéfices des sociétés, avec des taux différenciés selon la nature d’activité et les règles fiscales en vigueur.", "[S07]"], ["Auto-entrepreneur", "Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles.", "[S09], [S10]"], ["Obligation", "Titre de créance par lequel l’investisseur prête des fonds à un émetteur selon des conditions de rémunération et de remboursement prévues.", "[S38], [S41]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('55946280-2bd5-55c2-aa17-1e3fbf8c6cd4', '200e9d55-9c45-5a36-a72c-10938499430e', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre son régime sans figer les taux dans les cours. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('907fc753-b2ec-5270-a8e2-00518ae227d0', '200e9d55-9c45-5a36-a72c-10938499430e', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>IFU — Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur. [S04]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>TVA — Impôt calculé sur le chiffre d’affaires hors taxe pour les opérations et contribuables relevant des régimes concernés ; les taux et exonérations sont fixés par les textes en vigueur. [S05]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>BNC — Bénéfices des professions non commerciales ; le régime simplifié BNC concerne notamment certaines professions libérales et détermine le bénéfice à partir des recettes et dépenses nécessaires. [S06]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>IBS — Impôt sur les bénéfices des sociétés, avec des taux différenciés selon la nature d’activité et les règles fiscales en vigueur. [S07]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Auto-entrepreneur — Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles. [S09], [S10]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Obligation — Titre de créance par lequel l’investisseur prête des fonds à un émetteur selon des conditions de rémunération et de remboursement prévues. [S38], [S41]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b790a692-b061-5ede-8a5e-9d1861c89fcf', '200e9d55-9c45-5a36-a72c-10938499430e', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Identifier le régime. Dans une activité indépendante, identifier le régime doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>2. Distinguer CA, bénéfice et base taxable. Ce point demande de comparer des notions proches sans les confondre. Pour « Distinguer CA, bénéfice et base taxable », l''utilisateur doit identifier le critère qui change — nature du flux, horizon, risque, propriétaire, date ou base de calcul — puis appliquer ce critère à un exemple réel ou fictif.</p><p>3. Calendrier des déclarations. Dans une activité indépendante, calendrier des déclarations doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>4. Source officielle DGI. Dans une activité indépendante, source officielle dgi doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fd0e873c-0f03-5c03-9dd6-2c0e210900f1', '200e9d55-9c45-5a36-a72c-10938499430e', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Séparer finances personnelles et professionnelles.</p><p>Étape 2. Identifier le chiffre d’affaires, les coûts et les encaissements réels.</p><p>Étape 3. Prévoir les obligations et besoins de trésorerie.</p><p>Étape 4. Calculer marge, BFR ou seuil lorsque pertinent.</p><p>Étape 5. Conserver les pièces qui prouvent l’activité et les revenus.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0a51dea2-db93-5955-afd5-ffccb31a41c0', '200e9d55-9c45-5a36-a72c-10938499430e', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Fiscalité et obligations : savoir chercher la règle », relevez les données disponibles, identifiez au moins quatre notions parmi IFU, TVA, BNC, IBS, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ac466efb-6605-5760-9536-74bde2771c8e', '200e9d55-9c45-5a36-a72c-10938499430e', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : FINCLUDIA ne doit pas apprendre ''un seul taux pour tous''. Un auto-entrepreneur, un professionnel BNC ou une société peuvent relever de règles différentes. L’utilisateur doit apprendre à identifier son régime avant de calculer.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9879cce3-6435-59ca-b944-2b1feaccf80f', '200e9d55-9c45-5a36-a72c-10938499430e', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Associer 6 profils fictifs à la question réglementaire à vérifier : IFU, BNC, TVA, IBS, IRG, etc.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('70147368-a07a-5f1e-a72f-280b7f62cc72', '200e9d55-9c45-5a36-a72c-10938499430e', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>La bonne réponse est la bonne route de recherche, pas une valeur inventée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('67e2a996-d07a-51ef-9e37-f2cc19de5b43', '200e9d55-9c45-5a36-a72c-10938499430e', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2c1e8a6c-4cb6-5b34-b53c-675f0dcafa55', '200e9d55-9c45-5a36-a72c-10938499430e', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
