INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3c41f69d-3584-51ec-860f-ea4ec15b06ef', '200e9d55-9c45-5a36-a72c-10938499430e', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('68cfd36a-4d4c-5fbd-a489-dd1b6b73d902', '200e9d55-9c45-5a36-a72c-10938499430e', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Ouvrir le moteur réglementaire et enregistrer une règle sourcée."], ["Défi", "Retrouver source, date et article pour une obligation réelle."], ["Outil lié", "Reglo"], ["Preuve Skills Passport", "Preuve de recherche réglementaire."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S04, S05, S06, S07"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
