INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('295bbe5d-37c7-591d-93fa-a50c331d7afa', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'PRO-10 — Préparer un financement professionnel', 'Relier le besoin à l’instrument plutôt que chercher immédiatement une banque.', NULL, 10, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c80bde37-d686-5231-a70a-aa35025b0b84', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Libéraux, AE, microentreprises"], ["Niveau", "N2-N4"], ["Objectif measurable", "Relier le besoin à l’instrument plutôt que chercher immédiatement une banque."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dbf1cd04-a38f-53f7-b4b1-593aedfd0247', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Besoin en fonds de roulement", "Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation.", "[S15]"], ["Seuil de rentabilité", "Niveau de chiffre d’affaires à partir duquel l’entreprise couvre ses charges fixes et variables sans perte ni bénéfice.", "[S16]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Capacité de remboursement", "Montant qu’un budget peut consacrer durablement à une échéance sans compromettre les dépenses essentielles, la sécurité et les autres engagements.", "[S22], [S32]"], ["Horizon d’investissement", "Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné.", "[S02], [S41]"], ["Demande", "Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions.", "[S32]"], ["Besoin", "Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b0ffb79d-d785-5537-b079-b734bfa367aa', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Relier le besoin à l’instrument plutôt que chercher immédiatement une banque. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5c1cdbfd-0487-51d6-ab7e-ea420724f18e', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Besoin en fonds de roulement — Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation. [S15]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Seuil de rentabilité — Niveau de chiffre d’affaires à partir duquel l’entreprise couvre ses charges fixes et variables sans perte ni bénéfice. [S16]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Capacité de remboursement — Montant qu’un budget peut consacrer durablement à une échéance sans compromettre les dépenses essentielles, la sécurité et les autres engagements. [S22], [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Horizon d’investissement — Durée pendant laquelle un capital peut rester investi avant d’être nécessaire pour l’objectif concerné. [S02], [S41]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Demande — Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions. [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Besoin — Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer. [S01], [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c0c2ac44-071c-5260-8e2e-8a5d033efaa2', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Besoin BFR, équipement, véhicule, croissance. Le BFR apparaît lorsque l’entreprise paie des stocks ou charges avant d’encaisser ses clients. Il se pilote en agissant sur le stock, les délais clients, les délais fournisseurs et l’organisation du cycle d’exploitation.</p><p>Repère de calcul. BFR simplifié = stocks + créances d’exploitation − dettes d’exploitation.</p><p>2. Apport et capacité de remboursement. Dans une activité indépendante, apport et capacité de remboursement doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>3. Documents et scénarios. Pour « Documents et scénarios », la compétence est documentaire : savoir quelle information doit être conservée, qui l''émet, à quelle date et à quelle opération elle se rattache. Une trace exploitable doit permettre de reconstituer la décision.</p><p>4. Comparaison prudente. Dans une activité indépendante, comparaison prudente doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4957de03-1a4d-5103-9109-54a86e40a154', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Séparer finances personnelles et professionnelles.</p><p>Étape 2. Identifier le chiffre d’affaires, les coûts et les encaissements réels.</p><p>Étape 3. Prévoir les obligations et besoins de trésorerie.</p><p>Étape 4. Calculer marge, BFR ou seuil lorsque pertinent.</p><p>Étape 5. Conserver les pièces qui prouvent l’activité et les revenus.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3b84246f-ab80-559e-9712-6e2c6feb3606', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>BFR simplifié = stocks + créances d’exploitation − dettes d’exploitation.</p><p>Seuil de rentabilité = charges fixes ÷ taux de marge sur coûts variables.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('40994548-5743-5fb3-bcbd-45bea5db400f', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Préparer un financement professionnel », relevez les données disponibles, identifiez au moins quatre notions parmi Besoin en fonds de roulement, Seuil de rentabilité, Trésorerie, Risque financier, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0092da11-e03a-5116-a1e2-88b96824b65d', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 9, '{"html": "<h2>Approfondissement intégré — Diagnostiquer un besoin de financement</h2><ul><li><strong>Publics</strong> : Salariés, entrepreneurs, PME/PMI</li><li><strong>Compétences renforcées</strong> : identifier la nature du besoin; aligner durée du financement et durée économique; préparer les données</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Flux de financement</strong> : Flux qui modifient la taille ou la composition des capitaux propres et des emprunts. — [S14]</li><li><strong>Capacité de remboursement</strong> : Montant qu’un budget peut consacrer durablement à une échéance sans compromettre les dépenses essentielles, la sécurité et les autres engagements. — [S22], [S32]</li><li><strong>CAPEX</strong> : Dépense d’investissement destinée à acquérir ou améliorer un actif utilisé durablement dans l’activité. — [S13], [S42]</li><li><strong>Trésorerie</strong> : Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. — [S14], [S30]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6ef31ac2-8aaa-53db-a5b6-5664336a0932', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 10, '{"html": "<h3>Commencer par le besoin</h3><p>Avant de choisir un produit, il faut comprendre ce qui doit être financé : logement, véhicule, stock, créance client, machine, croissance, importation ou déficit temporaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9e90c127-88b9-508e-b4a0-279d707802e0', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 11, '{"html": "<h3>Principe d''alignement</h3><p>Un besoin très court ne devrait généralement pas être financé avec un instrument très long sans raison, et un actif utilisé pendant plusieurs années ne devrait pas être financé uniquement par une facilité très courte.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7727cfee-eb14-5bf7-99cd-ef0ddfe37549', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Une machine de production utilisée 7 ans doit être comparée avec un crédit moyen/long terme, un leasing ou une structure de finance islamique adaptée, plutôt qu''avec une facilité de quelques semaines.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4786155a-bc2a-5b72-be9f-30d0bb798751', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Pour cinq besoins fictifs, choisissez la famille d''instruments à analyser et justifiez l''horizon.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b19708df-fe27-5b13-b9e8-3b690f9bcedb', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : besoin de court terme (stock, décalage client) -&gt; instruments de trésorerie/working capital ; actif utilisé plusieurs années -&gt; crédit moyen-long terme, leasing ou structure adaptée ; croissance/capital immatériel -&gt; fonds propres ou financement mixte selon risque et capacité de remboursement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0290fcba-2c33-5b7e-8111-84f61ac5bdec', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e3374c95-3b48-52e9-b9c6-851d7610158b', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Avant de comparer les taux, il faut :</strong><br>A. Identifier le besoin<br>B. Choisir une banque au hasard<br>C. Signer<br>D. Acheter l''actif<br><em>A. Le besoin détermine les instruments pertinents.</em></li><li><strong>2. Le financement d''un stock saisonnier est généralement :</strong><br>A. Un besoin opérationnel<br>B. Un besoin de 20 ans<br>C. Une action<br>D. Un dividende<br><em>A. Il relève du cycle d''exploitation.</em></li><li><strong>3. Une machine longue durée doit être comparée avec :</strong><br>A. Des solutions alignées sur sa durée économique<br>B. Une dépense alimentaire<br>C. Un compte étudiant<br>D. Une taxe<br><em>A. L''horizon de financement est important.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e47f3d72-4ecf-57ba-909a-d38e546d7378', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une activité de service demande 1,5 M DA pour un véhicule alors que son besoin réel est 700 000 DA de matériel et 300 000 DA de BFR. Le diagnostic doit d’abord clarifier la nature du besoin.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('37c81489-af25-5671-a764-c569d3bb32bf', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Décomposer un besoin global de 2 M DA en investissement, BFR et sécurité de trésorerie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('30fe2f0c-8f43-5517-a84b-dec331ba45c7', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>La correction dépend du cas ; chaque composante doit être reliée à un horizon et un mode de financement potentiel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3822d605-4c93-5324-a92e-5bdb467ece59', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ac04151f-6592-53ae-9188-a4a32a2637ca', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0aaa9a9f-5c66-5ab0-a0fd-f0a868ff80e9', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7088c69e-21bf-5b95-9161-5d1109270c39', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6511df93-7f2b-596a-8b25-fdbd3b4c0e65', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un Funding Need."], ["Défi", "Préparer un dossier avec 100 % des pièces obligatoires de la checklist FINCLUDIA."], ["Outil lié", "Funding Navigator"], ["Preuve Skills Passport", "Dossier de besoin structuré."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S14, S15, S16, S22, S30"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('5821cdbf-8706-5630-b663-ce33c90b9a42', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'course', '295bbe5d-37c7-591d-93fa-a50c331d7afa', 'QCM — PRO-10', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
