INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9909f5eb-af73-58c4-9774-b6f008410aef', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Libéraux, AE, microentreprises"], ["Niveau", "N2-N4"], ["Objectif measurable", "Transformer l’historique d’activité en preuves financières compréhensibles."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ecb37be-164e-5236-b601-2e1077f2f49c', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Chiffre d’affaires", "Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable.", "[S04] [S05]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Besoin en fonds de roulement", "Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation.", "[S15]"], ["Certification interne FINCLUDIA", "Attestation interne de compétences acquises à l’issue d’un parcours FINCLUDIA ; elle ne constitue ni diplôme d’État, ni agrément professionnel, ni autorisation réglementaire.", "[S32]"], ["Concentration", "Exposition excessive à un nombre limité d’actifs, d’émetteurs, de secteurs, de clients ou de risques.", "[S38], [S41]"], ["Encaissement", "Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés.", "[S14], [S32]"], ["Facture", "Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables.", "[S04], [S05], [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('16873eb7-7f7f-544f-9468-bd158dfe8bf0', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Transformer l’historique d’activité en preuves financières compréhensibles. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6f43953d-6546-52c3-8b81-4b924de70901', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Chiffre d’affaires — Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable. [S04] [S05]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Besoin en fonds de roulement — Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation. [S15]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Certification interne FINCLUDIA — Attestation interne de compétences acquises à l’issue d’un parcours FINCLUDIA ; elle ne constitue ni diplôme d’État, ni agrément professionnel, ni autorisation réglementaire. [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Concentration — Exposition excessive à un nombre limité d’actifs, d’émetteurs, de secteurs, de clients ou de risques. [S38], [S41]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Encaissement — Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés. [S14], [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Facture — Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables. [S04], [S05], [S32]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. L’utilisateur doit distinguer flux personnels et professionnels, raisonner en trésorerie et en rentabilité, puis conserver les documents nécessaires au pilotage et à la conformité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0f066d1f-0a37-5fdd-97ac-55c7b733df35', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Ancienneté. Dans une activité indépendante, ancienneté doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>2. CA et croissance. Dans une activité indépendante, ca et croissance doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>3. Encaissements. Une vente n’est pas un encaissement tant que l’argent n’est pas effectivement reçu. Cette distinction est fondamentale pour la trésorerie et le BFR.</p><p>4. Clients récurrents/concentration. La concentration mesure la dépendance à un petit nombre d’actifs, clients, fournisseurs ou sources de revenu. Plus cette dépendance est forte, plus un choc ciblé peut affecter l’ensemble.</p><p>5. Marge. La marge est l’écart entre un prix de vente ou un chiffre d’affaires et une catégorie de coûts déterminée. Avant de comparer deux marges, il faut utiliser la même définition et le même périmètre de coûts.</p><p>6. Cash. Dans une activité indépendante, cash doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p><p>7. Documents. Les documents rendent la situation financière vérifiable : factures, relevés, états financiers, contrats, justificatifs fiscaux ou commerciaux. Un dossier incomplet augmente l’incertitude du financeur et peut retarder la décision.</p><p>8. Qualité des données. Dans une activité indépendante, qualité des données doit être relié au chiffre d''affaires, aux encaissements, aux coûts et à la trésorerie. La question pratique est de savoir si l''activité génère réellement du cash après les obligations et si le résultat peut être documenté.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0771bcc8-c1b0-5156-ac90-6681bca57ed6', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Séparer finances personnelles et professionnelles.</p><p>Étape 2. Identifier le chiffre d’affaires, les coûts et les encaissements réels.</p><p>Étape 3. Prévoir les obligations et besoins de trésorerie.</p><p>Étape 4. Calculer marge, BFR ou seuil lorsque pertinent.</p><p>Étape 5. Conserver les pièces qui prouvent l’activité et les revenus.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('17ffc00c-a639-54c8-ac1e-ce8d6e20e15c', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>BFR simplifié = stocks + créances d’exploitation − dettes d’exploitation.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d2c4f660-5066-5b0e-a51d-9c10eedb019e', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Construire son Passeport financier », relevez les données disponibles, identifiez au moins quatre notions parmi Chiffre d’affaires, Trésorerie, Besoin en fonds de roulement, Certification interne FINCLUDIA, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6d8dbd5f-bcbf-5f18-acca-a6f7dc030e9f', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un professionnel ayant 18 mois de factures et paiements rapprochés peut démontrer la régularité de son activité mieux qu’avec une simple déclaration de revenu isolée.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2362fae4-9d78-5849-9d81-b6d221ca6a42', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Choisir 8 indicateurs utiles à un passeport financier sans prétendre produire un score de crédit officiel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1780a9fb-abca-54eb-9fed-5d6c1706da9e', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Les indicateurs doivent être traçables, datés et explicables.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('99933b52-739c-5e8f-a7dc-365ee8bc3422', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8d9e8614-e382-5af1-8441-948662fb264f', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dedda8d0-27eb-596a-8e91-b03b56e3d5ed', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c2b85354-90da-5ae0-90b7-1ab700509bc9', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c0ed35c5-59ba-5de3-8266-4bf09745f643', '24e5888f-5b67-5ad3-a898-d77f88d0a191', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Générer un Pro Passport."], ["Défi", "Améliorer la complétude documentaire de 20 points."], ["Outil lié", "Passport"], ["Preuve Skills Passport", "Passeport exporté."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S04, S05, S14, S15, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
