INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'LIB-02 — Tarification et temps facturable', 'Construire un tarif tenant compte du temps non facturable et des charges.', NULL, 13, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bd35c841-5afd-58d3-a5eb-dee220ddfa40', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Professions libérales"], ["Niveau", "N2-N4"], ["Objectif measurable", "Construire un tarif tenant compte du temps non facturable et des charges."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7990be9f-c28f-5394-aee4-657166f9a19a', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Prix de revient", "Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service.", "[S16] [S30]"], ["Seuil de rentabilité", "Niveau de chiffre d’affaires à partir duquel l’entreprise couvre ses charges fixes et variables sans perte ni bénéfice.", "[S16]"], ["Marge sur coûts variables", "Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité.", "[S16]"], ["Facture", "Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables.", "[S04], [S05], [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4eefaa69-5ff8-5764-ab13-a1752ec8bd64', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Construire un tarif tenant compte du temps non facturable et des charges. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c4ca83d1-eab5-5a32-851a-34b44199dc32', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Prix de revient — Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service. [S16] [S30]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Seuil de rentabilité — Niveau de chiffre d’affaires à partir duquel l’entreprise couvre ses charges fixes et variables sans perte ni bénéfice. [S16]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Marge sur coûts variables — Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité. [S16]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Facture — Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables. [S04], [S05], [S32]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c78f094d-eb9b-530c-8d56-5050c491f797', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Jours disponibles. Pour une profession libérale, jours disponibles est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>2. Jours facturables. Pour une profession libérale, jours facturables est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>3. Coûts annuels. Pour « Coûts annuels », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>4. Revenu cible. Pour une profession libérale, revenu cible est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>5. Tarif minimum pédagogique. Pour une profession libérale, tarif minimum pédagogique est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cf2613bc-cc3d-5540-b24e-94f3a84120a9', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Mesurer le temps disponible et le temps réellement facturable.</p><p>Étape 2. Relier honoraires, encaissements et charges.</p><p>Étape 3. Provisionner fiscal/social et périodes creuses.</p><p>Étape 4. Suivre les créances et la dépendance clients.</p><p>Étape 5. Maintenir une réserve professionnelle avant de fixer la rémunération personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('36028338-0f75-52e2-9515-4b1c41298c0d', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Seuil de rentabilité = charges fixes ÷ taux de marge sur coûts variables.</p><p>Marge sur coûts variables = chiffre d’affaires − charges variables.</p><p>Prix de revient = coûts directs + quote-part des coûts indirects affectés selon une méthode explicite.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2fd0ffd1-e70e-5a9b-b0fd-2681ad85b783', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Tarification et temps facturable », relevez les données disponibles, identifiez au moins quatre notions parmi Prix de revient, Seuil de rentabilité, Marge sur coûts variables, Facture, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2c63632d-a4d2-553e-9006-737792729e3b', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un consultant dispose de 220 jours ouvrés mais n’en facture que 130 après prospection, administration, congés et formation. Son tarif doit couvrir les coûts sur ces 130 jours, pas sur 220.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c0439bc4-c792-5fc4-a8b7-9ad2a71e87e2', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Objectif de 3,9 M DA à couvrir sur 130 jours facturables : tarif journalier moyen nécessaire ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9c44d110-a7d0-5a4e-95bb-1fe785d16517', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>30 000 DA/jour.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f7a46771-e10e-5fe9-9b42-01e370614dcc', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b4e04cf3-e99b-5bef-9378-d384026e16d0', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('749bfabb-468a-57f3-9da2-995e1b84e3d2', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('925f08a8-f149-5ab0-9cbd-8c4f9a020f50', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('89f2448d-4c7c-576e-8234-39c9946cbfe4', '1dd6ef65-e6a7-5e30-ab9c-2406a766edc8', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Calculer son taux/jour ou taux/heure économique."], ["Défi", "Tester un scénario -20 % de jours facturables."], ["Outil lié", "Tarification"], ["Preuve Skills Passport", "Fiche tarif."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S16, S30"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
