INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('d36bf374-871a-5ddb-8516-987fa67d1bdf', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'LIB-03 — Variabilité du revenu et réserve professionnelle', 'Adapter la sécurité financière à des revenus irréguliers.', NULL, 14, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7c3c14d7-1de0-5c2f-9720-e3ff822ac35f', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Professions libérales"], ["Niveau", "N2-N4"], ["Objectif measurable", "Adapter la sécurité financière à des revenus irréguliers."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cb031d8a-e62b-5a13-9c79-6f175e4fbf98', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Fonds de sécurité", "Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles.", "[S03] [S32]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('af1fc6fd-cbfe-5af3-9327-726e36c607d7', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Adapter la sécurité financière à des revenus irréguliers. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('333f9435-9f8b-55b9-8754-c198ae02ff99', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Fonds de sécurité — Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles. [S03] [S32]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8ad2f0c3-b64e-5554-98b4-4b2a3ff56d96', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Saisonnalité. Pour une profession libérale, saisonnalité est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>2. Mois faibles. Pour une profession libérale, mois faibles est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>3. Réserve pro. Pour une profession libérale, réserve pro est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>Repère de calcul. Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p><p>4. Réserve personnelle. Pour une profession libérale, réserve personnelle est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>Repère de calcul. Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d82516f2-a41d-568e-b527-e55bded6888a', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Mesurer le temps disponible et le temps réellement facturable.</p><p>Étape 2. Relier honoraires, encaissements et charges.</p><p>Étape 3. Provisionner fiscal/social et périodes creuses.</p><p>Étape 4. Suivre les créances et la dépendance clients.</p><p>Étape 5. Maintenir une réserve professionnelle avant de fixer la rémunération personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7114b93e-16b4-58f3-a985-6c0e9d06990a', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a0aa4d0f-1484-5432-8d4b-08a5da57f5c7', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Variabilité du revenu et réserve professionnelle », relevez les données disponibles, identifiez au moins quatre notions parmi Fonds de sécurité, Trésorerie, Risque financier, Revenu, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a3958c3d-56aa-5b3c-9abc-c794c2d7989d', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un professionnel encaisse 500 000 DA en mars puis 180 000 DA en avril. Il doit dimensionner sa réserve à partir de ses charges et de la volatilité plutôt que d’un seul mois moyen.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('38d12e73-7e0b-53c1-be5e-335c8b644a16', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Sur 6 mois : 400, 200, 500, 250, 450, 300 kDA. Calculer la moyenne.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('60fe193c-722a-5ff1-a408-046a67bc0c8e', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>350 kDA/mois.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f2bfe09e-aca2-56c8-868e-0287dd5e9f49', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4c051104-eb9d-54b4-b006-e23883f6f3b1', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c4cbe3e7-326d-525f-96d6-7b887068f11b', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2ddf2739-8ed2-524e-bf7b-443daea7fb62', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ab6480a-059c-594c-97ad-3b1fa51df59e', 'd36bf374-871a-5ddb-8516-987fa67d1bdf', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Mesurer la volatilité de 12 mois."], ["Défi", "Construire une réserve couvrant le scénario de deux mois faibles."], ["Outil lié", "Cash & Réserve"], ["Preuve Skills Passport", "Analyse de volatilité."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S03, S14, S22, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
