INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('28d039f5-c820-5190-ba3a-4a09bd9996be', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'LIB-04 — Acomptes, honoraires et créances', 'Réduire le BFR d’une prestation par les modalités de facturation.', NULL, 15, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('61eea525-4138-56cd-85c9-3f03b83f77dc', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Professions libérales"], ["Niveau", "N2-N4"], ["Objectif measurable", "Réduire le BFR d’une prestation par les modalités de facturation."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('da425c64-e825-50c3-8be0-bb79151b34a1', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Créance client", "Montant facturé à un client mais non encore encaissé.", "[S15] [S32]"], ["Besoin en fonds de roulement", "Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation.", "[S15]"], ["Encaissement", "Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés.", "[S14] [S32]"], ["Facture", "Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables.", "[S04], [S05], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('39089e22-7cf6-5e1c-bbd9-e9557d453d8d', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Réduire le BFR d’une prestation par les modalités de facturation. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f8715e3c-48fd-5439-9d02-537b092a8395', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Créance client — Montant facturé à un client mais non encore encaissé. [S15] [S32]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Besoin en fonds de roulement — Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation. [S15]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Encaissement — Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés. [S14] [S32]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Facture — Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables. [S04], [S05], [S32]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3186bb8d-9b22-5bd8-96bd-4d1d631f60a0', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Acompte. Pour une profession libérale, acompte est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>2. Facturation par jalon. Pour une profession libérale, facturation par jalon est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>3. Solde. Pour une profession libérale, solde est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>Repère de calcul. Solde budgétaire = revenus de la période − dépenses de la période.</p><p>4. Délai client. « Délai client » doit être analysé à partir de la dépendance, du délai d''encaissement, de la qualité documentaire et du risque d''impayé. Une croissance du chiffre d''affaires peut dégrader le cash si les créances augmentent trop vite.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9dbe96c9-5056-5503-8558-2c353e24d250', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Mesurer le temps disponible et le temps réellement facturable.</p><p>Étape 2. Relier honoraires, encaissements et charges.</p><p>Étape 3. Provisionner fiscal/social et périodes creuses.</p><p>Étape 4. Suivre les créances et la dépendance clients.</p><p>Étape 5. Maintenir une réserve professionnelle avant de fixer la rémunération personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('71ce743a-fc51-570a-ad49-5dc67a8b2249', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>BFR simplifié = stocks + créances d’exploitation − dettes d’exploitation.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fb65c28d-5d9c-58c7-be12-fa798c4e19f5', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Acomptes, honoraires et créances », relevez les données disponibles, identifiez au moins quatre notions parmi Créance client, Besoin en fonds de roulement, Encaissement, Facture, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('17bb990e-316e-5ed5-90a0-fdc3668f5816', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un architecte facture 30 % à la commande, 40 % au jalon et 30 % à la livraison. Le calendrier d’encaissement réduit le financement nécessaire par rapport à une facturation à 100 % en fin de mission.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('064809d5-71fa-5b6d-8694-c7e85b7f46e5', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Mission 300 000 DA avec 30/40/30 : calculer chaque encaissement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bc47464a-1164-5f95-a490-e3f1d8ef0b8d', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>90 000 ; 120 000 ; 90 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f81c511b-8cd6-5d4f-a843-94ddb9bcc6e2', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('395d2e17-3be6-51b9-bf77-ad8ab06abd67', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ebf8ebea-b8e7-5ea3-a0e3-17304f38578d', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8c6d4f34-76c2-5dfd-8eee-cf6c983a8acd', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('01852f27-725a-5fca-b97d-e9aff618254f', '28d039f5-c820-5190-ba3a-4a09bd9996be', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un échéancier de prestation."], ["Défi", "Réduire de 15 jours le délai moyen simulé."], ["Outil lié", "Facturation"], ["Preuve Skills Passport", "Échéancier client."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S14, S15, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
