INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('d362a2ca-08cb-5a5b-b566-831acf7a1f53', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'LIB-05 — Provision fiscale et sociale', 'Distinguer cash bancaire et cash réellement disponible.', NULL, 16, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f355caf0-a6ae-5263-ba6f-aec5f9ea9fdb', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Professions libérales"], ["Niveau", "N2-N4"], ["Objectif measurable", "Distinguer cash bancaire et cash réellement disponible."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bf6c27f2-297c-55ed-b3a7-962c63ce35a9', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["BNC", "Bénéfices des professions non commerciales ; le régime simplifié BNC concerne notamment certaines professions libérales et détermine le bénéfice à partir des recettes et dépenses nécessaires.", "[S06]"], ["TVA", "Impôt calculé sur le chiffre d’affaires hors taxe pour les opérations et contribuables relevant des régimes concernés ; les taux et exonérations sont fixés par les textes en vigueur.", "[S05]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Provision", "Somme mise progressivement de côté pour une dépense future prévisible, même si elle n’est pas encore exigible.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('147a3d39-f632-5ae5-a285-ab80ebbe9e41', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Distinguer cash bancaire et cash réellement disponible. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1f1d12ff-1bf9-5118-a299-6641728f3448', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>BNC — Bénéfices des professions non commerciales ; le régime simplifié BNC concerne notamment certaines professions libérales et détermine le bénéfice à partir des recettes et dépenses nécessaires. [S06]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>TVA — Impôt calculé sur le chiffre d’affaires hors taxe pour les opérations et contribuables relevant des régimes concernés ; les taux et exonérations sont fixés par les textes en vigueur. [S05]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Provision — Somme mise progressivement de côté pour une dépense future prévisible, même si elle n’est pas encore exigible. [S32]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('78dffa0c-dbfd-548b-b116-c2c64a3e5f7d', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Provision. Provisionner consiste à mettre de côté progressivement pour une dépense future prévisible. Une dépense annuelle de 120 000 DA peut ainsi être préparée par une provision de 10 000 DA par mois.</p><p>2. Trésorerie disponible. Pour une profession libérale, trésorerie disponible est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>3. Échéances. Pour une profession libérale, échéances est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>4. Règles versionnées. Pour une profession libérale, règles versionnées est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('38804246-4cbb-554f-98bc-37ff98bb7539', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Mesurer le temps disponible et le temps réellement facturable.</p><p>Étape 2. Relier honoraires, encaissements et charges.</p><p>Étape 3. Provisionner fiscal/social et périodes creuses.</p><p>Étape 4. Suivre les créances et la dépendance clients.</p><p>Étape 5. Maintenir une réserve professionnelle avant de fixer la rémunération personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4f2cde36-42f3-5bc7-a178-4e9c07df35c1', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Provision fiscale et sociale », relevez les données disponibles, identifiez au moins quatre notions parmi BNC, TVA, Trésorerie, Provision, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a53c1a73-79a6-55cb-86a0-fd4e747e2feb', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un professionnel encaisse 400 000 DA : FINCLUDIA peut réserver un montant selon une règle/estimation paramétrée, mais doit afficher que le calcul fiscal dépend du régime et des textes en vigueur.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6228883a-a595-550a-be84-2c49de1d8c5c', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Si 400 000 DA encaissés et une provision interne de 15 % est définie par l’utilisateur, quel montant est réservé ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e54cdd26-fcda-5d92-a208-98a9d5f9e3bd', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>60 000 DA. Ce pourcentage est une hypothèse interne, pas un taux fiscal officiel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9e8f8f4b-649f-5971-875d-9882122c91cf', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d020fdfc-8d40-5cee-a179-dbee2e369e44', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('df76f12f-9222-5350-b2ef-7339494db25b', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ed16f627-00e6-5b8f-82d0-25da0c9de212', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('09bdf70b-de85-5bc9-ac02-c97988b3d739', 'd362a2ca-08cb-5a5b-b566-831acf7a1f53', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer une enveloppe provision."], ["Défi", "Maintenir 100 % des provisions planifiées sur 3 mois."], ["Outil lié", "Reglo + Cash"], ["Preuve Skills Passport", "Provision séparée."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S05, S06, S14, S30"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
