INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('6d662f93-904f-5d68-8434-d5a1ac3f86f1', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'LIB-06 — Risque de dépendance et continuité d’activité', 'Mesurer concentration clients et capacité de continuité.', NULL, 17, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c59e78a4-ead9-592d-aab7-e7df6c648b5d', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Professions libérales"], ["Niveau", "N2-N4"], ["Objectif measurable", "Mesurer concentration clients et capacité de continuité."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ddfcda0a-4e4d-5dc8-911c-737b82128941', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Diversification", "Répartition d’une exposition entre plusieurs actifs, activités, clients ou sources afin de limiter la dépendance à un seul élément.", "[S02] [S32]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Fonds de sécurité", "Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles.", "[S03] [S32]"], ["Concentration", "Exposition excessive à un nombre limité d’actifs, d’émetteurs, de secteurs, de clients ou de risques.", "[S38], [S41]"], ["ARR", "Annualisation pédagogique du revenu récurrent, souvent calculée à partir du MRR lorsque le modèle et la stabilité des revenus le permettent.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('217f6fe9-2b26-53f8-9018-f5f78803739b', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Mesurer concentration clients et capacité de continuité. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ff3fb274-c5c5-5d5c-bac8-874ed917f893', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Diversification — Répartition d’une exposition entre plusieurs actifs, activités, clients ou sources afin de limiter la dépendance à un seul élément. [S02] [S32]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Fonds de sécurité — Réserve liquide destinée à absorber des dépenses imprévues ou une baisse temporaire de revenu ; FINCLUDIA l’exprime souvent en mois de dépenses essentielles. [S03] [S32]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>Concentration — Exposition excessive à un nombre limité d’actifs, d’émetteurs, de secteurs, de clients ou de risques. [S38], [S41]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p><p>ARR — Annualisation pédagogique du revenu récurrent, souvent calculée à partir du MRR lorsque le modèle et la stabilité des revenus le permettent. [S32]</p><p>Application dans ce module. La notion est reliée au temps facturable, aux honoraires, aux créances, aux provisions et à la continuité de revenu ; le professionnel doit préserver une séparation claire entre activité et vie personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b69a8175-4102-5016-b574-e1b46ab8887d', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Part du principal client. « Part du principal client » doit être analysé à partir de la dépendance, du délai d''encaissement, de la qualité documentaire et du risque d''impayé. Une croissance du chiffre d''affaires peut dégrader le cash si les créances augmentent trop vite.</p><p>2. Arrêt maladie/activité. Pour une profession libérale, arrêt maladie/activité est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>3. Remplacement. Pour une profession libérale, remplacement est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>4. Protection et réserve. Pour une profession libérale, protection et réserve est analysé en fonction du temps disponible, des honoraires, des créances clients et des périodes sans facturation. Le professionnel doit mesurer l''effet sur sa réserve et sa rémunération personnelle.</p><p>Repère de calcul. Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b126f6b1-3f05-5b8f-b7e3-17b71376ba27', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Mesurer le temps disponible et le temps réellement facturable.</p><p>Étape 2. Relier honoraires, encaissements et charges.</p><p>Étape 3. Provisionner fiscal/social et périodes creuses.</p><p>Étape 4. Suivre les créances et la dépendance clients.</p><p>Étape 5. Maintenir une réserve professionnelle avant de fixer la rémunération personnelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('47d6731d-dc9f-538f-8500-9efdbc46aff9', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Mois de réserve = liquidités affectées à la sécurité ÷ dépenses essentielles mensuelles.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7c536bc4-f422-5a8f-8ca5-b04898f041ba', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Risque de dépendance et continuité d’activité », relevez les données disponibles, identifiez au moins quatre notions parmi Diversification, Risque financier, Fonds de sécurité, Concentration, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('adb95bae-195c-5b14-84a7-6c7b791533f4', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un consultant réalise 55 % de son CA avec un seul client. FINCLUDIA déclenche un stress test de perte du client, sans qualifier automatiquement le niveau de risque comme ''acceptable'' ou ''inacceptable''.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aec3cdc6-4401-5b15-9bba-986df81dc376', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>CA total 6 M DA, client principal 2,1 M DA. Calculer concentration.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ab67083e-a8ef-5a02-afb8-9470d63e7f42', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>35 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('07340ac4-cbd9-593c-afa4-d12eca1dada4', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a854ba32-8cc1-5d52-91ad-929bbbf15a80', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c2138a51-2b13-5d8b-82d9-d138b1adf335', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bcb42867-66d4-5640-8cd4-703bcd95f978', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b17e9394-844a-5e43-8466-29ff87881113', '6d662f93-904f-5d68-8434-d5a1ac3f86f1', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Réaliser un stress test perte client."], ["Défi", "Créer 3 actions de diversification."], ["Outil lié", "Risques Pro"], ["Preuve Skills Passport", "Plan de continuité."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S03, S22, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
