INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('dfd88b59-d67b-5f44-a7b3-47132222a6ce', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'AE-02 — CA, IFU et seuils versionnés', 'Comprendre le lien entre chiffre d’affaires et régime fiscal sans hard-coder les seuils.', NULL, 19, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('746a3071-ab81-5e6c-9c33-51394ad16574', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Auto-entrepreneurs"], ["Niveau", "N2-N3"], ["Objectif measurable", "Comprendre le lien entre chiffre d’affaires et régime fiscal sans hard-coder les seuils."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f2a8c9ef-0a0e-5421-ac4c-dfdfb6ff78c0', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Chiffre d’affaires", "Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable.", "[S04] [S05]"], ["IFU", "Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur.", "[S04]"], ["Auto-entrepreneur", "Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles.", "[S09] [S10]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cb0b6b7a-d023-5eb3-a3a8-1b4269ebd488', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre le lien entre chiffre d’affaires et régime fiscal sans hard-coder les seuils. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dff45d5a-3bc5-50a1-9da7-bcb6fdaf76be', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Chiffre d’affaires — Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable. [S04] [S05]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>IFU — Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur. [S04]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Auto-entrepreneur — Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles. [S09] [S10]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f092b7c0-4988-5ff2-8b94-8943deb708bb', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. CA annuel. Dans le parcours auto-entrepreneur, ca annuel est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>2. Seuil du statut/régime. Dans le parcours auto-entrepreneur, seuil du statut/régime est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>3. Taux IFU en vigueur. Dans le parcours auto-entrepreneur, taux ifu en vigueur est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>4. Minimum d’imposition. Dans le parcours auto-entrepreneur, minimum d’imposition est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>5. Dépassements et changement de situation. Dans le parcours auto-entrepreneur, dépassements et changement de situation est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('52fc843a-4ae0-567c-bb58-cdbaa928de3f', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier l’éligibilité et la règle active.</p><p>Étape 2. Tracer le chiffre d’affaires et les factures.</p><p>Étape 3. Séparer provision fiscale/sociale et cash disponible.</p><p>Étape 4. Calculer prix, marge et temps.</p><p>Étape 5. Préparer les preuves nécessaires pour grandir ou demander un financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b675362f-161c-5a64-aa30-3b4a55851d6b', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « CA, IFU et seuils versionnés », relevez les données disponibles, identifiez au moins quatre notions parmi Chiffre d’affaires, IFU, Auto-entrepreneur, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('22535dbd-954d-5176-83a8-07b51699a6ea', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Au 8 novembre 2026, la DGI publie pour l’auto-entrepreneur un seuil de 5 M DA de CA annuel et un taux IFU de 0,5 %. FINCLUDIA doit charger ces valeurs depuis le moteur réglementaire et les dater, car elles peuvent évoluer.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d2186aaa-2223-53e2-ac9b-4e51ca02dee5', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>CA mensuel moyen 350 000 DA : projeter un CA annuel simple.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('63b4a06f-4d17-57c1-88a7-753511a18dec', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>350 000 × 12 = 4,2 M DA, sous réserve de saisonnalité et de variation réelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ec03a97-74d6-5dc8-a983-e67cbc33e11b', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('574383e1-c0f2-55e8-81db-9f8f9212de2e', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f712a213-1335-5b78-be02-f6fb8d37c6b0', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ca424aa-7ac0-5e60-a2f7-32ac7594d195', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4e8f0313-250c-5a0c-9ec5-58eafdb7c531', 'dfd88b59-d67b-5f44-a7b3-47132222a6ce', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Activer le suivi CA annuel projeté."], ["Défi", "Anticiper l’atteinte de 80 %, 90 %, 100 % du seuil actif sans affirmer automatiquement un changement de statut."], ["Outil lié", "Reglo AE"], ["Preuve Skills Passport", "Projection CA + source règle."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S04, S05, S09, S10"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
