INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('ee14228e-f360-5e61-9521-68f2e9c7bd36', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'AE-03 — Facturation et preuve de revenu', 'Utiliser les documents commerciaux comme données financières structurées.', NULL, 20, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f18431a4-1216-5723-988e-e72a1d7bf822', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Auto-entrepreneurs"], ["Niveau", "N2-N3"], ["Objectif measurable", "Utiliser les documents commerciaux comme données financières structurées."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d084025b-a323-5b60-a676-9c01261852c3', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Chiffre d’affaires", "Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable.", "[S04] [S05]"], ["Encaissement", "Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés.", "[S14] [S32]"], ["Créance client", "Montant facturé à un client mais non encore encaissé.", "[S15] [S32]"], ["Facture", "Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables.", "[S04], [S05], [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c847393a-cb74-507f-9208-e70e339764e1', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Utiliser les documents commerciaux comme données financières structurées. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('70064c08-e5da-5bca-b1c4-3045bacacfc0', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Chiffre d’affaires — Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable. [S04] [S05]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Encaissement — Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés. [S14] [S32]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Créance client — Montant facturé à un client mais non encore encaissé. [S15] [S32]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Facture — Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables. [S04], [S05], [S32]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bb0193b0-2fdc-59a1-ab2f-30fe0074c006', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Devis. Dans le parcours auto-entrepreneur, devis est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>2. Facture. Une facture est à la fois une pièce commerciale et une preuve de créance ou de vente. Il faut en distinguer la date, le montant, l’objet, le client, les éléments fiscaux et l’état de paiement.</p><p>3. Avoir. Dans le parcours auto-entrepreneur, avoir est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>4. Paiement. Dans le parcours auto-entrepreneur, paiement est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>5. Historique client. « Historique client » doit être analysé à partir de la dépendance, du délai d''encaissement, de la qualité documentaire et du risque d''impayé. Une croissance du chiffre d''affaires peut dégrader le cash si les créances augmentent trop vite.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b37091b4-4925-5ed1-8060-db46a7e20931', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier l’éligibilité et la règle active.</p><p>Étape 2. Tracer le chiffre d’affaires et les factures.</p><p>Étape 3. Séparer provision fiscale/sociale et cash disponible.</p><p>Étape 4. Calculer prix, marge et temps.</p><p>Étape 5. Préparer les preuves nécessaires pour grandir ou demander un financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('148dc548-295f-5bc9-8642-ffbf3e17b9b7', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Facturation et preuve de revenu », relevez les données disponibles, identifiez au moins quatre notions parmi Chiffre d’affaires, Encaissement, Créance client, Facture, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8b86736a-785a-5491-906e-87672abbab23', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un développeur indépendant facture 120 000 DA, reçoit 60 000 DA à la commande puis 60 000 DA à la livraison. FINCLUDIA distingue facture, deux paiements et solde.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fb6951cd-7a20-5177-a140-0a9b7b24e76f', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Facture 150 000 DA ; paiements 50 000 et 40 000. Calculer solde.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f89a5c93-9365-5153-9e41-680184b13da1', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>60 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('27851079-894c-51ae-b716-81e2d20cb919', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4969a072-45e4-535d-8885-ab7e35f1bc2f', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1600cdb1-4586-500c-875f-4667d05cf21f', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('24b070a7-a884-53dd-8cb7-326abc519207', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('898e2981-63ed-5c30-ae06-9e619d6a59ac', 'ee14228e-f360-5e61-9521-68f2e9c7bd36', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un cycle devis→facture→paiement."], ["Défi", "100 % des factures du mois rapprochées."], ["Outil lié", "Facturation Lite"], ["Preuve Skills Passport", "Cycle documenté."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S04, S05, S14, S15, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
