INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('95e02803-abc4-5c5d-9265-e6896621616a', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'AE-04 — Cashbox auto-entrepreneur', 'Transformer le CA en cash réellement utilisable.', NULL, 21, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e4d7f087-cc89-53ea-9a37-49a28e2adf5a', '95e02803-abc4-5c5d-9265-e6896621616a', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Auto-entrepreneurs"], ["Niveau", "N2-N3"], ["Objectif measurable", "Transformer le CA en cash réellement utilisable."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bc008a8b-fbe5-5e70-9c4b-e12e1bef3196', '95e02803-abc4-5c5d-9265-e6896621616a', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["IFU", "Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur.", "[S04]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Auto-entrepreneur", "Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles.", "[S09], [S10]"], ["Encaissement", "Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés.", "[S14], [S32]"], ["Provision", "Somme mise progressivement de côté pour une dépense future prévisible, même si elle n’est pas encore exigible.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2d23c1cd-42ac-5f79-aacf-7a8444d102a8', '95e02803-abc4-5c5d-9265-e6896621616a', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Transformer le CA en cash réellement utilisable. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e4a8d00e-fdb6-56e5-897e-5e8a461e371c', '95e02803-abc4-5c5d-9265-e6896621616a', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>IFU — Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur. [S04]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Auto-entrepreneur — Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles. [S09], [S10]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Encaissement — Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés. [S14], [S32]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Provision — Somme mise progressivement de côté pour une dépense future prévisible, même si elle n’est pas encore exigible. [S32]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bbb041cc-fedb-5fd4-8611-381e3cc01d63', '95e02803-abc4-5c5d-9265-e6896621616a', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Encaissements. Une vente n’est pas un encaissement tant que l’argent n’est pas effectivement reçu. Cette distinction est fondamentale pour la trésorerie et le BFR.</p><p>2. Dépenses. Une dépense fixe revient de manière régulière et son montant est connu ou peu variable. Elle réduit la marge de manœuvre à court terme et doit être recensée avant les dépenses flexibles.</p><p>3. Provision. Provisionner consiste à mettre de côté progressivement pour une dépense future prévisible. Une dépense annuelle de 120 000 DA peut ainsi être préparée par une provision de 10 000 DA par mois.</p><p>4. Cash disponible. Dans le parcours auto-entrepreneur, cash disponible est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e6386e61-144b-5229-867c-a1ea7845ff51', '95e02803-abc4-5c5d-9265-e6896621616a', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier l’éligibilité et la règle active.</p><p>Étape 2. Tracer le chiffre d’affaires et les factures.</p><p>Étape 3. Séparer provision fiscale/sociale et cash disponible.</p><p>Étape 4. Calculer prix, marge et temps.</p><p>Étape 5. Préparer les preuves nécessaires pour grandir ou demander un financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aa89f4b7-0a08-550e-9d7e-ad12ee87a6a9', '95e02803-abc4-5c5d-9265-e6896621616a', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Cashbox auto-entrepreneur », relevez les données disponibles, identifiez au moins quatre notions parmi Trésorerie, IFU, Dépense, Auto-entrepreneur, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3e6ccde2-8027-5eb3-a34c-7f8c4e298094', '95e02803-abc4-5c5d-9265-e6896621616a', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un AE encaisse 300 000 DA, dépense 90 000 DA et réserve 20 000 DA de provision interne : cash disponible pédagogique = 190 000 DA.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('feb4be68-bec2-51a7-bcf6-1de5111f794e', '95e02803-abc4-5c5d-9265-e6896621616a', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Encaissements 450 000, dépenses 150 000, provision 30 000 : cash restant ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cea4b32b-9606-5189-9d2f-f64795838ba4', '95e02803-abc4-5c5d-9265-e6896621616a', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>270 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('50928eb2-1f64-57e8-94a7-0eab9c520b2c', '95e02803-abc4-5c5d-9265-e6896621616a', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0875cfbf-39e0-5d7a-8599-27cde3fa6480', '95e02803-abc4-5c5d-9265-e6896621616a', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
