INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('579a0316-a364-58c2-826e-62f3e6ba7c5d', '95e02803-abc4-5c5d-9265-e6896621616a', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ce4187c8-b0e6-55de-a494-b1344e32fbc9', '95e02803-abc4-5c5d-9265-e6896621616a', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Configurer Cashbox."], ["Défi", "Suivre 30 jours de cash sans mélange perso/pro."], ["Outil lié", "Cashbox"], ["Preuve Skills Passport", "Mois cash complet."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S04, S14, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
