INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('e72298f0-a61a-52ef-9199-ff33ffbe6814', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'AE-07 — Financement et capacité documentaire', 'Préparer un dossier de financement sans produire un score bancaire officiel.', NULL, 24, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b2cece7a-b5be-5dee-b859-8243b8960891', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Auto-entrepreneurs"], ["Niveau", "N2-N3"], ["Objectif measurable", "Préparer un dossier de financement sans produire un score bancaire officiel."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4b318506-5ca0-5871-8107-86216ced3ce8', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Chiffre d’affaires", "Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable.", "[S04] [S05]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Encaissement", "Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés.", "[S14], [S32]"], ["Besoin", "Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer.", "[S01], [S32]"], ["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('23257701-0e75-5b90-ab19-8e968008caea', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Préparer un dossier de financement sans produire un score bancaire officiel. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('215e14cc-34da-5469-a5fd-cfcbb8f14791', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Chiffre d’affaires — Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable. [S04] [S05]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Encaissement — Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés. [S14], [S32]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Besoin — Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer. [S01], [S32]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Dette — Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. [S01], [S32]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9a9606ff-1236-54c5-9312-22f11845b0da', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Historique CA. Dans le parcours auto-entrepreneur, historique ca est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>2. Encaissements. Une vente n’est pas un encaissement tant que l’argent n’est pas effectivement reçu. Cette distinction est fondamentale pour la trésorerie et le BFR.</p><p>3. Dettes. « Dettes » doit être relié à la nature et à la durée du besoin, au coût total, aux garanties éventuelles et à la capacité de remboursement. Une mensualité faible n''est pas suffisante pour juger la qualité d''un financement.</p><p>Repère de calcul. Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>4. Apport. L’apport représente les ressources propres mobilisées par le porteur du projet ou l’entreprise. Il réduit le montant à financer mais diminue aussi les liquidités disponibles ; il faut donc préserver une marge de sécurité.</p><p>5. Documents. Les documents rendent la situation financière vérifiable : factures, relevés, états financiers, contrats, justificatifs fiscaux ou commerciaux. Un dossier incomplet augmente l’incertitude du financeur et peut retarder la décision.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1255bbe3-a99f-5816-8496-14a34296d899', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier l’éligibilité et la règle active.</p><p>Étape 2. Tracer le chiffre d’affaires et les factures.</p><p>Étape 3. Séparer provision fiscale/sociale et cash disponible.</p><p>Étape 4. Calculer prix, marge et temps.</p><p>Étape 5. Préparer les preuves nécessaires pour grandir ou demander un financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e747874e-1720-59c5-be9b-da59a25d77c4', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c796dead-99cd-5325-a0a7-df714fd9a429', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Financement et capacité documentaire », relevez les données disponibles, identifiez au moins quatre notions parmi Trésorerie, Chiffre d’affaires, Risque financier, Encaissement, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e512e732-2d42-5730-9571-82b38fb70924', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un AE avec 24 mois d’historique facturé/encaissé peut préparer un dossier plus explicable qu’un utilisateur sans historique, mais la banque conserve sa propre décision.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e913be38-81f5-5c31-a01d-0e780f11cab1', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Lister les 8 pièces/données que vous présenteriez à un financeur.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('65998e16-cfef-5765-b86a-3f38c586d5d1', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>L’exercice valorise cohérence, historique, besoin, capacité et justificatifs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bfee5cc5-38c3-5fd2-8bbe-871dab143ce8', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aa0051e4-ae55-5357-93e7-de50e98859a1', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
