INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('73d0dcbb-0790-5a90-ae6e-8423ce286353', 'e72298f0-a61a-52ef-9199-ff33ffbe6814', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Générer un Pro Passport."], ["Défi", "Atteindre 100 % de la checklist avant demande."], ["Outil lié", "Funding"], ["Preuve Skills Passport", "Passport financement."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S04, S05, S14, S22, S30"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
