INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('d6bff651-6593-5ac5-9f1d-759b963274cb', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'AE-08 — Grandir au-delà du statut', 'Identifier les signaux qui imposent de vérifier un changement de régime ou structure.', NULL, 25, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4ececd8a-3fc0-5ab0-8fa4-3638efc7b9a4', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Auto-entrepreneurs"], ["Niveau", "N2-N3"], ["Objectif measurable", "Identifier les signaux qui imposent de vérifier un changement de régime ou structure."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2e8bbaeb-50d9-5990-bcb4-865a976b76ec', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Auto-entrepreneur", "Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles.", "[S09] [S10]"], ["IFU", "Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur.", "[S04]"], ["Business model", "Description de la manière dont l’entreprise crée son offre, la délivre à ses clients et génère des revenus.", "[S17]"], ["Besoin", "Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer.", "[S01], [S32]"], ["CAPEX", "Dépense d’investissement destinée à acquérir ou améliorer un actif utilisé durablement dans l’activité.", "[S13], [S42]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8af5b609-75cb-5d9b-b8a0-7d2f17d9aec3', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Identifier les signaux qui imposent de vérifier un changement de régime ou structure. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('36004884-279c-5bd9-bba1-1cc65b055955', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Auto-entrepreneur — Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles. [S09] [S10]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>IFU — Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur. [S04]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Business model — Description de la manière dont l’entreprise crée son offre, la délivre à ses clients et génère des revenus. [S17]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>Besoin — Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer. [S01], [S32]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p><p>CAPEX — Dépense d’investissement destinée à acquérir ou améliorer un actif utilisé durablement dans l’activité. [S13], [S42]</p><p>Application dans ce module. La compétence combine gestion simple, preuve de chiffre d’affaires, facturation, trésorerie et vérification des règles actives du statut ; les seuils et taux ne sont jamais mémorisés comme permanents.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d59e7b19-2ad3-5b39-adba-018bc2812421', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Croissance CA. Dans le parcours auto-entrepreneur, croissance ca est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>2. Recrutement. Dans le parcours auto-entrepreneur, recrutement est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>3. Investissement. Dans le parcours auto-entrepreneur, investissement est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>4. Besoin de capital. Dans le parcours auto-entrepreneur, besoin de capital est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p><p>5. Régime fiscal futur. Dans le parcours auto-entrepreneur, régime fiscal futur est traité avec une logique de simplicité et de preuve : documenter le chiffre d''affaires, isoler les obligations, suivre le cash et vérifier la règle officielle avant toute décision dépendant d''un seuil ou d''un taux.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('96913bff-297d-58b9-8796-4f7cb385d833', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier l’éligibilité et la règle active.</p><p>Étape 2. Tracer le chiffre d’affaires et les factures.</p><p>Étape 3. Séparer provision fiscale/sociale et cash disponible.</p><p>Étape 4. Calculer prix, marge et temps.</p><p>Étape 5. Préparer les preuves nécessaires pour grandir ou demander un financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('16e4b933-25e7-5660-83b5-9dd7254a4014', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Grandir au-delà du statut », relevez les données disponibles, identifiez au moins quatre notions parmi Auto-entrepreneur, IFU, Business model, Besoin, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e02d2435-8052-5c75-9cd0-7eb40a17bfb5', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un AE proche du seuil actif pendant plusieurs exercices doit consulter les règles en vigueur avant de poursuivre sa croissance ; FINCLUDIA déclenche une alerte réglementaire et non une transformation automatique.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2ec73269-92f7-5cd0-9b6d-4dac4385c822', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Créer 5 signaux de croissance qui justifient une revue du statut.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e4ba9301-e859-5729-aa7f-8a06f8ec2cc0', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Exemples : CA, embauche, CAPEX, associés, financement important.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ea4c5975-847f-5bff-8d37-55093be933c0', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ca05fa14-b40d-5305-8062-dcd83aefd49f', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5bc3d2ad-c808-5f2b-b4b7-153227156d77', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fd67e85d-8c2d-5ce7-8beb-8c73ae4122d3', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('30ccd5e4-e349-564d-8f79-d77bb5f3068b', 'd6bff651-6593-5ac5-9f1d-759b963274cb', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un rappel de revue annuelle du statut."], ["Défi", "Simuler une transition vers microentreprise/société."], ["Outil lié", "Reglo"], ["Preuve Skills Passport", "Rapport de transition."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S04, S09, S10, S17"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
