INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('60d8e956-9668-5e91-9eaf-81f9f7d558d8', '3db6ae40-94e7-5448-9d2a-6faee68c32b7', 'Cas intégrateur corrigé — Professionnels indépendants', NULL, NULL, 26, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('26b35fb6-e1fe-579d-aa8a-3f1011ed0317', '60d8e956-9668-5e91-9eaf-81f9f7d558d8', 'text', 1, '{"html": "<h3>Scénario\\nUne consultante facture 420 000 DA sur un mois mais n’encaisse que 300 000 DA. Ses coûts directs sont de 90 000 DA, ses charges fixes de 140 000 DA et elle réserve 45 000 DA pour obligations fiscales/sociales. Créances clients fin de mois : 180 000 DA.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d66907de-c003-587d-a31b-6127f284708a', '60d8e956-9668-5e91-9eaf-81f9f7d558d8', 'text', 2, '{"html": "<h2>Travail demandé</h2><p>1. Distinguer chiffre d’affaires, encaissements et trésorerie.</p><p>2. Calculer une marge pédagogique après coûts directs.</p><p>3. Calculer le solde de trésorerie simplifié après encaissements, charges fixes, coûts directs et réserve.</p><p>4. Expliquer le risque de créances clients.</p><p>5. Proposer deux actions de pilotage sans confondre revenu personnel et CA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4f8025fd-548d-5b5e-b57a-901fcda5dd41', '60d8e956-9668-5e91-9eaf-81f9f7d558d8', 'text', 3, '{"html": "<h2>Corrigé-type</h2><p>CA = 420 000 DA ; encaissements = 300 000 DA. Marge après coûts directs = 330 000 DA. Cash simplifié du mois = 300 000 - 90 000 - 140 000 - 45 000 = 25 000 DA avant autres flux. Les 180 000 DA de créances ne sont pas encore du cash. Actions : relance/conditions d’acompte et plan de trésorerie ; rémunération personnelle fixée à partir du cash disponible et non du CA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('abc2418e-0f93-5a51-9637-a4c3c984ca71', '60d8e956-9668-5e91-9eaf-81f9f7d558d8', 'table', 4, '{"headers": ["Critère", "Poids"], "rows": [["Exactitude technique / calculs", "35 %"], ["Interprétation et décision", "25 %"], ["Gestion du risque / conformité", "20 %"], ["Traçabilité et sources", "10 %"], ["Clarté de l’explication", "10 %"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b6d313b5-bf24-5620-89d4-d25e14e39199', '60d8e956-9668-5e91-9eaf-81f9f7d558d8', 'text', 5, '{"html": "<h3>Validation du cas intégrateur\\nSeuil : 75 %. Une erreur critique de sécurité, conformité, fraude, règle réglementaire active ou confusion réel/fictif doit être corrigée avant validation, même si le score global atteint 75 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'academy-entrepreneuriat-startup', 'FINCLUDIA Academy — Entrepreneuriat & startup', 'Problème client, business model, Projet Innovant, revenus récurrents, burn/runway, unit economics, cap table, financement et gouvernance.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Entrepreneuriat & startup', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'intermediate', '["START-01 — De l’idée au problème client", "START-02 — Construire le business model", "START-03 — Préparer un Projet Innovant", "START-04 — MRR, ARR et croissance récurrente", "START-05 — Burn et runway", "START-06 — Unit economics : CAC, LTV, churn", "START-07 — Cap table, valorisation et dilution", "START-08 — Financement startup", "START-09 — Label Startup et préparation du dossier", "START-10 — Data room et gouvernance"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '[]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('858bd904-b9f5-57f9-8569-1ab843192459', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'START-01 — De l’idée au problème client', 'Éviter de partir d’une solution sans problème vérifié.', NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ae91daa6-a664-5c78-8eb7-8ec0bae7b332', '858bd904-b9f5-57f9-8569-1ab843192459', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Porteurs de projets, startuppers"], ["Niveau", "N2-N4"], ["Objectif measurable", "Éviter de partir d’une solution sans problème vérifié."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e677e020-3ed8-528d-be92-0945945f79a7', '858bd904-b9f5-57f9-8569-1ab843192459', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Business model", "Description de la manière dont l’entreprise crée son offre, la délivre à ses clients et génère des revenus.", "[S17]"], ["Projet innovant", "Parcours de labellisation comportant notamment description du projet, innovation, pitch deck, prototype, avancement et modèle économique.", "[S12]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('81201eb4-fc53-50b2-8990-35321e445102', '858bd904-b9f5-57f9-8569-1ab843192459', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Éviter de partir d’une solution sans problème vérifié. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('58bfcfd0-2b8f-5a15-90b7-ea9339be79e8', '858bd904-b9f5-57f9-8569-1ab843192459', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Business model — Description de la manière dont l’entreprise crée son offre, la délivre à ses clients et génère des revenus. [S17]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Projet innovant — Parcours de labellisation comportant notamment description du projet, innovation, pitch deck, prototype, avancement et modèle économique. [S12]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e8d51b10-48f1-5921-8aa5-ebd64d0ec467', '858bd904-b9f5-57f9-8569-1ab843192459', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Problème. Dans une startup, problème n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>2. Segment client. « Segment client » doit être analysé à partir de la dépendance, du délai d''encaissement, de la qualité documentaire et du risque d''impayé. Une croissance du chiffre d''affaires peut dégrader le cash si les créances augmentent trop vite.</p><p>3. Hypothèses. « Hypothèses » se travaille par scénarios. L''utilisateur fixe une hypothèse de base, une hypothèse défavorable et, si utile, une hypothèse favorable ; il compare ensuite les effets sur le budget, le cash, la marge ou le risque.</p><p>4. Entretiens terrain. Dans une startup, entretiens terrain n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('32782750-dfb8-5ffe-af6a-7af85a9ec243', '858bd904-b9f5-57f9-8569-1ab843192459', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Formuler une hypothèse mesurable.</p><p>Étape 2. Choisir un indicateur directement lié à l’hypothèse.</p><p>Étape 3. Mesurer traction, unit economics et cash.</p><p>Étape 4. Tester un scénario de croissance ou de financement.</p><p>Étape 5. Documenter les résultats dans la data room et le tableau de bord.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e1fd863a-10a9-5f6c-9f98-b1569dd1c6ed', '858bd904-b9f5-57f9-8569-1ab843192459', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « De l’idée au problème client », relevez les données disponibles, identifiez au moins quatre notions parmi Business model, Projet innovant, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('acafa58e-091f-570b-a940-f4d8dd9e3531', '858bd904-b9f5-57f9-8569-1ab843192459', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un porteur de projet à Alger imagine une application de gestion de files d’attente. Avant de développer, il interroge 20 commerces et établissements pour vérifier la douleur, la fréquence et la volonté d’adopter une solution.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eccba505-bdf1-5a4c-b942-9a6ba5fb111c', '858bd904-b9f5-57f9-8569-1ab843192459', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Écrire 5 hypothèses à valider avant de construire le produit.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bdbb65b6-5125-5bbe-9467-87bf446cdc5e', '858bd904-b9f5-57f9-8569-1ab843192459', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Les hypothèses doivent couvrir problème, client, usage, valeur et paiement/adoption.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('70aa5b14-afa3-5919-9c09-0a8595c67108', '858bd904-b9f5-57f9-8569-1ab843192459', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('681299f8-88c9-5b5d-a629-c5893e7fdf34', '858bd904-b9f5-57f9-8569-1ab843192459', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ad006923-c9f3-5b21-ab11-9b38cf357db4', '858bd904-b9f5-57f9-8569-1ab843192459', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e2545bb3-7ff7-5170-82c1-138b83c9887e', '858bd904-b9f5-57f9-8569-1ab843192459', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('221bef04-a1f8-5799-93f7-632daf5cd86a', '858bd904-b9f5-57f9-8569-1ab843192459', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Réaliser 10 entretiens."], ["Défi", "Obtenir 3 preuves concrètes d’intérêt."], ["Outil lié", "Projet innovant"], ["Preuve Skills Passport", "Synthèse interviews."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S12, S17"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
