INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('d61579a8-fbd1-5d6b-8087-0627d6a6fbfd', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'START-02 — Construire le business model', 'Décrire comment le projet crée, délivre et capte de la valeur.', NULL, 2, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('40d8a3d5-3554-572f-8c82-99203ed094b6', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Porteurs de projets, startups"], ["Niveau", "N2-N4"], ["Objectif measurable", "Décrire comment le projet crée, délivre et capte de la valeur."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9d699179-c26d-5ca4-810c-a62ab09dff1b', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Business model", "Description de la manière dont l’entreprise crée son offre, la délivre à ses clients et génère des revenus.", "[S17]"], ["Chiffre d’affaires", "Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable.", "[S04] [S05]"], ["Charge variable", "Charge qui évolue avec le volume d’activité, par exemple certains achats de marchandises ou matières.", "[S16]"], ["Charge fixe", "Charge qui ne varie pas directement avec le volume d’activité à court terme, par exemple certains loyers ou abonnements.", "[S16]"], ["Facture", "Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables.", "[S04], [S05], [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"], ["Offre", "Quantité d’un bien ou service que les producteurs sont disposés à proposer selon les prix et autres conditions.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('53316caf-c107-5d37-a392-13567c578974', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Décrire comment le projet crée, délivre et capte de la valeur. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2f0b56ae-9769-5aad-b1b4-aa6705e5c72f', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Business model — Description de la manière dont l’entreprise crée son offre, la délivre à ses clients et génère des revenus. [S17]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Chiffre d’affaires — Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable. [S04] [S05]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Charge variable — Charge qui évolue avec le volume d’activité, par exemple certains achats de marchandises ou matières. [S16]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Charge fixe — Charge qui ne varie pas directement avec le volume d’activité à court terme, par exemple certains loyers ou abonnements. [S16]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Facture — Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables. [S04], [S05], [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Offre — Quantité d’un bien ou service que les producteurs sont disposés à proposer selon les prix et autres conditions. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ded43296-71fe-554c-ad40-218e6178957b', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Proposition de valeur. Dans une startup, proposition de valeur n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>2. Clients. « Clients » doit être analysé à partir de la dépendance, du délai d''encaissement, de la qualité documentaire et du risque d''impayé. Une croissance du chiffre d''affaires peut dégrader le cash si les créances augmentent trop vite.</p><p>3. Canaux. Dans une startup, canaux n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>4. Revenus. Un revenu fixe ou relativement stable est attendu avec une fréquence prévisible. Il peut servir de base au budget, alors qu’un revenu variable ou ponctuel doit être traité plus prudemment pour éviter de financer des charges permanentes avec une ressource incertaine.</p><p>5. Ressources et coûts. Pour « Ressources et coûts », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1732d8d9-9735-54da-9ac0-9cb67e7aa824', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Formuler une hypothèse mesurable.</p><p>Étape 2. Choisir un indicateur directement lié à l’hypothèse.</p><p>Étape 3. Mesurer traction, unit economics et cash.</p><p>Étape 4. Tester un scénario de croissance ou de financement.</p><p>Étape 5. Documenter les résultats dans la data room et le tableau de bord.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eceb9a05-dc76-5774-97aa-39f6fd5628c3', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Construire le business model », relevez les données disponibles, identifiez au moins quatre notions parmi Business model, Chiffre d’affaires, Charge variable, Charge fixe, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('706f4812-30a3-5ecc-9c20-42e0ffafbbd0', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une startup SaaS algérienne facture des abonnements B2B mensuels. Son business model précise qui paie, combien, pourquoi, par quel canal et quels coûts sont nécessaires pour servir le client.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c55df64e-ba0d-5011-a1c0-44eff619352e', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Décrire en 10 lignes comment un projet fictif gagne de l’argent.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('45705899-1039-52ef-b6f3-7461c8c0f6dd', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Le modèle doit contenir offre, client, revenu, canal et coûts principaux.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('86f0ea39-707b-58b3-aded-2e6abbb253c4', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ad31748-7f89-5cb4-a451-a40dcbf0385f', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5355e4ff-bdee-50d8-bc37-c9d5b13d9f37', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('063c9ddd-e543-5fd6-a261-25475a1d7834', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5acb9064-41d9-5863-b53a-4af8704f7fc7', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Compléter le Business Model FINCLUDIA."], ["Défi", "Tester le modèle auprès de 5 clients potentiels."], ["Outil lié", "Startup Lab"], ["Preuve Skills Passport", "Business model complété."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S04, S05, S16, S17"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('5e8ad5a5-1cae-585f-bfb8-41f6fb3af5a6', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'course', 'd61579a8-fbd1-5d6b-8087-0627d6a6fbfd', 'QCM — START-02', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('302e95d7-cb1e-5726-a1c4-18fecb5c1281', '5e8ad5a5-1cae-585f-bfb8-41f6fb3af5a6', 'single', 1, 'Quelle proposition définit le mieux « Business model » ?', 'La bonne réponse reprend la définition maître du concept « Business model ».', 1, '[]');
