INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('29e6b3a7-b73e-592a-83ea-c39bca55a7f7', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'START-03 — Préparer un Projet Innovant', 'Construire les pièces et preuves attendues dans le parcours de labellisation.', NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1172e4b3-5492-5b50-bc41-e29964f6af98', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Porteurs de projets"], ["Niveau", "N2-N4"], ["Objectif measurable", "Construire les pièces et preuves attendues dans le parcours de labellisation."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('53542e84-643b-522f-9599-15b2c13754ff', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Projet innovant", "Parcours de labellisation comportant notamment description du projet, innovation, pitch deck, prototype, avancement et modèle économique.", "[S12]"], ["Business model", "Description de la manière dont l’entreprise crée son offre, la délivre à ses clients et génère des revenus.", "[S17]"], ["Demande", "Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('60fab164-6685-524f-96c7-a6df31f9f10a', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Construire les pièces et preuves attendues dans le parcours de labellisation. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('507f8af6-1851-51c2-a974-dc70506180c3', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Projet innovant — Parcours de labellisation comportant notamment description du projet, innovation, pitch deck, prototype, avancement et modèle économique. [S12]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Business model — Description de la manière dont l’entreprise crée son offre, la délivre à ses clients et génère des revenus. [S17]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Demande — Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bd8f1a3f-b58f-55a7-85a9-176d5498c298', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Description courte. Dans une startup, description courte n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>2. Innovation. Dans une startup, innovation n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>3. Pitch deck. Dans une startup, pitch deck n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>4. Prototype. Dans une startup, prototype n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>5. Avancement. Dans une startup, avancement n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>6. Modèle B2B/B2C/B2G. Dans une startup, modèle b2b/b2c/b2g n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>7. Propriété intellectuelle. Dans une startup, propriété intellectuelle n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('36fa6f4f-f05e-5b65-9e6a-ea9604a14c38', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Formuler une hypothèse mesurable.</p><p>Étape 2. Choisir un indicateur directement lié à l’hypothèse.</p><p>Étape 3. Mesurer traction, unit economics et cash.</p><p>Étape 4. Tester un scénario de croissance ou de financement.</p><p>Étape 5. Documenter les résultats dans la data room et le tableau de bord.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e3b6b1b1-0b0f-53cd-8411-6efb711487b4', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Préparer un Projet Innovant », relevez les données disponibles, identifiez au moins quatre notions parmi Projet innovant, Business model, Demande, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cbea60a5-ff21-578f-aa54-3d4ce0f98306', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Le portail Startup.dz demande aujourd’hui une description, les aspects d’innovation, un pitch deck, une photo du prototype, l’avancement et le modèle économique : FINCLUDIA transforme ces éléments en checklist pédagogique datée.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ba61608e-7eef-59e1-81ab-450cd7c50529', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Créer la checklist des éléments du dossier Projet Innovant.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bef96839-9481-5617-b574-1a2e850a032d', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>La correction doit correspondre aux champs actuellement demandés sur Startup.dz, avec date de vérification.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('13383c53-06d9-5d82-be76-c5ee592eccc8', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6f73d61f-1ede-5016-b071-6223b549df5f', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a61683b0-82c3-57e1-9985-7bcd411be212', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('35f068c9-1d6f-5902-9043-6a5581e48d89', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ec73a011-2252-5997-b3a7-7a49fa9b9bdc', '29e6b3a7-b73e-592a-83ea-c39bca55a7f7', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Préparer un pitch deck."], ["Défi", "Présenter le projet en 5 minutes à un jury fictif."], ["Outil lié", "Projet innovant"], ["Preuve Skills Passport", "Pitch + checklist."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S12, S17"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
