INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('db7ce968-2e86-5d71-aeb8-2cab2a6761a0', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'START-04 — MRR, ARR et croissance récurrente', 'Comprendre les revenus récurrents et leur qualité.', NULL, 4, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0ee66e2f-ff21-5140-b0cd-88b6ca92382d', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Startups à abonnement"], ["Niveau", "N2-N4"], ["Objectif measurable", "Comprendre les revenus récurrents et leur qualité."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7bb1e097-f4c1-52f8-b861-4bf36f003e5b', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["MRR", "Revenu mensuel récurrent utilisé comme indicateur pédagogique pour les modèles à abonnement ; il exclut les revenus non récurrents selon la convention retenue par FINCLUDIA.", "[S32]"], ["ARR", "Annualisation pédagogique du revenu récurrent, souvent calculée à partir du MRR lorsque le modèle et la stabilité des revenus le permettent.", "[S32]"], ["Chiffre d’affaires", "Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable.", "[S04] [S05]"], ["Facture", "Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables.", "[S04], [S05], [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e71fa49b-cce9-54d9-a839-c52887a3ce59', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre les revenus récurrents et leur qualité. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aa9ca91a-87a4-55ba-aa94-d6bd67a959af', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>MRR — Revenu mensuel récurrent utilisé comme indicateur pédagogique pour les modèles à abonnement ; il exclut les revenus non récurrents selon la convention retenue par FINCLUDIA. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>ARR — Annualisation pédagogique du revenu récurrent, souvent calculée à partir du MRR lorsque le modèle et la stabilité des revenus le permettent. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Chiffre d’affaires — Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable. [S04] [S05]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Facture — Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables. [S04], [S05], [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('795f56e7-e067-53ff-a2a9-7eddc2b984f3', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Revenu récurrent. Dans une startup, revenu récurrent n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>2. Nouveaux clients. « Nouveaux clients » doit être analysé à partir de la dépendance, du délai d''encaissement, de la qualité documentaire et du risque d''impayé. Une croissance du chiffre d''affaires peut dégrader le cash si les créances augmentent trop vite.</p><p>3. Expansion. Dans une startup, expansion n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>4. Perte de revenu. Dans une startup, perte de revenu n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('220cda66-79db-54f2-83b2-4e04ec4080b2', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Formuler une hypothèse mesurable.</p><p>Étape 2. Choisir un indicateur directement lié à l’hypothèse.</p><p>Étape 3. Mesurer traction, unit economics et cash.</p><p>Étape 4. Tester un scénario de croissance ou de financement.</p><p>Étape 5. Documenter les résultats dans la data room et le tableau de bord.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('abfbb70b-eb4e-5e29-a8de-27afd3745e0a', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « MRR, ARR et croissance récurrente », relevez les données disponibles, identifiez au moins quatre notions parmi MRR, ARR, Chiffre d’affaires, Facture, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('85809e27-b023-54fa-a6f2-bae1ffb81246', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une startup facture 100 clients à 4 000 DA/mois : MRR brut simple = 400 000 DA si tous les abonnements sont actifs et récurrents selon la convention du produit.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8f69e0b6-4afb-58d6-bf1f-a57e99c33c2b', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>80 clients × 5 000 DA/mois : MRR ? ARR annualisé simple ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a82e3584-c383-5a1c-b877-cafc2e59b640', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>MRR = 400 000 DA ; ARR = 4,8 M DA si l’annualisation est pertinente.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3628da6d-0b5e-5037-80b9-6d20dc71e98d', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3339b97f-1d66-5323-9bc2-35e82f84daa9', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6bc64f20-6f57-5e60-b4db-d00c2b91260b', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('674cd4fe-6765-5291-b6aa-49615cf7362e', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('19d8dc47-4332-5877-a68f-917ff00e5401', 'db7ce968-2e86-5d71-aeb8-2cab2a6761a0', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Construire un tableau MRR sur 6 mois."], ["Défi", "Expliquer trois facteurs de croissance ou baisse du MRR."], ["Outil lié", "Startup Metrics"], ["Preuve Skills Passport", "Courbe MRR."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S04, S05, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
