INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('ebdc34aa-4c88-5638-a0fe-9329fc72960f', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'START-05 — Burn et runway', 'Mesurer la vitesse de consommation de cash et l’horizon de survie.', NULL, 5, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e4bc3531-5cad-5ceb-b40d-4bae8ef75781', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Startups"], ["Niveau", "N2-N4"], ["Objectif measurable", "Mesurer la vitesse de consommation de cash et l’horizon de survie."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e95d90dd-9855-53ba-b095-db93b54373f3', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Burn", "Consommation nette de trésorerie d’une startup sur une période lorsque ses décaissements dépassent ses encaissements.", "[S32]"], ["Runway", "Nombre de mois pendant lesquels une startup peut continuer à fonctionner avec sa trésorerie disponible sous une hypothèse donnée de consommation nette de cash.", "[S32]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Décaissement", "Sortie effective de trésorerie ; il se distingue d’une charge comptable qui peut être constatée à une autre date.", "[S14], [S42]"], ["Encaissement", "Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés.", "[S14], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5dca8423-5579-55ec-9ce3-a4085e5bad0f', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Mesurer la vitesse de consommation de cash et l’horizon de survie. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a8133028-2fcf-58d9-ae21-aa16d0975279', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Burn — Consommation nette de trésorerie d’une startup sur une période lorsque ses décaissements dépassent ses encaissements. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Runway — Nombre de mois pendant lesquels une startup peut continuer à fonctionner avec sa trésorerie disponible sous une hypothèse donnée de consommation nette de cash. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Décaissement — Sortie effective de trésorerie ; il se distingue d’une charge comptable qui peut être constatée à une autre date. [S14], [S42]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Encaissement — Entrée de trésorerie effectivement reçue. Une vente facturée et un encaissement ne sont donc pas nécessairement simultanés. [S14], [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b5082800-e9b4-58a7-9ce5-b3b7b69d7920', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Cash disponible. Dans une startup, cash disponible n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>2. Encaissements. Une vente n’est pas un encaissement tant que l’argent n’est pas effectivement reçu. Cette distinction est fondamentale pour la trésorerie et le BFR.</p><p>3. Décaissements. Dans une startup, décaissements n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>4. Burn net. Le burn net mesure la consommation nette de trésorerie d’une startup sur une période lorsque les sorties dépassent les entrées. Il doit être calculé sur des flux réels et non seulement à partir du budget prévu.</p><p>Repère de calcul. Burn net mensuel = décaissements − encaissements, lorsque les décaissements sont supérieurs.</p><p>5. Runway. Le runway estime combien de mois la startup peut fonctionner avec le cash disponible si son burn reste comparable. Il s’agit d’un indicateur de scénario : une levée, une hausse des ventes ou une nouvelle dépense le modifient immédiatement.</p><p>Repère de calcul. Runway = trésorerie disponible ÷ burn net mensuel, sous hypothèse de burn stable.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('481957ed-5a8b-57c2-a046-1e5f4617baf0', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Formuler une hypothèse mesurable.</p><p>Étape 2. Choisir un indicateur directement lié à l’hypothèse.</p><p>Étape 3. Mesurer traction, unit economics et cash.</p><p>Étape 4. Tester un scénario de croissance ou de financement.</p><p>Étape 5. Documenter les résultats dans la data room et le tableau de bord.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dd9e4377-e791-55d6-83a4-0568a8a9b6e5', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Burn net mensuel = décaissements − encaissements, lorsque les décaissements sont supérieurs.</p><p>Runway = trésorerie disponible ÷ burn net mensuel, sous hypothèse de burn stable.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dc027345-841c-5e4b-a633-76a1fb33d119', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Burn et runway », relevez les données disponibles, identifiez au moins quatre notions parmi Burn, Runway, Trésorerie, Décaissement, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1c7d3b50-1f98-5c74-a774-dc05ef10c161', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une startup dispose de 6 M DA de cash et consomme net 750 000 DA par mois : runway pédagogique = 8 mois si le burn reste constant.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('12c8ea98-db7d-5221-89d5-cbf9a400adae', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Cash 4,2 M DA, burn 600 kDA/mois : runway ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2bd6701b-b67c-5f04-b934-18ba99262f64', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>7 mois.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b18016aa-2dd7-5fd7-bc87-512ebd6a33ab', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('61431947-d076-5c7f-a670-241ee1d23edd', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b9dc6e17-8839-5162-8945-84cd400ddc0a', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
