INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a6560093-28ae-5817-8702-a8b9d84c9dc0', 'ebdc34aa-4c88-5638-a0fe-9329fc72960f', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Calculer burn et runway actuels."], ["Défi", "Runway Game : recrutement + retard levée + baisse revenu."], ["Outil lié", "Runway"], ["Preuve Skills Passport", "Scénario runway."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S14, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
