INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('897f0cda-14cd-5821-9210-0b587b20f29b', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'START-06 — Unit economics : CAC, LTV, churn', 'Relier acquisition, rétention et marge.', NULL, 6, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2877a2fe-f791-5462-8639-f578fcc5e457', '897f0cda-14cd-5821-9210-0b587b20f29b', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Startups"], ["Niveau", "N2-N4"], ["Objectif measurable", "Relier acquisition, rétention et marge."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('002f58a9-be46-52d3-bc6f-40674c80cb55', '897f0cda-14cd-5821-9210-0b587b20f29b', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["CAC", "Coût d’acquisition client : dépenses commerciales/marketing attribuées à l’acquisition divisées par le nombre de nouveaux clients, selon une convention explicite.", "[S32]"], ["LTV", "Valeur économique estimée d’un client sur sa durée de relation, calculée selon les hypothèses de marge et de rétention affichées.", "[S32]"], ["Churn", "Taux de perte de clients ou de revenu récurrent sur une période, selon la convention de calcul affichée.", "[S32]"], ["Marge sur coûts variables", "Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité.", "[S16]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d26fd389-1875-535d-88a1-9cde4ca5464b', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Relier acquisition, rétention et marge. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7331d040-54d1-5d0a-921e-0b8a628e0736', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>CAC — Coût d’acquisition client : dépenses commerciales/marketing attribuées à l’acquisition divisées par le nombre de nouveaux clients, selon une convention explicite. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>LTV — Valeur économique estimée d’un client sur sa durée de relation, calculée selon les hypothèses de marge et de rétention affichées. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Churn — Taux de perte de clients ou de revenu récurrent sur une période, selon la convention de calcul affichée. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Marge sur coûts variables — Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité. [S16]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('83d17424-d296-54b9-9594-7a6bc5ef9b04', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. CAC. Le CAC mesure les ressources consacrées à l’acquisition rapportées aux nouveaux clients attribuables à ces dépenses. La difficulté principale est de définir correctement quelles dépenses inclure et sur quelle période.</p><p>Repère de calcul. CAC = dépenses d’acquisition attribuables ÷ nombre de nouveaux clients acquis sur la période.</p><p>2. Marge client. La marge mesure ce qui reste après certains coûts, selon la convention choisie. Il faut toujours préciser de quelle marge on parle et quels coûts ont été déduits.</p><p>3. Rétention. Dans une startup, rétention n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>4. Churn client/revenu. Le churn mesure la perte de clients ou de revenu récurrent. Il faut préciser s’il s’agit de churn clients ou revenu, car les deux peuvent raconter des histoires différentes lorsque les clients ont des tailles inégales.</p><p>Repère de calcul. Churn = clients perdus sur la période ÷ base de clients au début de période, selon la convention retenue.</p><p>5. Payback pédagogique. Dans une startup, payback pédagogique n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>Repère de calcul. Payback simple = investissement initial ÷ économie ou cash-flow annuel moyen lorsque l’hypothèse de stabilité est acceptable.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9e9cef6f-cf49-5487-8ae9-b78cd25606f9', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Formuler une hypothèse mesurable.</p><p>Étape 2. Choisir un indicateur directement lié à l’hypothèse.</p><p>Étape 3. Mesurer traction, unit economics et cash.</p><p>Étape 4. Tester un scénario de croissance ou de financement.</p><p>Étape 5. Documenter les résultats dans la data room et le tableau de bord.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('28d27f55-4e97-582f-a2fb-d8a95d5b91dd', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Marge sur coûts variables = chiffre d’affaires − charges variables.</p><p>CAC = dépenses d’acquisition attribuables ÷ nombre de nouveaux clients acquis sur la période.</p><p>LTV est une estimation de la valeur économique d’un client sur la durée de relation ; la formule dépend du modèle économique.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('24859339-5587-5f2c-872b-7572ce5c186f', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Unit economics : CAC, LTV, churn », relevez les données disponibles, identifiez au moins quatre notions parmi CAC, LTV, Churn, Marge sur coûts variables, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d1909245-59d5-5759-9d8b-06cc7496b657', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une startup dépense 600 000 DA en acquisition et gagne 60 nouveaux clients attribuables : CAC pédagogique = 10 000 DA/client selon la convention choisie.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('34dba391-33de-55e2-86dc-a905bae69fe2', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Marketing/vente attribuable = 900 000 DA ; 75 nouveaux clients : CAC ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('956a7431-00fc-5682-9068-745c97821d0b', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>12 000 DA/client.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7b95bd9c-7547-591d-aea1-28c3dbbd7fc8', '897f0cda-14cd-5821-9210-0b587b20f29b', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4457b387-0eee-52a8-8713-68b5888c0024', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9ebfb091-0707-536f-8ae2-d38160d4d3d0', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ba47d3f5-7a47-5ba4-8178-234abf22889b', '897f0cda-14cd-5821-9210-0b587b20f29b', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a1e362c1-9b6a-53a9-bf91-885134409170', '897f0cda-14cd-5821-9210-0b587b20f29b', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Calculer CAC et churn sur une période."], ["Défi", "Réduire le CAC simulé de 20 % ou améliorer la rétention et observer l’impact."], ["Outil lié", "Unit Economics"], ["Preuve Skills Passport", "Fiche CAC/LTV/churn."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S16, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
