INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('1b0e3c21-4f32-55da-afb6-abd03e73b6ff', 'aeacca3f-3dbd-59dc-aaf3-05746e411a70', 'single', 1, 'Quelle proposition définit le mieux « CAC » ?', 'La bonne réponse reprend la définition maître du concept « CAC ».', 1, '[]');
