INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'START-07 — Cap table, valorisation et dilution', 'Comprendre la répartition du capital avant une levée.', NULL, 7, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8328768f-e3a2-55e4-ad61-1f3fde145b74', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Startups"], ["Niveau", "N2-N4"], ["Objectif measurable", "Comprendre la répartition du capital avant une levée."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('881ed2e4-9b66-5933-ab82-746cfed76a60', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Cap table", "Tableau de répartition du capital d’une société entre fondateurs, investisseurs et autres détenteurs de titres.", "[S32]"], ["Dilution", "Réduction du pourcentage de détention d’un actionnaire lorsque de nouveaux titres sont émis sans souscription proportionnelle de sa part.", "[S32]"], ["Valorisation pré-money", "Valeur conventionnelle d’une société immédiatement avant une opération d’investissement.", "[S32]"], ["Valorisation post-money", "Valeur conventionnelle après investissement ; dans un modèle simple, pré-money + nouvel investissement.", "[S32]"], ["Action", "Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre.", "[S38], [S41]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d026de5d-df59-5760-9a05-743cf9d454c1', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre la répartition du capital avant une levée. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('495feac4-a34d-546e-9601-4f442ba75fb4', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Cap table — Tableau de répartition du capital d’une société entre fondateurs, investisseurs et autres détenteurs de titres. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Dilution — Réduction du pourcentage de détention d’un actionnaire lorsque de nouveaux titres sont émis sans souscription proportionnelle de sa part. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Valorisation pré-money — Valeur conventionnelle d’une société immédiatement avant une opération d’investissement. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Valorisation post-money — Valeur conventionnelle après investissement ; dans un modèle simple, pré-money + nouvel investissement. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Action — Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre. [S38], [S41]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2a203b6a-b322-5e17-8df6-326fbce29490', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Actionnaires. Dans une startup, actionnaires n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>2. Pré-money. Dans une startup, pré-money n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>3. Investissement. Dans une startup, investissement n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>4. Post-money. Dans une startup, post-money n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>5. Pourcentage investisseur. Dans une startup, pourcentage investisseur n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('56149ce0-dac4-56a7-8db5-a8f9b9712034', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Formuler une hypothèse mesurable.</p><p>Étape 2. Choisir un indicateur directement lié à l’hypothèse.</p><p>Étape 3. Mesurer traction, unit economics et cash.</p><p>Étape 4. Tester un scénario de croissance ou de financement.</p><p>Étape 5. Documenter les résultats dans la data room et le tableau de bord.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aa015888-d552-54bf-942d-a0912237453c', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Part post-money d’un nouvel investisseur = investissement ÷ valorisation post-money dans le cas simple.</p><p>Valorisation post-money = valorisation pré-money + nouvel investissement dans le schéma pédagogique simple.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('78b1f30c-834f-5fc8-b99c-20b7ba94f3af', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Cap table, valorisation et dilution », relevez les données disponibles, identifiez au moins quatre notions parmi Cap table, Dilution, Valorisation pré-money, Valorisation post-money, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('897410be-2874-5196-9bc9-f25aba798a8d', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Startup valorisée 40 M DA pré-money ; investisseur apporte 10 M DA. Post-money simple = 50 M DA et investisseur détient 20 % si l’opération est structurée uniquement sur cette base simple.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('69d7b815-1bbb-5d2f-944e-0d791cce0db0', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Pré-money 30 M, investissement 6 M. Post-money et part théorique ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5ba6fbf5-20c4-5f40-b812-c5a62939e2db', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Post-money = 36 M ; part = 16,67 % dans ce modèle simplifié.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('45ce8927-8ade-5f83-9667-fdfff7411b50', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2a261b8c-0035-5ab4-b84d-0840f0aeca30', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('36a04ce2-44ca-5fdf-b7f4-4496a7c38dfc', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
