INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7cce9ff8-0dbe-5b61-9520-2997c8d978be', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer une cap table avant/après."], ["Défi", "Simuler trois tours de financement."], ["Outil lié", "Cap Table"], ["Preuve Skills Passport", "Cap table scénarisée."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('d662630b-5364-5e3b-9d03-a4f238c017c9', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'course', 'cd18fa7b-8c36-5225-9de3-6fcc69fa7bb8', 'QCM — START-07', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
