INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('d715caf3-4869-5e5c-9c23-5ad71cac8d1a', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'START-08 — Financement startup', 'Comparer bootstrapping, fonds propres, quasi-fonds propres et autres solutions sans promettre d’accès.', NULL, 8, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f9a0ef6f-f530-500e-adc9-9c51e94c5bb8', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Startups"], ["Niveau", "N2-N4"], ["Objectif measurable", "Comparer bootstrapping, fonds propres, quasi-fonds propres et autres solutions sans promettre d’accès."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dcb58e3f-6dca-530b-bb23-8ebdf9fbd0e6', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Business plan", "Dossier structurant le projet, ses hypothèses, son marché et ses prévisions financières, notamment compte de résultat, trésorerie, seuil de rentabilité et financement.", "[S18]"], ["Runway", "Nombre de mois pendant lesquels une startup peut continuer à fonctionner avec sa trésorerie disponible sous une hypothèse donnée de consommation nette de cash.", "[S32]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Dilution", "Réduction du pourcentage de détention d’un actionnaire lorsque de nouveaux titres sont émis sans souscription proportionnelle de sa part.", "[S32]"], ["Besoin", "Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer.", "[S01], [S32]"], ["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01], [S32]"], ["Burn", "Consommation nette de trésorerie d’une startup sur une période lorsque ses décaissements dépassent ses encaissements.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4652ba52-7fbc-5781-9ca4-327c57eb8e48', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comparer bootstrapping, fonds propres, quasi-fonds propres et autres solutions sans promettre d’accès. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6df024b7-7b31-5032-98b5-e6ff5e62bbc4', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Business plan — Dossier structurant le projet, ses hypothèses, son marché et ses prévisions financières, notamment compte de résultat, trésorerie, seuil de rentabilité et financement. [S18]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Runway — Nombre de mois pendant lesquels une startup peut continuer à fonctionner avec sa trésorerie disponible sous une hypothèse donnée de consommation nette de cash. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Dilution — Réduction du pourcentage de détention d’un actionnaire lorsque de nouveaux titres sont émis sans souscription proportionnelle de sa part. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Besoin — Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer. [S01], [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Dette — Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. [S01], [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Burn — Consommation nette de trésorerie d’une startup sur une période lorsque ses décaissements dépassent ses encaissements. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c97b9ac2-0baa-51ef-b0ac-39bb4bd141c3', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Besoin. Un besoin financier est l’objet précis à financer : stock, machine, créance, véhicule, logement ou décalage temporaire de trésorerie. Sa nature, son montant et sa durée économique déterminent les familles de solutions à comparer.</p><p>2. Milestones. Dans une startup, milestones n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>3. Dilution. Dans une startup, dilution n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>Repère de calcul. Part post-money d’un nouvel investisseur = investissement ÷ valorisation post-money dans le cas simple.</p><p>4. Dette vs equity. Ce point demande de comparer des notions proches sans les confondre. Pour « Dette vs equity », l''utilisateur doit identifier le critère qui change — nature du flux, horizon, risque, propriétaire, date ou base de calcul — puis appliquer ce critère à un exemple réel ou fictif.</p><p>Repère de calcul. Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>5. Calendrier. Dans une startup, calendrier n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6d67453f-0261-58d8-b5fe-eb13225de4d5', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Formuler une hypothèse mesurable.</p><p>Étape 2. Choisir un indicateur directement lié à l’hypothèse.</p><p>Étape 3. Mesurer traction, unit economics et cash.</p><p>Étape 4. Tester un scénario de croissance ou de financement.</p><p>Étape 5. Documenter les résultats dans la data room et le tableau de bord.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d55479d7-58ae-564a-a67e-b83abf454933', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>Burn net mensuel = décaissements − encaissements, lorsque les décaissements sont supérieurs.</p><p>Runway = trésorerie disponible ÷ burn net mensuel, sous hypothèse de burn stable.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cde8caa2-9095-56d1-832f-04c97c69bcdf', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Financement startup », relevez les données disponibles, identifiez au moins quatre notions parmi Business plan, Runway, Risque financier, Dilution, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d9a6e40f-b158-55e9-9aa5-928d0764e600', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 9, '{"html": "<h2>Approfondissement intégré — Crowdfunding et fonds propres</h2><ul><li><strong>Publics</strong> : Startups, PME, investisseurs</li><li><strong>Compétences renforcées</strong> : comprendre crowdfunding et equity; calculer dilution; distinguer financement et rendement garanti</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Crowdfunding</strong> : Financement participatif mobilisant plusieurs contributeurs ou investisseurs autour d’un projet selon une forme et un cadre réglementaire déterminés. — [S47]</li><li><strong>Dilution</strong> : Réduction du pourcentage de détention d’un actionnaire lorsque de nouveaux titres sont émis sans souscription proportionnelle de sa part. — [S32]</li><li><strong>Valorisation pré-money</strong> : Valeur conventionnelle d’une société immédiatement avant une opération d’investissement. — [S32]</li><li><strong>Valorisation post-money</strong> : Valeur conventionnelle après investissement ; dans un modèle simple, pré-money + nouvel investissement. — [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4c48343a-0ece-5cd5-a5df-ca068446a4fb', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 10, '{"html": "<h3>Financement participatif</h3><p>Le crowdfunding permet de mobiliser plusieurs participants autour d''un projet selon un cadre et une structure définis. En Algérie, les conseillers en investissement participatif sont encadrés par la COSOB.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('89ebd9ba-aafb-5059-b638-1b0d0039563c', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 11, '{"html": "<h3>Fonds propres</h3><p>Lever des fonds propres ne crée pas une échéance de remboursement comme une dette, mais dilue la participation des fondateurs et partage la valeur future.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9c326db8-70a4-5a7b-b636-6fd5b2f5e76c', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Une startup valorisée 20 M DA avant levée reçoit 5 M DA. À titre pédagogique, la valorisation post-money est 25 M DA et les nouveaux investisseurs représentent 20 % si la transaction suit cette logique simple.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('096ebe6d-bd14-5c51-8794-b92e2820d887', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Simulez trois levées avec valorisations différentes et calculez la dilution.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('318a8d01-cb85-5079-a445-5c646d10e83e', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : dans un modèle simple, post-money = pré-money + investissement ; part du nouvel investisseur = investissement/post-money ; part des anciens associés après opération = pré-money/post-money. Plus la valorisation pré-money est faible à investissement constant, plus la dilution est forte.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('09ed3024-2201-5252-8bce-307f83901f4d', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7b56058b-03de-520e-9bd3-c122a384f0bd', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Lever des fonds propres entraîne généralement :</strong><br>A. Une dilution<br>B. Une mensualité bancaire obligatoire<br>C. Un impôt unique<br>D. Une garantie de succès<br><em>A. Les nouveaux investisseurs reçoivent une part.</em></li><li><strong>2. Le crowdfunding réel en Algérie est :</strong><br>A. Sans cadre<br>B. Encadré notamment par la COSOB pour les CIP<br>C. Un simple blog<br>D. Un dépôt bancaire<br><em>B. Le statut CIP est réglementé.</em></li><li><strong>3. Un rendement crowdfunding est-il garanti ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Seulement pour une startup<br><em>B. Le risque doit être expliqué.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('26858259-b230-5073-9c13-1cbe26496d1c', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une startup ayant 4 mois de runway et un produit non stabilisé peut comparer une levée, une réduction du burn et un financement non dilutif ; FINCLUDIA ne décide pas à sa place.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('42e2137a-c7eb-5f07-b5c2-8de90f630815', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Pour un besoin de 12 M DA, proposer trois familles de financement et leurs compromis.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('54755789-45f1-58a1-9905-f406b933bfb8', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>Réponse attendue : au moins trois familles avec coût, dilution, remboursement et contraintes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('838d7ff2-2df7-5c3e-b30d-7e7f7d280af1', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('44c7d51b-eb1a-56fe-b490-a42a3c430943', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0f148e3d-55b1-5952-a84c-19d2f5b5337e', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('962c55f6-298a-5179-9ba7-c2686b2b7e5a', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('40861f41-ce07-5339-a548-a9ae2ea148d4', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un Funding Plan."], ["Défi", "Relier chaque tranche de financement à un milestone."], ["Outil lié", "Funding Startup"], ["Preuve Skills Passport", "Plan financement."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S18, S22, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('592b5359-7e05-5ef2-a9f7-194963c03b08', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'course', 'd715caf3-4869-5e5c-9c23-5ad71cac8d1a', 'QCM — START-08', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
