INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'START-09 — Label Startup et préparation du dossier', 'Vérifier les critères officiels à date et préparer les pièces.', NULL, 9, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b5f886b8-22b2-5d8f-8092-db92fbebf176', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Startups"], ["Niveau", "N2-N4"], ["Objectif measurable", "Vérifier les critères officiels à date et préparer les pièces."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3b6ea6f2-9450-5300-93a2-443cd09daf4f', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Label Startup", "Label algérien attribué sous conditions portant notamment sur l’âge de la société, l’innovation, le potentiel de croissance, la taille, le capital et le chiffre d’affaires selon le cadre en vigueur.", "[S11]"], ["Projet innovant", "Parcours de labellisation comportant notamment description du projet, innovation, pitch deck, prototype, avancement et modèle économique.", "[S12]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cd94637b-a3ab-541b-8aad-ff07fb8960cc', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Vérifier les critères officiels à date et préparer les pièces. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f9598aea-14e1-52c4-b6f8-785c5c071aee', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Label Startup — Label algérien attribué sous conditions portant notamment sur l’âge de la société, l’innovation, le potentiel de croissance, la taille, le capital et le chiffre d’affaires selon le cadre en vigueur. [S11]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Projet innovant — Parcours de labellisation comportant notamment description du projet, innovation, pitch deck, prototype, avancement et modèle économique. [S12]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('690a3018-68d4-51ba-ad83-3b5f7b0adcbb', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Âge société. Dans une startup, âge société n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>2. Innovation. Dans une startup, innovation n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>3. Croissance. Dans une startup, croissance n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>4. CA plafond fixé par comité. Dans une startup, ca plafond fixé par comité n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>5. Capital. Dans une startup, capital n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>6. Taille. Dans une startup, taille n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8186e4a9-2c11-5709-bea8-b6c28217a4da', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Formuler une hypothèse mesurable.</p><p>Étape 2. Choisir un indicateur directement lié à l’hypothèse.</p><p>Étape 3. Mesurer traction, unit economics et cash.</p><p>Étape 4. Tester un scénario de croissance ou de financement.</p><p>Étape 5. Documenter les résultats dans la data room et le tableau de bord.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('89e9a9e0-27eb-5d34-a55a-fc3aaf57cfbc', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Label Startup et préparation du dossier », relevez les données disponibles, identifiez au moins quatre notions parmi Label Startup, Projet innovant, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('234e6e90-0ac7-591c-a0d6-6258c3dbaf80', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Startup.dz indique actuellement notamment : société de moins de 8 ans, modèle innovant, potentiel de croissance, plafond de CA fixé par le comité, capital détenu à au moins 50 % par les catégories prévues et moins de 250 employés. FINCLUDIA doit dater cette checklist.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('91ea1e4f-f4f4-5bae-a57a-dd738a3eccb9', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Pour un cas fictif, vérifier critère par critère sans conclure juridiquement à l’éligibilité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2216ecd7-59b3-5cfd-b26f-cac7264adaa5', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Le résultat doit être ''compatible / information manquante / non compatible apparent'' avec source et date.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3f54d09e-498a-5a56-8ad1-f54c0e2e219a', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8aa15cf5-5b3b-59c9-a63a-099697907d7c', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('57c0363a-b60c-5160-a87b-dd12b3446d09', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b2e5ce1d-65d7-5f75-b6a4-0b7f23a0ae65', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0cc653c0-feb5-5eb0-9a1d-56489696dff2', '02c2df93-1d44-58ee-a0c5-70d6ce5cd2b2', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Compléter la checklist Startup.dz."], ["Défi", "Résoudre toutes les informations manquantes."], ["Outil lié", "Reglo Startup"], ["Preuve Skills Passport", "Checklist datée."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S11, S12"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
