INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a4413131-d5b3-549f-aec2-fcb21805d5c6', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Startups"], ["Niveau", "N2-N4"], ["Objectif measurable", "Préparer une information structurée pour associés et investisseurs."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c37447d4-dab0-59e0-a63a-26f334ae72fe', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Comptabilité financière", "Système d’organisation de l’information financière permettant de saisir, classer, évaluer et présenter des données donnant une image fidèle de la situation, de la performance et de la trésorerie.", "[S13]"], ["Cap table", "Tableau de répartition du capital d’une société entre fondateurs, investisseurs et autres détenteurs de titres.", "[S32]"], ["Business plan", "Dossier structurant le projet, ses hypothèses, son marché et ses prévisions financières, notamment compte de résultat, trésorerie, seuil de rentabilité et financement.", "[S18]"], ["Data room", "Espace structuré rassemblant les documents utiles à une analyse, une levée de fonds, un audit ou une relation avec un financeur.", "[S18], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ab4b6f27-acb2-5f02-a312-89d785b0419d', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Préparer une information structurée pour associés et investisseurs. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cc37d11d-1cd7-579b-8841-1fece8f76621', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Comptabilité financière — Système d’organisation de l’information financière permettant de saisir, classer, évaluer et présenter des données donnant une image fidèle de la situation, de la performance et de la trésorerie. [S13]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Cap table — Tableau de répartition du capital d’une société entre fondateurs, investisseurs et autres détenteurs de titres. [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Business plan — Dossier structurant le projet, ses hypothèses, son marché et ses prévisions financières, notamment compte de résultat, trésorerie, seuil de rentabilité et financement. [S18]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p><p>Data room — Espace structuré rassemblant les documents utiles à une analyse, une levée de fonds, un audit ou une relation avec un financeur. [S18], [S32]</p><p>Application dans ce module. La notion est utilisée pour tester une hypothèse, mesurer la traction ou le cash, préparer une décision de financement et documenter l’information destinée à l’équipe ou aux investisseurs.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a497ff7d-b2df-5360-a0ca-86a1a1929967', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Statuts. Dans une startup, statuts n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>2. Cap table. Dans une startup, cap table n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>3. Comptes. Dans une startup, comptes n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>4. Contrats. Dans une startup, contrats n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>5. KPI. Dans une startup, kpi n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>6. PI. Le PIB mesure la production finale réalisée sur un territoire pendant une période selon des conventions statistiques. Il renseigne sur l’activité, mais pas directement sur la répartition des revenus ni le bien-être de chaque ménage.</p><p>7. Prévisions. Dans une startup, prévisions n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p><p>8. Décisions. Dans une startup, décisions n''est utile que s''il est relié à une hypothèse mesurable. FINCLUDIA demande de préciser la donnée observée, la période, l''objectif de décision et l''effet attendu sur la traction, l''économie unitaire ou le runway.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5ea02e19-44ab-5a8e-8b5e-0775147c74e0', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Formuler une hypothèse mesurable.</p><p>Étape 2. Choisir un indicateur directement lié à l’hypothèse.</p><p>Étape 3. Mesurer traction, unit economics et cash.</p><p>Étape 4. Tester un scénario de croissance ou de financement.</p><p>Étape 5. Documenter les résultats dans la data room et le tableau de bord.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('56e44d91-8969-5ebf-96b3-a9cc48695631', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Data room et gouvernance », relevez les données disponibles, identifiez au moins quatre notions parmi Comptabilité financière, Cap table, Business plan, Data room, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5a912488-e91a-5cb6-bb7e-c9084fb8778c', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une startup prépare un dossier comprenant statuts, cap table, contrats clients clés, états financiers, KPIs, propriété intellectuelle et prévisionnel. FINCLUDIA vérifie la complétude sans certifier la qualité juridique.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('83a865d0-a7bf-5440-9c46-9a38f8c34dec', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Construire une arborescence de data room en 8 dossiers.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e0b55ced-cf11-50a4-a74d-181d4f9482ab', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Doivent apparaître gouvernance, finance, commercial, juridique, PI, RH, produit et financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('22b3f7cf-47a0-57bb-a72a-1e45d018b094', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('961e3131-e159-50cd-91f5-61f9355284bd', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ea929c67-e719-5f80-b90d-8da9cd80d945', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cf3c3358-7a97-5d47-9b24-d00d6905b22f', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('58797d75-e190-5e15-9e2e-4400be77bcf2', '62f3a11f-22ab-54c5-aefa-b4c85ebc17af', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer la data room checklist."], ["Défi", "Atteindre 90 % de complétude."], ["Outil lié", "Documents Startup"], ["Preuve Skills Passport", "Data room indexée."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S13, S18, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
