INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('8869d553-57a3-540c-9419-90dc2020a1f6', '9a4f92ff-c29d-5c10-95d0-2e3461e2d6cc', 'Cas intégrateur corrigé — Entrepreneuriat & startup', NULL, NULL, 11, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('293d2168-3830-50f5-8de1-63642d5641d3', '8869d553-57a3-540c-9419-90dc2020a1f6', 'text', 1, '{"html": "<h3>Scénario\\nUne startup dispose de 9 M DA de trésorerie. Encaissements mensuels récurrents : 1,2 M DA. Décaissements mensuels : 2,1 M DA. Elle compte 400 clients payants, dépense 600 000 DA/mois en acquisition et envisage une levée de 6 M DA pour 20 % du capital post-opération.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5bc49b15-6122-5e03-8ab9-fdbaa5bed83e', '8869d553-57a3-540c-9419-90dc2020a1f6', 'text', 2, '{"html": "<h2>Travail demandé</h2><p>1. Calculer le burn net mensuel.</p><p>2. Calculer le runway avant levée.</p><p>3. Calculer le CAC pédagogique du mois si 100 nouveaux clients sont acquis.</p><p>4. Calculer la valorisation post-money et pré-money implicites de l’offre.</p><p>5. Expliquer les limites de ces indicateurs et les pièces à mettre dans la data room.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cef881d5-efb9-596e-8308-407a97af7c57', '8869d553-57a3-540c-9419-90dc2020a1f6', 'text', 3, '{"html": "<h2>Corrigé-type</h2><p>Burn net = 2,1 - 1,2 = 0,9 M DA/mois. Runway ≈ 9/0,9 = 10 mois. CAC = 600 000/100 = 6 000 DA/nouveau client. Si 6 M représentent 20 % post-money, post-money = 30 M DA et pré-money = 24 M DA. Ces chiffres sont des indicateurs/scénarios ; ils doivent être reliés à churn, marge, croissance, qualité des revenus et documents de gouvernance.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3860794a-e2c6-5321-b843-324d2f8bcc2e', '8869d553-57a3-540c-9419-90dc2020a1f6', 'table', 4, '{"headers": ["Critère", "Poids"], "rows": [["Exactitude technique / calculs", "35 %"], ["Interprétation et décision", "25 %"], ["Gestion du risque / conformité", "20 %"], ["Traçabilité et sources", "10 %"], ["Clarté de l’explication", "10 %"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ca034184-4b7b-576f-8fd9-099f4733bff8', '8869d553-57a3-540c-9419-90dc2020a1f6', 'text', 5, '{"html": "<h3>Validation du cas intégrateur\\nSeuil : 75 %. Une erreur critique de sécurité, conformité, fraude, règle réglementaire active ou confusion réel/fictif doit être corrigée avant validation, même si le score global atteint 75 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('be5e9d97-a7db-5415-aca7-8d9050d84043', 'academy-finance-dentreprise-pme-pmi', 'FINCLUDIA Academy — Finance d’entreprise, PME & PMI', 'États financiers, marges, BFR, trésorerie, forecast, dette, clients, stocks, coûts industriels, CAPEX, financement et pilotage.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Finance d’entreprise, PME & PMI', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'advanced', '["BUS-01 — Lire les états financiers", "BUS-02 — Rentabilité et marges", "BUS-03 — BFR et cycle du cash", "BUS-04 — Trésorerie 13 semaines", "BUS-05 — Budget, forecast et analyse des écarts", "BUS-06 — Dette, capacité de service et structure financière", "BUS-07 — Clients, concentration et impayés", "BUS-08 — Stock et capital immobilisé", "BUS-09 — Coût industriel et coût de revient", "BUS-10 — Capacité, productivité et qualité", "BUS-11 — CAPEX et décision d’investissement", "BUS-12 — Financement et pack financeur"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '[]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'BUS-01 — Lire les états financiers', 'Comprendre situation financière, performance et trésorerie.', NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('19e44da3-3a65-5f6b-ad32-d026ab9fb28c', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Microentreprises structurées, PME, PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Comprendre situation financière, performance et trésorerie."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9300ac6d-90ed-56f6-926e-57686e3da735', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Comptabilité financière", "Système d’organisation de l’information financière permettant de saisir, classer, évaluer et présenter des données donnant une image fidèle de la situation, de la performance et de la trésorerie.", "[S13]"], ["Flux de trésorerie d’exploitation", "Flux de trésorerie issus principalement des activités génératrices de revenus et des activités qui ne sont ni d’investissement ni de financement.", "[S14]"], ["Flux d’investissement", "Flux liés notamment à l’acquisition ou à la cession d’actifs à long terme et d’investissements non assimilés à de la trésorerie.", "[S14]"], ["Flux de financement", "Flux qui modifient la taille ou la composition des capitaux propres et des emprunts.", "[S14]"], ["Compte de résultat", "État financier présentant produits et charges afin d’expliquer la performance d’une entité sur une période.", "[S13], [S42]"], ["Tableau de flux de trésorerie", "État financier expliquant les flux de trésorerie liés aux activités d’exploitation, d’investissement et de financement.", "[S14]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14], [S30]"], ["Bilan", "État financier présentant la situation patrimoniale et financière d’une entité à une date donnée.", "[S13], [S42]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cabade40-cfb7-5f1e-88c6-e144ea444b5d', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre situation financière, performance et trésorerie. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bd2970bd-4c58-5e69-be27-c5387cdbb003', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Comptabilité financière — Système d’organisation de l’information financière permettant de saisir, classer, évaluer et présenter des données donnant une image fidèle de la situation, de la performance et de la trésorerie. [S13]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Flux de trésorerie d’exploitation — Flux de trésorerie issus principalement des activités génératrices de revenus et des activités qui ne sont ni d’investissement ni de financement. [S14]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Flux d’investissement — Flux liés notamment à l’acquisition ou à la cession d’actifs à long terme et d’investissements non assimilés à de la trésorerie. [S14]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Flux de financement — Flux qui modifient la taille ou la composition des capitaux propres et des emprunts. [S14]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Compte de résultat — État financier présentant produits et charges afin d’expliquer la performance d’une entité sur une période. [S13], [S42]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Tableau de flux de trésorerie — État financier expliquant les flux de trésorerie liés aux activités d’exploitation, d’investissement et de financement. [S14]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14], [S30]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Bilan — État financier présentant la situation patrimoniale et financière d’une entité à une date donnée. [S13], [S42]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a94c6065-dfdb-52a8-8880-080ccac1690b', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Bilan : actifs/passifs. En finance d''entreprise, bilan : actifs/passifs doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>2. Compte de résultat : performance. En finance d''entreprise, compte de résultat : performance doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>3. Tableau de flux : exploitation/investissement/financement. « Tableau de flux : exploitation/investissement/financement » doit être relié à la nature et à la durée du besoin, au coût total, aux garanties éventuelles et à la capacité de remboursement. Une mensualité faible n''est pas suffisante pour juger la qualité d''un financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('75b98e7b-6f3e-574e-b5bb-184bab7c4edd', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Relier bilan, résultat et trésorerie.</p><p>Étape 2. Choisir une période et une définition stable de l’indicateur.</p><p>Étape 3. Calculer puis rapprocher le résultat de l’évolution du cash.</p><p>Étape 4. Tester l’effet d’un choc client, stock, prix ou financement.</p><p>Étape 5. Préparer une décision et les pièces à présenter au financeur ou au comité de gestion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dbea37ec-99f6-5302-9b96-3ced473af30d', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Lire les états financiers », relevez les données disponibles, identifiez au moins quatre notions parmi Comptabilité financière, Flux de trésorerie d’exploitation, Flux d’investissement, Flux de financement, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('02e892b0-3d39-5b53-b8c7-3798f09953ce', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 8, '{"html": "<h2>Approfondissement intégré — Lire un compte de résultat</h2><ul><li><strong>Publics</strong> : Entrepreneurs, dirigeants, étudiants en économie</li><li><strong>Compétences renforcées</strong> : identifier la formation du résultat; comprendre marge et charges; repérer les leviers de performance</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Compte de résultat</strong> : État financier présentant produits et charges afin d’expliquer la performance d’une entité sur une période. — [S13], [S42]</li><li><strong>Chiffre d’affaires</strong> : Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable. — [S04], [S05]</li><li><strong>Marge</strong> : Écart entre un revenu ou chiffre d’affaires et une catégorie de coûts définie. Une marge doit toujours préciser son périmètre : marge brute, marge sur coûts variables, marge nette, etc. — [S47]</li><li><strong>Résultat / benefice</strong> : Excédent des produits sur les charges sur une période ; pour les BNC, la DGI définit le bénéfice comme l’excédent des recettes sur les dépenses nécessaires à l’exercice. — [S06], [S13]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('27e7dc41-0234-5c71-8a01-88782026a279', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 9, '{"html": "<h3>Structure</h3><p>Un compte de résultat explique la performance sur une période : revenus, coûts, charges puis résultat. La présentation exacte dépend du référentiel et de l''entreprise, mais le raisonnement reste : combien l''activité génère et combien elle consomme.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a9c93046-d2f5-56d2-b364-819c3d40ebb0', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 10, '{"html": "<h3>Questions à poser</h3><p>Le CA progresse-t-il ? La marge progresse-t-elle aussi ? Quelles charges augmentent le plus ? Le résultat est-il récurrent ou dépend-il d''un élément exceptionnel ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7dca9ed5-01c7-5fdb-b69c-4d067d51c79e', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'callout', 11, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>CA +10 %, marge brute +4 %, frais généraux +18 % : l''entreprise grandit mais sa structure de coûts se détériore. Le diagnostic ne doit pas s''arrêter à la croissance du CA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f4fa5c38-6284-5dd2-8704-6f5a7ff80881', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 12, '{"html": "<h3>Exercice complémentaire intégré</h3><p>À partir d''un mini compte de résultat fictif, identifiez trois explications possibles à une baisse de résultat malgré une hausse du CA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('51c27f7e-3ac8-540b-82f5-daa5dbeeedb1', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 13, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : trois explications possibles sont 1) baisse du taux de marge ou hausse des coûts directs ; 2) croissance plus rapide des frais généraux ; 3) hausse des charges financières, amortissements ou éléments exceptionnels. Il faut comparer taux et montants, pas seulement le CA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9eb85446-bf37-5edf-a9e2-34d1605334ae', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 14, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('67a9ef06-d53e-53c1-a963-0e12bd619289', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 15, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Le compte de résultat mesure surtout :</strong><br>A. Une performance sur une période<br>B. Le patrimoine à une date<br>C. Le prix de l''action<br>D. Le nombre de salariés<br><em>A. Il montre la formation du résultat sur une période.</em></li><li><strong>2. CA +10 % et résultat -5 % signifie :</strong><br>A. Impossible<br>B. Les coûts/charges ont probablement progressé davantage<br>C. Le bilan est faux<br>D. Le cash est forcément positif<br><em>B. La croissance du revenu ne garantit pas la rentabilité.</em></li><li><strong>3. Une marge en baisse est :</strong><br>A. Un signal à analyser<br>B. Toujours normale<br>C. Un impôt<br>D. Une créance<br><em>A. Elle peut révéler prix, coût ou mix défavorables.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('667b7f6f-e8f8-511a-9f85-4bcdf9e7ee70', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 16, '{"html": "<h2>Approfondissement intégré — Lire un bilan</h2><ul><li><strong>Publics</strong> : Entrepreneurs, dirigeants PME/PMI, étudiants</li><li><strong>Compétences renforcées</strong> : distinguer actif, passif et capitaux propres; comprendre la structure financière; relier bilan et risque</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Bilan</strong> : État financier présentant la situation patrimoniale et financière d’une entité à une date donnée. — [S13], [S42]</li><li><strong>Actif</strong> : Ressource économique détenue ou contrôlée par une personne ou une entité et susceptible de contribuer à sa situation patrimoniale ou à son activité. — [S47]</li><li><strong>Passif</strong> : Obligation ou dette envers un tiers figurant dans la structure financière d’une personne ou d’une entité. — [S47]</li><li><strong>Capitaux propres</strong> : Part résiduelle des actifs d’une entité après déduction de ses passifs, selon les règles comptables applicables. — [S47]</li><li><strong>Patrimoine net</strong> : Valeur des actifs détenus diminuée des dettes et autres passifs retenus. — [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f0f9e0ff-a1fd-5f7c-9b8e-545e1dfe3c39', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 17, '{"html": "<h3>Actif</h3><p>L''actif représente les ressources économiques contrôlées ou utilisées : immobilisations, stocks, créances, trésorerie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ce4c1085-982a-5a38-bf4c-af41c8c53a63', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 18, '{"html": "<h3>Passif et capitaux propres</h3><p>Le passif comprend les dettes et obligations. Les capitaux propres représentent la part résiduelle revenant aux propriétaires après les dettes, selon la logique comptable.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9d259058-347a-53c4-bc9d-6dc7a79294a1', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 19, '{"html": "<h3>Lecture financière</h3><p>Un bilan aide à comprendre la liquidité, le poids de la dette, la dépendance au stock et la solidité des fonds propres.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('98a0430a-5b2a-586a-bed5-344a82faef63', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'callout', 20, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Deux entreprises peuvent avoir le même CA mais des bilans très différents : l''une financée surtout par fonds propres, l''autre très endettée. Leur risque financier n''est pas identique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4067d488-2e7f-53d8-85da-0c60485fb79d', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 21, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Classez 10 postes fictifs entre actif, dette et capitaux propres.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0ace8a96-08d6-5b67-96b7-d63907974056', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 22, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : actif = ressources contrôlées (trésorerie, créances, stocks, immobilisations) ; passif/dettes = obligations envers des tiers ; capitaux propres = part résiduelle. La classification doit s’appuyer sur la nature économique de chaque poste.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f6918810-1722-5615-9228-fe754227b3da', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 23, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5babf759-12e7-5a19-88c4-e8f19b5161d0', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 24, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Une créance client est généralement :</strong><br>A. Un actif<br>B. Une dette bancaire<br>C. Un impôt<br>D. Un dividende<br><em>A. L''entreprise attend un encaissement.</em></li><li><strong>2. Un emprunt bancaire est généralement :</strong><br>A. Un actif<br>B. Une dette<br>C. Un revenu<br>D. Un stock<br><em>B. Il représente une obligation de remboursement.</em></li><li><strong>3. Les capitaux propres servent notamment à analyser :</strong><br>A. La structure financière<br>B. La météo<br>C. Le prix du carburant uniquement<br>D. Le DSO seul<br><em>A. Ils sont une composante importante de la solvabilité.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c66ee364-8845-55a4-ba8b-a165311b847d', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 25, '{"html": "<h2>Approfondissement intégré — Tableau de flux de trésorerie</h2><ul><li><strong>Publics</strong> : Dirigeants PME/PMI, startups, étudiants</li><li><strong>Compétences renforcées</strong> : distinguer flux opérationnels, investissement et financement; identifier l''origine du cash; interpréter un cash-flow négatif</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Tableau de flux de trésorerie</strong> : État financier expliquant les flux de trésorerie liés aux activités d’exploitation, d’investissement et de financement. — [S14]</li><li><strong>Flux de trésorerie d’exploitation</strong> : Flux de trésorerie issus principalement des activités génératrices de revenus et des activités qui ne sont ni d’investissement ni de financement. — [S14]</li><li><strong>Flux d’investissement</strong> : Flux liés notamment à l’acquisition ou à la cession d’actifs à long terme et d’investissements non assimilés à de la trésorerie. — [S14]</li><li><strong>Flux de financement</strong> : Flux qui modifient la taille ou la composition des capitaux propres et des emprunts. — [S14]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8ccc8779-98b9-501f-af14-6d7fdb918392', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 26, '{"html": "<h3>Trois grandes familles</h3><p>Flux opérationnels : activité courante. Flux d''investissement : achat/vente d''actifs et projets. Flux de financement : dette, capital et remboursements.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b733633a-6476-5ac8-b7ba-d4cf68712698', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 27, '{"html": "<h3>Pourquoi c''est crucial</h3><p>Une entreprise peut afficher du bénéfice tout en consommant du cash. Le tableau de flux aide à voir si le cash provient réellement de l''activité ou d''un nouvel emprunt.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8ffaf922-62aa-5f4a-9527-08170651d4ba', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'callout', 28, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Une startup brûle 2 M DA de cash opérationnel mais lève 10 M DA de capital : son cash bancaire augmente malgré une activité encore déficitaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4b11c0a6-9645-5205-8dc5-1722f1f7e84a', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 29, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Classez six mouvements : encaissement client, achat machine, nouvel emprunt, remboursement prêt, paiement fournisseur, augmentation de capital.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c28c0a06-2a24-5174-8e04-b0277a959eea', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 30, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : encaissement client et paiement fournisseur = exploitation ; achat de machine = investissement ; nouvel emprunt, remboursement du principal d’un prêt et augmentation de capital = financement. Les intérêts peuvent être présentés selon la convention comptable retenue.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8865e6c2-d8df-5ad7-a4f1-93b5e196f953', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 31, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8a49bc60-c2f7-564a-a944-d7c03ae36d2b', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 32, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. L''achat d''une machine relève généralement de :</strong><br>A. Opérationnel<br>B. Investissement<br>C. Financement<br>D. Fiscal<br><em>B. C''est un investissement.</em></li><li><strong>2. Un nouvel emprunt relève de :</strong><br>A. Financement<br>B. Stock<br>C. CA<br>D. Dividende<br><em>A. Il apporte une ressource financière.</em></li><li><strong>3. Cash positif = activité rentable ?</strong><br>A. Toujours<br>B. Pas nécessairement<br>C. Oui pour toute startup<br>D. Seulement en banque<br><em>B. Le cash peut venir du financement.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a9b41172-1a26-5bee-be47-80fc583eac54', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 33, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une PME industrielle peut afficher un bénéfice comptable mais une trésorerie tendue si les créances clients et stocks absorbent le cash.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a0fd0c26-1ff3-59b3-81df-704f904e2bbb', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 34, '{"html": "<h2>Exercice d’application</h2><p>Associer 12 postes à bilan, résultat ou flux de trésorerie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7bc10235-e7e4-52fb-9216-bd78155d025b', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 35, '{"html": "<h2>Corrigé-type</h2><p>La correction doit respecter la nature économique du poste ; les flux sont classés exploitation/investissement/financement selon IAS 7 lorsque pertinent pédagogiquement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('25d504aa-5a36-5aae-9c60-35ec05506a71', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'table', 36, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4ae265f7-b5cb-5498-8ce4-c0e3ccf69238', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 37, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0eaaad83-7f2e-5adc-9b10-9226ce421bc0', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 38, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('807d3554-ac90-5f77-b4cc-cec4df94dbd5', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'text', 39, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2954d553-9e39-5b76-b78e-9db6973f52f5', '3bc8077e-b861-5e89-b3fc-3749da3e8fd4', 'table', 40, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Importer un jeu d’états financiers fictifs."], ["Défi", "Expliquer les 5 variations principales."], ["Outil lié", "CFO Cockpit"], ["Preuve Skills Passport", "Lecture commentée."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S13, S14"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
