INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('f8df977c-e05f-589f-90c4-e10fdbdc8e9a', 'fe6984e2-4969-5cd1-af7d-f7de28c8faba', 1, 'Conserver indéfiniment la première valeur trouvée, même si la règle change.', 0);
