INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('ca9e7c14-f035-5cb8-baf2-1fe332ee4037', 'e9126d0e-864d-597e-8f06-9125e71e9a30', 2, 'Le temps passé sur l’écran, sans action de l’utilisateur.', 0);
