INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'BUS-02 — Rentabilité et marges', 'Comprendre où se crée ou se détruit la rentabilité.', NULL, 2, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e135e34c-577f-5536-b9a7-80c6dc7061ec', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Microentreprises, PME, PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Comprendre où se crée ou se détruit la rentabilité."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('01ff6d85-32c9-58ea-ade9-88bd38b5b627', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Résultat / benefice", "Excédent des produits sur les charges sur une période ; pour les BNC, la DGI définit le bénéfice comme l’excédent des recettes sur les dépenses nécessaires à l’exercice.", "[S06] [S13]"], ["Marge sur coûts variables", "Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité.", "[S16]"], ["Chiffre d’affaires", "Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable.", "[S04] [S05]"], ["Dépense variable", "Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('beff85c9-2231-5747-8794-787b96fc9167', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre où se crée ou se détruit la rentabilité. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('50a73740-281e-5129-a6f5-092dba208dce', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Résultat / bénéfice — Excédent des produits sur les charges sur une période ; pour les BNC, la DGI définit le bénéfice comme l’excédent des recettes sur les dépenses nécessaires à l’exercice. [S06] [S13]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Marge sur coûts variables — Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité. [S16]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Chiffre d’affaires — Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable. [S04] [S05]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Dépense variable — Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport. [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('20c10d2c-880f-5413-8fb2-1ddca47e37dd', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Marge brute. La marge mesure ce qui reste après certains coûts, selon la convention choisie. Il faut toujours préciser de quelle marge on parle et quels coûts ont été déduits.</p><p>Repère de calcul. Marge brute = ventes − coûts directement rattachés aux ventes selon la convention de gestion retenue.</p><p>2. Marge sur coûts variables. La marge mesure ce qui reste après certains coûts, selon la convention choisie. Il faut toujours préciser de quelle marge on parle et quels coûts ont été déduits.</p><p>Repère de calcul. Marge sur coûts variables = chiffre d’affaires − charges variables.</p><p>3. Résultat. En finance d''entreprise, résultat doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>4. Rentabilité par produit/client. « Rentabilité par produit/client » doit être analysé à partir de la dépendance, du délai d''encaissement, de la qualité documentaire et du risque d''impayé. Une croissance du chiffre d''affaires peut dégrader le cash si les créances augmentent trop vite.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b62009b7-807b-54e1-a5e9-0615236e9634', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Relier bilan, résultat et trésorerie.</p><p>Étape 2. Choisir une période et une définition stable de l’indicateur.</p><p>Étape 3. Calculer puis rapprocher le résultat de l’évolution du cash.</p><p>Étape 4. Tester l’effet d’un choc client, stock, prix ou financement.</p><p>Étape 5. Préparer une décision et les pièces à présenter au financeur ou au comité de gestion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('34dd0813-254b-5596-b865-d6cefa999cb4', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Marge sur coûts variables = chiffre d’affaires − charges variables.</p><p>Marge brute = ventes − coûts directement rattachés aux ventes selon la convention de gestion retenue.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c237f4c2-561e-5dc7-9063-c66c7a5cc815', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Rentabilité et marges », relevez les données disponibles, identifiez au moins quatre notions parmi Résultat / bénéfice, Marge sur coûts variables, Chiffre d’affaires, Dépense variable, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6ef6a07a-d7e5-580b-b233-689f55748d7e', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 9, '{"html": "<h2>Approfondissement intégré — Ratios financiers essentiels</h2><ul><li><strong>Publics</strong> : Dirigeants, PME/PMI, entrepreneurs</li><li><strong>Compétences renforcées</strong> : calculer les principaux ratios; éviter les seuils universels; comparer dans le temps</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Current ratio</strong> : Ratio de liquidité calculé comme actif courant divisé par passif courant ; son interprétation dépend du secteur, de la saisonnalité et de la qualité des actifs courants. — [S47]</li><li><strong>Quick ratio</strong> : Ratio de liquidité rapide calculé, de façon simplifiée, comme actif courant hors stocks divisé par passif courant. — [S47]</li><li><strong>DSCR</strong> : Debt Service Coverage Ratio : rapport entre un cash-flow disponible selon la convention retenue et le service de la dette sur la période. Il doit être interprété selon le secteur et le financeur. — [S47]</li><li><strong>ROA</strong> : Indicateur rapportant un résultat aux actifs mobilisés. Sa définition exacte dépend de la convention de résultat et d’actifs retenue. — [S47]</li><li><strong>ROE</strong> : Indicateur rapportant un résultat aux capitaux propres. Il doit être analysé avec la structure financière et le niveau de risque. — [S47]</li><li><strong>DSO</strong> : Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période. — [S30], [S32]</li><li><strong>DPO</strong> : Indicateur pédagogique du délai moyen de règlement des fournisseurs, à rapprocher des achats à crédit. — [S32]</li><li><strong>DIO</strong> : Indicateur pédagogique du nombre moyen de jours pendant lesquels le stock reste immobilisé avant sa vente ou consommation. — [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('733cefb7-0c05-54ac-9279-9c24dd332c37', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 10, '{"html": "<h3>Ratios de liquidité</h3><p>Current ratio = actif courant / passif courant. Quick ratio = (actif courant - stocks) / passif courant.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ac7de726-1dfd-5c7a-ae29-b87aacee8463', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 11, '{"html": "<h3>Ratios de dette</h3><p>Dette/EBITDA mesure la dette relativement à une capacité opérationnelle indicative. DSCR compare un cash-flow disponible avec le service de la dette.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4d99b6a0-2ad5-53d9-af4d-971591bc9bed', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 12, '{"html": "<h3>Ratios de rentabilité et BFR</h3><p>Marge brute, marge nette, ROA, ROE, DSO, DPO, DIO et cycle de conversion du cash sont utiles selon le secteur.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('244d3e8c-c8dd-5bcd-8432-74e7cc079c4e', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'callout', 13, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>FINCLUDIA ne doit pas dire « current ratio 1,2 = bon » sans contexte. Le bon niveau dépend du secteur, de la saisonnalité, de l''historique et des exigences éventuelles d''un financeur.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4e7ff551-01b9-5489-b123-f669076ac357', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 14, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Calculez current ratio, quick ratio et DSCR sur un cas fictif. Comparez avec l''année précédente.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('24f36149-b23c-5804-9b69-0eb5dc611270', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 15, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : current ratio = actif courant/passif courant ; quick ratio = (actif courant - stocks)/passif courant ; DSCR = cash-flow disponible/service de la dette. Comparer à l’année précédente et expliquer les variations ; ne pas appliquer un seuil universel sans contexte.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d282c7c6-accd-5361-98cd-a045b405718c', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 16, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f46c9ebf-dcbd-5982-bd26-cdb8ea21ae28', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 17, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Le DSCR sert à apprécier :</strong><br>A. La couverture du service de la dette<br>B. La part des stocks<br>C. Le taux d''inflation<br>D. Le capital social<br><em>A. Il compare flux disponible et service de dette.</em></li><li><strong>2. Un ratio doit être interprété :</strong><br>A. Seul<br>B. Avec historique et contexte<br>C. Sans secteur<br>D. Toujours avec seuil 1<br><em>B. Les seuils universels sont trompeurs.</em></li><li><strong>3. DSO élevé indique souvent :</strong><br>A. Encaissement client plus lent<br>B. Dette fournisseur plus faible<br>C. Plus de capital<br>D. Moins de stock<br><em>A. Le délai client est plus long.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ac633297-8a2e-57dc-92b8-392a90c0b8c8', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 18, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une PME de distribution réalise 20 M DA de CA et 13 M DA de coûts directement liés aux ventes : marge brute pédagogique = 7 M DA, soit 35 % du CA.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c419a9e6-450f-506a-8d80-d78dc46ebd20', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 19, '{"html": "<h2>Exercice d’application</h2><p>CA 12 M, coût ventes 7,8 M. Marge brute et taux ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b962f9f8-e5d0-53d4-9382-d097f073575e', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 20, '{"html": "<h2>Corrigé-type</h2><p>4,2 M ; 35 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c7e1f48c-03db-5b26-82d9-b0bcc53f28a6', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'table', 21, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e8eb4142-264f-55e8-bafd-b72d80d18b30', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 22, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d74a8ce1-5fd0-5154-a7d7-1503f46382f1', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 23, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8f20a99d-803a-5f6f-ab58-366b94e45a66', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'text', 24, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a88aaa1a-f178-5fda-9fd8-c0ad57be4f9d', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'table', 25, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Construire une marge par ligne de produit."], ["Défi", "Identifier le produit qui détruit le plus de marge."], ["Outil lié", "Marge"], ["Preuve Skills Passport", "Analyse marges."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S04, S05, S06, S13, S16"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('06826369-88f5-5a06-b1cc-98afdf212086', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'course', '5b6d3e46-862d-5e0d-b018-fb9ef6af9b6b', 'QCM — BUS-02', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('512c90eb-0933-5b7e-931f-bfa0ce1569f9', '06826369-88f5-5a06-b1cc-98afdf212086', 'single', 1, 'Quelle proposition définit le mieux « Résultat / bénéfice » ?', 'La bonne réponse reprend la définition maître du concept « Résultat / bénéfice ».', 1, '[]');
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('1c02df9f-2ed3-589a-88ef-4df0cf6fe3c8', '512c90eb-0933-5b7e-931f-bfa0ce1569f9', 1, 'Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité.', 0);
INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('d4194f42-a372-5e26-a2ef-932ae0333559', '512c90eb-0933-5b7e-931f-bfa0ce1569f9', 2, 'Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable.', 0);
