INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'BUS-03 — BFR et cycle du cash', 'Piloter stock, clients et fournisseurs ensemble.', NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('43f53cfc-c9e7-51bb-9fb5-ee7a4d321dac', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Microentreprises, PME, PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Piloter stock, clients et fournisseurs ensemble."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('38904123-b500-51db-89e9-2a458f5660d5', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Besoin en fonds de roulement", "Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation.", "[S15]"], ["DSO", "Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période.", "[S30] [S32]"], ["DPO", "Indicateur pédagogique du délai moyen de règlement des fournisseurs, à rapprocher des achats à crédit.", "[S32]"], ["DIO", "Indicateur pédagogique du nombre moyen de jours pendant lesquels le stock reste immobilisé avant sa vente ou consommation.", "[S32]"], ["Cash Conversion Cycle", "Cycle de conversion du cash, généralement présenté comme DSO + DIO - DPO, pour visualiser la durée d’immobilisation du cash d’exploitation.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e17328ed-a19e-5082-b6a7-94bd94675fc9', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Piloter stock, clients et fournisseurs ensemble. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('575b6306-a591-5d3a-b5c3-05e645ff2247', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Besoin en fonds de roulement — Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation. [S15]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>DSO — Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période. [S30] [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>DPO — Indicateur pédagogique du délai moyen de règlement des fournisseurs, à rapprocher des achats à crédit. [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>DIO — Indicateur pédagogique du nombre moyen de jours pendant lesquels le stock reste immobilisé avant sa vente ou consommation. [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Cash Conversion Cycle — Cycle de conversion du cash, généralement présenté comme DSO + DIO - DPO, pour visualiser la durée d’immobilisation du cash d’exploitation. [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4f732f64-95da-5c6c-bb89-cd7a7d270f30', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. BFR. Le besoin en fonds de roulement mesure le cash immobilisé par le cycle d’exploitation. Il augmente généralement avec les stocks et créances et diminue avec le crédit fournisseur ; sa variation explique une partie des écarts entre résultat et trésorerie.</p><p>Repère de calcul. BFR simplifié = stocks + créances d’exploitation − dettes d’exploitation.</p><p>2. DSO. En finance d''entreprise, dso doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>Repère de calcul. DSO pédagogique ≈ créances clients ÷ chiffre d’affaires à crédit × nombre de jours de la période.</p><p>3. DPO. En finance d''entreprise, dpo doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>Repère de calcul. DPO pédagogique ≈ dettes fournisseurs ÷ achats à crédit × nombre de jours de la période.</p><p>4. DIO. En finance d''entreprise, dio doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>Repère de calcul. DIO pédagogique ≈ stock moyen ÷ coût des ventes × nombre de jours de la période.</p><p>5. CCC. En finance d''entreprise, ccc doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ecc0f768-e8fa-5804-b288-35fd8efcdee4', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Relier bilan, résultat et trésorerie.</p><p>Étape 2. Choisir une période et une définition stable de l’indicateur.</p><p>Étape 3. Calculer puis rapprocher le résultat de l’évolution du cash.</p><p>Étape 4. Tester l’effet d’un choc client, stock, prix ou financement.</p><p>Étape 5. Préparer une décision et les pièces à présenter au financeur ou au comité de gestion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7d3de1a8-db87-58e1-8464-d4936fb2037e', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>BFR simplifié = stocks + créances d’exploitation − dettes d’exploitation.</p><p>DSO pédagogique ≈ créances clients ÷ chiffre d’affaires à crédit × nombre de jours de la période.</p><p>DPO pédagogique ≈ dettes fournisseurs ÷ achats à crédit × nombre de jours de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c38f1305-558a-5e45-b126-e5e525309c89', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « BFR et cycle du cash », relevez les données disponibles, identifiez au moins quatre notions parmi Besoin en fonds de roulement, DSO, DPO, DIO, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2a6ed997-a6d6-53ba-9145-ae2a6c2ff2fa', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : PME avec DSO 60 jours, DIO 45 jours et DPO 30 jours : CCC pédagogique = 75 jours. Le cash est immobilisé longtemps dans le cycle.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1f8a86e2-bdf0-5400-94d2-c1410b53548f', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>DSO 50, DIO 40, DPO 25 : CCC ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8d5fb03e-365b-5c58-99b2-0ceb3027a2b2', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>65 jours.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7c9651d1-359f-5750-905f-3de4c24fbbfa', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7d63319e-826c-5a13-9133-faf5ea149aaf', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4a2afb40-8aed-5be9-8878-b022b550ae90', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8350ce01-ead9-500d-abeb-28f4c7ae6d7f', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1fe84554-e401-5e72-acbb-f90aa8fb618e', '064a239f-aec4-58d3-b94e-e9d09d7cd67f', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Calculer les 4 indicateurs."], ["Défi", "Réduire CCC de 15 jours par scénarios."], ["Outil lié", "BFR Cockpit"], ["Preuve Skills Passport", "CCC avant/après."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S15, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
