INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('93729a7f-827b-5c90-bc2f-971df426e9e8', '89dbb707-9f80-5458-8f38-f676b8e405b7', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Construire 13 semaines."], ["Défi", "Tester retard client +15 jours."], ["Outil lié", "Cash Forecast"], ["Preuve Skills Passport", "Prévision 13 semaines."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S14, S30"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
