INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c66b5d5a-a7b3-5cbe-a48b-4137b55bfdb3', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "PME, PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Piloter avec budget initial et révisions."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('05cd9f09-66e1-563d-8cc2-ede50986e64d', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01] [S32]"], ["Chiffre d’affaires", "Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable.", "[S04] [S05]"], ["Résultat / benefice", "Excédent des produits sur les charges sur une période ; pour les BNC, la DGI définit le bénéfice comme l’excédent des recettes sur les dépenses nécessaires à l’exercice.", "[S06] [S13]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Forecast", "Prévision révisée de l’activité et des résultats à partir des informations les plus récentes, distincte du budget initial.", "[S30], [S32]"], ["Action", "Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre.", "[S38], [S41]"], ["Écart budgétaire", "Différence entre une valeur réelle et une valeur budgétée ; son analyse vise à expliquer la cause avant de décider d’une action.", "[S30], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('035c503d-2607-55d9-ad2e-17ea46e19c74', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Piloter avec budget initial et révisions. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('88fab499-1701-516a-805d-3c6ec8173f45', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01] [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Chiffre d’affaires — Montant des ventes ou prestations facturées sur une période, avant déduction des charges ; son traitement fiscal dépend du régime applicable. [S04] [S05]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Résultat / bénéfice — Excédent des produits sur les charges sur une période ; pour les BNC, la DGI définit le bénéfice comme l’excédent des recettes sur les dépenses nécessaires à l’exercice. [S06] [S13]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Forecast — Prévision révisée de l’activité et des résultats à partir des informations les plus récentes, distincte du budget initial. [S30], [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Action — Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre. [S38], [S41]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Écart budgétaire — Différence entre une valeur réelle et une valeur budgétée ; son analyse vise à expliquer la cause avant de décider d’une action. [S30], [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('be4cd8f5-f5f7-5a94-a971-27ced157791f', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Budget annuel. « Budget annuel » transforme une intention en plan chiffré. Le budget doit distinguer ressources, priorités, engagements, marges de sécurité et écarts afin de permettre une correction en cours de période.</p><p>Repère de calcul. Solde budgétaire = revenus de la période − dépenses de la période.</p><p>2. Forecast actualisé. En finance d''entreprise, forecast actualisé doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>3. Écart volume/prix/coût. Pour « Écart volume/prix/coût », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>4. Actions correctives. En finance d''entreprise, actions correctives doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f813f295-9e5a-5908-9f12-52634f474a16', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Relier bilan, résultat et trésorerie.</p><p>Étape 2. Choisir une période et une définition stable de l’indicateur.</p><p>Étape 3. Calculer puis rapprocher le résultat de l’évolution du cash.</p><p>Étape 4. Tester l’effet d’un choc client, stock, prix ou financement.</p><p>Étape 5. Préparer une décision et les pièces à présenter au financeur ou au comité de gestion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c8cbab1b-29f1-578c-b39e-26b41edde6b1', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ed1a57b1-4287-5226-a0e1-783928dfe7a2', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Budget, forecast et analyse des écarts », relevez les données disponibles, identifiez au moins quatre notions parmi Budget, Chiffre d’affaires, Résultat / bénéfice, Trésorerie, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9d249189-ef01-5f8f-8337-05d9f36b6182', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 9, '{"html": "<h2>Approfondissement intégré — Budget d''entreprise, forecast et scénarios</h2><ul><li><strong>Publics</strong> : Entrepreneurs, startups, PME/PMI</li><li><strong>Compétences renforcées</strong> : distinguer budget et forecast; construire des scénarios; piloter par écarts</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Budget</strong> : Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. — [S01], [S32]</li><li><strong>Forecast</strong> : Prévision révisée de l’activité et des résultats à partir des informations les plus récentes, distincte du budget initial. — [S30], [S32]</li><li><strong>Écart budgétaire</strong> : Différence entre une valeur réelle et une valeur budgétée ; son analyse vise à expliquer la cause avant de décider d’une action. — [S30], [S32]</li><li><strong>Trésorerie</strong> : Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. — [S14], [S30]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9da9bddc-5b33-5004-a9e3-42b8744efc45', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 10, '{"html": "<h3>Budget vs forecast</h3><p>Le budget fixe une trajectoire planifiée. Le forecast actualise la trajectoire avec les informations nouvelles. Les deux doivent être comparés au réel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('610bbff1-5981-50a0-a40b-b365f887a9c5', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 11, '{"html": "<h3>Trois scénarios</h3><p>Sceptique, réaliste et optimiste permettent de tester la robustesse d''un projet. Les hypothèses doivent être explicites : volume, prix, coûts, DSO, change, croissance.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('52e4bf8e-b2c1-59cd-b42c-9ed35c92e74f', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Une PME prévoit 10 M DA de CA mensuel. Scénario sceptique : 8 M ; réaliste : 10 M ; optimiste : 12 M. Le forecast montre l''impact sur cash, marge et capacité de remboursement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4169e302-f58f-57a4-a140-5351290fa6df', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Créez trois scénarios pour votre activité et identifiez le mois où le cash devient négatif dans le scénario sceptique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5c3e15bd-a5d1-5160-a3f7-fe4f172ddbd0', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : expliciter les hypothèses de chaque scénario (volume, prix, coûts, DSO, change). Construire le plan de trésorerie mois par mois ; le premier mois où le solde cumulé devient négatif constitue un signal pour agir sur coûts, encaissements, financement ou calendrier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cb3c2324-aeef-56ba-bb5c-01020476f075', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('82c7a412-ece5-5781-a91f-65f2db4c68ac', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Un forecast est :</strong><br>A. Une prévision mise à jour<br>B. Un bilan figé<br>C. Une loi fiscale<br>D. Un impôt<br><em>A. Il incorpore les informations récentes.</em></li><li><strong>2. Le scénario sceptique sert à :</strong><br>A. Prévoir uniquement le pire absolu<br>B. Tester la résistance à des hypothèses défavorables<br>C. Garantir la faillite<br>D. Remplacer le budget<br><em>B. Il mesure la robustesse.</em></li><li><strong>3. Les hypothèses d''un scénario doivent être :</strong><br>A. Cachées<br>B. Explicites<br>C. Identiques pour toutes les entreprises<br>D. Aléatoires<br><em>B. La transparence rend la simulation utile.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('97fb8210-9ba2-51e9-a402-bbc5264a7d54', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une PME budgète 10 M DA au trimestre et réalise 9,2 M. L’écart de -8 % doit être analysé : volume, prix, retard ou mix.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b228a673-3511-5e21-bba4-d2ea35b79a21', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Budget 8 M, réel 8,8 M : écart % ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0979aa7d-ef00-5e44-85a6-06f054a45c04', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>+10 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('20f9db28-9c8f-5365-b804-8713ede10718', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a5581ce8-d209-542e-a143-c3e50106fada', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('68ddce80-2dd5-5aad-9e04-936510cde0cf', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eb37f31a-bd09-5e2f-9fb7-0d772de8f592', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a8ef28d3-171e-5032-8c46-28921ec955ee', 'ac71dbc0-dca0-5d33-9a13-0879dd797545', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Faire un forecast à fin d’année."], ["Défi", "Expliquer les 5 écarts les plus importants."], ["Outil lié", "Budget Business"], ["Preuve Skills Passport", "Forecast validé."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S04, S05, S06, S13, S14, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
