INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d03b53f2-8d73-59d6-b781-9f508863dc62', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "PME, PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Identifier le risque commercial lié aux clients."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9244d5d6-4f49-5f8e-87ba-c675b509452e', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Diversification", "Répartition d’une exposition entre plusieurs actifs, activités, clients ou sources afin de limiter la dépendance à un seul élément.", "[S02] [S32]"], ["Créance client", "Montant facturé à un client mais non encore encaissé.", "[S15] [S32]"], ["DSO", "Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période.", "[S30] [S32]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Concentration", "Exposition excessive à un nombre limité d’actifs, d’émetteurs, de secteurs, de clients ou de risques.", "[S38], [S41]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3e51a8e3-9924-51f6-a1c4-476deef126d7', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Identifier le risque commercial lié aux clients. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('720f785c-2906-59dd-8ec2-5ca98cf8f69e', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Diversification — Répartition d’une exposition entre plusieurs actifs, activités, clients ou sources afin de limiter la dépendance à un seul élément. [S02] [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Créance client — Montant facturé à un client mais non encore encaissé. [S15] [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>DSO — Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période. [S30] [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Concentration — Exposition excessive à un nombre limité d’actifs, d’émetteurs, de secteurs, de clients ou de risques. [S38], [S41]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eb6aaa05-8bec-5918-bc13-4ca4822b1e3b', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Top clients/CA. « Top clients/CA » doit être analysé à partir de la dépendance, du délai d''encaissement, de la qualité documentaire et du risque d''impayé. Une croissance du chiffre d''affaires peut dégrader le cash si les créances augmentent trop vite.</p><p>2. Aging. En finance d''entreprise, aging doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>3. Retards. En finance d''entreprise, retards doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>4. Stress perte client. « Stress perte client » doit être analysé à partir de la dépendance, du délai d''encaissement, de la qualité documentaire et du risque d''impayé. Une croissance du chiffre d''affaires peut dégrader le cash si les créances augmentent trop vite.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ce7923a0-1ec0-5561-a0be-c9d07266bd04', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Relier bilan, résultat et trésorerie.</p><p>Étape 2. Choisir une période et une définition stable de l’indicateur.</p><p>Étape 3. Calculer puis rapprocher le résultat de l’évolution du cash.</p><p>Étape 4. Tester l’effet d’un choc client, stock, prix ou financement.</p><p>Étape 5. Préparer une décision et les pièces à présenter au financeur ou au comité de gestion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('03241b0f-ae31-5cee-91a7-c771586c1a66', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>DSO pédagogique ≈ créances clients ÷ chiffre d’affaires à crédit × nombre de jours de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d5387b8b-eb93-5886-940a-70e88da1d218', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Clients, concentration et impayés », relevez les données disponibles, identifiez au moins quatre notions parmi Diversification, Créance client, DSO, Risque financier, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('46694fc7-7ef5-5ac4-9942-22789e5a652e', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une PME réalise 38 % de son CA avec un seul client. FINCLUDIA teste l’impact de la perte de ce client sur marge et cash sans produire une notation externe.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f3c94954-0bda-5272-a8a9-0314ae3a125d', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Top client 9 M sur CA 30 M : concentration ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9a0a9783-5e89-59ac-84b8-c0b6ba7bfc4b', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>30 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('56e9cd61-a069-505f-ad34-4908566d9f8f', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('80e5fdcf-fd41-5099-8ce6-53089ea8518a', 'e85f4050-b5b1-5af6-ad79-05f06f5fd447', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
