INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('72694338-0d48-53a9-860c-e4146ba9c850', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'BUS-09 — Coût industriel et coût de revient', 'Calculer un coût produit utilisable pour prix et décisions.', NULL, 9, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e9bd8f7c-45d2-5d49-a0ee-4bf08ab7027c', '72694338-0d48-53a9-860c-e4146ba9c850', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Calculer un coût produit utilisable pour prix et décisions."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c7df1646-007e-5898-b5eb-c9f769b12ed7', '72694338-0d48-53a9-860c-e4146ba9c850', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Prix de revient", "Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service.", "[S16] [S30]"], ["Charge fixe", "Charge qui ne varie pas directement avec le volume d’activité à court terme, par exemple certains loyers ou abonnements.", "[S16]"], ["Charge variable", "Charge qui évolue avec le volume d’activité, par exemple certains achats de marchandises ou matières.", "[S16]"], ["Quote-part", "Part d’une dépense commune attribuée à une personne selon une règle de partage égale, proportionnelle ou personnalisée.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9ba8f822-9395-5463-8bc8-64333b5588a5', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Calculer un coût produit utilisable pour prix et décisions. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('89debd16-b353-5e0e-b506-28eb2061ab1a', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Prix de revient — Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service. [S16] [S30]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Charge fixe — Charge qui ne varie pas directement avec le volume d’activité à court terme, par exemple certains loyers ou abonnements. [S16]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Charge variable — Charge qui évolue avec le volume d’activité, par exemple certains achats de marchandises ou matières. [S16]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Quote-part — Part d’une dépense commune attribuée à une personne selon une règle de partage égale, proportionnelle ou personnalisée. [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7612f8a6-e073-5bcc-a83a-7cfd8d0e8d43', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Matières. En finance d''entreprise, matières doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>2. Main-d’œuvre directe. En finance d''entreprise, main-d’œuvre directe doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>3. Énergie. En finance d''entreprise, énergie doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>4. Machine. En finance d''entreprise, machine doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>5. Frais indirects. En finance d''entreprise, frais indirects doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1390d484-e2e4-57c2-a70b-a3b9c55926bb', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Relier bilan, résultat et trésorerie.</p><p>Étape 2. Choisir une période et une définition stable de l’indicateur.</p><p>Étape 3. Calculer puis rapprocher le résultat de l’évolution du cash.</p><p>Étape 4. Tester l’effet d’un choc client, stock, prix ou financement.</p><p>Étape 5. Préparer une décision et les pièces à présenter au financeur ou au comité de gestion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('871c7bbb-6378-55b7-8e3c-edf0c0465b54', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Prix de revient = coûts directs + quote-part des coûts indirects affectés selon une méthode explicite.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('095a3e5b-72c8-541c-baf2-d2441a986549', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Coût industriel et coût de revient », relevez les données disponibles, identifiez au moins quatre notions parmi Prix de revient, Charge fixe, Charge variable, Quote-part, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a25d2317-43d0-50fb-afcd-1371fe3d1170', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une unité agroalimentaire calcule le coût d’un lot à partir des matières, de l’énergie, du personnel direct et d’une quote-part de frais indirects, plutôt qu’à partir du seul prix des matières.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fc3051dc-c206-519b-bb53-565bfda41d47', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Produit : matières 600 DA, MOD 200, énergie 80, emballage 70, indirects 150. Coût complet ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5521b44f-bc5f-5774-adb2-5a8e9a20e08c', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>1 100 DA/unité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f1c3b007-0e6a-5a35-bf81-789101b4358a', '72694338-0d48-53a9-860c-e4146ba9c850', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('534c6fe7-dfb7-5e4d-b7df-3cba205f2c2c', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6b0f32b8-99a6-5100-8532-2aa6bd0de04f', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('37a73bcd-8d41-5b9a-b8a4-83eceee84793', '72694338-0d48-53a9-860c-e4146ba9c850', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d0008e85-11e6-532c-8f42-98bd75bfc0d2', '72694338-0d48-53a9-860c-e4146ba9c850', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Construire une fiche coût standard."], ["Défi", "Comparer coût standard/réel sur un mois."], ["Outil lié", "Costing"], ["Preuve Skills Passport", "Fiche coût."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S16, S30"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
