INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('d54997eb-9127-5c74-ad8d-285e4042ff1d', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'BUS-10 — Capacité, productivité et qualité', 'Relier production, ressources et coût de non-qualité.', NULL, 10, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a617f65d-40df-5ce9-a482-9d2a3b8adafb', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Relier production, ressources et coût de non-qualité."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('78df748f-3cc6-5ace-b8ac-6458478880bb', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Prix de revient", "Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service.", "[S16] [S30]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Productivité", "Rapport entre une production obtenue et les ressources utilisées pour la produire ; elle peut être mesurée par travailleur, heure de travail ou autre facteur.", "[S43], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cded8c5f-6bd0-561a-818b-be422cc0c9c8', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Relier production, ressources et coût de non-qualité. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('efb7dc77-f09b-5e30-9737-c65c0c52f14d', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Prix de revient — Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service. [S16] [S30]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Productivité — Rapport entre une production obtenue et les ressources utilisées pour la produire ; elle peut être mesurée par travailleur, heure de travail ou autre facteur. [S43], [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('60ca95d5-d905-5108-8b72-c315b37552d3', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Capacité théorique/réelle. En finance d''entreprise, capacité théorique/réelle doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>2. Taux d’utilisation. En finance d''entreprise, taux d’utilisation doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>3. Productivité. En finance d''entreprise, productivité doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>4. Rebuts. En finance d''entreprise, rebuts doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>5. Retouches. En finance d''entreprise, retouches doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d1e1587d-dbdf-5c23-8a51-0053d2a6e1dc', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Relier bilan, résultat et trésorerie.</p><p>Étape 2. Choisir une période et une définition stable de l’indicateur.</p><p>Étape 3. Calculer puis rapprocher le résultat de l’évolution du cash.</p><p>Étape 4. Tester l’effet d’un choc client, stock, prix ou financement.</p><p>Étape 5. Préparer une décision et les pièces à présenter au financeur ou au comité de gestion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2fc0cfd5-3c27-5d6d-b193-02720556a974', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Prix de revient = coûts directs + quote-part des coûts indirects affectés selon une méthode explicite.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ed3982c6-87ca-5e7f-8776-a661b25df35e', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Capacité, productivité et qualité », relevez les données disponibles, identifiez au moins quatre notions parmi Prix de revient, Risque financier, Productivité, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('89204253-b2b8-5101-b3b3-192d8c88afdd', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une ligne peut produire 10 000 unités/mois mais en réalise 7 500 : utilisation 75 %. Si 375 sont rebutées, taux de rebut = 5 % des unités produites.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5b9d9747-759c-5362-bbb5-cda7af885504', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Capacité 12 000, production 9 000 : utilisation ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d20346c1-6683-5c2f-b6d1-9eacbec17203', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>75 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b5a0c417-a1e1-54b3-bf05-7cbdbbc80343', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ebf1e55e-0614-5ee7-b6fa-d0cf0aab7a2a', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('452dafc6-c0aa-5a63-96cc-c7aca1d4fb69', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9653d027-2457-5333-acee-d46486e96fb3', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dc368eaf-7222-568b-9b5f-55499bcd9191', 'd54997eb-9127-5c74-ad8d-285e4042ff1d', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Mesurer capacité et rebut."], ["Défi", "Réduire fictivement rebut de 2 points et recalculer coût."], ["Outil lié", "PMI Dashboard"], ["Preuve Skills Passport", "Tableau capacité/qualité."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S16, S22, S30"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
