INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'BUS-11 — CAPEX et décision d’investissement', 'Évaluer un investissement avant financement.', NULL, 11, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d3153d9c-9d89-5dc4-8f1a-69840b44e8bc', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "PME, PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Évaluer un investissement avant financement."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f246cc6f-9ef0-5807-b621-031589a8171b', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Investissement en Algérie", "Projet de création, extension ou autre opération d’investissement relevant du cadre de la loi 22-18 et des procédures d’enregistrement et d’accompagnement de l’AAPI.", "[S28]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["CAPEX", "Dépense d’investissement destinée à acquérir ou améliorer un actif utilisé durablement dans l’activité.", "[S13], [S42]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ecbeda4c-a4b8-507b-bee1-a298d129793f', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Évaluer un investissement avant financement. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4bd161f2-ebab-54a2-ae45-aa758cee9c0f', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Investissement en Algérie — Projet de création, extension ou autre opération d’investissement relevant du cadre de la loi 22-18 et des procédures d’enregistrement et d’accompagnement de l’AAPI. [S28]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>CAPEX — Dépense d’investissement destinée à acquérir ou améliorer un actif utilisé durablement dans l’activité. [S13], [S42]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9008fca9-c4bf-5c1d-bf99-8fcd0ad5cf30', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Coût initial. Pour « Coût initial », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>2. Économies/flux attendus. En finance d''entreprise, économies/flux attendus doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>3. Payback. Le payback mesure le temps nécessaire pour récupérer l’investissement initial à partir des économies ou cash-flows attendus. Il est simple à comprendre mais ignore ce qui se passe après la récupération et, dans sa version simple, la valeur temps de l’argent.</p><p>Repère de calcul. Payback simple = investissement initial ÷ économie ou cash-flow annuel moyen lorsque l’hypothèse de stabilité est acceptable.</p><p>4. VAN/TRI pédagogiques. En finance d''entreprise, van/tri pédagogiques doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>5. Scénarios. Les scénarios permettent de tester la robustesse d’une décision. Un scénario central décrit l’hypothèse la plus probable ; un scénario prudent ou défavorable mesure ce qui se passe si les ventes baissent, les coûts montent ou les encaissements sont retardés.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('480bab78-c75a-5a5d-b079-4c7f738b2b7a', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Relier bilan, résultat et trésorerie.</p><p>Étape 2. Choisir une période et une définition stable de l’indicateur.</p><p>Étape 3. Calculer puis rapprocher le résultat de l’évolution du cash.</p><p>Étape 4. Tester l’effet d’un choc client, stock, prix ou financement.</p><p>Étape 5. Préparer une décision et les pièces à présenter au financeur ou au comité de gestion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('579cbefc-214d-552e-9e59-85f3f73b6a6c', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Payback simple = investissement initial ÷ économie ou cash-flow annuel moyen lorsque l’hypothèse de stabilité est acceptable.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eae6676a-86f5-5f69-bbfb-b612060c50dd', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « CAPEX et décision d’investissement », relevez les données disponibles, identifiez au moins quatre notions parmi Investissement en Algérie, Trésorerie, Risque financier, CAPEX, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('85a7ea9e-031d-5587-abb9-4f6167e8328e', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une machine coûte 12 M DA et économise 3 M DA/an avant autres effets. Le payback simple est 4 ans, mais la décision doit aussi considérer maintenance, financement, impôts, risque et valeur résiduelle.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cd444f24-796d-58fd-b2cd-e3bca350f18f', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>CAPEX 8 M, économie annuelle 2 M : payback simple ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d6934e82-0538-52be-b963-c5a3bf513b95', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>4 ans.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('87877838-80d4-56f3-aceb-01577a3f5b22', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('576fb746-4518-575c-9e13-a07e4ac8aa12', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4e3fed53-135a-5a7a-9592-ccb40d03cc33', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('06b33413-b7f4-5100-8878-e83e79e6caf3', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0318fff4-b704-5fb7-8367-1a9c9657d1dc', 'b9fa2ae2-792f-54a6-abc1-9fa5c5d64fec', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un dossier CAPEX."], ["Défi", "Comparer acheter/leasing/ne pas investir."], ["Outil lié", "CAPEX Simulator"], ["Preuve Skills Passport", "Dossier investissement."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S14, S22, S28, S30"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
