INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('c96604c5-6281-5ebd-978e-5601aa65456f', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'BUS-12 — Financement et pack financeur', 'Préparer un besoin et un dossier traçable.', NULL, 12, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d00843ea-ba4f-58aa-ac8b-26c8a623ba20', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "PME, PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Préparer un besoin et un dossier traçable."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('04755dd2-d5ce-5e0f-b7dd-8c9a88204c27', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Business plan", "Dossier structurant le projet, ses hypothèses, son marché et ses prévisions financières, notamment compte de résultat, trésorerie, seuil de rentabilité et financement.", "[S18]"], ["Besoin en fonds de roulement", "Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation.", "[S15]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Surface financière importateur", "Exigence bancaire applicable aux importations de biens destinés à la revente en l’état ; l’Instruction 05-2026 prévoit notamment l’appréciation préalable de la situation financière par la banque domiciliataire.", "[S29]"], ["Demande", "Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions.", "[S32]"], ["Besoin", "Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer.", "[S01], [S32]"], ["Stock", "Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés.", "[S13], [S42]"], ["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ccd7c115-2f77-5d2f-a0e9-fcbbd96da821', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Préparer un besoin et un dossier traçable. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c8977c99-dfba-5832-b503-800bb721a246', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Business plan — Dossier structurant le projet, ses hypothèses, son marché et ses prévisions financières, notamment compte de résultat, trésorerie, seuil de rentabilité et financement. [S18]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Besoin en fonds de roulement — Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation. [S15]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Surface financière importateur — Exigence bancaire applicable aux importations de biens destinés à la revente en l’état ; l’Instruction 05-2026 prévoit notamment l’appréciation préalable de la situation financière par la banque domiciliataire. [S29]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Demande — Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions. [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Besoin — Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer. [S01], [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Stock — Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés. [S13], [S42]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Dette — Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. [S01], [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8c2ca145-4687-501c-9353-666709c52232', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Besoin. Un besoin financier est l’objet précis à financer : stock, machine, créance, véhicule, logement ou décalage temporaire de trésorerie. Sa nature, son montant et sa durée économique déterminent les familles de solutions à comparer.</p><p>2. Apport. L’apport représente les ressources propres mobilisées par le porteur du projet ou l’entreprise. Il réduit le montant à financer mais diminue aussi les liquidités disponibles ; il faut donc préserver une marge de sécurité.</p><p>3. Cash-flow. Le cash-flow désigne ici les flux de trésorerie générés ou consommés par l’activité. Pour rembourser une dette, la question centrale n’est pas seulement le bénéfice comptable mais la disponibilité effective du cash aux dates d’échéance.</p><p>4. Dette. La dette crée une obligation de remboursement selon un calendrier. Son analyse combine capital restant, coût, échéances, garanties, sensibilité à une baisse de revenu ou de cash-flow et conséquences d’un retard.</p><p>Repère de calcul. Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>5. Documents. Les documents rendent la situation financière vérifiable : factures, relevés, états financiers, contrats, justificatifs fiscaux ou commerciaux. Un dossier incomplet augmente l’incertitude du financeur et peut retarder la décision.</p><p>6. Scénarios. Les scénarios permettent de tester la robustesse d’une décision. Un scénario central décrit l’hypothèse la plus probable ; un scénario prudent ou défavorable mesure ce qui se passe si les ventes baissent, les coûts montent ou les encaissements sont retardés.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a11e36e4-9407-5ade-bd3a-467403c3d132', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Relier bilan, résultat et trésorerie.</p><p>Étape 2. Choisir une période et une définition stable de l’indicateur.</p><p>Étape 3. Calculer puis rapprocher le résultat de l’évolution du cash.</p><p>Étape 4. Tester l’effet d’un choc client, stock, prix ou financement.</p><p>Étape 5. Préparer une décision et les pièces à présenter au financeur ou au comité de gestion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c0e23384-7a52-5748-8616-72ef994e3f13', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>BFR simplifié = stocks + créances d’exploitation − dettes d’exploitation.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('92bbcd6e-3069-5b2b-a7ba-af724eecbbf3', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Financement et pack financeur », relevez les données disponibles, identifiez au moins quatre notions parmi Business plan, Besoin en fonds de roulement, Trésorerie, Surface financière importateur, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f6a84641-34d2-58a2-b7c0-4060f9ba45a4', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une PME qui finance un nouveau stock doit expliquer l’augmentation de BFR, le cycle de vente et le remboursement, pas seulement demander un montant.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('00f25dde-9874-509c-859e-0c8c72085480', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Construire une note de besoin de 1 page pour 15 M DA de financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b7e33bd4-e1b4-5887-a8ea-8166dc1ca7f4', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Elle doit présenter objet, montant, durée économique, cash-flow, apport, risques et pièces.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('09660313-a126-53a9-a269-c19adc81d154', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ccf32701-908f-5027-9c5f-9e572e663530', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5510140f-678f-5dad-ad80-037284595f74', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('28163fbe-e075-552d-97b9-3a75f83fe9b7', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('85eae47b-23bb-5774-96ab-651e5c7ad458', 'c96604c5-6281-5ebd-978e-5601aa65456f', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Générer un Business Passport."], ["Défi", "Atteindre 90 % de complétude du pack."], ["Outil lié", "Funding Business"], ["Preuve Skills Passport", "Pack financement."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S14, S15, S18, S29, S30"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
