INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'BUS-13 — Fiscalité entreprise : savoir piloter sans coder les taux', 'Comprendre TVA, IBS et obligations comme règles versionnées.', NULL, 13, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f13e7f36-d928-5915-9a73-177690930aa9', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "PME, PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Comprendre TVA, IBS et obligations comme règles versionnées."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9a933d9d-3d02-572a-9e75-d564e3a12f7e', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["TVA", "Impôt calculé sur le chiffre d’affaires hors taxe pour les opérations et contribuables relevant des régimes concernés ; les taux et exonérations sont fixés par les textes en vigueur.", "[S05]"], ["IBS", "Impôt sur les bénéfices des sociétés, avec des taux différenciés selon la nature d’activité et les règles fiscales en vigueur.", "[S07]"], ["Comptabilité financière", "Système d’organisation de l’information financière permettant de saisir, classer, évaluer et présenter des données donnant une image fidèle de la situation, de la performance et de la trésorerie.", "[S13]"], ["CAC", "Coût d’acquisition client : dépenses commerciales/marketing attribuées à l’acquisition divisées par le nombre de nouveaux clients, selon une convention explicite.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a09ef6d0-b276-5a9d-a28e-be13dfef093d', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre TVA, IBS et obligations comme règles versionnées. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bb652f5f-bc0b-5a10-b55d-95a9d54ef3d5', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>TVA — Impôt calculé sur le chiffre d’affaires hors taxe pour les opérations et contribuables relevant des régimes concernés ; les taux et exonérations sont fixés par les textes en vigueur. [S05]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>IBS — Impôt sur les bénéfices des sociétés, avec des taux différenciés selon la nature d’activité et les règles fiscales en vigueur. [S07]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Comptabilité financière — Système d’organisation de l’information financière permettant de saisir, classer, évaluer et présenter des données donnant une image fidèle de la situation, de la performance et de la trésorerie. [S13]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>CAC — Coût d’acquisition client : dépenses commerciales/marketing attribuées à l’acquisition divisées par le nombre de nouveaux clients, selon une convention explicite. [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2d1de4a4-fae3-52a0-b2ec-b0750be00d17', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. TVA collectée/déductible. En finance d''entreprise, tva collectée/déductible doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>2. IBS selon activité. En finance d''entreprise, ibs selon activité doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>3. Déclarations. En finance d''entreprise, déclarations doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p><p>4. Sources DGI. En finance d''entreprise, sources dgi doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b71d27fd-da5b-5cbd-8086-b104e0c6e881', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Relier bilan, résultat et trésorerie.</p><p>Étape 2. Choisir une période et une définition stable de l’indicateur.</p><p>Étape 3. Calculer puis rapprocher le résultat de l’évolution du cash.</p><p>Étape 4. Tester l’effet d’un choc client, stock, prix ou financement.</p><p>Étape 5. Préparer une décision et les pièces à présenter au financeur ou au comité de gestion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('916415de-fdac-59ca-a4fa-c8e6ac32ec5f', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>CAC = dépenses d’acquisition attribuables ÷ nombre de nouveaux clients acquis sur la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('32f30400-11bb-58ba-92cc-677401372f63', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Fiscalité entreprise : savoir piloter sans coder les taux », relevez les données disponibles, identifiez au moins quatre notions parmi TVA, IBS, Comptabilité financière, CAC, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b789921d-6b04-5baa-96fa-ead19835f166', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Au 8 novembre 2026, la DGI publie des taux TVA de 19 % et 9 %, et des taux IBS par nature d’activité. FINCLUDIA affiche les valeurs depuis le moteur de règles avec date, jamais comme constantes cachées.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('abd24b56-80c0-5cba-b190-df519ec2ad75', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>À partir d’un profil fictif, identifier les règles DGI à rechercher avant calcul.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('04ce72e5-b5a2-5a2f-b67e-560008c4e2ba', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>La réponse attendue est une liste de règles et sources, pas un taux supposé.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('23218440-a965-5b39-b8f5-02b7d223d07a', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('79129d1d-967b-5c48-9d2c-5d4eec351f7f', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5ce195fd-cbe9-57d7-9ba7-310abc985601', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a94b018f-ad59-515f-9a83-ce5f4b7dd3f7', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fe79c396-b71f-5495-9042-c452a0ba1363', '48d3db6c-fd7f-539a-9d90-0fcd0ca6986b', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer le calendrier fiscal de l’entreprise."], ["Défi", "Vérifier 100 % des règles par source officielle."], ["Outil lié", "Reglo Business"], ["Preuve Skills Passport", "Calendrier sourcé."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S05, S07, S13"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
