INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'BUS-14 — CFO War Room', 'Combiner les indicateurs dans un scénario de crise.', NULL, 14, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a0f4724c-edd8-5534-8e1c-b1654cb63655', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "PME, PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Combiner les indicateurs dans un scénario de crise."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f08e3953-97c2-5fce-8d78-c2ee93011d42', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Besoin en fonds de roulement", "Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation.", "[S15]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["DSO", "Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période.", "[S30] [S32]"], ["DIO", "Indicateur pédagogique du nombre moyen de jours pendant lesquels le stock reste immobilisé avant sa vente ou consommation.", "[S32]"], ["Action", "Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre.", "[S38], [S41]"], ["Stock", "Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés.", "[S13], [S42]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3d4d3865-90b8-56fa-9df7-32ae80e3a902', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Combiner les indicateurs dans un scénario de crise. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a7842dcb-3aff-55ad-a2c4-940b7eaa8c06', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Besoin en fonds de roulement — Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation. [S15]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>DSO — Indicateur pédagogique du délai moyen d’encaissement des créances clients, généralement rapporté aux ventes à crédit sur une période. [S30] [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>DIO — Indicateur pédagogique du nombre moyen de jours pendant lesquels le stock reste immobilisé avant sa vente ou consommation. [S32]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Action — Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre. [S38], [S41]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p><p>Stock — Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés. [S13], [S42]</p><p>Application dans ce module. La compétence attendue est de relier résultat, bilan et trésorerie ; un indicateur n’est jamais interprété seul, mais avec sa période, sa base de calcul et ses conséquences sur le cash et le financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7a6eff30-4645-55a5-b548-1176963447d4', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Client en retard. « Client en retard » doit être analysé à partir de la dépendance, du délai d''encaissement, de la qualité documentaire et du risque d''impayé. Une croissance du chiffre d''affaires peut dégrader le cash si les créances augmentent trop vite.</p><p>2. Stock +20 %. « Stock +20 % » mobilise de la trésorerie tant que les biens ne sont pas vendus ou consommés. Le suivi doit combiner valeur du stock, vitesse de rotation, risque d''invendu et conséquences sur le BFR.</p><p>3. Coût fournisseur +15 %. Pour « Coût fournisseur +15 % », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>4. Financement retardé. « Financement retardé » doit être relié à la nature et à la durée du besoin, au coût total, aux garanties éventuelles et à la capacité de remboursement. Une mensualité faible n''est pas suffisante pour juger la qualité d''un financement.</p><p>5. Plan 90 jours. En finance d''entreprise, plan 90 jours doit être rapproché des états financiers et du cash. L''utilisateur précise la période et la base de calcul, mesure l''écart éventuel, puis explique l''effet sur la rentabilité, le BFR, la liquidité ou la capacité de financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('95616c65-8474-5f45-83e0-c90ae34b4153', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Relier bilan, résultat et trésorerie.</p><p>Étape 2. Choisir une période et une définition stable de l’indicateur.</p><p>Étape 3. Calculer puis rapprocher le résultat de l’évolution du cash.</p><p>Étape 4. Tester l’effet d’un choc client, stock, prix ou financement.</p><p>Étape 5. Préparer une décision et les pièces à présenter au financeur ou au comité de gestion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a892cb2e-82c8-5938-85c5-e228c845d38d', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>BFR simplifié = stocks + créances d’exploitation − dettes d’exploitation.</p><p>DSO pédagogique ≈ créances clients ÷ chiffre d’affaires à crédit × nombre de jours de la période.</p><p>DIO pédagogique ≈ stock moyen ÷ coût des ventes × nombre de jours de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('daaa70a7-e0f0-5142-bf9f-309be5c62d29', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « CFO War Room », relevez les données disponibles, identifiez au moins quatre notions parmi Besoin en fonds de roulement, Trésorerie, Risque financier, DSO, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('84756d4c-3d74-5228-9952-4896f5c8a08c', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 9, '{"html": "<h2>Approfondissement intégré — Gestion des risques</h2><ul><li><strong>Publics</strong> : Familles, entrepreneurs, dirigeants</li><li><strong>Compétences renforcées</strong> : identifier probabilité et impact; distinguer prévention et transfert du risque; construire un Risk Radar</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Risque financier</strong> : Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. — [S02], [S22]</li><li><strong>Concentration</strong> : Exposition excessive à un nombre limité d’actifs, d’émetteurs, de secteurs, de clients ou de risques. — [S38], [S41]</li><li><strong>Risque client</strong> : Risque qu’un client paie en retard, ne paie pas ou crée une concentration excessive dans les revenus ou créances. — [S30], [S32]</li><li><strong>Risque fournisseur</strong> : Risque lié à la capacité, la qualité, la conformité, les délais ou la solidité d’un fournisseur. — [S32]</li><li><strong>Risque réglementaire</strong> : Risque qu’une règle applicable change, soit mal interprétée ou ne soit pas respectée, affectant une opération ou sa conformité. — [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ad6136d2-1fd9-5318-bde4-4694805e7287', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 10, '{"html": "<h3>Risque = événement + impact</h3><p>Un risque financier ne se résume pas à une perte possible. Il faut estimer sa probabilité, son impact, la capacité d''absorption et les mesures de mitigation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e137ef2c-6b11-5782-bca1-19655163f6d5', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 11, '{"html": "<h3>Risques personnels et entreprises</h3><p>Particulier : perte de revenu, maladie, dette, fraude. Entreprise : client majeur, fournisseur, change, stock, cyber, liquidité, conformité, incendie, panne.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1947c8b7-5363-5451-a9f8-f9bc67ec80dd', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Si un client représente 45 % du CA, le risque de concentration est élevé même si ce client paie correctement aujourd''hui.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9b16d810-5986-5da4-a3e1-b206ad2c469f', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Créez une matrice 3x3 probabilité/impact pour cinq risques de votre profil.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4dbc3da7-c5a4-5937-a073-500ea43ed08f', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : noter probabilité 1-3 et impact 1-3, calculer une priorité simple, puis documenter prévention, réduction, transfert/assurance ou acceptation. Les risques critiques nécessitent au moins une mesure, un responsable et un indicateur de suivi.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4d4529d8-fb2d-5e2e-b89a-2636d38fd229', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5ac82b4d-e070-5550-8fb7-7af2ae8c509a', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Le risque de concentration signifie :</strong><br>A. Avoir trop peu de dépendance<br>B. Dépendre excessivement d''un client/actif<br>C. Avoir beaucoup de cash<br>D. Payer ses impôts<br><em>B. Un choc sur un seul acteur peut être critique.</em></li><li><strong>2. Une réserve de cash est une mesure de :</strong><br>A. Résilience<br>B. Spéculation<br>C. Fiscalité<br>D. Marketing<br><em>A. Elle absorbe les chocs.</em></li><li><strong>3. Une assurance peut être :</strong><br>A. Un transfert de certains risques<br>B. Une garantie de profit<br>C. Un impôt<br>D. Un actif coté<br><em>A. Elle transfère certains risques contre une prime.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('caa1fc37-d14e-553b-868e-6440e76eae04', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Cas : PME d’emballage à Oran. Client principal retarde 45 jours, stock augmente de 20 % et fournisseur augmente ses prix. L’équipe doit quantifier l’impact cash et proposer 3 actions.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('604504a8-6e0b-502f-8b8c-b634dac1a5a1', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Construire un plan de réponse en 3 priorités.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a42db0d1-26db-5268-a723-b105715ed353', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>Chaque action doit avoir impact attendu, responsable, délai et indicateur.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ee97957e-ba2a-5a5e-9ed3-b534660b35b3', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('56540cf2-61c4-5e45-8e25-ce115fdfe93a', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
