INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ddbfc778-ebf9-5b10-b479-b974a0b87a8f', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2873eb42-2048-5463-92d5-f5ad9d87e33e', '66176397-ad7e-5b8a-b0d3-b743eb6b778f', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Ouvrir War Room."], ["Défi", "Ramener le cash minimum au-dessus de zéro dans le scénario."], ["Outil lié", "CFO War Room"], ["Preuve Skills Passport", "Plan 90 jours."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S14, S15, S22, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
