INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('f09a9c8c-4c5f-5966-a939-9a26be7e359c', 'be5e9d97-a7db-5415-aca7-8d9050d84043', 'Cas intégrateur corrigé — Finance d’entreprise, PME & PMI', NULL, NULL, 15, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1a87319e-3837-5ec1-9799-c942ad4f3e35', 'f09a9c8c-4c5f-5966-a939-9a26be7e359c', 'text', 1, '{"html": "<h3>Scénario\\nUne PME réalise 48 M DA de CA annuel. Coûts variables : 28,8 M ; charges fixes : 14,4 M. Stocks : 6 M ; créances clients : 8 M ; dettes fournisseurs : 4 M. Trésorerie disponible : 3 M. Un CAPEX de 5 M DA est envisagé.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1073f6df-66ef-596a-ae54-4c1d207aa05d', 'f09a9c8c-4c5f-5966-a939-9a26be7e359c', 'text', 2, '{"html": "<h2>Travail demandé</h2><p>1. Calculer la marge sur coûts variables et son taux.</p><p>2. Calculer le seuil de rentabilité simplifié.</p><p>3. Calculer le BFR simplifié.</p><p>4. Comparer BFR et trésorerie disponible.</p><p>5. Dire quelles analyses sont nécessaires avant de lancer le CAPEX.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2641e1d5-6356-58cd-96ce-7eb51b783829', 'f09a9c8c-4c5f-5966-a939-9a26be7e359c', 'text', 3, '{"html": "<h2>Corrigé-type</h2><p>Marge sur coûts variables = 48 - 28,8 = 19,2 M DA, soit 40 %. Seuil de rentabilité = 14,4/0,40 = 36 M DA de CA. BFR = 6 + 8 - 4 = 10 M DA. La trésorerie de 3 M ne couvre pas ce BFR à elle seule. Avant CAPEX : plan 13 semaines, financement, capacité de service de dette, gain de productivité attendu, scénario adverse et priorités de cash.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2b31144b-af99-58fb-8f2e-04cf85a7b360', 'f09a9c8c-4c5f-5966-a939-9a26be7e359c', 'table', 4, '{"headers": ["Critère", "Poids"], "rows": [["Exactitude technique / calculs", "35 %"], ["Interprétation et décision", "25 %"], ["Gestion du risque / conformité", "20 %"], ["Traçabilité et sources", "10 %"], ["Clarté de l’explication", "10 %"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0fb04257-178a-5dfc-a085-b8b3b04258c0', 'f09a9c8c-4c5f-5966-a939-9a26be7e359c', 'text', 5, '{"html": "<h3>Validation du cas intégrateur\\nSeuil : 75 %. Une erreur critique de sécurité, conformité, fraude, règle réglementaire active ou confusion réel/fictif doit être corrigée avant validation, même si le score global atteint 75 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('dbbd5c9d-643c-53e2-b31f-7ca144ab77c4', 'academy-conomie', 'FINCLUDIA Academy — Économie', 'Circuit économique, PIB, inflation, emploi, monnaie, politiques monétaire et budgétaire, change, cycle et chocs mondiaux.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Économie', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'intermediate', '["ECO-01 — Le circuit économique : ménages, entreprises, État et reste du monde", "ECO-02 — PIB, croissance et niveau de vie", "ECO-03 — Inflation et pouvoir d’achat", "ECO-04 — Emploi, chômage et revenu", "ECO-05 — Monnaie, Banque d’Algérie et politique monétaire", "ECO-06 — Budget de l’État et politique budgétaire", "ECO-07 — Taux de change, commerce extérieur et balance des paiements", "ECO-08 — Cycle économique, taux et décisions d’entreprise", "ECO-09 — Marchés mondiaux, matières premières et transmission des chocs", "ECO-10 — Lire une statistique économique avec esprit critique"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '["ETU", "LYC", "SAL"]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'dbbd5c9d-643c-53e2-b31f-7ca144ab77c4', 'ECO-01 — Le circuit économique : ménages, entreprises, État et reste du monde', 'Comprendre comment circulent biens, travail, revenus, impôts, épargne et financement.', NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d3606a07-e128-5aa9-af1f-92ddb8093038', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Tous publics"], ["Niveau", "N1"], ["Objectif measurable", "Comprendre comment circulent biens, travail, revenus, impôts, épargne et financement."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2e4a98b9-38dc-5ac1-912b-9eb5465242ed', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Circuit économique", "représentation des flux réels et financiers entre grands agents.", "[S32]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01], [S32]"], ["Offre", "Quantité d’un bien ou service que les producteurs sont disposés à proposer selon les prix et autres conditions.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('56f358f4-8fc3-5451-a6a6-3f05979ee7a1', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre comment circulent biens, travail, revenus, impôts, épargne et financement. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('412d7b33-71bd-5f37-8f91-44a588349c75', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Circuit économique — représentation des flux réels et financiers entre grands agents. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01], [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Offre — Quantité d’un bien ou service que les producteurs sont disposés à proposer selon les prix et autres conditions. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4aeb7380-a822-55f0-93f5-ba0b46658a9b', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Ménages offrent travail et consomment. Pour ménages offrent travail et consomment, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>2. Entreprises produisent, paient et investissent. Pour entreprises produisent, paient et investissent, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>3. État prélève et dépense ; système financier canalise une partie des ressources. Pour état prélève et dépense ; système financier canalise une partie des ressources, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a9830945-ae85-5ae0-a5fc-b175ef670bcf', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier l’indicateur et sa définition statistique.</p><p>Étape 2. Vérifier source, période, unité et population couverte.</p><p>Étape 3. Distinguer niveau, variation nominale et variation réelle.</p><p>Étape 4. Expliquer les canaux de transmission possibles.</p><p>Étape 5. Éviter de transformer un indicateur macroéconomique en prédiction certaine pour un individu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0a20d516-95ab-563a-a5de-273ae66e613a', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cdeb1c39-bb29-515d-a7d5-d40e8110088f', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Le circuit économique : ménages, entreprises, État et reste du monde », relevez les données disponibles, identifiez au moins quatre notions parmi Circuit économique, Dépense, Épargne, Offre, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0d885b20-1ce5-51f5-9662-2f8aec71b953', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un salarié reçoit 80 000 DA, consomme, paie certains impôts et épargne : ses décisions deviennent des flux pour d’autres agents.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e78438d5-9080-51d4-82cc-fcfc8df3685b', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Dessiner les flux d’un achat de produit fabriqué localement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8db08b7f-3c85-515b-af3f-ae69f8e2654c', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Identifier au moins ménage, entreprise, paiement, bien et prélèvement éventuel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4dbcc0ad-4d47-5741-8f56-9e65d8fac80a', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2f7613e5-ef6d-5617-9efe-5f3b0af2c705', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9878a46c-7234-5085-b9b6-10cf931c9f3e', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('293b2889-13bd-5e05-ac3a-38139c2cf9cd', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('badcae64-d903-5eff-846a-3173abaa3fe9', '4aa7019b-7e3c-53a1-803b-538e7dc6a536', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer une carte des flux"], ["Défi", "Relier 10 opérations à leur agent"], ["Outil lié", "Econo Map"], ["Preuve Skills Passport", "Carte des flux"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
