INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0027312a-ff66-50c5-9d9a-393aaa68487c', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Lycéens, étudiants, entrepreneurs, dirigeants"], ["Niveau", "N2"], ["Objectif measurable", "Lire correctement un indicateur d’activité sans le confondre avec le revenu de chacun."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a01a27ff-b02b-57f2-8cb0-25bac2659815', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["PIB", "valeur de la production finale réalisée sur un territoire.", "[S43] [S32]"], ["Croissance économique", "évolution du niveau d’activité, souvent mesurée en volume.", "[S43]"], ["PIB reel", "PIB corrigé des variations de prix afin de mieux mesurer l’évolution des volumes produits.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cb98b06f-30ee-509f-acbf-0692026c6587', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Lire correctement un indicateur d’activité sans le confondre avec le revenu de chacun. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7050d3fe-78d9-5614-a9cc-201c4729735b', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>PIB — valeur de la production finale réalisée sur un territoire. [S43] [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Croissance économique — évolution du niveau d’activité, souvent mesurée en volume. [S43]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>PIB réel — PIB corrigé des variations de prix afin de mieux mesurer l’évolution des volumes produits. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('102e3581-8fac-529c-b29e-66bf9d987300', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. PIB nominal vs réel. Le PIB nominal valorise la production aux prix courants ; le PIB réel cherche à isoler l’évolution des volumes en neutralisant l’effet des prix. Une hausse nominale peut donc être largement expliquée par l’inflation.</p><p>2. PIB total vs par habitant. Le PIB total mesure la taille de l’économie ; le PIB par habitant rapporte ce total à la population. Ce dernier facilite certaines comparaisons mais ne décrit ni la distribution des revenus ni le niveau de vie de chaque personne.</p><p>3. Croissance ne signifie pas répartition égale des gains. Pour croissance ne signifie pas répartition égale des gains, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8dd45204-cfce-5d89-8a60-0eb42cb1fc94', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier l’indicateur et sa définition statistique.</p><p>Étape 2. Vérifier source, période, unité et population couverte.</p><p>Étape 3. Distinguer niveau, variation nominale et variation réelle.</p><p>Étape 4. Expliquer les canaux de transmission possibles.</p><p>Étape 5. Éviter de transformer un indicateur macroéconomique en prédiction certaine pour un individu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('49e0b2bf-b061-57b8-a128-27f3fdb9a410', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « PIB, croissance et niveau de vie », relevez les données disponibles, identifiez au moins quatre notions parmi PIB, Croissance économique, PIB réel, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b9e63e5f-403d-5919-ba8f-95af1d15834b', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 8, '{"html": "<h2>Approfondissement intégré — PIB, croissance, chômage et productivité</h2><ul><li><strong>Publics</strong> : Lycéens, étudiants, salariés, entrepreneurs</li><li><strong>Compétences renforcées</strong> : comprendre les grands agrégats; relier macroéconomie et décisions individuelles; éviter les interprétations simplistes</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>PIB</strong> : Mesure de la valeur de la production finale de biens et services réalisée sur un territoire pendant une période ; il sert à suivre la taille et l’évolution de l’activité économique. — [S43], [S32]</li><li><strong>Croissance économique</strong> : Variation du niveau d’activité économique, souvent suivie par l’évolution du PIB réel entre deux périodes. — [S43], [S32]</li><li><strong>Chômage</strong> : Situation d’une personne sans emploi, disponible et recherchant un emploi selon la définition statistique applicable ; le taux dépend de la population active retenue. — [S43], [S32]</li><li><strong>Productivité</strong> : Rapport entre une production obtenue et les ressources utilisées pour la produire ; elle peut être mesurée par travailleur, heure de travail ou autre facteur. — [S43], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c50181cb-33a1-522e-a877-244067177c42', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 9, '{"html": "<h3>PIB et croissance</h3><p>Le PIB mesure la valeur de la production finale réalisée sur un territoire pendant une période, selon les conventions statistiques. La croissance mesure l''évolution de cette activité en volume ou selon la mesure retenue.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d20407d3-f972-5ea9-9938-06b6e6056116', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 10, '{"html": "<h3>Chômage et productivité</h3><p>Le taux de chômage mesure une situation sur le marché du travail selon des définitions statistiques. La productivité rapporte la production à des ressources utilisées ; elle joue un rôle majeur dans la croissance de long terme.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('247c278b-3035-5785-ac10-408bb9805316', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'callout', 11, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Une économie peut connaître une croissance du PIB sans que tous les ménages voient immédiatement leur revenu augmenter. Les agrégats macroéconomiques ne décrivent pas toutes les situations individuelles.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9796644d-92ac-52c1-9f49-837a3c09c586', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 12, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Expliquez en 5 lignes comment une hausse de productivité peut influencer une entreprise et ses salariés.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e3015d89-c52d-5501-81b2-d02feea62435', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 13, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : une hausse de productivité permet davantage de production par unité de travail/capital ; elle peut réduire le coût unitaire et améliorer la marge ou les salaires, mais l’effet dépend de la demande, de la concurrence et du partage des gains. Elle peut aussi modifier les besoins en emplois et compétences.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6c381a3f-c5d2-5493-9816-201fe25ef926', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 14, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cd379ba5-3ba6-592e-ae91-759fe045da0d', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 15, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Le PIB mesure :</strong><br>A. Une production agrégée<br>B. Le patrimoine de chaque ménage<br>C. Le cours de Bourse<br>D. Le prix de l''or uniquement<br><em>A. C''est un agrégat de production.</em></li><li><strong>2. Croissance du PIB = hausse garantie du revenu de chacun ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Seulement en industrie<br><em>B. La répartition et les situations diffèrent.</em></li><li><strong>3. La productivité rapporte :</strong><br>A. Production à ressources utilisées<br>B. Dette au salaire uniquement<br>C. Impôt au CA<br>D. Dividende au stock<br><em>A. Elle mesure une efficacité relative.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('195162b0-5778-5ced-a909-05a9035c55f2', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 16, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une hausse du PIB réel peut coexister avec des situations individuelles différentes selon secteur, emploi et prix.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a181a861-4091-52a5-9e98-728d967a8d5f', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 17, '{"html": "<h2>Exercice d’application</h2><p>Classer quatre affirmations comme correctes ou abusives.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ec416125-953b-58c5-ae26-c78ad105b3e5', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 18, '{"html": "<h2>Corrigé-type</h2><p>Refuser toute déduction automatique du PIB vers le bien-être individuel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eeedf9ad-fa30-56ea-861f-d9ecce03b69c', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'table', 19, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f079a834-76bd-5534-88f3-f971d9058744', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 20, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('834d2de0-69c1-5ec7-ae07-6266a13a168a', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 21, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('252b9898-6e55-5c40-8956-7985cb76bc95', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'text', 22, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cf9a9868-33d3-5c06-b80f-ea5ad9c21b0b', '307a3396-8473-5c1c-84a1-d8f964ee9e4d', 'table', 23, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Faire une fiche indicateur"], ["Défi", "Corriger trois mauvaises interprétations"], ["Outil lié", "Macro Dashboard"], ["Preuve Skills Passport", "Fiche PIB"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32, S43"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
