INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('591f93c4-611b-59f4-a159-67b7dfd827b3', '7b53aa9e-5fe7-5d53-9cc0-4aa2cc097a53', 'single', 4, 'Lorsqu’une donnée réglementaire, bancaire, fiscale ou de marché est utilisée, quel réflexe FINCLUDIA est correct ?', 'FINCLUDIA versionne les règles évolutives et sépare toujours simulation, information et décision.', 1, '[]');
