INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('294e9f91-bd46-527e-ae7d-d3dd6df6711f', '7b53aa9e-5fe7-5d53-9cc0-4aa2cc097a53', 'single', 5, 'Quelle preuve doit permettre au site de confirmer l’application de la compétence ?', 'La progression repose sur une preuve d’application, pas seulement sur la consultation du contenu.', 1, '[]');
