INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'dbbd5c9d-643c-53e2-b31f-7ca144ab77c4', 'ECO-03 — Inflation et pouvoir d’achat', 'Relier évolution des prix, revenu et budget réel.', NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d8a130e6-2cc4-59ee-b5b0-54f4ebbe8943', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Tous publics"], ["Niveau", "N1-N2"], ["Objectif measurable", "Relier évolution des prix, revenu et budget réel."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5a8f9ca1-ada3-5e46-9bee-08d9a13af375', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Inflation", "hausse générale et durable du niveau des prix, suivie par l’IPC.", "[S43]"], ["Pouvoir d’achat", "quantité de biens/services accessible avec une ressource.", "[S43] [S32]"], ["Besoin", "Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer.", "[S01], [S32]"], ["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01], [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('311cafa9-ddcb-5c8f-9687-db5357ab1170', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Relier évolution des prix, revenu et budget réel. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c77dd2f2-8183-5fe8-ad16-fae2350db551', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Inflation — hausse générale et durable du niveau des prix, suivie par l’IPC. [S43]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Pouvoir d’achat — quantité de biens/services accessible avec une ressource. [S43] [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Besoin — Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer. [S01], [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01], [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e551def3-a751-51b9-981b-14d1278b3407', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Un taux d’inflation est une moyenne. L’inflation est une hausse générale et durable du niveau des prix. Son effet concret dépend de la structure de consommation de chaque ménage et de l’évolution de ses revenus.</p><p>Repère de calcul. Rendement réel exact = (1 + rendement nominal) ÷ (1 + inflation) − 1.</p><p>2. Le panier personnel peut évoluer différemment. Pour le panier personnel peut évoluer différemment, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>3. Comparer croissance du revenu et prix sur la même période. Pour « Comparer croissance du revenu et prix sur la même période », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0fcfceb7-b4ba-5962-b8b8-cc5a636264d8', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier l’indicateur et sa définition statistique.</p><p>Étape 2. Vérifier source, période, unité et population couverte.</p><p>Étape 3. Distinguer niveau, variation nominale et variation réelle.</p><p>Étape 4. Expliquer les canaux de transmission possibles.</p><p>Étape 5. Éviter de transformer un indicateur macroéconomique en prédiction certaine pour un individu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a2a9b5b1-67a1-5c7e-9902-3738eab30bd8', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Rendement réel exact = (1 + rendement nominal) ÷ (1 + inflation) − 1.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ea25a945-d431-50ef-8afa-5f5888848e0b', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Inflation et pouvoir d’achat », relevez les données disponibles, identifiez au moins quatre notions parmi Inflation, Pouvoir d’achat, Besoin, Budget, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('90608143-86a1-5cc0-a2c1-fa2ab3a68309', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 9, '{"html": "<h2>Approfondissement intégré — Inflation, taux d''intérêt et pouvoir d''achat</h2><ul><li><strong>Publics</strong> : Tous publics</li><li><strong>Compétences renforcées</strong> : comprendre inflation; relier inflation et taux; raisonner en valeur réelle</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Inflation</strong> : Hausse générale et durable du niveau des prix ; son suivi en Algérie s’appuie notamment sur l’indice des prix à la consommation publié par l’ONS. — [S43]</li><li><strong>Taux d’intérêt</strong> : Prix du temps et du crédit exprimé en pourcentage selon une convention et une période ; son interprétation exige de préciser base, durée, frais et capitalisation. — [S34], [S32]</li><li><strong>Pouvoir d’achat</strong> : Quantité de biens et services qu’un revenu ou un capital permet d’acquérir ; il évolue selon le niveau des prix et l’évolution des ressources. — [S43], [S32]</li><li><strong>Rendement</strong> : Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon. — [S01], [S41]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('21796e81-b702-5e4a-b0ea-0861bfc046c5', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 10, '{"html": "<h3>Inflation</h3><p>L''inflation désigne une hausse générale du niveau des prix sur une période. Elle réduit le pouvoir d''achat d''une somme nominale si les revenus ne progressent pas au même rythme.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('58aec544-4350-5b61-8d3f-dcb47a1f53ad', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 11, '{"html": "<h3>Taux d''intérêt</h3><p>Les taux influencent le coût du crédit, l''attractivité de l''épargne et les valorisations d''actifs. Les mécanismes sont complexes : une hausse des taux ne produit pas le même effet sur tous les agents.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('df39bfa9-9f18-50b8-97ca-fcc824f0099d', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Un revenu passe de 100 000 à 104 000 DA (+4 %) tandis que le panier de dépenses progresse de 6 %. Le revenu nominal augmente, mais le pouvoir d''achat peut reculer.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('930498d8-3f0a-5b26-b4b8-3cbd71760bc3', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Calculez un rendement réel approximatif pour un placement à 7 % dans un scénario d''inflation à 5 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f32c3494-6bf5-596a-bcfa-c53af2a67ec7', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : rendement réel exact approximatif = (1,07/1,05) - 1 ≈ 1,90 %. L’approximation simple 7 % - 5 % = 2 % est proche, mais le calcul exact est préférable pour l’enseignement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6479e85e-5468-54d8-b744-e2bc600c1119', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8efeaae4-9784-5a97-af6c-6050ff702b6a', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Inflation signifie :</strong><br>A. Baisse générale des prix<br>B. Hausse générale du niveau des prix<br>C. Hausse automatique des salaires<br>D. Baisse des taux<br><em>B. Elle concerne le niveau général des prix.</em></li><li><strong>2. Rendement nominal 7 % et inflation 5 % donne environ :</strong><br>A. 7 % réel<br>B. 2 % réel approximatif<br>C. 12 % réel<br>D. 0 % garanti<br><em>B. En approximation simple, l''écart est proche de 2 %.</em></li><li><strong>3. Une hausse des taux peut rendre le crédit :</strong><br>A. Toujours gratuit<br>B. Potentiellement plus coûteux<br>C. Toujours moins cher<br>D. Sans effet<br><em>B. Le coût de financement peut augmenter.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a3f2d3c9-c6d1-5164-af47-95597dcc519c', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Budget alimentation de 30 000 DA ; scénario pédagogique +5 % : besoin théorique de 31 500 DA si tout le panier augmentait exactement de 5 %.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8dc23746-15d1-53a3-9c67-17a794e4119f', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Appliquer trois scénarios d’inflation fictive à un panier de 100 000 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('94970343-e080-5856-a354-88600554d9f1', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>Résultats = 100 000 × (1+taux) ; rappeler que le taux est hypothétique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('855829b0-5a36-5219-a7e5-0059b9626dc0', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3373d07a-1db7-5df7-bfa3-130f1910a54e', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6285a23c-6f83-5e20-926c-45ac5e133af9', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('523e9a11-fac0-5417-926e-cc059eb5f978', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7f939a4d-5022-5da1-8215-200fd2c45daa', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Tester mon panier"], ["Défi", "Identifier les catégories les plus sensibles"], ["Outil lié", "Inflation Simulator"], ["Preuve Skills Passport", "Simulation datée"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32, S43"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('d98b074e-6d6f-57a1-a6d9-803fd2e46370', 'dbbd5c9d-643c-53e2-b31f-7ca144ab77c4', 'course', 'b7e9f81b-5d53-57eb-b130-78bfaa2a7ca5', 'QCM — ECO-03', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
