INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('0c0ff887-aff7-52f3-b7af-fae81db8096c', 'a091e75a-96fd-58bf-8465-f226cf4b4808', 1, 'quantité de biens/services accessible avec une ressource.', 0);
