INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('923d5212-99e4-5c87-954a-e7ef83bede9d', 'dbbd5c9d-643c-53e2-b31f-7ca144ab77c4', 'ECO-04 — Emploi, chômage et revenu', 'Comprendre population active, emploi, chômage et limites d’un taux agrégé.', NULL, 4, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8095562b-9097-54c8-a45e-75e8ed81e1c6', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Lycéens, étudiants, demandeurs d’emploi, salariés"], ["Niveau", "N2"], ["Objectif measurable", "Comprendre population active, emploi, chômage et limites d’un taux agrégé."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0d476b35-4f2d-570b-9a2c-1871ed50ffd2', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Chômage", "situation définie statistiquement selon absence d’emploi, disponibilité et recherche.", "[S43] [S32]"], ["Revenu", "Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination.", "[S08]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b77572d5-3efa-53f7-bc75-040581fc18db', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre population active, emploi, chômage et limites d’un taux agrégé. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fd30e250-483d-5641-a8f4-f08c62005aa8', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Chômage — situation définie statistiquement selon absence d’emploi, disponibilité et recherche. [S43] [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Revenu — Flux de ressources perçu par une personne ou une activité. Pour un salarié, la DGI rattache les traitements et salaires aux rémunérations reçues en contrepartie d’un travail sous lien de subordination. [S08]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('89173418-0c38-591e-9807-5788721ee920', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Population totale ≠ population active. Pour population totale ≠ population active, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>2. Taux de chômage ≠ part de toute la population sans emploi. Pour taux de chômage ≠ part de toute la population sans emploi, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>3. Revenu, employabilité et compétences ont des dimensions distinctes. Pour revenu, employabilité et compétences ont des dimensions distinctes, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('693ab360-a889-5444-a795-209cbd0518f3', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier l’indicateur et sa définition statistique.</p><p>Étape 2. Vérifier source, période, unité et population couverte.</p><p>Étape 3. Distinguer niveau, variation nominale et variation réelle.</p><p>Étape 4. Expliquer les canaux de transmission possibles.</p><p>Étape 5. Éviter de transformer un indicateur macroéconomique en prédiction certaine pour un individu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('22807cbc-08e5-57d1-a219-dc45682d31ae', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Emploi, chômage et revenu », relevez les données disponibles, identifiez au moins quatre notions parmi Chômage, Revenu, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c9541a1a-1e3b-5411-9774-d7c101d3ebbe', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un étudiant non disponible pour travailler peut ne pas être classé chômeur selon la définition statistique utilisée.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e3491d21-92e1-5d15-a825-3c6337009db7', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Classer six profils fictifs selon activité/emploi/chômage avec hypothèses données.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('36ff2761-e89b-5bc1-b98d-846e91645ee1', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Appliquer la définition fournie ; ne pas extrapoler sans information.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c8c45c92-d41f-5ed5-bd95-f349e07ba2ed', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2bef9974-55d9-508d-a401-cb64ba44afa2', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9695415b-c9b6-5c67-a84c-5f003ed11f69', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('16421a8e-feb0-5497-8a43-d077bff6e635', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d65d5282-28ea-515d-a8cc-a7c707ba21fd', '923d5212-99e4-5c87-954a-e7ef83bede9d', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Construire une carte emploi/revenu"], ["Défi", "Repérer une mauvaise lecture d’un taux"], ["Outil lié", "Career Finance Map"], ["Preuve Skills Passport", "Cas classés"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32, S43"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
