INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('7d8bd4de-a068-570c-b324-53072fc253f9', '972219eb-6f6b-538f-bb82-7d07a3d046d7', 'single', 4, 'Lorsqu’une donnée réglementaire, bancaire, fiscale ou de marché est utilisée, quel réflexe FINCLUDIA est correct ?', 'FINCLUDIA versionne les règles évolutives et sépare toujours simulation, information et décision.', 1, '[]');
