INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'dbbd5c9d-643c-53e2-b31f-7ca144ab77c4', 'ECO-05 — Monnaie, Banque d’Algérie et politique monétaire', 'Comprendre le rôle de la banque centrale et les canaux de la politique monétaire.', NULL, 5, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b5af991b-f04d-5221-84d5-ea11fd6d73b2', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Étudiants, salariés, entrepreneurs, dirigeants"], ["Niveau", "N2-N3"], ["Objectif measurable", "Comprendre le rôle de la banque centrale et les canaux de la politique monétaire."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e4fcce12-3b1c-5d59-869f-88e1f3b46bad', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Banque centrale", "institution en charge de missions monétaires et de stabilité.", "[S33] [S34]"], ["Politique monétaire", "décisions agissant sur les conditions monétaires et financières.", "[S33] [S34]"], ["Liquidité", "Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur.", "[S14], [S32]"], ["Dépense variable", "Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('60ef1b5e-0085-5d26-90f0-ae1066750577', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre le rôle de la banque centrale et les canaux de la politique monétaire. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8b540897-3623-5874-bb51-9140f81d6ffe', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Banque centrale — institution en charge de missions monétaires et de stabilité. [S33] [S34]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Politique monétaire — décisions agissant sur les conditions monétaires et financières. [S33] [S34]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Liquidité — Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur. [S14], [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Dépense variable — Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4c2014b7-a914-5fca-9fcd-9c65c01e8dad', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Stabilité des prix comme objectif. Pour « Stabilité des prix comme objectif », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>2. Liquidité, crédit, systèmes de paiement et change. La liquidité décrit la facilité avec laquelle une ressource peut être mobilisée rapidement sans forte perte de valeur. Un actif peut avoir de la valeur tout en étant peu utile pour régler une échéance immédiate.</p><p>3. Les effets sur crédit et économie passent par plusieurs canaux, pas instantanément. « Les effets sur crédit et économie passent par plusieurs canaux, pas instantanément » doit être relié à la nature et à la durée du besoin, au coût total, aux garanties éventuelles et à la capacité de remboursement. Une mensualité faible n''est pas suffisante pour juger la qualité d''un financement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('26589042-65fd-517e-93ec-69201b62996a', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier l’indicateur et sa définition statistique.</p><p>Étape 2. Vérifier source, période, unité et population couverte.</p><p>Étape 3. Distinguer niveau, variation nominale et variation réelle.</p><p>Étape 4. Expliquer les canaux de transmission possibles.</p><p>Étape 5. Éviter de transformer un indicateur macroéconomique en prédiction certaine pour un individu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e0c7cb70-eb1f-535c-9006-87bb863fcbcc', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Monnaie, Banque d’Algérie et politique monétaire », relevez les données disponibles, identifiez au moins quatre notions parmi Banque centrale, Politique monétaire, Liquidité, Dépense variable, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('303b6709-0a79-5b7f-b2e7-d6c133a1a140', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 8, '{"html": "<h2>Approfondissement intégré — Banque centrale, monnaie et politique monétaire</h2><ul><li><strong>Publics</strong> : Étudiants, cadres, entrepreneurs</li><li><strong>Compétences renforcées</strong> : comprendre rôle d''une banque centrale; relier monnaie, taux et stabilité; identifier les limites d''une explication simpliste</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Banque centrale</strong> : Institution chargée de fonctions monétaires et financières publiques. En Algérie, la Banque d’Algérie veille notamment à la stabilité des prix, régule la liquidité et le crédit, surveille les systèmes de paiement, organise le marché des changes et contribue à la solidité du système bancaire. — [S33], [S34]</li><li><strong>Politique monétaire</strong> : Ensemble des décisions et instruments par lesquels la banque centrale agit sur les conditions monétaires et financières afin de poursuivre ses objectifs, notamment la stabilité des prix. — [S33], [S34]</li><li><strong>Liquidité financière</strong> : Capacité à convertir un actif en monnaie disponible rapidement, à un coût et avec une perte de valeur limités. — [S01], [S41]</li><li><strong>Taux d’intérêt</strong> : Prix du temps et du crédit exprimé en pourcentage selon une convention et une période ; son interprétation exige de préciser base, durée, frais et capitalisation. — [S34], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('34bc929c-f509-5625-923b-545396da6d66', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 9, '{"html": "<h3>Banque centrale</h3><p>Une banque centrale met en œuvre les missions que lui confère la loi : politique monétaire, stabilité et supervision selon le cadre national. Les outils influencent liquidité et conditions monétaires.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('54969299-b7c8-525b-858c-032dc179e869', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 10, '{"html": "<h3>Transmission</h3><p>Une décision monétaire peut se transmettre aux taux bancaires, au crédit, à l''épargne, au change et à l''activité, mais avec des délais et des effets différents selon le contexte.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dd2a20bc-03b1-5af5-87d5-82a34b736743', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'callout', 11, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>FINCLUDIA doit enseigner qu''une hausse ou baisse d''un taux directeur ne se transforme pas mécaniquement en variation identique de tous les crédits proposés aux particuliers.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d73f9d58-6090-5ac5-bc0d-cc550bc9c5ee', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 12, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Dessinez une chaîne : banque centrale → banques → crédit/épargne → consommation/investissement → activité/prix.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f18d2f59-aadc-5e35-bb4f-02d8d7aef394', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 13, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : Banque centrale -&gt; conditions de liquidité/taux -&gt; banques -&gt; coût/disponibilité du crédit et rémunération de l’épargne -&gt; consommation/investissement -&gt; activité/emploi/prix. Les transmissions comportent des délais et ne sont jamais mécaniques à 1 pour 1.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('33d0e4de-ec11-595e-8b91-74ae0503f505', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 14, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4642109b-bb82-525f-95d0-6fd0c28655d2', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 15, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Une banque centrale est :</strong><br>A. Une banque commerciale ordinaire<br>B. Une institution monétaire centrale<br>C. Une entreprise de e-commerce<br>D. Un fonds d''investissement privé<br><em>B. Elle joue un rôle institutionnel spécifique.</em></li><li><strong>2. La transmission monétaire est :</strong><br>A. Instantanée et identique partout<br>B. Progressive et contextuelle<br>C. Inexistante<br>D. Un impôt<br><em>B. Les effets passent par plusieurs canaux.</em></li><li><strong>3. Les taux bancaires particuliers sont toujours égaux au taux directeur ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Seulement en Bourse<br><em>B. Les banques ajoutent risques, coûts et conditions.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5dbc1ef6-0681-552c-82cb-5c4acb0ae7b5', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 16, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une variation des conditions monétaires peut influencer coût du financement et décisions d’investissement, avec délais et effets variables.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d5bdaaf4-2622-54eb-93ad-a105c1df45bb', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 17, '{"html": "<h2>Exercice d’application</h2><p>Construire une chaîne de transmission fictive en cinq étapes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d19e170b-ce4c-5f46-b287-2567408a5485', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 18, '{"html": "<h2>Corrigé-type</h2><p>Chaque flèche doit être expliquée comme mécanisme possible, non certitude mécanique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('03c8f04a-0f9e-5f75-97fb-85b1786df4e4', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'table', 19, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('970f46c4-6af4-5710-b827-a4318b31a832', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'text', 20, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
