INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2e220ac8-772b-56ec-b4d8-b99f26f2e298', '48af35cf-a659-5887-bbd2-a20fdeaaa6f4', 'table', 23, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Cartographier une transmission monétaire"], ["Défi", "Éviter la causalité simpliste"], ["Outil lié", "Macro Simulator"], ["Preuve Skills Passport", "Chaîne commentée"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S33, S34"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
