INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d6cf3464-13e1-56e5-b42f-b4564e9b605b', '56a04645-8019-5002-9aaa-b15be48091c3', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Lycéens, étudiants, entrepreneurs, citoyens"], ["Niveau", "N2"], ["Objectif measurable", "Comprendre recettes, dépenses, solde et arbitrages publics."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8e18123e-f8e8-53d6-9246-fbf324032feb', '56a04645-8019-5002-9aaa-b15be48091c3', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Politique budgétaire", "décisions publiques sur recettes, dépenses et solde.", "[S32]"], ["Déficit budgétaire", "dépenses supérieures aux recettes sur le périmètre et la période retenus.", "[S32]"], ["Transfert de fonds", "Mouvement d’argent entre personnes ou comptes ; FINCLUDIA distingue le déplacement de fonds d’un revenu nouvellement créé.", "[S20], [S32]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01], [S32]"], ["Stock", "Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés.", "[S13], [S42]"], ["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b76ce922-00ba-5b35-8cc2-e8c3e0c33970', '56a04645-8019-5002-9aaa-b15be48091c3', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre recettes, dépenses, solde et arbitrages publics. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b8ec2ac7-b174-5f8c-aebf-056a7971c0b0', '56a04645-8019-5002-9aaa-b15be48091c3', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Politique budgétaire — décisions publiques sur recettes, dépenses et solde. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Déficit budgétaire — dépenses supérieures aux recettes sur le périmètre et la période retenus. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Transfert de fonds — Mouvement d’argent entre personnes ou comptes ; FINCLUDIA distingue le déplacement de fonds d’un revenu nouvellement créé. [S20], [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01], [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Stock — Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés. [S13], [S42]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Dette — Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. [S01], [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a46fa02e-ec38-5353-813e-6e737113208c', '56a04645-8019-5002-9aaa-b15be48091c3', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Impôts et autres recettes. Pour impôts et autres recettes, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>2. Dépenses de fonctionnement, transferts et investissement. Pour dépenses de fonctionnement, transferts et investissement, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>3. Déficit annuel ≠ dette totale. « Déficit annuel ≠ dette totale » doit être relié à la nature et à la durée du besoin, au coût total, aux garanties éventuelles et à la capacité de remboursement. Une mensualité faible n''est pas suffisante pour juger la qualité d''un financement.</p><p>Repère de calcul. Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bbaad3d2-d68c-5e55-b498-43f0c8ab7ef6', '56a04645-8019-5002-9aaa-b15be48091c3', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier l’indicateur et sa définition statistique.</p><p>Étape 2. Vérifier source, période, unité et population couverte.</p><p>Étape 3. Distinguer niveau, variation nominale et variation réelle.</p><p>Étape 4. Expliquer les canaux de transmission possibles.</p><p>Étape 5. Éviter de transformer un indicateur macroéconomique en prédiction certaine pour un individu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('30fd020f-a92b-576d-ba81-77537d240aa6', '56a04645-8019-5002-9aaa-b15be48091c3', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b7477f44-1b36-5525-b718-6c947f547d6f', '56a04645-8019-5002-9aaa-b15be48091c3', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Budget de l’État et politique budgétaire », relevez les données disponibles, identifiez au moins quatre notions parmi Politique budgétaire, Déficit budgétaire, Transfert de fonds, Dépense, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f88858eb-e140-5a50-b205-b6e06c70f601', '56a04645-8019-5002-9aaa-b15be48091c3', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un budget public fictif prévoit 10 unités de recettes et 12 de dépenses : déficit de 2 unités pour cette période.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('80bf53b6-96cc-502f-b123-4fe6293dcf7d', '56a04645-8019-5002-9aaa-b15be48091c3', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Distinguer déficit, dette, dépense et investissement dans huit phrases.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0fb0be0e-309b-52a7-ae81-599ea1d43f32', '56a04645-8019-5002-9aaa-b15be48091c3', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Corriger les confusions de stock et de flux.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('68c4de9a-a083-523f-b7a9-0fd3b190c555', '56a04645-8019-5002-9aaa-b15be48091c3', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f5d02e54-7516-5038-81bf-f12a5416eebe', '56a04645-8019-5002-9aaa-b15be48091c3', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
