INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'dbbd5c9d-643c-53e2-b31f-7ca144ab77c4', 'ECO-07 — Taux de change, commerce extérieur et balance des paiements', 'Relier devise, import/export, prix et flux internationaux.', NULL, 7, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('67eec84e-225b-58c7-a2b2-36329f678846', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Étudiants, diaspora, entrepreneurs, importateurs/exportateurs"], ["Niveau", "N2-N3"], ["Objectif measurable", "Relier devise, import/export, prix et flux internationaux."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f634178d-d9d6-5f61-a0e7-63b7ae4f47d2', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Taux de change", "prix d’une monnaie dans une autre.", "[S20] [S21]"], ["Balance commerciale", "exportations moins importations de biens.", "[S32]"], ["Balance des paiements", "cadre plus large des transactions avec les non-résidents.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('28eae99a-9cb4-5ed6-ae17-666ed9f1147c', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Relier devise, import/export, prix et flux internationaux. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('801bf6ad-29cf-56a5-ae01-27fed4bcbe02', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Taux de change — prix d’une monnaie dans une autre. [S20] [S21]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Balance commerciale — exportations moins importations de biens. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Balance des paiements — cadre plus large des transactions avec les non-résidents. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fd80533e-3f86-5e1d-b9eb-7278afd77b39', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Dépréciation/appréciation et coût en DZD. Pour « Dépréciation/appréciation et coût en DZD », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>2. Import/export et devises. Pour import/export et devises, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>3. Ne pas confondre balance commerciale et balance des paiements. Pour ne pas confondre balance commerciale et balance des paiements, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>Repère de calcul. Balance commerciale = exportations de biens − importations de biens.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2ffac9cb-7942-5a49-b9d0-3f12731e1ed7', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier l’indicateur et sa définition statistique.</p><p>Étape 2. Vérifier source, période, unité et population couverte.</p><p>Étape 3. Distinguer niveau, variation nominale et variation réelle.</p><p>Étape 4. Expliquer les canaux de transmission possibles.</p><p>Étape 5. Éviter de transformer un indicateur macroéconomique en prédiction certaine pour un individu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('20456600-8411-5f67-9f55-3b7e2f546099', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Balance commerciale = exportations de biens − importations de biens.</p><p>Valeur convertie = montant en devise × taux de conversion retenu ; le taux et sa date doivent être conservés.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0c5df434-345e-5fea-8379-fa642202797c', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Taux de change, commerce extérieur et balance des paiements », relevez les données disponibles, identifiez au moins quatre notions parmi Taux de change, Balance commerciale, Balance des paiements, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0fe34fe7-2359-50da-9e88-98a383a88e19', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 9, '{"html": "<h2>Approfondissement intégré — Taux de change, devises et économie ouverte</h2><ul><li><strong>Publics</strong> : Diaspora, importateurs, étudiants, entrepreneurs</li><li><strong>Compétences renforcées</strong> : comprendre taux de change; mesurer une exposition devise; distinguer scénario de change et prévision</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Taux de change</strong> : Prix d’une monnaie exprimé dans une autre monnaie ; pour toute opération réelle, la source, la date et la règle de change applicable doivent être conservées. — [S20], [S21]</li><li><strong>Risque de change</strong> : Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. — [S20], [S21]</li><li><strong>Balance des paiements</strong> : Cadre statistique retraçant les transactions économiques entre résidents d’une économie et non-résidents sur une période. — [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c4d41572-66e8-5368-b306-b925e330a8a6', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 10, '{"html": "<h3>Taux de change</h3><p>Un taux de change exprime le prix relatif de deux monnaies. Pour une entreprise qui importe ou exporte, une variation peut modifier coût, marge et compétitivité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a4267928-dea3-5ecc-93a0-ff715c5a2833', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 11, '{"html": "<h3>Risque de change</h3><p>Le risque vient d''un écart entre une obligation future en devise et les ressources dans cette même devise. FINCLUDIA doit permettre des scénarios, pas prétendre prédire avec certitude le futur taux.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e8ca8232-5d77-57fd-a41a-f286632fb709', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Une machine achetée 20 000 EUR coûte davantage en DA si le taux applicable se déplace défavorablement avant paiement. Le bon outil teste -5 %, central, +5 %, +10 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6db25157-afc5-522b-a316-d673a0f06f36', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Simulez l''effet de trois taux de change sur une facture d''importation et recalculez la marge.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fc214222-9209-550a-a5c6-537a8cbaee77', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : pour chaque scénario, coût en DA = montant en devise x taux de change + coûts locaux. Recalculer ensuite coût unitaire, prix de revient et marge. Un taux défavorable à l’import augmente le coût en DA toutes choses égales.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f7733f99-9ec1-5e6a-893b-fe22764c229f', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c5e648b0-577a-5e67-ac4d-fb8597540445', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Une variation du change peut affecter :</strong><br>A. Le coût d''importation<br>B. Uniquement les salaires publics<br>C. Jamais la marge<br>D. Seulement la Bourse<br><em>A. Le coût en monnaie locale change.</em></li><li><strong>2. Un scénario de change est :</strong><br>A. Une garantie<br>B. Une hypothèse<br>C. Une obligation fiscale<br>D. Un dividende<br><em>B. Il sert à tester la sensibilité.</em></li><li><strong>3. Une exposition devise existe notamment quand :</strong><br>A. Paiement futur en devise<br>B. Aucune opération étrangère<br>C. Budget en DA uniquement<br>D. Stock nul<br><em>A. Le montant futur dépend du change.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('665f0443-172f-599b-b502-d5bb335ec0f1', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une machine à 10 000 EUR coûte davantage en DA si le taux EUR/DZD utilisé pour le calcul augmente, toutes choses égales par ailleurs.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dec9b318-49f2-5e82-9366-51cbc9253a1b', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Tester +5 %, -5 % sur un coût en devise.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8dc22503-5e16-5b55-80ae-91d5bb9cefb9', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>Afficher taux de départ, taux de scénario, date fictive et coût converti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1e0059ab-e30c-5c95-943c-3aa1c3b7dfea', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cbd94261-1ce1-56cf-bd83-b0c0aab52ed8', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('91bc086a-bc98-569e-a697-172bebc9168b', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ecebcb29-0420-57d6-b6b6-fc29a8481b38', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4569077b-5408-5770-90c7-827397d37323', '0b50d9b4-7efc-5bdd-bccb-996a67c10e9e', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Faire un stress test FX"], ["Défi", "Trouver le taux qui annule une marge fictive"], ["Outil lié", "FX Simulator"], ["Preuve Skills Passport", "Analyse sensibilité"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S20, S21, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
