INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'dbbd5c9d-643c-53e2-b31f-7ca144ab77c4', 'ECO-08 — Cycle économique, taux et décisions d’entreprise', 'Relier contexte macroéconomique et scénarios d’entreprise sans prédiction automatique.', NULL, 8, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3bfa9785-b191-5d3e-a7d7-ab6d367604fc', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Étudiants, entrepreneurs, PME/PMI"], ["Niveau", "N3"], ["Objectif measurable", "Relier contexte macroéconomique et scénarios d’entreprise sans prédiction automatique."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('24ae407b-bf14-522b-aac1-34fb4261a939', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Cycle économique", "phases d’activité observées à travers plusieurs indicateurs.", "[S43] [S32]"], ["Taux d’intérêt", "coût du financement selon convention.", "[S34] [S32]"], ["Dépense variable", "Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport.", "[S32]"], ["Demande", "Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions.", "[S32]"], ["Stock", "Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés.", "[S13], [S42]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9d271ab2-254c-5fdd-a1d0-6fb570ff093b', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Relier contexte macroéconomique et scénarios d’entreprise sans prédiction automatique. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9dfe794c-b173-5eae-9545-3e5e409109f4', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Cycle économique — phases d’activité observées à travers plusieurs indicateurs. [S43] [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Taux d’intérêt — coût du financement selon convention. [S34] [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Dépense variable — Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Demande — Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Stock — Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés. [S13], [S42]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('68087cbc-d932-5d48-8866-705b1541c9fa', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Demande, stocks, investissement et financement peuvent réagir au cycle. « Demande, stocks, investissement et financement peuvent réagir au cycle » mobilise de la trésorerie tant que les biens ne sont pas vendus ou consommés. Le suivi doit combiner valeur du stock, vitesse de rotation, risque d''invendu et conséquences sur le BFR.</p><p>2. Sensibilité différente selon secteurs. Pour sensibilité différente selon secteurs, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>3. Construire des scénarios plutôt que prétendre prévoir. « Construire des scénarios plutôt que prétendre prévoir » se travaille par scénarios. L''utilisateur fixe une hypothèse de base, une hypothèse défavorable et, si utile, une hypothèse favorable ; il compare ensuite les effets sur le budget, le cash, la marge ou le risque.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0a7b99b6-c6c2-5e28-a4d6-f57aab72b54f', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier l’indicateur et sa définition statistique.</p><p>Étape 2. Vérifier source, période, unité et population couverte.</p><p>Étape 3. Distinguer niveau, variation nominale et variation réelle.</p><p>Étape 4. Expliquer les canaux de transmission possibles.</p><p>Étape 5. Éviter de transformer un indicateur macroéconomique en prédiction certaine pour un individu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('909edf10-94e4-59d3-ba4c-dbb91a1aa4cb', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>ROE = résultat ÷ capitaux propres moyens, selon la convention d’analyse.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5bf6e87a-42c4-5f33-b162-8458767d04a0', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Cycle économique, taux et décisions d’entreprise », relevez les données disponibles, identifiez au moins quatre notions parmi Cycle économique, Taux d’intérêt, Dépense variable, Demande, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0d8dc077-acdc-5287-98b5-357a95dc0e8e', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une PME teste CA -10 %, coûts +5 % et délai client +15 jours dans un scénario défavorable.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('03243514-85f7-5507-96d4-170f502cd5a8', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Construire trois scénarios macro pour une PME fictive.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8e11de2c-21e1-50f9-a766-03fe1db9944e', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Chaque scénario relie hypothèse macro à variable opérationnelle sans certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a7bcd681-ade7-56bc-a0e7-b04cd7ffbba9', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('df993518-6d30-5fba-a147-09b032f4bea4', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('acf0cd48-8994-564e-8b2a-1155511a5216', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('61b4957b-3861-57a3-87bb-2841067bd6c3', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('24939e48-e606-53bf-9fa1-0d3c45ae6d1a', '37c0cfda-9eb8-5417-89e8-25dd3ffaa288', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Relier macro et budget"], ["Défi", "Identifier 5 variables sensibles"], ["Outil lié", "Scenario Lab"], ["Preuve Skills Passport", "Matrice macro"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S30, S32, S43"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
