INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5b9efe59-e43b-5314-bb26-b6635582df23', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Étudiants, dirigeants, importateurs/exportateurs"], ["Niveau", "N3"], ["Objectif measurable", "Comprendre comment des prix mondiaux et chocs externes peuvent affecter coûts, marges et budgets."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('270b6f3f-83f7-5979-8cc5-6cf6b275f00a', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Prix mondial", "prix de référence sur un marché international, variable selon produit, qualité, lieu et contrat.", "[S32]"], ["Matière première", "Ressource de base échangée et utilisée dans la production, dont le prix peut influencer coûts, inflation et commerce extérieur.", "[S32]"], ["Dépense variable", "Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1e34c955-a83b-54a6-843f-3083cc44ebb4', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre comment des prix mondiaux et chocs externes peuvent affecter coûts, marges et budgets. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c1423d2d-3b16-5773-bd1c-65a48884da4b', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Prix mondial — prix de référence sur un marché international, variable selon produit, qualité, lieu et contrat. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Matière première — Ressource de base échangée et utilisée dans la production, dont le prix peut influencer coûts, inflation et commerce extérieur. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Dépense variable — Dépense dont le montant évolue avec l’usage, les quantités ou les choix, par exemple alimentation, énergie ou transport. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5e9f1ad9-c4df-5081-9278-90ce40e43afe', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Matières premières, fret, devises et taux sont des canaux distincts. Pour matières premières, fret, devises et taux sont des canaux distincts, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>2. Un choc externe peut se transmettre avec délai. Pour un choc externe peut se transmettre avec délai, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>3. L’exposition dépend du modèle économique. Pour l’exposition dépend du modèle économique, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('505da157-e1cf-56e3-92b1-49a7f9e4be01', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier l’indicateur et sa définition statistique.</p><p>Étape 2. Vérifier source, période, unité et population couverte.</p><p>Étape 3. Distinguer niveau, variation nominale et variation réelle.</p><p>Étape 4. Expliquer les canaux de transmission possibles.</p><p>Étape 5. Éviter de transformer un indicateur macroéconomique en prédiction certaine pour un individu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('047d42f8-4df8-5b1a-a33e-18eb6c7e3bc3', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7a4c300e-8b4d-5993-a5f6-0cf48bdd8268', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Marchés mondiaux, matières premières et transmission des chocs », relevez les données disponibles, identifiez au moins quatre notions parmi Prix mondial, Matière première, Dépense variable, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('59438b4b-60cb-5167-bb22-690cb0be38c0', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 9, '{"html": "<h2>Approfondissement intégré — Marchés internationaux, indices et cycles</h2><ul><li><strong>Publics</strong> : Étudiants, cadres, investisseurs</li><li><strong>Compétences renforcées</strong> : comprendre indice boursier; lire les marchés mondiaux sans spéculation; relier cycles économiques et actifs</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Indice boursier</strong> : Mesure synthétique de la performance d’un ensemble de titres selon une méthodologie déterminée ; il sert de baromètre mais ne représente pas toute l’économie. — [S47]</li><li><strong>Cycle économique</strong> : Alternance de phases d’expansion, ralentissement ou contraction de l’activité, observée à travers plusieurs indicateurs et sans règle mécanique unique. — [S43], [S32]</li><li><strong>Marché financier</strong> : Ensemble organisé de mécanismes, acteurs et infrastructures permettant l’émission, la négociation, la conservation et le règlement de titres financiers. — [S38], [S40]</li><li><strong>Taux d’intérêt</strong> : Prix du temps et du crédit exprimé en pourcentage selon une convention et une période ; son interprétation exige de préciser base, durée, frais et capitalisation. — [S34], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5119489b-52ab-5a35-8ae5-c8f83832b9d4', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 10, '{"html": "<h3>Indice</h3><p>Un indice agrège la performance d''un ensemble de titres selon une méthodologie. Il sert de baromètre ou de référence, mais ne représente jamais parfaitement toute l''économie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b93ce3f7-a22f-5f78-aa1f-ac8d839154dd', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 11, '{"html": "<h3>Marchés mondiaux</h3><p>Les grands marchés sont influencés par résultats des entreprises, taux, inflation, innovation, géopolitique, monnaies et flux d''investisseurs. FINCLUDIA doit enseigner l''analyse plutôt que produire un classement de « meilleurs placements ».</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('206b63cc-5401-55ce-81ae-86e2d8c4f3d5', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 12, '{"html": "<h3>Cycles</h3><p>Expansion, ralentissement, récession et reprise peuvent influencer bénéfices, emploi, crédit et actifs, mais les marchés anticipent souvent et ne suivent pas mécaniquement le PIB.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f9c09603-ce88-5671-9741-cf3cf98753b0', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'callout', 13, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Un indice peut monter alors qu''une partie des entreprises ou ménages souffrent. Les indices pondérés peuvent aussi être dominés par quelques grandes sociétés.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e36bb00b-d8ee-5eed-9a8d-b1979a12d217', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 14, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Choisissez deux indices internationaux et comparez leur composition, devise et secteurs dominants.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3b93bea5-c641-5b90-891e-833a71e509df', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 15, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : pour chaque indice, relever méthodologie, principaux composants/pondérations, devise, secteurs dominants et zone géographique. Expliquer pourquoi deux indices peuvent évoluer différemment et pourquoi un indice n’est pas l’économie entière.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7412d91f-1703-5502-93b6-abb5eb6c8697', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 16, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ae7d4585-a393-5d6c-ab09-34f13d599d39', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 17, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Un indice boursier est :</strong><br>A. Un panier calculé selon une méthodologie<br>B. Une garantie de rendement<br>C. Une banque<br>D. Un impôt<br><em>A. Il agrège un ensemble de titres.</em></li><li><strong>2. Bourse et économie réelle évoluent toujours de manière identique ?</strong><br>A. Oui<br>B. Non<br>C. Toujours le même jour<br>D. Seulement en récession<br><em>B. Les marchés anticipent et reflètent d''autres facteurs.</em></li><li><strong>3. FINCLUDIA devrait classer automatiquement le « meilleur placement » ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Seulement pour étudiants<br><em>B. La décision dépend du profil et du risque.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ab4baaec-7cb2-530a-b06b-ca1519001983', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 18, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une PMI importatrice de matière première subit simultanément un fret plus cher et un changement de devise : l’effet sur marge doit être simulé séparément puis combiné.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('582ab92f-183f-59c6-a7dc-9cd277f550cd', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 19, '{"html": "<h2>Exercice d’application</h2><p>Décomposer un choc global en prix matière, change, transport et délai.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('960aca46-cb6b-5a98-9fa8-6dd0691f1a63', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 20, '{"html": "<h2>Corrigé-type</h2><p>Produire un tableau d’impact par variable et un scénario combiné.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bdec2f65-f111-5d5b-9463-d771d39caf50', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'table', 21, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('71ab399b-f275-518b-8a45-1621fa6bfabd', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 22, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cb1ba886-7684-56e9-a58e-f113007dd99e', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 23, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f6f90d3e-c47f-5c05-861a-d1a8826f6873', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'text', 24, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('59f9af92-ddf6-5659-bb1a-74ace0bbfda0', 'b0e4c37f-564e-5d5a-9e08-6882b84cf643', 'table', 25, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Construire une carte d’exposition"], ["Défi", "Trouver les 3 expositions majeures"], ["Outil lié", "Global Exposure Map"], ["Preuve Skills Passport", "Carte risques"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S19, S20, S21, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
