INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('77b8817a-f262-5017-af7e-36286ee40c29', 'e0333cc5-290e-5ce4-bc34-5d34c282cd30', 'single', 2, 'Quelle action correspond le mieux à l’objectif du module « Marchés mondiaux, matières premières et transmission des chocs » ?', 'La compétence est validée par une action observable directement reliée à l’objectif du module.', 1, '[]');
