INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('c43c9218-d6da-5203-b057-4739faeb47d9', 'dbbd5c9d-643c-53e2-b31f-7ca144ab77c4', 'ECO-10 — Lire une statistique économique avec esprit critique', 'Savoir lire source, période, unité, population, nominal/réel et limites.', NULL, 10, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('99bbaf50-3e2f-5487-859f-29da1ef8bb33', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Tous publics"], ["Niveau", "N2"], ["Objectif measurable", "Savoir lire source, période, unité, population, nominal/réel et limites."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5ed53bc4-40e8-5213-a8ba-b3caef394d25', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Indicateur", "mesure construite selon une méthode, un périmètre et une période qui doivent être connus avant interprétation.", "[S32]"], ["Inflation", "Hausse générale et durable du niveau des prix ; son suivi en Algérie s’appuie notamment sur l’indice des prix à la consommation publié par l’ONS.", "[S43]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a6b7a8c2-8ef4-56dd-a3d2-0f417690d838', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Savoir lire source, période, unité, population, nominal/réel et limites. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d15126a6-c8c0-5924-b0c0-32e53c2f644a', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Indicateur — mesure construite selon une méthode, un périmètre et une période qui doivent être connus avant interprétation. [S32]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p><p>Inflation — Hausse générale et durable du niveau des prix ; son suivi en Algérie s’appuie notamment sur l’indice des prix à la consommation publié par l’ONS. [S43]</p><p>Application dans ce module. L’utilisateur apprend à lire l’indicateur, sa source, sa période et son unité, puis à expliquer les mécanismes de transmission sans confondre corrélation, causalité et prévision certaine.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b6740a85-f383-5f76-af68-143e91626871', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Toujours lire source et date. Pour toujours lire source et date, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>2. Comparer des grandeurs homogènes. Pour comparer des grandeurs homogènes, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p><p>3. Une corrélation ne prouve pas une causalité. Pour une corrélation ne prouve pas une causalité, l''analyse commence par la définition statistique et la source. L''utilisateur précise la période, l''unité et le champ, puis explique au moins un mécanisme par lequel l''indicateur peut influencer ménages ou entreprises sans en déduire une causalité automatique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1062e7b5-90e5-5558-b82a-209a6b573786', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier l’indicateur et sa définition statistique.</p><p>Étape 2. Vérifier source, période, unité et population couverte.</p><p>Étape 3. Distinguer niveau, variation nominale et variation réelle.</p><p>Étape 4. Expliquer les canaux de transmission possibles.</p><p>Étape 5. Éviter de transformer un indicateur macroéconomique en prédiction certaine pour un individu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7598cca9-76f9-5430-b603-40349fe8af14', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Rendement réel exact = (1 + rendement nominal) ÷ (1 + inflation) − 1.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6b857f97-680e-5a0a-a222-fee2d5e6894d', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Lire une statistique économique avec esprit critique », relevez les données disponibles, identifiez au moins quatre notions parmi Indicateur, Inflation, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('13bcff18-0c8b-57bb-80fa-89d7bdd8889d', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Deux publications utilisent des périodes différentes pour l’inflation : les chiffres ne sont pas directement comparables sans harmoniser la période.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('45e44999-0e8f-5d9e-8113-e5b1e8f87582', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Auditer cinq captures d’indicateurs fictifs et repérer les informations manquantes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('865b8a3b-62ca-51ec-8418-5ae5830e7f73', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Attendus : source, période, unité, méthode ou population au minimum.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d602c6d7-2877-5db1-9f73-ecf93b68d1d4', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('74cc8432-0190-5937-9161-d177c8b83d9f', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('38634719-3f79-56ee-8082-330dccb75051', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('141c1d74-d204-5678-8897-f7f9c7120ea1', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b566339d-01da-5535-9358-b7f5fa53be73', 'c43c9218-d6da-5203-b057-4739faeb47d9', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer une fiche source"], ["Défi", "Refuser un chiffre sans date"], ["Outil lié", "Source Checker"], ["Preuve Skills Passport", "Fiche de vérification"], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S32, S43"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
