INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('36820c69-87bb-531f-aede-98464d956d5d', '5df1e399-0221-58b6-bbd7-f31fc5f98788', 1, 'Vérifier la source, la date d’effet, le périmètre et le statut de fraîcheur avant de conclure.', 1);
