INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('016aa0a5-a7ac-569b-9238-29fa574e5749', 'b4402fd8-05d2-59fe-9ec4-2cccb601645e', 'single', 5, 'Quelle preuve doit permettre au site de confirmer l’application de la compétence ?', 'La progression repose sur une preuve d’application, pas seulement sur la consultation du contenu.', 1, '[]');
