INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('be9fb758-0ea2-51b1-9b7a-ccc39a6e8c21', '016aa0a5-a7ac-569b-9238-29fa574e5749', 2, 'Fiche de vérification', 1);
