INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('a1cb1c04-ae8f-536b-a17c-0bbc45305a79', 'dbbd5c9d-643c-53e2-b31f-7ca144ab77c4', 'Cas intégrateur corrigé — Économie', NULL, NULL, 11, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3164a38c-f3e3-518c-9de6-7e19e300bacd', 'a1cb1c04-ae8f-536b-a17c-0bbc45305a79', 'text', 1, '{"html": "<h3>Scénario\\nScénario pédagogique : l’IPC augmente de 5 %, le taux de change DZD/EUR se déprécie de 8 % et le taux directeur augmente. Une famille consacre 40 000 DA/mois à des postes sensibles aux prix ; une PME importe 20 % de ses achats.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9d39adb6-199e-5248-9399-81f0050d649a', 'a1cb1c04-ae8f-536b-a17c-0bbc45305a79', 'text', 2, '{"html": "<h2>Travail demandé</h2><p>1. Calculer l’effet mécanique de +5 % sur 40 000 DA de dépenses.</p><p>2. Expliquer les canaux possibles d’un mouvement de change sur l’entreprise.</p><p>3. Expliquer le lien possible entre hausse des taux et crédit.</p><p>4. Distinguer PIB nominal et pouvoir d’achat.</p><p>5. Identifier les statistiques officielles à consulter avant toute conclusion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('442e321f-b109-5cc4-8972-6e50f52913c0', 'a1cb1c04-ae8f-536b-a17c-0bbc45305a79', 'text', 3, '{"html": "<h2>Corrigé-type</h2><p>40 000 × 1,05 = 42 000 DA, soit +2 000 DA si tous les postes suivent exactement le scénario. Une dépréciation peut renchérir les coûts importés en DZD ; une hausse des taux peut affecter le coût/accès au crédit selon le marché et les décisions bancaires. PIB et pouvoir d’achat mesurent des réalités différentes. Les données doivent être sourcées auprès des institutions statistiques et monétaires compétentes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('83ef99c6-dba6-5a34-b4c0-d7768207de71', 'a1cb1c04-ae8f-536b-a17c-0bbc45305a79', 'table', 4, '{"headers": ["Critère", "Poids"], "rows": [["Exactitude technique / calculs", "35 %"], ["Interprétation et décision", "25 %"], ["Gestion du risque / conformité", "20 %"], ["Traçabilité et sources", "10 %"], ["Clarté de l’explication", "10 %"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b0a2d6fe-08b5-59bf-8c0f-22f260bd46ec', 'a1cb1c04-ae8f-536b-a17c-0bbc45305a79', 'text', 5, '{"html": "<h3>Validation du cas intégrateur\\nSeuil : 75 %. Une erreur critique de sécurité, conformité, fraude, règle réglementaire active ou confusion réel/fictif doit être corrigée avant validation, même si le score global atteint 75 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('007c22ab-18bc-5214-82ed-c9bae207558c', 'academy-diaspora-finance', 'FINCLUDIA Academy — Diaspora Finance', 'Budget multidevises, patrimoine mondial, change, transferts, projets en Algérie, investissement, protection sociale et gouvernance à distance.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Diaspora Finance', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'intermediate', '["DIA-01 — Budget multi-devises", "DIA-02 — Patrimoine mondial consolidé", "DIA-03 — Risque de change", "DIA-04 — Transferts et traçabilité", "DIA-05 — Construire un projet Algérie", "DIA-06 — Investir en Algérie : cadre et démarches", "DIA-07 — Protection sociale volontaire", "DIA-08 — Risques et gouvernance d’un projet à distance"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '[]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('7cbe39fa-430a-547e-9b99-64be32087f4a', '007c22ab-18bc-5214-82ed-c9bae207558c', 'DIA-01 — Budget multi-devises', 'Gérer revenus, dépenses et objectifs dans plusieurs devises.', NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9fa68341-129d-590b-8939-e16577e047ae', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Diaspora"], ["Niveau", "N2-N4"], ["Objectif measurable", "Gérer revenus, dépenses et objectifs dans plusieurs devises."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a2d11187-e76a-52d1-9b5d-dd4a5b3e3c18', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01] [S32]"], ["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Patrimoine net", "Valeur des actifs détenus diminuée des dettes et autres passifs retenus.", "[S32]"], ["Origine des marchandises", "Lien économique ou douanier entre une marchandise et un pays, établi selon des règles spécifiques et pouvant influencer traitement et préférences.", "[S25], [S26]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ab7ea23f-15c5-5f3f-9cec-1ab9026e7934', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Gérer revenus, dépenses et objectifs dans plusieurs devises. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f9959201-ee42-5c65-909a-6bd63eeca50a', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01] [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Patrimoine net — Valeur des actifs détenus diminuée des dettes et autres passifs retenus. [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Origine des marchandises — Lien économique ou douanier entre une marchandise et un pays, établi selon des règles spécifiques et pouvant influencer traitement et préférences. [S25], [S26]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('50802972-1cd1-56fe-8f7e-b5bfeb1a8871', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Devise native. Dans un contexte diaspora, devise native est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>2. Devise de consolidation. Dans un contexte diaspora, devise de consolidation est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>3. Taux daté. Dans un contexte diaspora, taux daté est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>4. Historique des conversions. Dans un contexte diaspora, historique des conversions est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('924cb229-f737-5ca8-8883-b0a19ba7f7e5', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Conserver chaque montant dans sa devise d’origine.</p><p>Étape 2. Enregistrer taux et date de conversion.</p><p>Étape 3. Séparer budget de vie, soutien familial et projet Algérie.</p><p>Étape 4. Tracer les transferts et justificatifs.</p><p>Étape 5. Tester la sensibilité au change et à un retard de projet.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9ec234cb-a543-5321-ad32-3abdf0dbb927', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('92ef4f7a-496c-5c6b-b1a6-71aae47003b7', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Budget multi-devises », relevez les données disponibles, identifiez au moins quatre notions parmi Budget, Risque de change, Patrimoine net, Origine des marchandises, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c9722e9e-3251-5b29-9029-4a938d5fe883', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 9, '{"html": "<h2>Approfondissement intégré — Diaspora : patrimoine multi-devises et projet Algérie</h2><ul><li><strong>Publics</strong> : Diaspora algérienne</li><li><strong>Compétences renforcées</strong> : consolider EUR/DZD et actifs; séparer transfert, dépense et investissement; piloter un projet à distance</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Patrimoine net</strong> : Valeur des actifs détenus diminuée des dettes et autres passifs retenus. — [S32]</li><li><strong>Taux de change</strong> : Prix d’une monnaie exprimé dans une autre monnaie ; pour toute opération réelle, la source, la date et la règle de change applicable doivent être conservées. — [S20], [S21]</li><li><strong>Risque de change</strong> : Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. — [S20], [S21]</li><li><strong>Investissement en Algérie</strong> : Projet de création, extension ou autre opération d’investissement relevant du cadre de la loi 22-18 et des procédures d’enregistrement et d’accompagnement de l’AAPI. — [S28]</li><li><strong>Transfert de fonds</strong> : Mouvement d’argent entre personnes ou comptes ; FINCLUDIA distingue le déplacement de fonds d’un revenu nouvellement créé. — [S20], [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('82c87617-b47a-504e-ac27-eee4ad6b5c08', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 10, '{"html": "<h3>Patrimoine multi-devises</h3><p>Un membre de la diaspora peut avoir revenus, épargne et actifs dans plusieurs devises. FINCLUDIA doit conserver la devise d''origine et utiliser des conversions indicatives avec date/source.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5987a9e2-ef6d-5685-8590-f1c8e5c88df7', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 11, '{"html": "<h3>Project Control</h3><p>Pour un projet en Algérie, le tableau doit distinguer budget, décaissements, pièces, jalons, avance, retard et écart.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cbaf4b5c-4ea4-50a1-acb7-787dc4079cb6', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'callout', 12, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Projet à 25 000 EUR : 12 000 EUR déjà documentés, trois jalons sur cinq achevés. Le suivi doit montrer ce qui a été payé, à qui, pour quel jalon et avec quelle preuve.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9cb3836c-5b1c-5700-9554-8e46f00fc073', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 13, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Créez un budget projet en deux devises et identifiez l''exposition au change.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bcda0651-333c-50d2-8ec7-72a75c953f6a', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 14, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : conserver les montants dans leur devise d’origine, ajouter le taux et la date de conversion, puis présenter une vue consolidée. Tester plusieurs taux EUR/DZD pour mesurer l’exposition ; distinguer transfert familial, dépense de projet et investissement et rattacher chaque décaissement à un jalon/preuve.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5957cfaf-0bb3-53a1-ab95-ce53f27d6141', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 15, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cd50623e-9702-5e11-8a28-62f53c3c0a7c', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 16, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Une conversion EUR/DZD doit conserver :</strong><br>A. La date et le taux utilisé<br>B. Seulement le montant converti<br>C. Aucune source<br>D. Un rendement<br><em>A. La traçabilité est essentielle.</em></li><li><strong>2. Un transfert familial et un investissement sont :</strong><br>A. Toujours identiques<br>B. Des flux à distinguer<br>C. Des impôts<br>D. Des dividendes<br><em>B. Leur finalité et traitement diffèrent.</em></li><li><strong>3. Project Control sert à :</strong><br>A. Suivre budget et jalons<br>B. Prédire les élections<br>C. Remplacer un notaire<br>D. Fixer le taux de change<br><em>A. Il améliore la transparence du projet.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2132796d-db51-59d8-8a4c-6613d74a8c34', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 17, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un ingénieur en France perçoit 3 000 EUR et finance un projet familial en Algérie. FINCLUDIA conserve les montants d’origine en EUR et DZD et affiche une consolidation indicative avec taux daté.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('06395d71-76ee-5a12-9d5a-0149ad9cf30a', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 18, '{"html": "<h2>Exercice d’application</h2><p>Convertir 2 000 EUR au taux pédagogique de 150 DZD/EUR.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('39408e53-e977-5423-88f3-cbc77358f8cf', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 19, '{"html": "<h2>Corrigé-type</h2><p>300 000 DZD. Le taux est une hypothèse d’exercice, pas le taux officiel du jour.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8c410db3-8698-56a4-bae9-80bc84d2c14f', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'table', 20, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('07bac8cb-a388-5021-80da-f40f0d087617', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 21, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('950651b5-d83b-55f4-812c-ce175cd222e3', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 22, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5da7fae3-d6b5-5327-a0a9-98634a3ab2c6', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'text', 23, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7ae0226f-6e24-5e95-8ce9-12069da0b396', '7cbe39fa-430a-547e-9b99-64be32087f4a', 'table', 24, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un budget multi-devises."], ["Défi", "Comparer deux scénarios de change."], ["Outil lié", "Money Multi-FX"], ["Preuve Skills Passport", "Budget multi-devises."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S20, S21, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
