INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('52fcb7d5-6dc9-576d-ac59-4ad392b3e89b', '66887281-8785-5d77-a93e-ad5086bce6ae', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Diaspora"], ["Niveau", "N2-N4"], ["Objectif measurable", "Consolider actifs et dettes sans perdre la devise d’origine."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('008e446c-0e11-5f55-a1ae-690e279f6e33', '66887281-8785-5d77-a93e-ad5086bce6ae', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Patrimoine net", "Valeur des actifs détenus diminuée des dettes et autres passifs retenus.", "[S32]"], ["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Liquidité", "Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur.", "[S14] [S32]"], ["Origine des marchandises", "Lien économique ou douanier entre une marchandise et un pays, établi selon des règles spécifiques et pouvant influencer traitement et préférences.", "[S25], [S26]"], ["Épargne", "Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur.", "[S01], [S32]"], ["Dette", "Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d306a935-0a33-53bf-83d8-45c50b7c5ef3', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Consolider actifs et dettes sans perdre la devise d’origine. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9d529e7f-14bd-507f-b1a0-569691b94e69', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Patrimoine net — Valeur des actifs détenus diminuée des dettes et autres passifs retenus. [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Liquidité — Capacité d’un actif à être mobilisé rapidement en moyens de paiement avec peu de perte de valeur. [S14] [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Origine des marchandises — Lien économique ou douanier entre une marchandise et un pays, établi selon des règles spécifiques et pouvant influencer traitement et préférences. [S25], [S26]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Épargne — Part des ressources non consommée et mise de côté pour la sécurité, un objectif ou un investissement futur. [S01], [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Dette — Obligation de remboursement envers un tiers, suivie par son capital restant, sa mensualité, son coût et son échéance. [S01], [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3857d31a-a221-59d3-b91b-7e12285b33a8', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Actifs pays de résidence. Dans un contexte diaspora, actifs pays de résidence est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>2. Actifs Algérie. Dans un contexte diaspora, actifs algérie est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>3. Dettes. « Dettes » doit être relié à la nature et à la durée du besoin, au coût total, aux garanties éventuelles et à la capacité de remboursement. Une mensualité faible n''est pas suffisante pour juger la qualité d''un financement.</p><p>Repère de calcul. Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>4. Taux de conversion daté. Dans un contexte diaspora, taux de conversion daté est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('be68866f-dd91-54f7-888d-1a871e9d86bd', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Conserver chaque montant dans sa devise d’origine.</p><p>Étape 2. Enregistrer taux et date de conversion.</p><p>Étape 3. Séparer budget de vie, soutien familial et projet Algérie.</p><p>Étape 4. Tracer les transferts et justificatifs.</p><p>Étape 5. Tester la sensibilité au change et à un retard de projet.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('648245ee-d85e-5beb-89fe-3f2758aa2320', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Taux d’épargne = épargne de la période ÷ revenu disponible × 100.</p><p>Taux d’effort pédagogique = mensualités de dette ÷ revenu disponible × 100 ; il s’agit d’un indicateur, pas d’un seuil légal universel.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c9b1a022-42b1-5f3b-a011-53de9f6cde5f', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Patrimoine mondial consolidé », relevez les données disponibles, identifiez au moins quatre notions parmi Patrimoine net, Risque de change, Liquidité, Origine des marchandises, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3ed526ce-7b9e-58a2-8531-a7a8046d1a7c', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un utilisateur détient une épargne en EUR, un appartement en Algérie et une dette dans son pays de résidence. FINCLUDIA conserve chaque devise et calcule une vue consolidée indicative.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4dd1045c-966c-5968-a199-1af4ca766f98', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Construire une vue de patrimoine avec 4 actifs et 2 dettes dans 2 devises.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('177d2e37-3cca-598c-a7eb-5a3d4cc11e85', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Toutes les valeurs doivent conserver devise d’origine et date de conversion.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d84175c4-4b49-5ea1-805a-a759680043f0', '66887281-8785-5d77-a93e-ad5086bce6ae', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4b36cde4-7dd1-5dbd-97c3-938a0d989563', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('be64d9d7-1441-51eb-a3fa-7a335fb26940', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c5150872-c3af-57c8-b333-043311175e3e', '66887281-8785-5d77-a93e-ad5086bce6ae', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('370e8d0d-149a-5933-878d-977e4dad80a2', '66887281-8785-5d77-a93e-ad5086bce6ae', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer la carte patrimoniale."], ["Défi", "Mettre à jour les taux et mesurer l’effet FX."], ["Outil lié", "Patrimoine"], ["Preuve Skills Passport", "Net worth multi-FX."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S14, S20, S21, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
