INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('40688199-b44b-5de5-9462-035aefc40f52', '007c22ab-18bc-5214-82ed-c9bae207558c', 'DIA-03 — Risque de change', 'Comprendre comment la devise modifie le coût ou la valeur d’un projet.', NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2fa04726-0beb-5817-9d5b-b55136c73b22', '40688199-b44b-5de5-9462-035aefc40f52', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Diaspora"], ["Niveau", "N2-N4"], ["Objectif measurable", "Comprendre comment la devise modifie le coût ou la valeur d’un projet."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b81b3349-07b5-57fd-a147-4072199b29fd', '40688199-b44b-5de5-9462-035aefc40f52', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Besoin", "Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('50598800-3bcc-576c-807e-505e96049bce', '40688199-b44b-5de5-9462-035aefc40f52', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre comment la devise modifie le coût ou la valeur d’un projet. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('186e598a-80ce-58ce-ac66-88d7c6a9d09b', '40688199-b44b-5de5-9462-035aefc40f52', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Besoin — Dépense ou ressource répondant à une nécessité prioritaire dans un contexte donné ; son caractère essentiel dépend de la situation de la personne ou du foyer. [S01], [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('80d1ee39-3901-5342-8eba-3b4be85db860', '40688199-b44b-5de5-9462-035aefc40f52', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Exposition. L’exposition au change correspond au montant dont la valeur économique varie avec le taux de change. Elle dépend du calendrier des paiements et encaissements et peut être compensée partiellement par des flux dans la même devise.</p><p>2. Taux de référence. Dans un contexte diaspora, taux de référence est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>3. Sensibilité. Dans un contexte diaspora, sensibilité est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>4. Scénarios. Les scénarios permettent de tester la robustesse d’une décision. Un scénario central décrit l’hypothèse la plus probable ; un scénario prudent ou défavorable mesure ce qui se passe si les ventes baissent, les coûts montent ou les encaissements sont retardés.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c2450f93-3078-55f6-861b-d3a6cd70a136', '40688199-b44b-5de5-9462-035aefc40f52', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Conserver chaque montant dans sa devise d’origine.</p><p>Étape 2. Enregistrer taux et date de conversion.</p><p>Étape 3. Séparer budget de vie, soutien familial et projet Algérie.</p><p>Étape 4. Tracer les transferts et justificatifs.</p><p>Étape 5. Tester la sensibilité au change et à un retard de projet.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f4167534-08a2-52a6-b4ec-8b36a83785c5', '40688199-b44b-5de5-9462-035aefc40f52', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Risque de change », relevez les données disponibles, identifiez au moins quatre notions parmi Risque de change, Risque financier, Besoin, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bb723b19-cbb9-57d1-bae9-38c9dfd6ef89', '40688199-b44b-5de5-9462-035aefc40f52', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Projet Algérie de 5 M DA financé depuis l’euro : une variation du DZD/EUR modifie le montant d’euros nécessaire.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bc2d1d86-7366-5d13-aed2-4eb0fa977348', '40688199-b44b-5de5-9462-035aefc40f52', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Besoin 3 M DA ; taux 150 puis 165 DZD/EUR. Calculer EUR nécessaires dans chaque scénario.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('70be77e3-0c35-51af-a996-c1077b930e21', '40688199-b44b-5de5-9462-035aefc40f52', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>20 000 EUR puis ≈18 182 EUR.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cc5a43d7-8b33-5106-b872-cdbe38318d36', '40688199-b44b-5de5-9462-035aefc40f52', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d65f84ee-a8bb-52ea-95a5-4a0457668da7', '40688199-b44b-5de5-9462-035aefc40f52', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e0d61e1d-dd95-5a22-8ef6-0950cf67c756', '40688199-b44b-5de5-9462-035aefc40f52', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c62bec9a-166f-5bd7-8ea8-38cf5db28441', '40688199-b44b-5de5-9462-035aefc40f52', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5eeaacdc-c1a5-596c-b2b8-d1a83df9e670', '40688199-b44b-5de5-9462-035aefc40f52', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un stress test FX."], ["Défi", "Comparer ±10 % de taux."], ["Outil lié", "FX Simulator"], ["Preuve Skills Passport", "Rapport FX."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S20, S21, S22"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
