INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ace4f2d8-f0f4-5df7-84c2-8a023965e5a1', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Diaspora"], ["Niveau", "N2-N4"], ["Objectif measurable", "Comparer coût, délai, conformité et preuve des transferts via canaux légaux."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ffda28c6-733e-56ac-8f1f-2adb5a31c119', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Éducation financière bancaire", "Objectif de protection de la clientèle visant notamment la transparence et la capacité du client à prendre des décisions éclairées dans ses relations avec les banques et établissements concernés.", "[S22]"], ["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Traçabilité", "Capacité à reconstituer l’origine, la date, la justification et les étapes d’une opération ou d’une décision.", "[S32]"], ["Transfert de fonds", "Mouvement d’argent entre personnes ou comptes ; FINCLUDIA distingue le déplacement de fonds d’un revenu nouvellement créé.", "[S20], [S32]"], ["Offre", "Quantité d’un bien ou service que les producteurs sont disposés à proposer selon les prix et autres conditions.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('937bf31a-4935-5f37-b02b-484b1bef8f61', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comparer coût, délai, conformité et preuve des transferts via canaux légaux. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('92eb2a07-d861-5528-b797-8122a060d324', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Éducation financière bancaire — Objectif de protection de la clientèle visant notamment la transparence et la capacité du client à prendre des décisions éclairées dans ses relations avec les banques et établissements concernés. [S22]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Traçabilité — Capacité à reconstituer l’origine, la date, la justification et les étapes d’une opération ou d’une décision. [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Transfert de fonds — Mouvement d’argent entre personnes ou comptes ; FINCLUDIA distingue le déplacement de fonds d’un revenu nouvellement créé. [S20], [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Offre — Quantité d’un bien ou service que les producteurs sont disposés à proposer selon les prix et autres conditions. [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9df51324-0662-5737-a522-54d4e481c044', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Frais. Dans un contexte diaspora, frais est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>2. Taux. Le taux de change exprime la valeur d’une monnaie dans une autre. Une variation peut modifier le coût en dinars d’une importation, la valeur d’un actif étranger ou le montant reçu lors d’un transfert.</p><p>3. Délai. Dans un contexte diaspora, délai est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>4. Preuve. Pour « Preuve », la compétence est documentaire : savoir quelle information doit être conservée, qui l''émet, à quelle date et à quelle opération elle se rattache. Une trace exploitable doit permettre de reconstituer la décision.</p><p>5. Canal officiel. Dans un contexte diaspora, canal officiel est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('08324484-e17f-55ef-914b-751024d64aeb', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Conserver chaque montant dans sa devise d’origine.</p><p>Étape 2. Enregistrer taux et date de conversion.</p><p>Étape 3. Séparer budget de vie, soutien familial et projet Algérie.</p><p>Étape 4. Tracer les transferts et justificatifs.</p><p>Étape 5. Tester la sensibilité au change et à un retard de projet.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('58cf026b-304f-5700-b4f9-8efcd2c9cc34', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Transferts et traçabilité », relevez les données disponibles, identifiez au moins quatre notions parmi Éducation financière bancaire, Risque de change, Risque financier, Traçabilité, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e920e7f1-6856-56fb-ba31-c3004f2a63ee', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : FINCLUDIA compare les caractéristiques publiées des canaux légaux sans exécuter le transfert. Chaque offre doit avoir source et date.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ef108452-d6e8-5fab-a424-e38552ec8bb3', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Construire un comparatif à 5 critères entre deux solutions fictives.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('545026d4-1fa4-50b2-876f-6a10c21b77eb', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Critères : coût total, taux, délai, plafond, traçabilité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('39b1f49d-e069-56b3-8154-b89728502e55', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9e3062fa-2d60-5b2f-baf3-15b790a1de44', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a28f0669-7388-5cb8-87c9-9da0ca3939c3', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a2f3cd1a-a0f6-5e96-8c0d-779c49aa790b', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d808207d-e20f-52b0-a412-f784afb04e3d', '52959d0b-c950-58ba-abfa-23e48cb5546c', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Enregistrer un transfert comme preuve de projet."], ["Défi", "Atteindre 100 % de justificatifs sur un projet test."], ["Outil lié", "Comparateur"], ["Preuve Skills Passport", "Comparatif daté."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S20, S21, S22"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
