INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d6562abf-870b-5bfc-8a26-c18deb3328b0', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Diaspora"], ["Niveau", "N2-N4"], ["Objectif measurable", "Piloter budget, jalons, preuves et responsables."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a346cd46-776c-51ab-ad4e-ad561fc3b5c5', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Objectif financier", "Projet défini par un montant, un horizon, une priorité et une contribution à fournir.", "[S01] [S32]"], ["Investissement en Algérie", "Projet de création, extension ou autre opération d’investissement relevant du cadre de la loi 22-18 et des procédures d’enregistrement et d’accompagnement de l’AAPI.", "[S28]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Dépense", "Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité.", "[S32]"], ["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('13265fec-7409-5846-a38a-4f5195fe8d75', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Piloter budget, jalons, preuves et responsables. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b96457ff-448f-5a84-9225-b516487af6ba', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Objectif financier — Projet défini par un montant, un horizon, une priorité et une contribution à fournir. [S01] [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Investissement en Algérie — Projet de création, extension ou autre opération d’investissement relevant du cadre de la loi 22-18 et des procédures d’enregistrement et d’accompagnement de l’AAPI. [S28]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Dépense — Sortie de ressources destinée à acquérir un bien, un service ou à honorer une obligation. Dans FINCLUDIA, elle est classée par catégorie, caractère essentiel et périodicité. [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01], [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('096fd0a8-120d-5013-bd0d-d85e713cf8ac', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Budget. La politique budgétaire utilise les recettes, dépenses et soldes publics pour financer les missions de l’État et influencer l’activité économique.</p><p>Repère de calcul. Solde budgétaire = revenus de la période − dépenses de la période.</p><p>2. Jalons. Dans un contexte diaspora, jalons est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>3. Dépenses. Une dépense fixe revient de manière régulière et son montant est connu ou peu variable. Elle réduit la marge de manœuvre à court terme et doit être recensée avant les dépenses flexibles.</p><p>4. Preuves. Pour « Preuves », la compétence est documentaire : savoir quelle information doit être conservée, qui l''émet, à quelle date et à quelle opération elle se rattache. Une trace exploitable doit permettre de reconstituer la décision.</p><p>5. Responsable local. Dans un contexte diaspora, responsable local est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('12d4f5e0-5282-5f02-80a3-e731fbf72b55', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Conserver chaque montant dans sa devise d’origine.</p><p>Étape 2. Enregistrer taux et date de conversion.</p><p>Étape 3. Séparer budget de vie, soutien familial et projet Algérie.</p><p>Étape 4. Tracer les transferts et justificatifs.</p><p>Étape 5. Tester la sensibilité au change et à un retard de projet.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cc0b6793-4a23-5332-8599-7e5c74c88cf6', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bc787d9a-ff4a-5f83-8e3b-4023212e4700', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Construire un projet Algérie », relevez les données disponibles, identifiez au moins quatre notions parmi Objectif financier, Investissement en Algérie, Trésorerie, Dépense, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f5d86fba-0270-5828-8880-58b77c5acf03', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une famille diaspora finance la rénovation d’un logement à Tizi Ouzou : budget 4 M DA, 4 jalons, paiements documentés et marge d’imprévu.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6ba9bdff-84bc-555e-bddb-44f5dd9e3654', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Découper un projet de 4 M DA en 4 jalons avec 10 % d’imprévu.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bf148872-2909-5eaf-8b18-c25cf22844cf', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Budget opérationnel = 3,6 M DA + 0,4 M de réserve si l’on choisit 10 % du total.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a26e7294-075c-57f2-9792-a22870787e22', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('64268836-3608-5b0f-b4b5-1278d54255c8', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7bea987b-be20-5cb6-aba5-bf81ae03ff38', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('489c107b-7139-59a1-93df-755129eea567', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2d6b19da-fbc2-5d6c-b3e2-68bf60f57470', '09050d0c-ea8b-547c-ade8-1e9d16598436', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer Project Tracker."], ["Défi", "Aucune dépense sans jalon et preuve dans le cas pratique."], ["Outil lié", "Projet Algérie"], ["Preuve Skills Passport", "Budget + preuves."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S14, S28, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
