INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('68218439-4e5b-5a0b-8538-ad64c08fc637', '007c22ab-18bc-5214-82ed-c9bae207558c', 'DIA-06 — Investir en Algérie : cadre et démarches', 'Comprendre le cadre AAPI et les démarches sans promettre d’avantage.', NULL, 6, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a2b2853f-e4f5-5f40-b897-a8aed9a7ea42', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Diaspora investisseurs"], ["Niveau", "N2-N4"], ["Objectif measurable", "Comprendre le cadre AAPI et les démarches sans promettre d’avantage."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3eb74169-125e-52a5-abc8-dfc65103816a', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Investissement en Algérie", "Projet de création, extension ou autre opération d’investissement relevant du cadre de la loi 22-18 et des procédures d’enregistrement et d’accompagnement de l’AAPI.", "[S28]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Obligation", "Titre de créance par lequel l’investisseur prête des fonds à un émetteur selon des conditions de rémunération et de remboursement prévues.", "[S38], [S41]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e3612359-6821-5d69-9651-7de68cef10a6', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre le cadre AAPI et les démarches sans promettre d’avantage. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f0a01b0b-cb26-544f-b43b-af981530d542', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Investissement en Algérie — Projet de création, extension ou autre opération d’investissement relevant du cadre de la loi 22-18 et des procédures d’enregistrement et d’accompagnement de l’AAPI. [S28]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Obligation — Titre de créance par lequel l’investisseur prête des fonds à un émetteur selon des conditions de rémunération et de remboursement prévues. [S38], [S41]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fc3600bb-c8d8-5f34-bdc2-c5843dc73540', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Investisseur résident/non-résident. Dans un contexte diaspora, investisseur résident/non-résident est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>2. Enregistrement. Dans un contexte diaspora, enregistrement est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>3. Plateforme investisseur. Dans un contexte diaspora, plateforme investisseur est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>4. Droits et obligations. Dans un contexte diaspora, droits et obligations est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('014c88e4-16c8-5566-8fe7-31a627ef1fe1', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Conserver chaque montant dans sa devise d’origine.</p><p>Étape 2. Enregistrer taux et date de conversion.</p><p>Étape 3. Séparer budget de vie, soutien familial et projet Algérie.</p><p>Étape 4. Tracer les transferts et justificatifs.</p><p>Étape 5. Tester la sensibilité au change et à un retard de projet.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('473e8648-130e-5b93-8653-175e7aa57d42', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Investir en Algérie : cadre et démarches », relevez les données disponibles, identifiez au moins quatre notions parmi Investissement en Algérie, Risque financier, Obligation, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('29b24b52-eef0-5d6e-840b-0c0f2a2e2cbc', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Le guide AAPI rappelle que les personnes physiques ou morales, nationales ou étrangères, résidentes ou non-résidentes peuvent investir dans le cadre de la loi 22-18, selon procédures et conditions applicables.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('838cd111-6355-55ce-b254-e3e0926ef2d2', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Retrouver dans le guide AAPI les étapes d’enregistrement d’un projet fictif.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0d6e70c4-72d4-56c9-99e8-61fc610caae4', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>La preuve est la checklist sourcée et datée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('62a4591f-1f7c-5a11-91f1-079a11b146b7', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('81bb179d-e1be-55f9-a7ef-3754e8f46098', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('26d49ac9-9732-5405-892e-22513651c168', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('341e8623-34a1-5eb5-9de8-48c5ca575a9a', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f315d316-00d8-5609-8d47-d7a65b17462f', '68218439-4e5b-5a0b-8538-ad64c08fc637', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer le dossier Investissement."], ["Défi", "Valider tous les liens officiels."], ["Outil lié", "Reglo Invest"], ["Preuve Skills Passport", "Checklist AAPI."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S22, S28"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
