INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4d81ca64-d213-5301-b934-e2761037bc99', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Diaspora"], ["Niveau", "N2-N4"], ["Objectif measurable", "Connaître le parcours CNAS lorsque applicable."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f474ea4b-8228-5384-b8af-6adfc4117543', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Bien-être financier", "État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière.", "[S03]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Demande", "Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('32200c64-c636-539b-a84c-b5dff7a38694', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Connaître le parcours CNAS lorsque applicable. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bc86dae7-e171-586b-9d1a-476b7cb06fa7', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Bien-être financier — État dans lequel une personne peut gérer ses obligations, absorber des chocs, poursuivre ses objectifs et se sentir en confiance vis-à-vis de sa vie financière. [S03]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p><p>Demande — Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions. [S32]</p><p>Application dans ce module. La notion est appliquée en conservant la devise d’origine, le taux de conversion et sa date, ainsi que les preuves des transferts et des dépenses liées au projet en Algérie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d31c53cf-84c4-53ce-8868-e0faa472fb8a', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Demande. Dans un contexte diaspora, demande est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>2. Justificatifs. Pour « Justificatifs », la compétence est documentaire : savoir quelle information doit être conservée, qui l''émet, à quelle date et à quelle opération elle se rattache. Une trace exploitable doit permettre de reconstituer la décision.</p><p>3. Suivi. Dans un contexte diaspora, suivi est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p><p>4. Centre d’affiliation. Dans un contexte diaspora, centre d’affiliation est suivi avec la devise d''origine, la date, le taux de conversion éventuel et le justificatif. FINCLUDIA distingue la valeur économique réelle du simple effet de conversion comptable.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2bf864bb-7a05-5558-a484-843dcff8e5ac', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Conserver chaque montant dans sa devise d’origine.</p><p>Étape 2. Enregistrer taux et date de conversion.</p><p>Étape 3. Séparer budget de vie, soutien familial et projet Algérie.</p><p>Étape 4. Tracer les transferts et justificatifs.</p><p>Étape 5. Tester la sensibilité au change et à un retard de projet.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ae83b5a-52bb-5a7a-a9a5-fcbc609d12fe', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Protection sociale volontaire », relevez les données disponibles, identifiez au moins quatre notions parmi Bien-être financier, Risque financier, Demande, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dd09ea04-2d91-5d3f-bac3-4e0ec1863dfa', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : La CNAS dispose d’un parcours en ligne d’affiliation volontaire des membres de la communauté nationale à l’étranger avec pièces justificatives et suivi de demande.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a7444d25-3e02-5090-9fb5-e21184924cbe', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Énumérer les catégories de pièces visibles sur le formulaire CNAS actuel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('96c83b39-3e4c-5d99-b166-9be721c1c720', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Extrait de naissance, passeport, carte consulaire, justificatif d’activité professionnelle, selon le formulaire actuel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('08b25d95-cbad-5ab0-a67d-fc7e5057235b', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3b5ec117-dd49-59ec-9320-8e040d35ee94', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5d27c25a-70bd-5e9b-af50-068d2693a711', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('329d7dee-1982-56d0-9ac9-681ca1600122', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fef825cc-2e34-5342-b9e5-6e02d9060e3a', '1d4cbebd-19dd-5381-8ccb-4ebe808472e1', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer une checklist sociale."], ["Défi", "Vérifier la page officielle avant chaque campagne pédagogique."], ["Outil lié", "Démarches"], ["Preuve Skills Passport", "Checklist CNAS."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S03, S22"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
