INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('8e9b2481-54bd-55d4-b099-30770cbc7f8a', '007c22ab-18bc-5214-82ed-c9bae207558c', 'Cas intégrateur corrigé — Diaspora Finance', NULL, NULL, 9, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d5843d68-24ee-5007-845d-5f1cbf20f357', '8e9b2481-54bd-55d4-b099-30770cbc7f8a', 'text', 1, '{"html": "<h3>Scénario\\nUn membre de la diaspora reçoit 2 600 EUR/mois, dépense 1 700 EUR dans son pays de résidence, transfère 250 EUR à sa famille et affecte 300 EUR/mois à un projet en Algérie. Le reste constitue une marge. Il veut suivre la valeur DZD avec un taux sourcé et daté.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e1d697af-1512-5c38-9c61-aa6de594bb53', '8e9b2481-54bd-55d4-b099-30770cbc7f8a', 'text', 2, '{"html": "<h2>Travail demandé</h2><p>1. Calculer la marge mensuelle en EUR.</p><p>2. Séparer les flux du budget résidence, soutien familial et projet Algérie.</p><p>3. Expliquer pourquoi la conversion en DZD ne crée pas un nouveau revenu.</p><p>4. Construire un stress de change ±10 %.</p><p>5. Définir les preuves à conserver pour le projet Algérie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('15d750c9-cd3c-5332-a100-74cbcb656827', '8e9b2481-54bd-55d4-b099-30770cbc7f8a', 'text', 3, '{"html": "<h2>Corrigé-type</h2><p>Marge = 2 600 - 1 700 - 250 - 300 = 350 EUR. Chaque poche doit être suivie séparément. La conversion change l’unité de mesure, pas le revenu économique. Le stress ±10 % doit conserver taux, date et devise d’origine. Les preuves peuvent inclure budget, jalons, documents, justificatifs et validations du projet.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fc6d3b1d-5ee1-5bbb-b271-1438937247df', '8e9b2481-54bd-55d4-b099-30770cbc7f8a', 'table', 4, '{"headers": ["Critère", "Poids"], "rows": [["Exactitude technique / calculs", "35 %"], ["Interprétation et décision", "25 %"], ["Gestion du risque / conformité", "20 %"], ["Traçabilité et sources", "10 %"], ["Clarté de l’explication", "10 %"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d936a0c3-6eb4-5278-910b-d4c34f10cebe', '8e9b2481-54bd-55d4-b099-30770cbc7f8a', 'text', 5, '{"html": "<h3>Validation du cas intégrateur\\nSeuil : 75 %. Une erreur critique de sécurité, conformité, fraude, règle réglementaire active ou confusion réel/fictif doit être corrigée avant validation, même si le score global atteint 75 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('0afccae8-5a8e-5c40-963c-e8f9d9179ce8', 'academy-micro-importation', 'FINCLUDIA Academy — Micro-importation', 'Cadre, produit, budget voyage, coût rendu, prix, douane/fiscalité, documents, stock et trésorerie.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Micro-importation', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'advanced', '["MI-01 — Cadre de la micro-importation", "MI-02 — Choisir un produit importable et rentable", "MI-03 — Budget du déplacement", "MI-04 — Calculer le coût rendu", "MI-05 — Fixer prix et marge", "MI-06 — Douane, fiscalité et comptabilité simplifiée", "MI-07 — Documents, déclaration et conformité", "MI-08 — Stock, trésorerie et cycle de vente"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '[]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('01b33aa9-3157-51e2-b158-84303ee09dcd', '0afccae8-5a8e-5c40-963c-e8f9d9179ce8', 'MI-01 — Cadre de la micro-importation', 'Comprendre la définition légale, le statut requis et les limites actives.', NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('137c2653-253b-5e30-9e6a-f449ee841487', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Micro-importateurs"], ["Niveau", "N3-N4"], ["Objectif measurable", "Comprendre la définition légale, le statut requis et les limites actives."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e011e4f1-c4e8-5acc-90d4-0aa54448194c', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Micro-importation", "Activité individuelle exercée sous statut auto-entrepreneur lors de déplacements à l’étranger pour importer à la revente des quantités limitées de biens dans les limites prévues par le décret 25-170.", "[S23] [S24]"], ["Auto-entrepreneur", "Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles.", "[S09] [S10]"], ["IFU", "Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur.", "[S04]"], ["Action", "Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre.", "[S38], [S41]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e2f96a7c-88ff-52fb-8f4e-0f5bcbfd4b79', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre la définition légale, le statut requis et les limites actives. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1eded7bc-4f51-5487-b94c-611c6c19b0dd', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Micro-importation — Activité individuelle exercée sous statut auto-entrepreneur lors de déplacements à l’étranger pour importer à la revente des quantités limitées de biens dans les limites prévues par le décret 25-170. [S23] [S24]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Auto-entrepreneur — Statut algérien accessible à une personne physique remplissant les conditions légales et exerçant une activité figurant sur la liste officielle des activités éligibles. [S09] [S10]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>IFU — Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur. [S04]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Action — Titre représentant une fraction du capital d’une société et exposant son détenteur au potentiel de gain comme au risque de perte, selon les droits attachés au titre. [S38], [S41]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fa1d8a53-5ff4-5aea-a2fc-87b70e5c9151', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Décret 25-170. Pour décret 25-170, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>2. Statut auto-entrepreneur. Pour statut auto-entrepreneur, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>3. Limite par déplacement. Pour limite par déplacement, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>4. Nombre maximal de déplacements. Pour nombre maximal de déplacements, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>5. Règles fiscales/douanières versionnées. Pour règles fiscales/douanières versionnées, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fe98f5a5-fa53-50c1-9417-8cee30b7b128', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier éligibilité et règles actives.</p><p>Étape 2. Construire le coût complet du voyage et du lot.</p><p>Étape 3. Calculer coût unitaire, prix et marge.</p><p>Étape 4. Contrôler documents, stock et trésorerie.</p><p>Étape 5. Clôturer l’opération avec preuve et retour d’expérience.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c6135fe9-9461-5b69-8c39-2bc6e806b628', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Cadre de la micro-importation », relevez les données disponibles, identifiez au moins quatre notions parmi Micro-importation, Auto-entrepreneur, IFU, Action, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3e23e047-bcdc-53ec-9432-39157c6fd5e6', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Le décret 25-170 définit la micro-importation comme des opérations individuelles lors de déplacements à l’étranger, pour revente en l’état, dans la limite actuellement fixée à 1,8 M DA par déplacement et deux déplacements par mois au maximum. FINCLUDIA doit dater ces valeurs.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8f57f7ae-7811-5e97-b2fb-baf1ad175d97', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Un utilisateur prévoit 3 voyages dans le même mois : quelle action FINCLUDIA doit-il faire ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7ab6359c-d5c2-5586-ab12-956b06d1849f', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Afficher une incompatibilité apparente avec la limite actuelle et renvoyer vers la règle officielle ; ne pas autoriser le moteur à présenter le dossier comme conforme.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ee589560-7f7c-5917-835e-6a4664750af8', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('af36ec39-3aff-5e10-bd0a-00eba576ed07', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b0981a76-a973-5d07-a447-c20c5c5666c2', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1888d9f2-4d8b-5d26-8576-5605523afc02', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('29fda603-c52b-58a0-81da-e210785926ed', '01b33aa9-3157-51e2-b158-84303ee09dcd', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Valider la checklist réglementaire."], ["Défi", "Passer un quiz de conformité à 100 % sur les règles critiques."], ["Outil lié", "Reglo MicroImport"], ["Preuve Skills Passport", "Checklist datée."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S04, S09, S10, S23, S24"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
