INSERT IGNORE INTO `quiz_questions` (`id`, `quizId`, `type`, `position`, `prompt`, `explanation`, `points`, `acceptedAnswers`) VALUES ('8059d195-c6e3-5ab0-87e9-49fcf4d85fd4', '71b10a2d-bed2-5358-9066-e69b777f1e40', 'single', 3, 'Dans le cas pratique du module, quelle démarche est la plus correcte ?', 'Le corrigé-type exige un raisonnement explicite, traçable et cohérent avec les données du cas.', 1, '[]');
