INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', '0afccae8-5a8e-5c40-963c-e8f9d9179ce8', 'MI-02 — Choisir un produit importable et rentable', 'Évaluer demande, marge, volume, transport et conformité avant achat.', NULL, 2, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3cf87ccf-dbdf-5be2-a45d-5c22bdac6927', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Micro-importateurs"], ["Niveau", "N3-N4"], ["Objectif measurable", "Évaluer demande, marge, volume, transport et conformité avant achat."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('148d7269-0ba1-5201-a5e1-096c488ea415', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Coût rendu", "Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus.", "[S19] [S25] [S32]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Marge sur coûts variables", "Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité.", "[S16]"], ["Conformité", "Respect des règles, procédures, autorisations et exigences applicables à une activité, un produit, une opération ou un acteur.", "[S25], [S31], [S32]"], ["Demande", "Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cda30675-4d2d-5381-8717-358f063782e4', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Évaluer demande, marge, volume, transport et conformité avant achat. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3dd4edd4-2a3b-5baa-ad2b-fe53563fe40c', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Coût rendu — Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus. [S19] [S25] [S32]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Marge sur coûts variables — Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité. [S16]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Conformité — Respect des règles, procédures, autorisations et exigences applicables à une activité, un produit, une opération ou un acteur. [S25], [S31], [S32]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Demande — Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions. [S32]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('122fdda4-b5c3-595f-b6b6-b0d860bd9515', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Prix achat. Pour « Prix achat », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>2. Volume/poids. Pour volume/poids, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>3. Demande. Pour demande, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>4. Conformité. Pour conformité, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>5. Marge. La marge est l’écart entre un prix de vente ou un chiffre d’affaires et une catégorie de coûts déterminée. Avant de comparer deux marges, il faut utiliser la même définition et le même périmètre de coûts.</p><p>6. Risque invendu. Le risque lié à « Risque invendu » doit être décrit par sa cause, sa probabilité, son impact et les mesures de réduction possibles. FINCLUDIA ne cherche pas à supprimer toute incertitude, mais à rendre le risque visible et documenté.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('26e914b0-a216-52ff-a8c5-910ebc3a750a', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier éligibilité et règles actives.</p><p>Étape 2. Construire le coût complet du voyage et du lot.</p><p>Étape 3. Calculer coût unitaire, prix et marge.</p><p>Étape 4. Contrôler documents, stock et trésorerie.</p><p>Étape 5. Clôturer l’opération avec preuve et retour d’expérience.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9c965458-42d2-5840-b68b-c88ffa6d1b03', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Marge sur coûts variables = chiffre d’affaires − charges variables.</p><p>Coût rendu = achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques + autres coûts attribuables.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ca061b97-bb17-50e2-b47e-8a7ecb5b42cc', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Choisir un produit importable et rentable », relevez les données disponibles, identifiez au moins quatre notions parmi Coût rendu, Risque financier, Marge sur coûts variables, Conformité, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('58338710-d313-5a33-bc8b-bd3543bd51ca', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un micro-importateur hésite entre accessoires légers à forte marge et articles volumineux à faible marge. Le choix doit intégrer transport, droits, risque et rotation, pas seulement le prix fournisseur.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0e6141e9-ab32-5501-997f-68ae23c8b8ab', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Comparer deux produits fictifs avec prix, poids, transport et prix de vente.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d2ee39d1-5515-5838-9aa4-dc1059225acf', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Calculer coût rendu unitaire et marge de chacun avant décision.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('68ded914-b4cd-5217-b973-c154398a68dd', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2d9a0f56-c164-5008-871f-f65de4b5b3e2', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5e818a6e-1db7-5c20-b267-f072748dc23f', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d9f14711-0003-522f-afa3-d5572225f9dd', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bf630057-a4db-5177-a76b-19e1b987346d', '48ae04f0-4d7b-5ba2-aeee-a9745c8f0838', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer une fiche produit."], ["Défi", "Rejeter tout produit dont la conformité n’est pas vérifiée."], ["Outil lié", "Product Screen"], ["Preuve Skills Passport", "Fiche produit."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S16, S19, S22, S25, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
