INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', '0afccae8-5a8e-5c40-963c-e8f9d9179ce8', 'MI-03 — Budget du déplacement', 'Budgéter voyage et achat sans mélanger allocation touristique et financement activité.', NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a411b61e-faac-5bd3-a52b-f5396fe5428e', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Micro-importateurs"], ["Niveau", "N3-N4"], ["Objectif measurable", "Budgéter voyage et achat sans mélanger allocation touristique et financement activité."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('eca4a4af-3c45-5c10-b725-b5707c73cb0b', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Budget", "Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages.", "[S01] [S32]"], ["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Micro-importation", "Activité individuelle exercée sous statut auto-entrepreneur lors de déplacements à l’étranger pour importer à la revente des quantités limitées de biens dans les limites prévues par le décret 25-170.", "[S23] [S24]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('db122504-6617-50a1-a659-81abf1ba381c', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Budgéter voyage et achat sans mélanger allocation touristique et financement activité. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0e236e58-efcf-5d3c-9fb4-66719873217c', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Budget — Plan chiffré qui rapproche, sur une période, les ressources attendues des dépenses prévues afin d’anticiper un solde et des arbitrages. [S01] [S32]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Micro-importation — Activité individuelle exercée sous statut auto-entrepreneur lors de déplacements à l’étranger pour importer à la revente des quantités limitées de biens dans les limites prévues par le décret 25-170. [S23] [S24]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5f8b8eac-7d8b-5875-ab59-6b09a1e4756a', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Billet. Pour billet, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>2. Hébergement. Pour hébergement, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>3. Transport. Pour transport, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>4. Achat. L’achat correspond ici au prix facturé par le fournisseur pour les biens ou services. En commerce international, le montant doit être conservé dans sa devise d’origine, rapproché de la facture et converti avec un taux daté seulement pour les besoins du calcul en dinars.</p><p>5. Frais. Pour frais, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>6. Marge sécurité. La marge mesure ce qui reste après certains coûts, selon la convention choisie. Il faut toujours préciser de quelle marge on parle et quels coûts ont été déduits.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('61de514a-2407-527d-aa65-e3926567725b', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier éligibilité et règles actives.</p><p>Étape 2. Construire le coût complet du voyage et du lot.</p><p>Étape 3. Calculer coût unitaire, prix et marge.</p><p>Étape 4. Contrôler documents, stock et trésorerie.</p><p>Étape 5. Clôturer l’opération avec preuve et retour d’expérience.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b0535d46-5602-58dc-980e-feac67752383', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('698de62a-6014-5a7d-9546-0ecbe47fcf50', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Budget du déplacement », relevez les données disponibles, identifiez au moins quatre notions parmi Budget, Risque de change, Micro-importation, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e0ef8d0c-853a-5ecf-bcb7-2d23bda9dc86', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : FINCLUDIA sépare budget personnel du voyage et budget marchandises de l’activité. Les règles de financement en devises doivent être chargées depuis les sources officielles/ANAE.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c59a4caa-e5e8-55e4-a95d-c383eb32f42d', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Construire un budget voyage de 250 000 DA hors achat marchandises.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b0c9aaec-3f32-59b9-9c6e-58ee77ee88af', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Le corrigé vérifie cohérence des catégories et réserve, pas un montant unique.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b97d60cc-94a7-55ee-b8bf-44ac97cbeb56', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('342fb71f-bc84-5ff6-81c8-97c988e77f9f', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5aaececb-940c-542a-97d0-f76ee84ca28e', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8d2e2719-fdd5-5297-bebf-0f00f9103423', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('df964d14-92cc-5202-8661-58a248598f08', 'fe563774-6727-5bc2-a10f-4d1cbdb8a9f9', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer Travel Budget."], ["Défi", "Respecter l’enveloppe dans un cas simulé."], ["Outil lié", "MicroImport Budget"], ["Preuve Skills Passport", "Budget voyage."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S01, S20, S21, S23, S24, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
