INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', '0afccae8-5a8e-5c40-963c-e8f9d9179ce8', 'MI-04 — Calculer le coût rendu', 'Calculer le coût complet avant prix de vente.', NULL, 4, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('67019b01-03c5-5879-a5e7-78c673f2aef2', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Micro-importateurs"], ["Niveau", "N3-N4"], ["Objectif measurable", "Calculer le coût complet avant prix de vente."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('014eec7c-25f5-5268-b125-6e1061be0e5c', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Coût rendu", "Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus.", "[S19] [S25] [S32]"], ["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Micro-importation", "Activité individuelle exercée sous statut auto-entrepreneur lors de déplacements à l’étranger pour importer à la revente des quantités limitées de biens dans les limites prévues par le décret 25-170.", "[S23] [S24]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('df7639ab-fcae-5c6a-908e-c9f6f56b865b', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Calculer le coût complet avant prix de vente. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('20de6b20-bb3e-53ae-9482-7498d3237a6f', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Coût rendu — Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus. [S19] [S25] [S32]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Micro-importation — Activité individuelle exercée sous statut auto-entrepreneur lors de déplacements à l’étranger pour importer à la revente des quantités limitées de biens dans les limites prévues par le décret 25-170. [S23] [S24]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('58adb95c-e3c9-542b-9862-9fd48e9aba1d', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Achat converti. L’achat converti est la valeur du prix fournisseur après conversion dans la devise de pilotage. FINCLUDIA conserve toujours le montant d’origine, la devise, le taux utilisé et sa date afin de rendre le calcul vérifiable.</p><p>2. Fret/transport. Pour fret/transport, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>3. Droits/taxes. Les droits et taxes sont des prélèvements liés à l’opération selon la réglementation applicable. Ils doivent être calculés à partir des règles actives, de l’assiette et du classement pertinents ; FINCLUDIA ne les fige jamais dans un cours permanent.</p><p>4. Frais. Pour frais, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>5. Coût unitaire. Pour « Coût unitaire », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3b15c784-bf13-5a6f-aeeb-ea3519dea5be', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier éligibilité et règles actives.</p><p>Étape 2. Construire le coût complet du voyage et du lot.</p><p>Étape 3. Calculer coût unitaire, prix et marge.</p><p>Étape 4. Contrôler documents, stock et trésorerie.</p><p>Étape 5. Clôturer l’opération avec preuve et retour d’expérience.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6527ba30-aae1-5f8a-9d4f-d9c4d4442f07', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Coût rendu = achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques + autres coûts attribuables.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0e06431b-76f0-508a-af9b-2f07a80eef90', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Calculer le coût rendu », relevez les données disponibles, identifiez au moins quatre notions parmi Coût rendu, Risque de change, Micro-importation, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a705fa48-ca75-5b73-8854-b0c8dcd96fa9', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Achat équivalent 900 000 DA + 60 000 transport + 45 000 droits/frais + 25 000 local = 1 030 000 DA de coût rendu pédagogique avant autres éléments éventuels.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0414152d-3403-541c-b005-eb616dc0c246', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Coût total 1 200 000 DA pour 80 unités : coût unitaire ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7f909b39-912b-5aec-9a13-f01b91171c03', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>15 000 DA/unité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e8ac98cb-b159-5f3b-a766-a22ac7e68301', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9099ac28-6028-5227-a0f9-e568234b1ea2', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b9e1a0b2-868f-5d26-bec2-1f205acaaaba', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3883037c-762e-5d16-a040-ab5281f7d26b', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7f852598-e2b5-5389-904e-44dbeb7ed0c4', 'ab33dfb8-ac5d-5e05-a5b3-93ce91a667d3', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Utiliser Landed Cost Calculator."], ["Défi", "Tester choc FX +10 % et transport +15 %."], ["Outil lié", "Landed Cost"], ["Preuve Skills Passport", "Calcul enregistré."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S19, S20, S21, S23, S24, S25, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
