INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5d72cfca-b7dc-527b-ad66-0531d740458f', '12ce0032-2c36-58a6-aa61-d5aea2368838', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer 3 scénarios de prix."], ["Défi", "Tester 20 % d’invendus."], ["Outil lié", "Pricing"], ["Preuve Skills Passport", "Table prix/marge."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S16, S19, S25, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
