INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('cb3a59c5-b36a-563b-beb8-9698dcebd607', '0afccae8-5a8e-5c40-963c-e8f9d9179ce8', 'MI-06 — Douane, fiscalité et comptabilité simplifiée', 'Comprendre les règles applicables sans les figer.', NULL, 6, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1e205d99-c9ce-5295-b325-239e7a639c02', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Micro-importateurs"], ["Niveau", "N3-N4"], ["Objectif measurable", "Comprendre les règles applicables sans les figer."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b0c9adf3-1980-5ba1-9245-acbe1542278d', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Micro-importation", "Activité individuelle exercée sous statut auto-entrepreneur lors de déplacements à l’étranger pour importer à la revente des quantités limitées de biens dans les limites prévues par le décret 25-170.", "[S23] [S24]"], ["IFU", "Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur.", "[S04]"], ["Comptabilité financière", "Système d’organisation de l’information financière permettant de saisir, classer, évaluer et présenter des données donnant une image fidèle de la situation, de la performance et de la trésorerie.", "[S13]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('86777aaa-265a-580c-b066-cb142ff0fe2e', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre les règles applicables sans les figer. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1d4dbccb-0847-5081-b9fe-ee43636455fd', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Micro-importation — Activité individuelle exercée sous statut auto-entrepreneur lors de déplacements à l’étranger pour importer à la revente des quantités limitées de biens dans les limites prévues par le décret 25-170. [S23] [S24]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>IFU — Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur. [S04]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Comptabilité financière — Système d’organisation de l’information financière permettant de saisir, classer, évaluer et présenter des données donnant une image fidèle de la situation, de la performance et de la trésorerie. [S13]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d89dca00-d496-5fad-90e3-9f10f9f54a49', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Droit de douane actif. Pour droit de douane actif, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>2. Régime IFU spécifique. Pour régime ifu spécifique, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>3. Déclaration simplifiée. Pour déclaration simplifiée, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>4. Comptabilité simplifiée. Pour comptabilité simplifiée, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0f17170f-ac74-5db4-885c-04220d214c53', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier éligibilité et règles actives.</p><p>Étape 2. Construire le coût complet du voyage et du lot.</p><p>Étape 3. Calculer coût unitaire, prix et marge.</p><p>Étape 4. Contrôler documents, stock et trésorerie.</p><p>Étape 5. Clôturer l’opération avec preuve et retour d’expérience.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('80cf132d-6f26-55c1-a1b7-96b465f9737d', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Douane, fiscalité et comptabilité simplifiée », relevez les données disponibles, identifiez au moins quatre notions parmi Micro-importation, IFU, Comptabilité financière, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('368b9eaf-b800-5bea-bc7b-0ef031edaadb', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Le cadre actuel prévoit des règles douanières/fiscales spécifiques pour la micro-importation. FINCLUDIA doit lire les paramètres actifs du moteur réglementaire et afficher la source officielle avant tout calcul.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('52195975-44d9-5f2b-8ce1-cd324151554c', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Identifier les paramètres qui doivent être dynamiques dans le calculateur.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7a83e345-8159-5428-9d02-d405a86f163d', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Plafond, voyages, droits, base IFU, taux IFU, produits exclus, financement devises, documents.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9a85ebd0-ab4f-5320-a658-7d18a2ac8eeb', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('06e74833-4287-5f85-8864-13528e0c4933', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b0ba5e68-e7ae-5ae8-ab73-c95ebf42f197', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('16dccb97-7707-5af7-ac4c-9f4749fb4ebb', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d3f11c6f-c873-57c9-9f17-776108ee979a', 'cb3a59c5-b36a-563b-beb8-9698dcebd607', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Ouvrir le détail de la règle avant calcul."], ["Défi", "Recalculer un cas après changement fictif de règle."], ["Outil lié", "Reglo"], ["Preuve Skills Passport", "Trace de règle utilisée."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S04, S13, S23, S24"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
