INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('ab56c56e-2859-50ef-9206-74a6104da063', '0afccae8-5a8e-5c40-963c-e8f9d9179ce8', 'MI-07 — Documents, déclaration et conformité', 'Maintenir une preuve complète de l’opération.', NULL, 7, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e3e4f2ff-54f9-53a4-989a-acd719a18578', 'ab56c56e-2859-50ef-9206-74a6104da063', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Micro-importateurs"], ["Niveau", "N3-N4"], ["Objectif measurable", "Maintenir une preuve complète de l’opération."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('78cc39ed-a67b-5139-ad8b-f2f88414d47f', 'ab56c56e-2859-50ef-9206-74a6104da063', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Contrôle de conformité à l’importation", "Contrôle documentaire, visuel et, le cas échéant, analytique visant à vérifier la conformité des produits importés avant admission.", "[S25] [S31]"], ["Micro-importation", "Activité individuelle exercée sous statut auto-entrepreneur lors de déplacements à l’étranger pour importer à la revente des quantités limitées de biens dans les limites prévues par le décret 25-170.", "[S23] [S24]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Conformité", "Respect des règles, procédures, autorisations et exigences applicables à une activité, un produit, une opération ou un acteur.", "[S25], [S31], [S32]"], ["Facture", "Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables.", "[S04], [S05], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('47be6dd7-73c7-5bdf-8487-c2277090d73a', 'ab56c56e-2859-50ef-9206-74a6104da063', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Maintenir une preuve complète de l’opération. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('22461081-e8a7-5031-962e-0842baca4c4b', 'ab56c56e-2859-50ef-9206-74a6104da063', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Contrôle de conformité à l’importation — Contrôle documentaire, visuel et, le cas échéant, analytique visant à vérifier la conformité des produits importés avant admission. [S25] [S31]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Micro-importation — Activité individuelle exercée sous statut auto-entrepreneur lors de déplacements à l’étranger pour importer à la revente des quantités limitées de biens dans les limites prévues par le décret 25-170. [S23] [S24]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Conformité — Respect des règles, procédures, autorisations et exigences applicables à une activité, un produit, une opération ou un acteur. [S25], [S31], [S32]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Facture — Document commercial constatant une vente ou une prestation et précisant notamment parties, nature, quantité, prix et éléments fiscaux applicables. [S04], [S05], [S32]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('32e1728b-4d9d-5cc3-973d-5841de5fe133', 'ab56c56e-2859-50ef-9206-74a6104da063', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Carte/statut. Pour carte/statut, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>2. Déclaration préalable. Pour déclaration préalable, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>3. Factures. Une facture est à la fois une pièce commerciale et une preuve de créance ou de vente. Il faut en distinguer la date, le montant, l’objet, le client, les éléments fiscaux et l’état de paiement.</p><p>4. Liste marchandises. Pour liste marchandises, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>5. Étiquetage/preuves selon règles. Pour « Étiquetage/preuves selon règles », la compétence est documentaire : savoir quelle information doit être conservée, qui l''émet, à quelle date et à quelle opération elle se rattache. Une trace exploitable doit permettre de reconstituer la décision.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('177cd9fe-75c4-55c7-8b34-ab8e738c1819', 'ab56c56e-2859-50ef-9206-74a6104da063', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier éligibilité et règles actives.</p><p>Étape 2. Construire le coût complet du voyage et du lot.</p><p>Étape 3. Calculer coût unitaire, prix et marge.</p><p>Étape 4. Contrôler documents, stock et trésorerie.</p><p>Étape 5. Clôturer l’opération avec preuve et retour d’expérience.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2052192a-49e3-5f35-aa3b-4b40b1a0c366', 'ab56c56e-2859-50ef-9206-74a6104da063', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Documents, déclaration et conformité », relevez les données disponibles, identifiez au moins quatre notions parmi Contrôle de conformité à l’importation, Micro-importation, Risque financier, Conformité, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d1d9c92b-73cb-51c9-ae92-41a2807f4af2', 'ab56c56e-2859-50ef-9206-74a6104da063', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un lot sans preuve d’achat ou contenant un produit non autorisé doit déclencher un blocage pédagogique ''à vérifier'' et non être traité comme conforme.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('195007a4-3eb7-5705-b6b3-6695026c63e4', 'ab56c56e-2859-50ef-9206-74a6104da063', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Construire une checklist avant départ / achat / retour / vente.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d92ae1a7-ed71-568f-b318-7c33a3d745aa', 'ab56c56e-2859-50ef-9206-74a6104da063', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>La checklist doit séparer documents activité, marchandises et preuve de vente.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1c43021e-b2d3-58db-ba64-96e7cbf67e13', 'ab56c56e-2859-50ef-9206-74a6104da063', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('76f5385f-e344-574c-b9d1-53c6ae5d7f39', 'ab56c56e-2859-50ef-9206-74a6104da063', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ec67994a-f807-5a22-be70-200f69d9cc22', 'ab56c56e-2859-50ef-9206-74a6104da063', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4f20691a-9813-507b-8845-cb18f5b9dcb4', 'ab56c56e-2859-50ef-9206-74a6104da063', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b0f0a6e7-5e74-5e20-bf24-49971992c9e7', 'ab56c56e-2859-50ef-9206-74a6104da063', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Compléter le dossier opération."], ["Défi", "0 document critique manquant dans le cas pratique."], ["Outil lié", "Document Checklist"], ["Preuve Skills Passport", "Dossier complet."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S22, S23, S24, S25, S31"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
