INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('0c71858b-dc2a-54b8-a771-45a66a056b63', '0afccae8-5a8e-5c40-963c-e8f9d9179ce8', 'MI-08 — Stock, trésorerie et cycle de vente', 'Mesurer capital immobilisé, rotation et récupération du cash.', NULL, 8, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c692434a-18b1-508f-bcf4-baf2302c61bf', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Micro-importateurs"], ["Niveau", "N3-N4"], ["Objectif measurable", "Mesurer capital immobilisé, rotation et récupération du cash."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1a77b430-8b8c-5a75-b60d-7d3b037f9ea5', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["DIO", "Indicateur pédagogique du nombre moyen de jours pendant lesquels le stock reste immobilisé avant sa vente ou consommation.", "[S32]"], ["Besoin en fonds de roulement", "Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation.", "[S15]"], ["Trésorerie", "Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions.", "[S14] [S30]"], ["Coût rendu", "Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus.", "[S19] [S25] [S32]"], ["Stock", "Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés.", "[S13], [S42]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8ec0b4f0-ded2-5989-b211-c715a308c6b8', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Mesurer capital immobilisé, rotation et récupération du cash. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a3e082a4-e7b2-5249-b586-9b971c5e06c9', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>DIO — Indicateur pédagogique du nombre moyen de jours pendant lesquels le stock reste immobilisé avant sa vente ou consommation. [S32]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Besoin en fonds de roulement — Besoin de trésorerie créé par les décalages entre dépenses d’exploitation et encaissements ; de façon simplifiée, stocks + créances d’exploitation - dettes d’exploitation. [S15]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Trésorerie — Disponibilités et flux de liquidités mobilisables pour régler les obligations. Le pilotage distingue encaissements, décaissements et prévisions. [S14] [S30]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Coût rendu — Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus. [S19] [S25] [S32]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p><p>Stock — Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés. [S13], [S42]</p><p>Application dans ce module. L’utilisateur relie chaque décision au coût complet, à la marge, au stock, aux preuves et aux règles réglementaires versionnées avant chaque opération.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f275f2a9-cdc8-559c-8166-05de3d012a66', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Stock initial. « Stock initial » mobilise de la trésorerie tant que les biens ne sont pas vendus ou consommés. Le suivi doit combiner valeur du stock, vitesse de rotation, risque d''invendu et conséquences sur le BFR.</p><p>2. Ventes. Pour ventes, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>3. Invendus. Pour invendus, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>4. Rotation. Pour rotation, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p><p>5. Cash récupéré. Pour cash récupéré, le micro-importateur doit relier la décision au budget du déplacement, au coût rendu, à la marge, au stock et aux preuves exigées. Toute valeur réglementaire est lue depuis une règle versionnée à la date de l''opération.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6929c4ff-4c5b-5907-9e93-a1d31b934f46', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Vérifier éligibilité et règles actives.</p><p>Étape 2. Construire le coût complet du voyage et du lot.</p><p>Étape 3. Calculer coût unitaire, prix et marge.</p><p>Étape 4. Contrôler documents, stock et trésorerie.</p><p>Étape 5. Clôturer l’opération avec preuve et retour d’expérience.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bdeae3ec-649b-5e77-b2ba-1e0859576ba9', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>BFR simplifié = stocks + créances d’exploitation − dettes d’exploitation.</p><p>DIO pédagogique ≈ stock moyen ÷ coût des ventes × nombre de jours de la période.</p><p>Coût rendu = achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques + autres coûts attribuables.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2cdda0e5-2710-5a7f-a2ea-cfd04e419af1', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Stock, trésorerie et cycle de vente », relevez les données disponibles, identifiez au moins quatre notions parmi DIO, Besoin en fonds de roulement, Trésorerie, Coût rendu, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('04792a46-7c9b-5bcf-be8d-17bcaedc9af0', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un lot coûte 1,2 M DA et 70 % est vendu le premier mois. Les 30 % restants continuent à immobiliser du capital et doivent être suivis.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2ddb87c9-8e60-59e2-b013-307674d81281', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Lot 100 unités, 65 vendues : taux écoulement ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('70a98230-c64a-599d-bb08-d93864c2d220', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>65 %.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('449e34de-140d-5c84-95b8-3b5506f823ba', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8a4cf57a-7d98-5d35-8682-383dc65fecf4', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d119cf7f-6a81-5d18-aeb8-350bbbba2129', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2925750b-d530-5363-8259-ab18ea368d87', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0f15df77-4b62-58fb-a445-2ff940f105a3', '0c71858b-dc2a-54b8-a771-45a66a056b63', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un suivi lot par lot."], ["Défi", "Vendre fictivement 100 % du lot en optimisant marge et délai."], ["Outil lié", "Stock Lite"], ["Preuve Skills Passport", "Cycle lot complet."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S14, S15, S19, S25, S30, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
