INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('e24a99a4-d051-5389-8452-61338f9b5072', '0afccae8-5a8e-5c40-963c-e8f9d9179ce8', 'Cas intégrateur corrigé — Micro-importation', NULL, NULL, 9, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e48d7d33-1e55-5166-93e4-d9e006be2136', 'e24a99a4-d051-5389-8452-61338f9b5072', 'text', 1, '{"html": "<h3>Scénario\\nUn auto-entrepreneur prépare un déplacement pédagogique avec 900 000 DA de marchandises, 120 000 DA de voyage/logistique, 45 000 DA de frais divers et 25 000 DA de pertes/risques estimés. Il prévoit 150 unités revendues 9 000 DA pièce. Les limites réglementaires ne sont pas figées dans le cas : elles doivent être lues dans la capsule active.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e2b43ac2-c539-5d6f-9917-78f694499e0c', 'e24a99a4-d051-5389-8452-61338f9b5072', 'text', 2, '{"html": "<h2>Travail demandé</h2><p>1. Calculer le coût complet du lot.</p><p>2. Calculer le coût unitaire pédagogique.</p><p>3. Calculer le CA potentiel et la marge brute avant autres charges.</p><p>4. Vérifier la capsule réglementaire active avant validation du dossier.</p><p>5. Identifier les documents et preuves à conserver.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3494fea0-56fd-584a-9e31-baf41d53d2c6', 'e24a99a4-d051-5389-8452-61338f9b5072', 'text', 3, '{"html": "<h2>Corrigé-type</h2><p>Coût complet = 900 000 + 120 000 + 45 000 + 25 000 = 1 090 000 DA. Coût unitaire ≈ 7 266,67 DA. CA potentiel = 1 350 000 DA. Marge brute pédagogique = 260 000 DA avant autres charges/impôts. La conformité ne peut être validée qu’après lecture des paramètres réglementaires actifs et des documents requis.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2aab3e98-3848-5967-9c8b-b11d03325926', 'e24a99a4-d051-5389-8452-61338f9b5072', 'table', 4, '{"headers": ["Critère", "Poids"], "rows": [["Exactitude technique / calculs", "35 %"], ["Interprétation et décision", "25 %"], ["Gestion du risque / conformité", "20 %"], ["Traçabilité et sources", "10 %"], ["Clarté de l’explication", "10 %"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('55d19b6c-96b1-52d3-a71a-38e5e68e4af3', 'e24a99a4-d051-5389-8452-61338f9b5072', 'text', 5, '{"html": "<h3>Validation du cas intégrateur\\nSeuil : 75 %. Une erreur critique de sécurité, conformité, fraude, règle réglementaire active ou confusion réel/fictif doit être corrigée avant validation, même si le score global atteint 75 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('dd86ab27-9811-5ef9-bdb4-9c4f5f233445', 'academy-commerce-international', 'FINCLUDIA Academy — Commerce international', 'Flux trade, contreparties, Incoterms, paiements, change, coût rendu, douane, domiciliation, financement, export et risques.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Commerce international', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'advanced', '["TR-01 — Comprendre les trois flux du commerce international", "TR-02 — Qualifier fournisseur et contrepartie", "TR-03 — Comprendre les Incoterms® 2020", "TR-04 — Choisir un mode de paiement international", "TR-05 — Gérer le risque de change", "TR-06 — Calculer le coût rendu international", "TR-07 — Douane et conformité à l’importation", "TR-08 — Domiciliation et règles de change", "TR-09 — Financement du commerce extérieur", "TR-10 — Fixer un prix export", "TR-11 — Piloter une expédition", "TR-12 — Gérer les risques internationaux"]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '[]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'dd86ab27-9811-5ef9-bdb4-9c4f5f233445', 'TR-01 — Comprendre les trois flux du commerce international', 'Distinguer flux marchandises, flux financiers et flux documentaires.', NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dd3a6c40-cf5f-57a5-b3fc-7e017547689d', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Importateurs, exportateurs, PME/PMI"], ["Niveau", "N3-N5"], ["Objectif measurable", "Distinguer flux marchandises, flux financiers et flux documentaires."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('00846439-63cb-54b6-9335-ce3bef170712', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Incoterms®", "Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises.", "[S19]"], ["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Contrôle de conformité à l’importation", "Contrôle documentaire, visuel et, le cas échéant, analytique visant à vérifier la conformité des produits importés avant admission.", "[S25] [S31]"], ["Conformité", "Respect des règles, procédures, autorisations et exigences applicables à une activité, un produit, une opération ou un acteur.", "[S25], [S31], [S32]"], ["Ordre de bourse", "Instruction transmise à un intermédiaire habilité pour acheter ou vendre un instrument financier selon des conditions définies.", "[S39], [S40]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('756ba99c-b674-5a89-a630-3c4b836c5771', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Distinguer flux marchandises, flux financiers et flux documentaires. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d08b831b-4ab3-58ea-a459-8a007b5a260b', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Incoterms® — Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises. [S19]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Contrôle de conformité à l’importation — Contrôle documentaire, visuel et, le cas échéant, analytique visant à vérifier la conformité des produits importés avant admission. [S25] [S31]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Conformité — Respect des règles, procédures, autorisations et exigences applicables à une activité, un produit, une opération ou un acteur. [S25], [S31], [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Ordre de bourse — Instruction transmise à un intermédiaire habilité pour acheter ou vendre un instrument financier selon des conditions définies. [S39], [S40]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('97d2e46b-6646-545c-9b7c-26442ea0252c', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Flux physique. Le flux physique correspond au mouvement réel des marchandises : préparation, départ, transport, contrôle, arrivée et livraison. Sa chronologie peut être différente de celle du paiement et des documents.</p><p>2. Flux financier. Le flux financier décrit les paiements, financements, commissions, garanties et conversions de devises liés à l’opération. Il peut intervenir avant, pendant ou après le mouvement de la marchandise.</p><p>3. Flux documentaire. Le flux documentaire regroupe facture, transport, origine, assurance, documents bancaires et douaniers. Une incohérence de dates, montants ou désignations peut bloquer une opération même si la marchandise est conforme.</p><p>4. Acteurs : vendeur, acheteur, banque, transporteur, douane, assureur. Dans une opération internationale, acteurs : vendeur, acheteur, banque, transporteur, douane, assureur est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('105d7b0c-d626-53dc-96b7-d1c02263c4ae', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Cartographier marchandise, argent et documents.</p><p>Étape 2. Fixer contrat, Incoterm, mode de paiement et calendrier.</p><p>Étape 3. Calculer coût rendu ou prix export avec devise datée.</p><p>Étape 4. Vérifier banque, douane et conformité.</p><p>Étape 5. Construire un registre de risques et une preuve documentaire complète.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9e9605da-c251-5653-b392-59b5c51a2dcb', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Comprendre les trois flux du commerce international », relevez les données disponibles, identifiez au moins quatre notions parmi Incoterms®, Risque de change, Contrôle de conformité à l’importation, Conformité, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c5fd038e-603b-5ba3-a762-2f0647ec8de9', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une PME algérienne importe une machine d’Italie : la machine voyage physiquement, les documents suivent un circuit de conformité/transport et le paiement suit un circuit bancaire distinct.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4928b050-b255-5fee-b3c3-5d2335272f1f', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Dessiner les trois flux d’une importation fictive.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e389a1e3-7505-5a23-ba23-c31b2d3f370e', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Chaque flux doit mentionner acteur, document/objet et ordre des étapes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('04e591e2-858f-5c34-aab8-275d61d490f5', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6a72f539-e2d5-5879-af21-b33068a5668d', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('251cb45f-d45b-5347-845a-d6abcd023365', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ceb9b5cd-4e55-5ec4-a28a-4d531ec7d899', '4e601a15-3053-52d4-a7b7-dbe19f0d1e72', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
