INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'dd86ab27-9811-5ef9-bdb4-9c4f5f233445', 'TR-02 — Qualifier fournisseur et contrepartie', 'Réduire le risque avant contrat.', NULL, 2, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9302053b-ecc2-5938-812c-b974f227ef1f', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Importateurs, exportateurs"], ["Niveau", "N3-N5"], ["Objectif measurable", "Réduire le risque avant contrat."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e0db29b3-1afc-5a1c-bd09-5c75ac357415', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Diversification", "Répartition d’une exposition entre plusieurs actifs, activités, clients ou sources afin de limiter la dépendance à un seul élément.", "[S02] [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('289a8b12-0357-5a5c-a79c-cce493994efb', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Réduire le risque avant contrat. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('28f431f3-e0f6-5a1a-9ae0-ad0487b9ecaf', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Diversification — Répartition d’une exposition entre plusieurs actifs, activités, clients ou sources afin de limiter la dépendance à un seul élément. [S02] [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('58d12a15-1cc5-5f2f-a80b-cda17856f9cd', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Identité. Dans une opération internationale, identité est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>2. Références. Dans une opération internationale, références est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>3. Pays. Dans une opération internationale, pays est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>4. Conditions. Dans une opération internationale, conditions est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>5. Documents. Les documents rendent la situation financière vérifiable : factures, relevés, états financiers, contrats, justificatifs fiscaux ou commerciaux. Un dossier incomplet augmente l’incertitude du financeur et peut retarder la décision.</p><p>6. Historique. Dans une opération internationale, historique est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('abdcac4d-6028-57ff-bf96-4a409af2d1ae', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Cartographier marchandise, argent et documents.</p><p>Étape 2. Fixer contrat, Incoterm, mode de paiement et calendrier.</p><p>Étape 3. Calculer coût rendu ou prix export avec devise datée.</p><p>Étape 4. Vérifier banque, douane et conformité.</p><p>Étape 5. Construire un registre de risques et une preuve documentaire complète.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7b22c060-1e27-5f8a-81b6-82ea7349c7b5', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Qualifier fournisseur et contrepartie », relevez les données disponibles, identifiez au moins quatre notions parmi Risque financier, Diversification, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bcb11c4e-29e1-59bc-9a67-e83596f30963', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Avant une commande de 50 000 EUR, une PME vérifie identité légale, références, coordonnées bancaires, cohérence des documents et conditions commerciales du fournisseur.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e23e2746-2be0-58b7-8a7c-2df4ec2fd003', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Créer une grille de 10 contrôles contrepartie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b13765e3-d82c-5eaa-be4d-5608697dcef9', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>La grille doit inclure identité, preuves, coordonnées, références, pays, sanctions/règles selon sources pertinentes.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b06b04d7-77ce-58b6-b31d-ce194de1bfeb', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8ae63e55-5c17-5762-af8e-2d6d67607ead', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8513801d-a403-526c-bf2b-9b015c955902', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fe64b400-4c59-50ae-ae75-a0a32c32a0b7', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3d9ef336-e32b-554e-87c6-19d2a65c8ae1', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Évaluer un fournisseur fictif."], ["Défi", "Aucune alerte rouge non traitée."], ["Outil lié", "Counterparty Risk"], ["Preuve Skills Passport", "Fiche fournisseur."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S22, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('ff66974d-171d-5566-86b8-bcc894adba7e', 'dd86ab27-9811-5ef9-bdb4-9c4f5f233445', 'course', '0d9877ca-0368-5621-8b0a-8e8a2dcf9af4', 'QCM — TR-02', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
