INSERT IGNORE INTO `quiz_choices` (`id`, `questionId`, `position`, `text`, `isCorrect`) VALUES ('288dd872-48ec-5ed4-bae5-04aadccb379e', '096c8c93-90b3-5c94-af41-333aec8fa7dc', 1, 'Répartition d’une exposition entre plusieurs actifs, activités, clients ou sources afin de limiter la dépendance à un seul élément.', 0);
