INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('668cc3c4-142e-597c-804d-9eae911463f1', 'dd86ab27-9811-5ef9-bdb4-9c4f5f233445', 'TR-03 — Comprendre les Incoterms® 2020', 'Comprendre obligations, coûts et transfert des risques.', NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('69b7ba71-64b8-5a25-b764-3f2a136da0a4', '668cc3c4-142e-597c-804d-9eae911463f1', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Importateurs, exportateurs"], ["Niveau", "N3-N5"], ["Objectif measurable", "Comprendre obligations, coûts et transfert des risques."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d268d5d1-0356-5c40-ad07-67f95ead5aec', '668cc3c4-142e-597c-804d-9eae911463f1', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Incoterms®", "Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises.", "[S19]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Coût rendu", "Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus.", "[S19] [S25] [S32]"], ["Transfert de fonds", "Mouvement d’argent entre personnes ou comptes ; FINCLUDIA distingue le déplacement de fonds d’un revenu nouvellement créé.", "[S20], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('686df308-c348-533b-b1c2-f23465370d8f', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comprendre obligations, coûts et transfert des risques. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('74263c5f-d23b-5835-98ef-e2deceb5ecfe', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Incoterms® — Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises. [S19]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Coût rendu — Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus. [S19] [S25] [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Transfert de fonds — Mouvement d’argent entre personnes ou comptes ; FINCLUDIA distingue le déplacement de fonds d’un revenu nouvellement créé. [S20], [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fc6823b9-a1a0-528d-898f-fc2b8903fc52', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. 11 règles ICC. Dans une opération internationale, 11 règles icc est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>2. Lieu nommé. Dans une opération internationale, lieu nommé est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>3. Transport. Dans une opération internationale, transport est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>4. Assurance. L’assurance transfère certains risques définis au contrat contre une prime. Elle n’élimine pas tous les risques : exclusions, franchise, valeur assurée, procédure de déclaration et pièces justificatives doivent être comprises.</p><p>5. Formalités. Dans une opération internationale, formalités est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>6. Transfert du risque. Le risque lié à « Transfert du risque » doit être décrit par sa cause, sa probabilité, son impact et les mesures de réduction possibles. FINCLUDIA ne cherche pas à supprimer toute incertitude, mais à rendre le risque visible et documenté.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a7d99376-08ff-54ea-b8cb-d977fc2eff24', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Cartographier marchandise, argent et documents.</p><p>Étape 2. Fixer contrat, Incoterm, mode de paiement et calendrier.</p><p>Étape 3. Calculer coût rendu ou prix export avec devise datée.</p><p>Étape 4. Vérifier banque, douane et conformité.</p><p>Étape 5. Construire un registre de risques et une preuve documentaire complète.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1b2677c5-2e58-5a98-9267-6906dbe1a8cc', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Coût rendu = achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques + autres coûts attribuables.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('49987d8d-e4f6-5a45-8e48-7cebe22be5c3', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Comprendre les Incoterms® 2020 », relevez les données disponibles, identifiez au moins quatre notions parmi Incoterms®, Risque financier, Coût rendu, Transfert de fonds, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('90623de3-3132-5ada-87da-3fd136347360', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 9, '{"html": "<h2>Approfondissement intégré — Commerce international : Incoterms, paiements et risque</h2><ul><li><strong>Publics</strong> : Importateurs/exportateurs, micro-importateurs, PME</li><li><strong>Compétences renforcées</strong> : comprendre répartition coûts/risques; comparer moyens de paiement; identifier documents clés</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Incoterms®</strong> : Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises. — [S19]</li><li><strong>Remise documentaire</strong> : Mécanisme dans lequel des banques transmettent des documents contre paiement ou acceptation sans fournir le même engagement qu’un crédit documentaire. — [S19], [S32]</li><li><strong>Crédit documentaire</strong> : Engagement bancaire documentaire dans lequel le paiement dépend de la présentation de documents conformes aux termes convenus et aux règles applicables. — [S19], [S21], [S32]</li><li><strong>Coût rendu</strong> : Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus. — [S19], [S25], [S32]</li><li><strong>Risque fournisseur</strong> : Risque lié à la capacité, la qualité, la conformité, les délais ou la solidité d’un fournisseur. — [S32]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c37d6706-3d99-539f-be73-e0d348ba97e8', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 10, '{"html": "<h3>Incoterms</h3><p>Les Incoterms clarifient la répartition de certaines obligations, coûts et risques entre vendeur et acheteur. Ils ne remplacent pas le contrat complet ni les règles douanières.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bf0aee20-6713-50b2-9529-b9b8f680862d', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 11, '{"html": "<h3>Moyens de paiement</h3><p>Virement, remise documentaire, crédit documentaire et garanties offrent des niveaux différents de sécurité, coût et complexité. L''expérience avec le partenaire, le pays, le montant et les documents doivent être pris en compte.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('afc61a97-133a-5c81-b1ef-0db3998f3d69', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 12, '{"html": "<h3>Landed cost</h3><p>Le coût rendu additionne prix d''achat, transport, assurance, frais, droits/taxes applicables, coûts bancaires et logistiques jusqu''au point défini.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('30749ad8-2dea-5e09-96ab-383f870b6b67', '668cc3c4-142e-597c-804d-9eae911463f1', 'callout', 13, '{"variant": "info", "title": "Exemple algérien intégré", "html": "<p>Achat 8 000 EUR + fret + assurance + frais + transport local : la marge ne doit jamais être calculée seulement sur le prix fournisseur.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('104330d5-6b00-5cb4-a641-d1ad70dc7f16', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 14, '{"html": "<h3>Exercice complémentaire intégré</h3><p>Construisez un landed cost fictif et calculez le prix de vente minimum pour une marge cible.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a79fd0d5-95cf-57b6-abf6-6a722da42a72', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 15, '{"html": "<h3>Corrigé-type de l’exercice</h3><p>Corrigé-type : coût rendu = achat converti + fret + assurance + droits/taxes applicables + frais bancaires/logistiques + coûts locaux jusqu’au point défini. Si la marge cible est exprimée en % du prix de vente : prix minimum = coût rendu / (1 - taux de marge). Documenter Incoterm, devise et hypothèses.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b4ca29cc-01cc-519c-86f4-dcb15bb37c18', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 16, '{"html": "<h3>QCM de renforcement — réponse unique</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('912de58f-ea91-5593-ba08-223999bf1be8', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 17, '{"html": "<h3>QCM de renforcement</h3><ol><li><strong>1. Un Incoterm remplace-t-il tout le contrat ?</strong><br>A. Oui<br>B. Non<br>C. Toujours<br>D. Seulement à l''export<br><em>B. Il couvre des aspects définis, pas l''ensemble du contrat.</em></li><li><strong>2. Le landed cost comprend :</strong><br>A. Uniquement prix fournisseur<br>B. Tous les coûts pertinents jusqu''au point défini<br>C. Uniquement la douane<br>D. Le dividende<br><em>B. Il mesure le coût réel rendu.</em></li><li><strong>3. Le crédit documentaire est à comparer notamment selon :</strong><br>A. Sécurité, coût et complexité<br>B. Seulement la couleur du document<br>C. Le PIB<br>D. La météo<br><em>A. Le choix dépend du risque et de la relation.</em></li></ol>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b742dd0b-c77b-5e5d-a244-66ef4f3c99bd', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 18, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une vente FOB et une vente DDP ne répartissent pas les coûts et responsabilités de la même manière. FINCLUDIA doit expliquer la règle choisie sans remplacer le contrat de vente.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dc817a55-8705-59fd-b83a-796ba95edda4', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 19, '{"html": "<h2>Exercice d’application</h2><p>Comparer FCA, CIF et DAP sur transport, assurance et lieu de transfert de risque à l’aide des ressources ICC.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d65f198a-9ebd-570d-9ae6-417d3d0ff189', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 20, '{"html": "<h2>Corrigé-type</h2><p>Le corrigé doit s’appuyer sur la règle ICC 2020 et le lieu nommé précis.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c1008b79-74eb-51d5-8f31-832c9e8c0081', '668cc3c4-142e-597c-804d-9eae911463f1', 'table', 21, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8b4168e0-3e84-54fb-b73a-aea3a96a84e8', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 22, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9a770e78-c7cf-57ee-9a9f-5212399d240c', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 23, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('354fef90-4dc5-5024-b714-134e281496c3', '668cc3c4-142e-597c-804d-9eae911463f1', 'text', 24, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ba677250-f394-508b-9da5-d90867fc2817', '668cc3c4-142e-597c-804d-9eae911463f1', 'table', 25, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Utiliser Incoterm Navigator."], ["Défi", "Choisir une règle pour 3 opérations différentes et justifier."], ["Outil lié", "Incoterm Navigator"], ["Preuve Skills Passport", "Fiche choix Incoterm."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S19, S22, S25, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('a80eca0f-383d-59bc-9915-081945cf6e09', 'dd86ab27-9811-5ef9-bdb4-9c4f5f233445', 'course', '668cc3c4-142e-597c-804d-9eae911463f1', 'QCM — TR-03', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
