INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c86c9c77-4501-5f57-b55e-ca4f29438fde', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Importateurs, exportateurs"], ["Niveau", "N3-N5"], ["Objectif measurable", "Comparer sécurité, coût, complexité et confiance."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6078b1b1-b86e-5cfd-a54e-11e7001e3a80', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Éducation financière bancaire", "Objectif de protection de la clientèle visant notamment la transparence et la capacité du client à prendre des décisions éclairées dans ses relations avec les banques et établissements concernés.", "[S22]"], ["Crédit documentaire", "Engagement bancaire documentaire dans lequel le paiement dépend de la présentation de documents conformes aux termes convenus et aux règles applicables.", "[S19], [S21], [S32]"], ["Remise documentaire", "Mécanisme dans lequel des banques transmettent des documents contre paiement ou acceptation sans fournir le même engagement qu’un crédit documentaire.", "[S19], [S32]"], ["Risque client", "Risque qu’un client paie en retard, ne paie pas ou crée une concentration excessive dans les revenus ou créances.", "[S30], [S32]"], ["Demande", "Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('de963987-da49-5570-9a8d-5f00c0de8b9f', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Comparer sécurité, coût, complexité et confiance. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0434fbea-71a9-5f57-83c2-37baa3d47e9f', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Éducation financière bancaire — Objectif de protection de la clientèle visant notamment la transparence et la capacité du client à prendre des décisions éclairées dans ses relations avec les banques et établissements concernés. [S22]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Crédit documentaire — Engagement bancaire documentaire dans lequel le paiement dépend de la présentation de documents conformes aux termes convenus et aux règles applicables. [S19], [S21], [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Remise documentaire — Mécanisme dans lequel des banques transmettent des documents contre paiement ou acceptation sans fournir le même engagement qu’un crédit documentaire. [S19], [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Risque client — Risque qu’un client paie en retard, ne paie pas ou crée une concentration excessive dans les revenus ou créances. [S30], [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Demande — Quantité d’un bien ou service que les consommateurs sont disposés et capables d’acquérir selon les prix et autres conditions. [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('60eb945f-f470-5408-aab6-1abfc023eb71', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Paiement d’avance. Le paiement d’avance sécurise davantage le vendeur sur le risque de non-paiement mais augmente l’exposition de l’acheteur au risque de livraison ou de non-conformité. Le choix dépend du rapport de force et de la confiance entre parties.</p><p>2. Virement. Dans une opération internationale, virement est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>3. Remise documentaire. La remise documentaire organise la transmission de documents par les banques contre paiement ou acceptation. Les banques traitent les documents mais n’offrent pas le même engagement de paiement qu’un crédit documentaire.</p><p>4. Crédit documentaire. Le crédit documentaire repose sur un engagement bancaire conditionné à la présentation de documents conformes. La banque examine les documents, pas la marchandise elle-même ; la précision documentaire est donc centrale.</p><p>5. Garanties. Dans une opération internationale, garanties est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9884933f-e60d-5c0a-a450-1e461eace966', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Cartographier marchandise, argent et documents.</p><p>Étape 2. Fixer contrat, Incoterm, mode de paiement et calendrier.</p><p>Étape 3. Calculer coût rendu ou prix export avec devise datée.</p><p>Étape 4. Vérifier banque, douane et conformité.</p><p>Étape 5. Construire un registre de risques et une preuve documentaire complète.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ab43ea6f-8ee0-5722-95d3-198a7c778533', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Choisir un mode de paiement international », relevez les données disponibles, identifiez au moins quatre notions parmi Risque financier, Éducation financière bancaire, Crédit documentaire, Remise documentaire, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2508e3a1-405a-57be-aea1-251a24d56a85', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Un nouvel acheteur étranger demande 90 jours de délai. L’exportateur doit comparer risque client, coût bancaire et mécanismes documentaires plutôt que choisir automatiquement le moyen le moins cher.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('468e4cb2-fbd8-50dd-8591-16e5469503f8', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Classer 4 modes de paiement selon sécurité vendeur et complexité.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('51c31a11-d57c-5ec0-a471-f5f55f73e3ad', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Le classement dépend des hypothèses ; l’exercice exige une justification, pas un classement universel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('72aa8ecb-97d7-5c7e-9821-0199ec96078c', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e3b71508-254e-5796-a101-3e91f9e9d428', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('73dc8777-052a-5daf-bb69-0389c5b4a9de', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('15885f96-0420-5ac7-8bab-04a2bb98dc46', '424d9b30-ae11-5ecd-b5e8-3cb03c798a41', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
