INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('32df235d-b7bc-5df2-a43b-e783a7d949a7', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Importateurs, exportateurs, diaspora business"], ["Niveau", "N3-N5"], ["Objectif measurable", "Mesurer l’impact d’une variation de devise sur coût et marge."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f34e1d43-a123-53c8-bafc-c5c011932e04', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Coût rendu", "Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus.", "[S19] [S25] [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3e43e439-eda7-59fd-9aba-fa4c7528698d', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Mesurer l’impact d’une variation de devise sur coût et marge. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('18836e22-441e-5d69-ba8f-58efa36456e2', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Coût rendu — Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus. [S19] [S25] [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cd707a17-acc9-5e17-8465-8e96449e0f56', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Devise contrat. La devise du contrat détermine dans quelle monnaie le prix est exprimé et crée une exposition lorsque les coûts, ventes ou ressources sont dans une autre monnaie. Il faut la distinguer de la devise utilisée pour le reporting interne.</p><p>2. Taux scénario. Un taux de change de scénario est une hypothèse utilisée pour mesurer la sensibilité d’un coût ou d’une marge. Il ne constitue ni une prévision certaine ni un cours exécutable.</p><p>3. Exposition. L’exposition au change correspond au montant dont la valeur économique varie avec le taux de change. Elle dépend du calendrier des paiements et encaissements et peut être compensée partiellement par des flux dans la même devise.</p><p>4. Date paiement. Dans une opération internationale, date paiement est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>5. Marge après choc. La marge mesure ce qui reste après certains coûts, selon la convention choisie. Il faut toujours préciser de quelle marge on parle et quels coûts ont été déduits.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('673b5910-a98d-5a7a-aa82-79a7218e282c', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Cartographier marchandise, argent et documents.</p><p>Étape 2. Fixer contrat, Incoterm, mode de paiement et calendrier.</p><p>Étape 3. Calculer coût rendu ou prix export avec devise datée.</p><p>Étape 4. Vérifier banque, douane et conformité.</p><p>Étape 5. Construire un registre de risques et une preuve documentaire complète.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c04dc34b-b3bd-5198-82d9-78e36be604a0', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Coût rendu = achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques + autres coûts attribuables.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6d365bcb-eea6-56f1-b310-1c3dccdaafc7', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Gérer le risque de change », relevez les données disponibles, identifiez au moins quatre notions parmi Risque de change, Risque financier, Coût rendu, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('af8ec973-d74c-592c-948e-240b20330679', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Importateur doit payer 50 000 EUR. À 150 DZD/EUR, coût = 7,5 M DA ; à 165, coût = 8,25 M DA, soit +750 000 DA avant autres coûts.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b3e6d3e0-39bd-5e0c-b1ee-658f64b1c695', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Exposition 20 000 EUR, taux 150 puis 157,5 : impact en DA ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7adbbe11-3026-5355-a8e4-f820e31f660c', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>150 000 DA de coût supplémentaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3de0243c-6c52-5157-a55e-cf0896aaf217', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('38390c19-690d-595e-b3a4-805c4ee41ec4', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
