INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('58d20ce0-e67d-5239-8c15-5acf46a4558e', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'text', 15, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fc84da43-3504-5a28-aea7-b1a1ec3ce4ea', 'd7c66447-7e2a-598a-a7f6-67bb6d12a42c', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer un stress test FX ±10 %."], ["Défi", "Maintenir une marge positive dans trois scénarios."], ["Outil lié", "FX Exposure"], ["Preuve Skills Passport", "Rapport sensibilité."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S19, S20, S21, S22, S25, S32"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
