INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b3e49d52-58ed-5814-8b2b-60bbe9a78dae', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Importateurs"], ["Niveau", "N3-N5"], ["Objectif measurable", "Intégrer l’ensemble des coûts pertinents avant décision."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aafbb5af-9eac-5d8d-8af9-fa4291e6ab65', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Coût rendu", "Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus.", "[S19] [S25] [S32]"], ["Incoterms®", "Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises.", "[S19]"], ["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Stock", "Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés.", "[S13], [S42]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2340a6d3-d77a-58b6-8569-94291cbe018a', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Intégrer l’ensemble des coûts pertinents avant décision. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('17489492-a1b9-5cf9-b6d8-d787430c8253', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Coût rendu — Coût pédagogique total d’une marchandise jusqu’au point retenu : achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques et autres coûts inclus. [S19] [S25] [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Incoterms® — Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises. [S19]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Stock — Biens détenus pour être vendus, transformés ou consommés dans l’activité ; ils mobilisent des ressources financières tant qu’ils ne sont pas écoulés. [S13], [S42]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('10501363-c32a-533f-af0a-6bd4f21cde1c', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Achat. L’achat correspond ici au prix facturé par le fournisseur pour les biens ou services. En commerce international, le montant doit être conservé dans sa devise d’origine, rapproché de la facture et converti avec un taux daté seulement pour les besoins du calcul en dinars.</p><p>2. Fret. Le fret est le coût du transport principal de la marchandise. Son inclusion dans le prix fournisseur dépend du terme commercial retenu ; il faut donc éviter de le compter deux fois lorsque l’Incoterm prévoit déjà certains coûts de transport.</p><p>3. Assurance. L’assurance transfère certains risques définis au contrat contre une prime. Elle n’élimine pas tous les risques : exclusions, franchise, valeur assurée, procédure de déclaration et pièces justificatives doivent être comprises.</p><p>4. Droits/taxes. Les droits et taxes sont des prélèvements liés à l’opération selon la réglementation applicable. Ils doivent être calculés à partir des règles actives, de l’assiette et du classement pertinents ; FINCLUDIA ne les fige jamais dans un cours permanent.</p><p>5. Banque. La banque intervient comme prestataire de paiement, financeur ou intermédiaire réglementé selon l’opération. Pour un calcul de coût, il faut intégrer les frais bancaires, commissions et, le cas échéant, le coût lié au change sans confondre ces services avec le prix de la marchandise.</p><p>6. Transit. Le transit regroupe les opérations d’intermédiation logistique et douanière nécessaires au passage et au dédouanement des marchandises. Les honoraires, manutentions, formalités et débours doivent être identifiés séparément dans le coût complet.</p><p>7. Transport local. Le transport local couvre le déplacement de la marchandise avant ou après le transport principal sur le territoire concerné. Il doit être rattaché au lot ou à la destination selon une clé explicite lorsque plusieurs produits partagent le même transport.</p><p>8. Stockage/contrôle. Le stockage et les contrôles créent des coûts après l’arrivée de la marchandise et peuvent retarder la mise en vente. Leur durée influence à la fois le coût rendu et le capital immobilisé dans le stock.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('930158e8-e514-5add-8622-9e02ba102ae4', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Cartographier marchandise, argent et documents.</p><p>Étape 2. Fixer contrat, Incoterm, mode de paiement et calendrier.</p><p>Étape 3. Calculer coût rendu ou prix export avec devise datée.</p><p>Étape 4. Vérifier banque, douane et conformité.</p><p>Étape 5. Construire un registre de risques et une preuve documentaire complète.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('22d49b6a-dc51-550e-91d2-aebb2735d880', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Coût rendu = achat converti + fret + assurance + droits/taxes + frais bancaires/logistiques + autres coûts attribuables.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cdd402cb-5ffa-5993-a324-f0be01e62b81', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Calculer le coût rendu international », relevez les données disponibles, identifiez au moins quatre notions parmi Coût rendu, Incoterms®, Risque de change, Stock, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('81cdda9c-9380-516f-8aa7-ab59053f2b89', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Machine à 30 000 EUR, transport/assurance 3 000 EUR, autres coûts locaux 800 000 DA : FINCLUDIA convertit chaque composant selon les hypothèses et affiche le coût rendu total.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('322479eb-c811-5b96-9af1-37c81ff5338a', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Achat converti 4,5 M, fret 450k, droits/frais 900k, local 300k : total ?</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e1437754-56dd-5012-8a9f-32fc81b0677a', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>6,15 M DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9b50df15-5e11-582d-857f-cfd9c9bb4521', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b0aab3ae-5f6d-557c-8097-e90fbf4b0647', '9eabdd97-d9a9-54d7-84a6-d36519452785', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
