INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'dd86ab27-9811-5ef9-bdb4-9c4f5f233445', 'TR-08 — Domiciliation et règles de change', 'Savoir rechercher la règle bancaire applicable à la date de l’opération.', NULL, 8, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('57a9af5f-6371-5876-8064-ae028545e736', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Importateurs, exportateurs"], ["Niveau", "N3-N5"], ["Objectif measurable", "Savoir rechercher la règle bancaire applicable à la date de l’opération."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('95654bb0-25b0-54f4-9feb-668d4b802218', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Domiciliation bancaire du commerce extérieur", "Procédure bancaire encadrant certaines opérations de commerce extérieur conformément à la réglementation des changes et aux instructions de la Banque d’Algérie.", "[S20] [S21]"], ["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Surface financière importateur", "Exigence bancaire applicable aux importations de biens destinés à la revente en l’état ; l’Instruction 05-2026 prévoit notamment l’appréciation préalable de la situation financière par la banque domiciliataire.", "[S29]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('15365b29-2411-51dd-a005-f15315efa225', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Savoir rechercher la règle bancaire applicable à la date de l’opération. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('638d5e98-0bc1-5474-af89-493f34c3bd66', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Domiciliation bancaire du commerce extérieur — Procédure bancaire encadrant certaines opérations de commerce extérieur conformément à la réglementation des changes et aux instructions de la Banque d’Algérie. [S20] [S21]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Surface financière importateur — Exigence bancaire applicable aux importations de biens destinés à la revente en l’état ; l’Instruction 05-2026 prévoit notamment l’appréciation préalable de la situation financière par la banque domiciliataire. [S29]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ebdb6d6b-a7ea-5d4b-8fff-b5b93f24855e', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Règlement 07-01 modifié. Dans une opération internationale, règlement 07-01 modifié est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>2. Règlement 26-02. Dans une opération internationale, règlement 26-02 est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>3. Instructions en vigueur. Dans une opération internationale, instructions en vigueur est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>4. Surface financière revente en l’état. Dans une opération internationale, surface financière revente en l’état est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d207baf3-6313-5582-98ba-1b7599346d9f', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Cartographier marchandise, argent et documents.</p><p>Étape 2. Fixer contrat, Incoterm, mode de paiement et calendrier.</p><p>Étape 3. Calculer coût rendu ou prix export avec devise datée.</p><p>Étape 4. Vérifier banque, douane et conformité.</p><p>Étape 5. Construire un registre de risques et une preuve documentaire complète.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7b5ae64d-90ff-5b91-8313-fb0fd8259358', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Domiciliation et règles de change », relevez les données disponibles, identifiez au moins quatre notions parmi Domiciliation bancaire du commerce extérieur, Risque de change, Surface financière importateur, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6d783f4c-a8ac-53ab-9c47-d339d808f3c8', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : L’Instruction 05-2026 prévoit notamment que la banque domiciliataire apprécie la surface financière des opérateurs important des biens destinés à la revente en l’état, avec plusieurs exigences précises. FINCLUDIA ne doit pas généraliser cette règle à toutes les opérations sans vérifier le champ.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7e8f3083-8ab8-53d1-9b3d-1a6aa9562c17', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Pour une opération fictive, déterminer quelles sources Banque d’Algérie doivent être consultées avant domiciliation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0a399a09-2f1d-56f3-a4fe-b17c3912afc3', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Règlement des changes + instruction spécifique au type d’opération, avec date.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3f3f6de6-b84b-50b3-a455-351fac00f362', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('00c60bde-cdc2-53e2-b197-d8020fcf39b2', '85aabb1f-e5a7-50f4-ae9b-92edf23568da', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
