INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('1587124b-0467-553b-b31a-428c61165d21', 'dd86ab27-9811-5ef9-bdb4-9c4f5f233445', 'TR-10 — Fixer un prix export', 'Construire un prix qui couvre coût, logistique, Incoterm, change et marge.', NULL, 10, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6630c895-c691-5428-b9f3-d8a80a2d7115', '1587124b-0467-553b-b31a-428c61165d21', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Exportateurs"], ["Niveau", "N3-N5"], ["Objectif measurable", "Construire un prix qui couvre coût, logistique, Incoterm, change et marge."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d68732d6-d6a7-5784-8f2f-6d90171df588', '1587124b-0467-553b-b31a-428c61165d21', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Prix de revient", "Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service.", "[S16] [S30]"], ["Incoterms®", "Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises.", "[S19]"], ["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Marge sur coûts variables", "Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité.", "[S16]"], ["Dépense fixe", "Dépense récurrente dont le montant varie peu à court terme, par exemple un loyer ou un abonnement.", "[S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ce9afc95-bf13-5ee6-9b58-39281a10821f', '1587124b-0467-553b-b31a-428c61165d21', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Construire un prix qui couvre coût, logistique, Incoterm, change et marge. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c65cf68b-0f61-5687-b34f-4c55d0a0ab88', '1587124b-0467-553b-b31a-428c61165d21', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Prix de revient — Somme des coûts directs et indirects rattachés à la production ou à la fourniture d’un produit/service. [S16] [S30]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Incoterms® — Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises. [S19]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Marge sur coûts variables — Chiffre d’affaires diminué des charges variables ; elle sert notamment au calcul du seuil de rentabilité. [S16]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Dépense fixe — Dépense récurrente dont le montant varie peu à court terme, par exemple un loyer ou un abonnement. [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0b7b1a0a-cfea-5430-8ff1-bc5585baf638', '1587124b-0467-553b-b31a-428c61165d21', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Coût produit. Pour « Coût produit », il faut expliciter les composantes du coût avant d''interpréter un prix. Les montants directement visibles ne suffisent pas : frais, temps, transport, financement, pertes, fiscalité ou coûts indirects peuvent modifier la décision.</p><p>2. Emballage. Dans une opération internationale, emballage est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>3. Transport. Dans une opération internationale, transport est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>4. Assurance. L’assurance transfère certains risques définis au contrat contre une prime. Elle n’élimine pas tous les risques : exclusions, franchise, valeur assurée, procédure de déclaration et pièces justificatives doivent être comprises.</p><p>5. Commission. Dans une opération internationale, commission est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>6. Marge. La marge est l’écart entre un prix de vente ou un chiffre d’affaires et une catégorie de coûts déterminée. Avant de comparer deux marges, il faut utiliser la même définition et le même périmètre de coûts.</p><p>7. Devise. Dans une opération internationale, devise est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b6a389b6-ca30-5d44-a49d-dbd91e492f4d', '1587124b-0467-553b-b31a-428c61165d21', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Cartographier marchandise, argent et documents.</p><p>Étape 2. Fixer contrat, Incoterm, mode de paiement et calendrier.</p><p>Étape 3. Calculer coût rendu ou prix export avec devise datée.</p><p>Étape 4. Vérifier banque, douane et conformité.</p><p>Étape 5. Construire un registre de risques et une preuve documentaire complète.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9d484e90-c590-560c-965f-5a0c01b60fe2', '1587124b-0467-553b-b31a-428c61165d21', 'text', 7, '{"html": "<h3>Formules et repères de calcul</h3><p>Marge sur coûts variables = chiffre d’affaires − charges variables.</p><p>Prix de revient = coûts directs + quote-part des coûts indirects affectés selon une méthode explicite.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('de44b41e-0d6f-5f6f-a4d6-8e0ea59ffe9b', '1587124b-0467-553b-b31a-428c61165d21', 'text', 8, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Fixer un prix export », relevez les données disponibles, identifiez au moins quatre notions parmi Prix de revient, Incoterms®, Risque de change, Marge sur coûts variables, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2a2c4c13-ebe1-5b11-86f9-385b96ec1d2a', '1587124b-0467-553b-b31a-428c61165d21', 'text', 9, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Exportateur de dattes de Biskra calcule son prix en intégrant produit, emballage, transport intérieur, formalités et coûts associés à l’Incoterm choisi, puis teste la devise de facturation.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ca7b13d0-b478-5967-96b0-6072a4b1c311', '1587124b-0467-553b-b31a-428c61165d21', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Coût total export par unité 1 200 DA, marge cible 25 % du prix : calculer prix = coût/(1-0,25).</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a3f2c25d-5e0d-58af-8cbf-c44760d3f5cb', '1587124b-0467-553b-b31a-428c61165d21', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>1 600 DA.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b4450445-378d-5a80-adb0-ea7f075e872a', '1587124b-0467-553b-b31a-428c61165d21', 'table', 12, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1dfb44fd-4302-54e4-8ddb-8c8210416c32', '1587124b-0467-553b-b31a-428c61165d21', 'text', 13, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4a2ba57e-227e-5909-86de-c32ced81c8c4', '1587124b-0467-553b-b31a-428c61165d21', 'text', 14, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
