INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d1c98351-6b61-5e8d-aa1f-2ccff8416117', '1587124b-0467-553b-b31a-428c61165d21', 'table', 16, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer une offre export."], ["Défi", "Tester 3 Incoterms et deux taux de change."], ["Outil lié", "Export Pricing"], ["Preuve Skills Passport", "Offre export."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S16, S19, S20, S21, S30"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
