INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'dd86ab27-9811-5ef9-bdb4-9c4f5f233445', 'TR-11 — Piloter une expédition', 'Suivre les jalons, documents et responsabilités.', NULL, 11, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0dc89e2a-9d4a-5a51-9f95-77ffb71705af', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Importateurs, exportateurs"], ["Niveau", "N3-N5"], ["Objectif measurable", "Suivre les jalons, documents et responsabilités."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4feb0a6f-172b-56c4-ae2f-688d7f36c0fd', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Incoterms®", "Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises.", "[S19]"], ["Contrôle de conformité à l’importation", "Contrôle documentaire, visuel et, le cas échéant, analytique visant à vérifier la conformité des produits importés avant admission.", "[S25] [S31]"], ["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bcc80585-6e53-5a27-9497-5e88e613ca5a', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Suivre les jalons, documents et responsabilités. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f77fc166-5516-539b-9a75-0b29a9a181ce', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Incoterms® — Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises. [S19]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Contrôle de conformité à l’importation — Contrôle documentaire, visuel et, le cas échéant, analytique visant à vérifier la conformité des produits importés avant admission. [S25] [S31]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1885e316-8899-5177-b2e2-4a68f3b7b1dc', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Commande. Dans une opération internationale, commande est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>2. Production/préparation. Dans une opération internationale, production/préparation est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>3. Documents. Les documents rendent la situation financière vérifiable : factures, relevés, états financiers, contrats, justificatifs fiscaux ou commerciaux. Un dossier incomplet augmente l’incertitude du financeur et peut retarder la décision.</p><p>4. Départ. Dans une opération internationale, départ est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>5. Transport. Dans une opération internationale, transport est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>6. Douane. Dans une opération internationale, douane est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>7. Livraison. Dans une opération internationale, livraison est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>8. Paiement. Dans une opération internationale, paiement est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('41b2aae0-bc2d-5407-b5b7-f44b2e403521', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Cartographier marchandise, argent et documents.</p><p>Étape 2. Fixer contrat, Incoterm, mode de paiement et calendrier.</p><p>Étape 3. Calculer coût rendu ou prix export avec devise datée.</p><p>Étape 4. Vérifier banque, douane et conformité.</p><p>Étape 5. Construire un registre de risques et une preuve documentaire complète.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('5c79c611-6565-57ce-8cdd-aef0acc9e8a1', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Piloter une expédition », relevez les données disponibles, identifiez au moins quatre notions parmi Incoterms®, Contrôle de conformité à l’importation, Risque financier, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('10597193-dee1-5da4-bc02-e95fd071540d', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une PME exporte une commande : FINCLUDIA affiche jalons, documents manquants et responsabilité de chaque acteur, sans se substituer au transitaire ou à la banque.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('409ec159-9343-5bcc-88fb-ec304d60b675', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Construire une timeline de 10 jalons.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f7f7718b-44c5-5ae6-8c4d-11d2c21b61d8', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>La timeline doit relier chaque jalon à un document ou une validation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('17371e3c-a7c7-5f6a-a54f-57ff396bba83', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6cc4ee99-3073-5324-953a-187551e32adc', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('51a8e044-ca0b-55ce-ba38-db09eed63c9f', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4219a2cf-8c0d-5960-b884-3b849a511510', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d64f03da-091b-583e-9fac-ebabf9f96ad4', '64bbaac6-a66b-51ec-bb4f-e3f13fe04001', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer Shipment Timeline."], ["Défi", "Terminer un cas sans document manquant."], ["Outil lié", "Timeline"], ["Preuve Skills Passport", "Opération complète."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S19, S22, S25, S31"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
