INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('e42513ae-4215-54ce-b921-1456f49ae321', 'dd86ab27-9811-5ef9-bdb4-9c4f5f233445', 'TR-12 — Gérer les risques internationaux', 'Construire un registre de risques par opération.', NULL, 12, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d6d15f39-fed3-541e-9025-5c5dd17d6bde', 'e42513ae-4215-54ce-b921-1456f49ae321', 'table', 1, '{"headers": ["Cadre pédagogique", "Contenu"], "rows": [["Publics", "Importateurs, exportateurs"], ["Niveau", "N3-N5"], ["Objectif measurable", "Construire un registre de risques par opération."], ["Prérequis", "Aucun au niveau d’entrée ; sinon prérequis du parcours et compétences antérieures validées."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('08ef31e0-91d6-5aaf-ba93-01bc186b7bf3', 'e42513ae-4215-54ce-b921-1456f49ae321', 'table', 2, '{"headers": ["Notion", "Définition pédagogique de référence", "Réf."], "rows": [["Risque financier", "Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte.", "[S02] [S22]"], ["Risque de change", "Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge.", "[S20] [S21]"], ["Incoterms®", "Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises.", "[S19]"], ["Contrôle de conformité à l’importation", "Contrôle documentaire, visuel et, le cas échéant, analytique visant à vérifier la conformité des produits importés avant admission.", "[S25] [S31]"], ["Conformité", "Respect des règles, procédures, autorisations et exigences applicables à une activité, un produit, une opération ou un acteur.", "[S25], [S31], [S32]"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('370129fd-e8bd-580c-81ba-c5b0624df110', 'e42513ae-4215-54ce-b921-1456f49ae321', 'text', 3, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Construire un registre de risques par opération. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('49c39d1e-621f-52a0-8cd0-3af1d3a715fc', 'e42513ae-4215-54ce-b921-1456f49ae321', 'text', 4, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Risque financier — Possibilité qu’un résultat financier diffère défavorablement de ce qui était attendu ; il doit être étudié avec rendement, horizon, liquidité et capacité à supporter une perte. [S02] [S22]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Risque de change — Risque que la variation d’un taux de change modifie la valeur en dinars d’un encaissement, d’un paiement, d’un actif ou d’une marge. [S20] [S21]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Incoterms® — Onze règles ICC servant à répartir entre vendeur et acheteur certaines obligations, certains coûts et le transfert des risques liés à la livraison des marchandises. [S19]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Contrôle de conformité à l’importation — Contrôle documentaire, visuel et, le cas échéant, analytique visant à vérifier la conformité des produits importés avant admission. [S25] [S31]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p><p>Conformité — Respect des règles, procédures, autorisations et exigences applicables à une activité, un produit, une opération ou un acteur. [S25], [S31], [S32]</p><p>Application dans ce module. La notion doit être replacée dans les trois flux — marchandise, argent, documents — et dans la chronologie de l’opération ; les règles de change, douane et conformité sont vérifiées à la date du dossier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9f1f5062-e679-55c3-b7a8-014339fe38dd', 'e42513ae-4215-54ce-b921-1456f49ae321', 'text', 5, '{"html": "<h3>Développement des notions</h3><p>1. Pays. Dans une opération internationale, pays est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>2. Contrepartie. Dans une opération internationale, contrepartie est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>3. Paiement. Dans une opération internationale, paiement est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>4. Transport. Dans une opération internationale, transport est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p><p>5. Change. Le taux de change exprime la valeur d’une monnaie dans une autre. Une variation peut modifier le coût en dinars d’une importation, la valeur d’un actif étranger ou le montant reçu lors d’un transfert.</p><p>6. Document. Le crédit documentaire est fondé sur les documents et leur conformité aux termes convenus. Une opération commerciale correcte peut pourtant rencontrer un problème de paiement si les documents présentent des écarts.</p><p>7. Conformité. Dans une opération internationale, conformité est replacé dans la chronologie contrat → documents → transport → banque → douane → paiement. L''utilisateur doit identifier qui porte le coût, qui porte le risque et quelle pièce prouve l''étape.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2f700bee-f2d4-50fb-82a4-6f0702e6fa93', 'e42513ae-4215-54ce-b921-1456f49ae321', 'text', 6, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Cartographier marchandise, argent et documents.</p><p>Étape 2. Fixer contrat, Incoterm, mode de paiement et calendrier.</p><p>Étape 3. Calculer coût rendu ou prix export avec devise datée.</p><p>Étape 4. Vérifier banque, douane et conformité.</p><p>Étape 5. Construire un registre de risques et une preuve documentaire complète.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d5360dd4-b991-5433-b61f-7e43cba4d62b', 'e42513ae-4215-54ce-b921-1456f49ae321', 'text', 7, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Gérer les risques internationaux », relevez les données disponibles, identifiez au moins quatre notions parmi Risque financier, Risque de change, Incoterms®, Contrôle de conformité à l’importation, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7e617a56-beae-591a-8dfa-36495adf3486', 'e42513ae-4215-54ce-b921-1456f49ae321', 'text', 8, '{"html": "<h2>Cas pratique renforcé</h2><p>Cas algérien : Une vente à un nouveau client combine risque de non-paiement, change, transport et documentation. FINCLUDIA permet de les distinguer et de documenter les mesures de mitigation.</p><p>Identifier les notions du module présentes dans le cas.</p><p>Présenter le calcul, la classification ou la méthode nécessaire en montrant les étapes.</p><p>Interpréter le résultat : que signifie-t-il et que ne permet-il pas de conclure ?</p><p>Choisir une action et justifier le choix par les données du cas.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1dc46385-c604-59e6-91c4-1821928dc0a2', 'e42513ae-4215-54ce-b921-1456f49ae321', 'text', 9, '{"html": "<h2>Exercice d’application</h2><p>Évaluer 8 risques sur probabilité/impact.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('466179df-e41d-5981-a5c4-8b38274a5ae3', 'e42513ae-4215-54ce-b921-1456f49ae321', 'text', 10, '{"html": "<h2>Corrigé-type</h2><p>Le corrigé vérifie cohérence des mesures, pas une note universelle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6683b2c3-7f56-559e-bc89-552a18beb67b', 'e42513ae-4215-54ce-b921-1456f49ae321', 'table', 11, '{"headers": ["Étape du corrigé", "Attendu"], "rows": [["1. Diagnostic", "Identifier correctement données, période, acteurs et concepts."], ["2. Méthode", "Appliquer la formule, la classification ou la checklist du module sans sauter d’étape."], ["3. Résultat", "Présenter le résultat avec unité, période et convention."], ["4. Interprétation", "Expliquer ce que le résultat signifie et ce qu’il ne prouve pas."], ["5. Décision/contrôle", "Choisir une action cohérente et vérifier source, risque ou hypothèse si nécessaire."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f9e4040d-2162-57c8-8af7-9b3de08149ea', 'e42513ae-4215-54ce-b921-1456f49ae321', 'text', 12, '{"html": "<h2>À ne pas confondre</h2><p>Ne pas transformer un indicateur ou une simulation en décision automatique.</p><p>Vérifier période, périmètre, hypothèses et source.</p><p>Séparer donnée réelle, hypothèse pédagogique et règle réglementaire.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('25e34358-f4c4-58b3-a01b-60bd665ecdfc', 'e42513ae-4215-54ce-b921-1456f49ae321', 'text', 13, '{"html": "<h2>QCM à réponse unique — évaluation automatique</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1e786391-bc79-5aa5-ac7b-e812a25cb34b', 'e42513ae-4215-54ce-b921-1456f49ae321', 'text', 14, '{"html": "<h2>Application dans FINCLUDIA et validation</h2>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b7c460ba-f50c-57ab-9805-31fe91c6ee77', 'e42513ae-4215-54ce-b921-1456f49ae321', 'table', 15, '{"headers": ["Élément", "Règle"], "rows": [["Mission", "Créer Risk Register."], ["Défi", "Aucun risque critique sans action."], ["Outil lié", "Trade Risk"], ["Preuve Skills Passport", "Registre risques."], ["Règle de validation", "QCM ≥ 80 % ; exercice ≥ 70 % ; mission réalisée ; score module ≥ 80 % ; toute question critique doit être correcte."], ["Sources", "S02, S19, S20, S21, S22, S25, S31"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
