INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('99859b96-247e-52a0-890c-38d07aa456b0', 'dd86ab27-9811-5ef9-bdb4-9c4f5f233445', 'Cas intégrateur corrigé — Commerce international', NULL, NULL, 13, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e298bfae-956b-527b-af32-15d882319721', '99859b96-247e-52a0-890c-38d07aa456b0', 'text', 1, '{"html": "<h3>Scénario\\nUne PME algérienne achète fictivement 50 000 EUR de marchandise. Fret : 4 000 EUR, assurance : 500 EUR. Taux pédagogique à la date du devis : 150 DZD/EUR. Frais locaux estimés : 900 000 DA. Un scénario teste +10 % sur le taux de change avant paiement.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4202b1b3-afe4-53cb-ba53-51d61b2061c9', '99859b96-247e-52a0-890c-38d07aa456b0', 'text', 2, '{"html": "<h2>Travail demandé</h2><p>1. Calculer la valeur achat+fret+assurance en EUR.</p><p>2. Calculer l’équivalent DZD au taux initial, puis le coût avec frais locaux.</p><p>3. Recalculer sous +10 % de taux de change.</p><p>4. Expliquer ce que l’Incoterm règle et ne règle pas.</p><p>5. Identifier les contrôles banque/douane/conformité avant exécution.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('0f841701-665d-5d39-a1cf-e659c60c3d23', '99859b96-247e-52a0-890c-38d07aa456b0', 'text', 3, '{"html": "<h2>Corrigé-type</h2><p>Base EUR = 54 500 EUR. Au taux 150 : 8 175 000 DA ; avec frais locaux = 9 075 000 DA. Taux +10 % = 165 DZD/EUR : base = 8 992 500 DA ; avec frais locaux = 9 892 500 DA, soit +817 500 DA. L’Incoterm répartit obligations/coûts/risques de livraison mais ne remplace ni le contrat, ni le moyen de paiement, ni les règles de change/douane.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8b282cde-970b-5611-a6fd-5e05fd920aa7', '99859b96-247e-52a0-890c-38d07aa456b0', 'table', 4, '{"headers": ["Critère", "Poids"], "rows": [["Exactitude technique / calculs", "35 %"], ["Interprétation et décision", "25 %"], ["Gestion du risque / conformité", "20 %"], ["Traçabilité et sources", "10 %"], ["Clarté de l’explication", "10 %"]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1f45cac4-1878-5f37-bed7-bf19143e86ce', '99859b96-247e-52a0-890c-38d07aa456b0', 'text', 5, '{"html": "<h3>Validation du cas intégrateur\\nSeuil : 75 %. Une erreur critique de sécurité, conformité, fraude, règle réglementaire active ou confusion réel/fictif doit être corrigée avant validation, même si le score global atteint 75 %.</h3>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `formations` (`id`, `slug`, `title`, `description`, `status`, `requiredAccessLevel`, `categoryId`, `certificationEnabled`, `certificationTitle`, `certificationDescription`, `subtitle`, `level`, `objectives`, `prerequisites`, `publishedAt`, `createdAt`, `updatedAt`, `theme`, `targetAccountTypes`, `educationProfiles`) VALUES ('fae4fb4b-1c6d-5a3f-aeb2-395c9a4befa5', 'academy-rmunration-fiscalit-zakat-finance-responsable', 'FINCLUDIA Academy — Rémunération, fiscalité, Zakat & finance responsable', 'Parcours transversal destiné à compléter les finances personnelles et professionnelles par quatre sujets insuffisamment autonomes dans la V10 : fiche de paie, méthode fiscale, Zakat pédagogique et investissement vert.', 'published', 'standard', '4c2f266b-8881-53c9-aff5-f6fef0653ae3', 1, 'Certificat pédagogique — Rémunération, fiscalité, Zakat & finance responsable', 'Certificat pédagogique FINCLUDIA : il atteste un parcours de formation suivi et réussi, pas une habilitation professionnelle ni réglementaire.', 'FINCLUDIA Academy', 'beginner', '[]', '[]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 'FINCLUDIA Academy', '[]', '[]');
INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('561ce612-cb22-5990-ab7a-0129df51b407', 'fae4fb4b-1c6d-5a3f-aeb2-395c9a4befa5', 'SAL-01 — Lire une fiche de paie et relier brut/net au budget', NULL, NULL, 1, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c6df23d4-04a2-563f-b49c-1b112cde920b', '561ce612-cb22-5990-ab7a-0129df51b407', 'text', 1, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Maîtriser les notions centrales de « Lire une fiche de paie et relier brut/net au budget » et savoir les appliquer à une situation réelle ou simulée. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fb51b7d1-7ac1-5b0e-b041-d40ab350bdc1', '561ce612-cb22-5990-ab7a-0129df51b407', 'text', 2, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Fiche de paie — Document décrivant la rémunération d’une période et ses composantes : base, primes ou indemnités, retenues sociales et fiscales et net à payer, selon la situation applicable. [S47]</p><p>Application dans ce module. L’utilisateur apprend à distinguer rémunération brute, retenues et revenu réellement disponible afin de construire un budget réaliste et d’identifier les éléments exceptionnels.</p><p>Salaire brut — Rémunération avant les retenues sociales et fiscales applicables ; il ne correspond pas nécessairement au montant effectivement disponible pour le budget. [S47]</p><p>Application dans ce module. L’utilisateur apprend à distinguer rémunération brute, retenues et revenu réellement disponible afin de construire un budget réaliste et d’identifier les éléments exceptionnels.</p><p>Salaire net — Montant de rémunération restant après les retenues applicables et servant de référence pratique pour le revenu réellement disponible, sous réserve des autres flux du ménage. [S47]</p><p>Application dans ce module. L’utilisateur apprend à distinguer rémunération brute, retenues et revenu réellement disponible afin de construire un budget réaliste et d’identifier les éléments exceptionnels.</p><p>IRG sur salaires — Impôt sur le revenu global appliqué aux traitements et salaires selon un barème progressif, des abattements et règles de retenue à la source. [S08]</p><p>Application dans ce module. L’utilisateur apprend à distinguer rémunération brute, retenues et revenu réellement disponible afin de construire un budget réaliste et d’identifier les éléments exceptionnels.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b437f6b1-bba0-5a58-af9c-22c8353a1dda', '561ce612-cb22-5990-ab7a-0129df51b407', 'text', 3, '{"html": "<h3>Développement des notions</h3><p>1. Fiche de paie. La fiche de paie rassemble les composantes de la rémunération d’une période. Pour la lire, on repère d’abord la période et le salaire de base, puis les primes et indemnités, les retenues, et enfin le net à payer.</p><p>2. Salaire brut. Le salaire brut est la rémunération avant les retenues sociales et fiscales applicables. Il sert à comprendre la construction de la paie mais ne correspond pas au montant réellement disponible pour le budget du ménage.</p><p>3. Salaire net. Le salaire net est le montant restant après les retenues applicables. Pour un budget mensuel, FINCLUDIA privilégie le revenu net récurrent effectivement disponible et traite séparément les primes exceptionnelles.</p><p>4. IRG sur salaires. L’IRG sur salaires est un prélèvement fiscal appliqué selon les règles en vigueur. L’utilisateur n’a pas à mémoriser un barème périssable : il doit savoir identifier la ligne sur la paie, la période et la source officielle à vérifier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('e457646d-4931-5ef4-814c-20a82ca12969', '561ce612-cb22-5990-ab7a-0129df51b407', 'text', 4, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier période, base, primes et retenues.</p><p>Étape 2. Distinguer brut, net et éléments exceptionnels.</p><p>Étape 3. Repérer le revenu réellement récurrent.</p><p>Étape 4. Relier le net disponible au budget.</p><p>Étape 5. Conserver les justificatifs et vérifier toute anomalie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('6c3e431f-9b0d-50d3-900d-41a07a0c8e08', '561ce612-cb22-5990-ab7a-0129df51b407', 'text', 5, '{"html": "<h3>Formules et repères de calcul</h3><p>Solde budgétaire = revenus de la période − dépenses de la période.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('f676c3e8-ee6e-5c15-b6eb-5de0469741a3', '561ce612-cb22-5990-ab7a-0129df51b407', 'text', 6, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Lire une fiche de paie et relier brut/net au budget », relevez les données disponibles, identifiez au moins quatre notions parmi Fiche de paie, Salaire brut, Salaire net, IRG sur salaires, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p><ul><li><strong>Publics</strong> : Étudiants en fin de cycle, salariés, familles</li><li><strong>Niveau</strong> : N1-N2</li><li><strong>Objectif measurable</strong> : distinguer brut et net; identifier retenues et primes; relier fiche de paie au budget</li><li><strong>Prérequis</strong> : Fondamentaux du parcours concerné ; source active lorsque la règle est évolutive.</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Fiche de paie</strong> : Document décrivant la rémunération d’une période et ses composantes : base, primes ou indemnités, retenues sociales et fiscales et net à payer, selon la situation applicable. — [S47]</li><li><strong>Salaire brut</strong> : Rémunération avant les retenues sociales et fiscales applicables ; il ne correspond pas nécessairement au montant effectivement disponible pour le budget. — [S47]</li><li><strong>Salaire net</strong> : Montant de rémunération restant après les retenues applicables et servant de référence pratique pour le revenu réellement disponible, sous réserve des autres flux du ménage. — [S47]</li><li><strong>IRG sur salaires</strong> : Impôt sur le revenu global appliqué aux traitements et salaires selon un barème progressif, des abattements et règles de retenue à la source. — [S08]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('884c7e35-be1c-5864-a13f-f8bd4216cfa0', '561ce612-cb22-5990-ab7a-0129df51b407', 'text', 7, '{"html": "<h2>De quoi parle une fiche de paie ?</h2><p>La fiche de paie décrit la rémunération et les retenues selon la situation du salarié. FINCLUDIA doit apprendre à repérer : salaire de base, primes/indemnités, retenues sociales et fiscales, net à payer, période concernée et éventuels éléments exceptionnels.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('09a8a2c2-2c1f-5b67-8791-a5ca31607256', '561ce612-cb22-5990-ab7a-0129df51b407', 'text', 8, '{"html": "<h2>Pourquoi l''intégrer au budget ?</h2><p>Le budget doit se construire à partir du revenu réellement disponible, tout en conservant la compréhension du brut et des prélèvements pour éviter de confondre coût employeur, brut et net.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1cd088aa-ce1b-5316-aad0-fd802bf22af1', '561ce612-cb22-5990-ab7a-0129df51b407', 'callout', 9, '{"variant": "info", "title": "Cas algérien", "html": "<p>Sur une fiche fictive, le salaire brut peut être supérieur au montant réellement reçu. FINCLUDIA demandera à l''utilisateur de repérer le net à payer et d''identifier les lignes variables.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('20c05ec1-4348-55b8-a0d5-825cfafb1acf', '561ce612-cb22-5990-ab7a-0129df51b407', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Prenez une fiche de paie anonymisée ou fictive. Surlignez : base, primes, retenues et net. Expliquez chaque ligne en une phrase.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('938059eb-061d-5122-a576-728d9e97cb03', '561ce612-cb22-5990-ab7a-0129df51b407', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Corrigé-type : repérer la période, le salaire de base, les éléments variables, les retenues sociales/fiscales et le net à payer. Le budget courant s’appuie sur le revenu net récurrent réellement disponible ; une prime exceptionnelle ne doit pas être assimilée à un revenu mensuel garanti.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1ad38f2f-bfb1-5ea0-9eb4-a1f97eff0b43', '561ce612-cb22-5990-ab7a-0129df51b407', 'text', 12, '{"html": "<p>Validation  : QCM ≥ 80 %, exercice ≥ 70 %, mission/trace terminée et aucune erreur critique. Les données fiscales, religieuses ou réglementaires actives sont datées et sourcées.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
