INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'fae4fb4b-1c6d-5a3f-aeb2-395c9a4befa5', 'TAX-01 — Lire une obligation fiscale et sociale sans mémoriser des taux périssables', NULL, NULL, 2, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('470b0d02-5904-52ef-9de1-bda5fb117baf', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'text', 1, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Maîtriser les notions centrales de « Lire une obligation fiscale et sociale sans mémoriser des taux périssables » et savoir les appliquer à une situation réelle ou simulée. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('aa0c6744-1450-50c2-a1ee-aac19ecd800e', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'text', 2, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Impôt — Prélèvement obligatoire destiné au financement des charges publiques selon les règles applicables au contribuable, à l’assiette et à la période concernée. [S47]</p><p>Application dans ce module. La compétence n’est pas de mémoriser un taux : elle consiste à identifier le contribuable, l’assiette, la période, l’échéance, la source officielle et la preuve de déclaration ou de paiement.</p><p>Taxe — Prélèvement obligatoire établi selon une assiette ou un mécanisme défini par les textes en vigueur ; son traitement dépend du régime et de l’opération. [S47]</p><p>Application dans ce module. La compétence n’est pas de mémoriser un taux : elle consiste à identifier le contribuable, l’assiette, la période, l’échéance, la source officielle et la preuve de déclaration ou de paiement.</p><p>Cotisation sociale — Versement obligatoire ou volontaire selon le statut, destiné au financement de la protection sociale et/ou à l’ouverture de droits sociaux. [S47]</p><p>Application dans ce module. La compétence n’est pas de mémoriser un taux : elle consiste à identifier le contribuable, l’assiette, la période, l’échéance, la source officielle et la preuve de déclaration ou de paiement.</p><p>Déclaration fiscale — Obligation de communiquer à l’administration des informations selon un calendrier et un format déterminés ; elle peut conduire ou non à un paiement. [S47]</p><p>Application dans ce module. La compétence n’est pas de mémoriser un taux : elle consiste à identifier le contribuable, l’assiette, la période, l’échéance, la source officielle et la preuve de déclaration ou de paiement.</p><p>IFU — Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur. [S04]</p><p>Application dans ce module. La compétence n’est pas de mémoriser un taux : elle consiste à identifier le contribuable, l’assiette, la période, l’échéance, la source officielle et la preuve de déclaration ou de paiement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('d3ca0766-a9ee-580e-be66-85c6b8d44bae', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'text', 3, '{"html": "<h3>Développement des notions</h3><p>1. Impôt. Pour impôt, FINCLUDIA enseigne une méthode de recherche plutôt qu''un chiffre figé : statut du contribuable, nature de l''opération, assiette, période, échéance, source officielle et preuve.</p><p>2. Taxe. Pour taxe, FINCLUDIA enseigne une méthode de recherche plutôt qu''un chiffre figé : statut du contribuable, nature de l''opération, assiette, période, échéance, source officielle et preuve.</p><p>3. Cotisation sociale. Pour cotisation sociale, FINCLUDIA enseigne une méthode de recherche plutôt qu''un chiffre figé : statut du contribuable, nature de l''opération, assiette, période, échéance, source officielle et preuve.</p><p>4. Déclaration fiscale. Pour déclaration fiscale, FINCLUDIA enseigne une méthode de recherche plutôt qu''un chiffre figé : statut du contribuable, nature de l''opération, assiette, période, échéance, source officielle et preuve.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b71d7662-8736-5d0f-98da-c1d7239e4296', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'text', 4, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier statut et nature du revenu ou de l’opération.</p><p>Étape 2. Chercher la règle officielle applicable à la date concernée.</p><p>Étape 3. Distinguer assiette, taux, déclaration et paiement.</p><p>Étape 4. Conserver justificatifs, échéance et preuve.</p><p>Étape 5. Revalider la règle lorsqu’une nouvelle période ou un changement de statut intervient.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8302b9b5-538d-53a1-99fd-b2d82542d002', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'text', 5, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Lire une obligation fiscale et sociale sans mémoriser des taux périssables », relevez les données disponibles, identifiez au moins quatre notions parmi Impôt, Taxe, Cotisation sociale, Déclaration fiscale, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p><ul><li><strong>Publics</strong> : Salariés, indépendants, auto-entrepreneurs, dirigeants</li><li><strong>Niveau</strong> : N2-N4</li><li><strong>Objectif mesurable</strong> : distinguer impôt, taxe, cotisation et déclaration; comprendre qu''une règle dépend d''un profil; savoir vérifier une source officielle</li><li><strong>Prérequis</strong> : Fondamentaux du parcours concerné ; source active lorsque la règle est évolutive.</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Impôt</strong> : Prélèvement obligatoire destiné au financement des charges publiques selon les règles applicables au contribuable, à l’assiette et à la période concernée. — [S47]</li><li><strong>Taxe</strong> : Prélèvement obligatoire établi selon une assiette ou un mécanisme défini par les textes en vigueur ; son traitement dépend du régime et de l’opération. — [S47]</li><li><strong>Cotisation sociale</strong> : Versement obligatoire ou volontaire selon le statut, destiné au financement de la protection sociale et/ou à l’ouverture de droits sociaux. — [S47]</li><li><strong>Déclaration fiscale</strong> : Obligation de communiquer à l’administration des informations selon un calendrier et un format déterminés ; elle peut conduire ou non à un paiement. — [S47]</li><li><strong>IFU</strong> : Impôt forfaitaire unique algérien regroupant notamment des impositions simplifiées pour les contribuables relevant de ce régime, selon les conditions et seuils en vigueur. — [S04]</li><li><strong>Point de vigilance</strong></li><li><strong>Point pédagogique — Les règles fiscales changent. Le contenu pédagogique enseigne la méthode et renvoie vers les sources officielles à jour.</strong></li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('c6ed03e2-a61f-53bd-91af-1366ece6e221', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'text', 6, '{"html": "<h2>Quatre notions</h2><p>Un impôt finance les charges publiques selon les règles applicables. Une taxe peut être liée à une assiette ou un mécanisme spécifique. Une cotisation sociale finance ou ouvre des droits sociaux. Une déclaration est une obligation d''information qui peut ou non s''accompagner d''un paiement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('7bc110b4-e9a6-5aec-a261-0da3874faf9c', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'text', 7, '{"html": "<h2>Exemple IFU actuel</h2><p>La DGI indique en septembre 2026 que l''IFU regroupe notamment la TLS, la TVA et l''IRG. Le régime concerne plusieurs catégories sous conditions ; le seuil général cité pour plusieurs activités est de 8 000 000 DA de chiffre d''affaires annuel, tandis que le statut auto-entrepreneur relève d''un seuil spécifique de 5 000 000 DA. Les taux et règles dépendent de l''activité et doivent être vérifiés à la date d''utilisation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4835ac2d-6c0a-5031-ade7-b15f7cd1bbae', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'text', 8, '{"html": "<h2>Compétence fondamentale</h2><p>Un utilisateur FINCLUDIA ne doit pas mémoriser toutes les règles. Il doit savoir identifier son statut, trouver la règle applicable, lire la date d''effet et conserver les pièces.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('dfe5949a-d0b6-594b-a352-5158ab08c70e', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'callout', 9, '{"variant": "info", "title": "Cas algérien", "html": "<p>Un auto-entrepreneur ne doit pas appliquer automatiquement à son activité le régime d''une SARL. Le bon raisonnement commence par : statut, activité, chiffre d''affaires, période et source officielle.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4cdade85-aebc-591b-801e-fdb327366321', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Choisissez un statut fictif. Écrivez les cinq informations nécessaires avant de calculer une obligation fiscale.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4ba5472b-4fa7-5ba6-8b79-1497438ff204', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Corrigé-type : avant tout calcul, identifier au minimum : 1) statut juridique/fiscal ; 2) activité ; 3) revenu ou chiffre d’affaires et période ; 4) régime ou seuil applicable à la date considérée ; 5) source officielle et date de vérification. Ajouter la situation sociale/TVA lorsque pertinente.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4a15b00c-6306-5471-bc8f-4cdabcedb309', '57831b23-289b-5b5f-bf79-46d7bb8d2a84', 'text', 12, '{"html": "<p>Validation  : QCM ≥ 80 %, exercice ≥ 70 %, mission/trace terminée et aucune erreur critique. Les données fiscales, religieuses ou réglementaires actives sont datées et sourcées.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
