INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('23d39037-6954-5f01-a25f-cf22baa57a66', 'fae4fb4b-1c6d-5a3f-aeb2-395c9a4befa5', 'ETH-01 — Zakat : nisab, hawl, estimation et traçabilité méthodologique', NULL, NULL, 3, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('2ce77781-b738-5bc3-bbef-3c0f659bb273', '23d39037-6954-5f01-a25f-cf22baa57a66', 'text', 1, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Maîtriser les notions centrales de « Zakat : nisab, hawl, estimation et traçabilité méthodologique » et savoir les appliquer à une situation réelle ou simulée. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('bfc1315a-5756-56a6-b046-33a1202d1bdc', '23d39037-6954-5f01-a25f-cf22baa57a66', 'text', 2, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Zakat — Prélèvement religieux obligatoire pour les personnes et avoirs remplissant les conditions applicables. FINCLUDIA en présente une estimation pédagogique distincte de la fiscalité et renvoie les cas complexes vers une autorité qualifiée. [S47]</p><p>Application dans ce module. FINCLUDIA présente une méthode pédagogique de compréhension et d’estimation, distincte de la fiscalité ; les paramètres religieux sensibles sont datés, sourcés et les cas complexes sont renvoyés vers une autorité qualifiée.</p><p>Nisab — Seuil de richesse à partir duquel la Zakat peut devenir exigible selon la catégorie d’avoirs et la méthodologie religieuse retenue ; sa valeur monétaire doit être datée et sourcée. [S47]</p><p>Application dans ce module. FINCLUDIA présente une méthode pédagogique de compréhension et d’estimation, distincte de la fiscalité ; les paramètres religieux sensibles sont datés, sourcés et les cas complexes sont renvoyés vers une autorité qualifiée.</p><p>Hawl — Période de possession prise en compte dans certaines règles de Zakat ; son application dépend de la nature des avoirs et de la méthodologie religieuse suivie. [S47]</p><p>Application dans ce module. FINCLUDIA présente une méthode pédagogique de compréhension et d’estimation, distincte de la fiscalité ; les paramètres religieux sensibles sont datés, sourcés et les cas complexes sont renvoyés vers une autorité qualifiée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('64977d33-ca4b-5ed7-8385-3f1224cebc8c', '23d39037-6954-5f01-a25f-cf22baa57a66', 'text', 3, '{"html": "<h3>Développement des notions</h3><p>1. Zakat. Pour zakat, la plateforme présente la notion, les paramètres nécessaires à l''estimation et leurs sources. Lorsque la situation dépend d''une interprétation religieuse ou d''un cas particulier, l''utilisateur est explicitement orienté vers une autorité qualifiée.</p><p>2. Nisab. Pour nisab, la plateforme présente la notion, les paramètres nécessaires à l''estimation et leurs sources. Lorsque la situation dépend d''une interprétation religieuse ou d''un cas particulier, l''utilisateur est explicitement orienté vers une autorité qualifiée.</p><p>3. Hawl. Pour hawl, la plateforme présente la notion, les paramètres nécessaires à l''estimation et leurs sources. Lorsque la situation dépend d''une interprétation religieuse ou d''un cas particulier, l''utilisateur est explicitement orienté vers une autorité qualifiée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ee7b5fa8-d3c7-5bc7-9595-49814606d23c', '23d39037-6954-5f01-a25f-cf22baa57a66', 'text', 4, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Identifier la catégorie d’avoirs concernée.</p><p>Étape 2. Vérifier le nisab et la méthode retenue à la date d’évaluation.</p><p>Étape 3. Vérifier, lorsque pertinent, la condition de hawl.</p><p>Étape 4. Calculer une estimation pédagogique traçable.</p><p>Étape 5. Présenter les limites et renvoyer les cas complexes à une autorité religieuse qualifiée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('ad8176f2-5eb1-5696-afb4-cd9847784240', '23d39037-6954-5f01-a25f-cf22baa57a66', 'text', 5, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Zakat : nisab, hawl, estimation et traçabilité méthodologique », relevez les données disponibles, identifiez au moins quatre notions parmi Zakat, Nisab, Hawl, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p><ul><li><strong>Publics</strong> : Adultes, familles, entrepreneurs souhaitant utiliser ce module</li><li><strong>Niveau</strong> : N1-N3</li><li><strong>Objectif mesurable</strong> : comprendre nisab, hawl et taux; séparer Zakat et fiscalité; savoir utiliser un calculateur avec méthodologie explicite</li><li><strong>Prérequis</strong> : Fondamentaux du parcours concerné ; source active lorsque la règle est évolutive.</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Zakat</strong> : Prélèvement religieux obligatoire pour les personnes et avoirs remplissant les conditions applicables. FINCLUDIA en présente une estimation pédagogique distincte de la fiscalité et renvoie les cas complexes vers une autorité qualifiée. — [S47]</li><li><strong>Nisab</strong> : Seuil de richesse à partir duquel la Zakat peut devenir exigible selon la catégorie d’avoirs et la méthodologie religieuse retenue ; sa valeur monétaire doit être datée et sourcée. — [S47]</li><li><strong>Hawl</strong> : Période de possession prise en compte dans certaines règles de Zakat ; son application dépend de la nature des avoirs et de la méthodologie religieuse suivie. — [S47]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('db102585-dfed-5d8e-863f-2a2f33fc833b', '23d39037-6954-5f01-a25f-cf22baa57a66', 'text', 6, '{"html": "<h2>Positionnement FINCLUDIA</h2><p>Le module Zakat est pédagogique et distinct de la fiscalité. Il doit expliquer les principes, permettre une estimation et documenter la méthodologie utilisée. Les questions religieuses complexes doivent renvoyer vers des autorités ou experts qualifiés.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('9aa6d908-6506-5215-9275-47f1b5994def', '23d39037-6954-5f01-a25f-cf22baa57a66', 'text', 7, '{"html": "<h2>Référence algérienne 1447 H</h2><p>Pour l''année hégirienne 1447, le ministère des Affaires religieuses et des Wakfs a fixé le nisab à 2 295 000 DA, correspondant à 85 g d''or sur la référence annoncée, avec un taux de 2,5 % pour les avoirs concernés ayant atteint le nisab et accompli un hawl.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('45ffa223-eb9a-51e1-902b-f627517b55a2', '23d39037-6954-5f01-a25f-cf22baa57a66', 'text', 8, '{"html": "<h2>FINCLUDIA Zakat 360</h2><p>Le calculateur doit pouvoir distinguer liquidités, épargne, marchandises commerciales et autres postes selon la méthodologie retenue. La valeur du nisab doit être versionnée par année et source.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('a476ff8c-b50e-5ffe-b8d9-1e71699ffb94', '23d39037-6954-5f01-a25f-cf22baa57a66', 'callout', 9, '{"variant": "info", "title": "Cas algérien", "html": "<p>Base indicative fictive : 3 700 000 DA d''avoirs concernés. À 2,5 %, le calcul arithmétique donne 92 500 DA, sous réserve de la méthodologie religieuse applicable et des ajustements pertinents.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('b081816d-57a8-52c0-8499-c585d9eaad7b', '23d39037-6954-5f01-a25f-cf22baa57a66', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Créez une fiche Zakat fictive avec : liquidités, marchandises, créances et éléments à vérifier. Indiquez ce qui nécessite un avis expert.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('39d16414-5a81-538a-92a7-2d33f19550f0', '23d39037-6954-5f01-a25f-cf22baa57a66', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Corrigé-type : lister séparément liquidités, épargne, marchandises commerciales, créances et éléments incertains ; vérifier nisab et hawl selon la méthodologie retenue ; calculer uniquement sur la base éligible ; signaler tout cas religieux complexe pour avis qualifié. Le calculateur doit conserver année, source et hypothèses.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('3373bcfa-00bd-5e6a-b51f-d7585bf6370e', '23d39037-6954-5f01-a25f-cf22baa57a66', 'text', 12, '{"html": "<p>Validation  : QCM ≥ 80 %, exercice ≥ 70 %, mission/trace terminée et aucune erreur critique. Les données fiscales, religieuses ou réglementaires actives sont datées et sourcées.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `quizzes` (`id`, `formationId`, `scope`, `courseId`, `title`, `instructions`, `passingScore`, `maxAttempts`, `shuffleQuestions`, `isRequired`, `showCorrection`, `isComplete`, `createdAt`, `updatedAt`) VALUES ('c084cfc0-d51b-5d1c-8a5e-b05824b1a80d', 'fae4fb4b-1c6d-5a3f-aeb2-395c9a4befa5', 'course', '23d39037-6954-5f01-a25f-cf22baa57a66', 'QCM — ETH-01', 'QCM à réponse unique. Réussite à 80 % ; chaque réponse est expliquée après la correction.', 80, NULL, 1, 1, 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
