INSERT IGNORE INTO `courses` (`id`, `formationId`, `title`, `summary`, `body`, `position`, `isRequired`, `estimatedMinutes`, `createdAt`, `updatedAt`) VALUES ('c313aa62-41fd-5324-ba86-290d461b7d4a', 'fae4fb4b-1c6d-5a3f-aeb2-395c9a4befa5', 'ESG-01 — Finance verte : coût, économies, payback et risque', NULL, NULL, 4, 1, 25, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('cb625c78-c9db-524c-a746-01ae7e85fed8', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'text', 1, '{"html": "<h2>Mini-cours développé</h2><p>Objectif de compréhension. Maîtriser les notions centrales de « Finance verte : coût, économies, payback et risque » et savoir les appliquer à une situation réelle ou simulée. Le cours ne s''arrête pas au vocabulaire : l''utilisateur doit être capable d''identifier les données utiles, d''effectuer le raisonnement ou le calcul approprié, puis d''expliquer la décision obtenue et ses limites.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('87b66765-7e0c-567f-b5cb-ed94278338bf', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'text', 2, '{"html": "<h3>Définitions essentielles du mini-cours</h3><p>Finance verte — Approche de financement ou d’investissement intégrant des objectifs environnementaux, tout en exigeant une analyse des coûts, économies, risques, durée et viabilité financière. [S47]</p><p>Application dans ce module. La décision combine coût initial, économies attendues, durée de récupération, risque technique et impact ; un avantage environnemental ne dispense pas d’une analyse financière rigoureuse.</p><p>CAPEX — Dépense d’investissement destinée à acquérir ou améliorer un actif utilisé durablement dans l’activité. [S13], [S42]</p><p>Application dans ce module. La décision combine coût initial, économies attendues, durée de récupération, risque technique et impact ; un avantage environnemental ne dispense pas d’une analyse financière rigoureuse.</p><p>Payback — Délai de récupération simple d’un investissement, souvent estimé par investissement initial divisé par économie ou cash-flow annuel lorsque l’hypothèse de stabilité est acceptable. [S47]</p><p>Application dans ce module. La décision combine coût initial, économies attendues, durée de récupération, risque technique et impact ; un avantage environnemental ne dispense pas d’une analyse financière rigoureuse.</p><p>Rendement — Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon. [S01], [S41]</p><p>Application dans ce module. La décision combine coût initial, économies attendues, durée de récupération, risque technique et impact ; un avantage environnemental ne dispense pas d’une analyse financière rigoureuse.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('4b6550bf-9baf-5d08-a9b7-5a9f73a80cd8', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'text', 3, '{"html": "<h3>Développement des notions</h3><p>1. Finance verte. Pour finance verte, l''utilisateur mesure d''abord les flux financiers du projet, puis les bénéfices environnementaux annoncés, les risques techniques et la durée. Une économie future n''est intégrée qu''avec une hypothèse explicite et testée.</p><p>2. CAPEX. Pour capex, l''utilisateur mesure d''abord les flux financiers du projet, puis les bénéfices environnementaux annoncés, les risques techniques et la durée. Une économie future n''est intégrée qu''avec une hypothèse explicite et testée.</p><p>3. Payback. Le payback mesure le temps nécessaire pour récupérer l’investissement initial à partir des économies ou cash-flows attendus. Il est simple à comprendre mais ignore ce qui se passe après la récupération et, dans sa version simple, la valeur temps de l’argent.</p><p>Repère de calcul. Payback simple = investissement initial ÷ économie ou cash-flow annuel moyen lorsque l’hypothèse de stabilité est acceptable.</p><p>4. Rendement. Pour rendement, l''utilisateur mesure d''abord les flux financiers du projet, puis les bénéfices environnementaux annoncés, les risques techniques et la durée. Une économie future n''est intégrée qu''avec une hypothèse explicite et testée.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('1f568e47-f6b0-58cc-953b-6d7f00fe82da', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'text', 4, '{"html": "<h3>Méthode FINCLUDIA — passer de la notion à la décision</h3><p>Étape 1. Mesurer coût initial et économies attendues.</p><p>Étape 2. Intégrer maintenance, durée de vie et risque technique.</p><p>Étape 3. Calculer un payback simple si pertinent.</p><p>Étape 4. Tester plusieurs hypothèses de prix ou de production.</p><p>Étape 5. Comparer l’intérêt financier et l’impact environnemental sans promettre un rendement.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('48f53463-c62e-571b-90e5-c53eb2067385', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'text', 5, '{"html": "<h3>Formules et repères de calcul</h3><p>Payback simple = investissement initial ÷ économie ou cash-flow annuel moyen lorsque l’hypothèse de stabilité est acceptable.</p><p>Toute formule doit être accompagnée de la période, de l’unité, des hypothèses et d’une interprétation. Un résultat calculé n’est pas automatiquement une recommandation.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('43140023-6783-5df2-a264-fba4ff65daba', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'text', 6, '{"html": "<h3>Exercice guidé de compréhension</h3><p>À partir d''un cas fictif lié à « Finance verte : coût, économies, payback et risque », relevez les données disponibles, identifiez au moins quatre notions parmi Finance verte, CAPEX, Payback, Rendement, puis expliquez en cinq à huit lignes comment elles s''enchaînent avant toute décision.</p><p>Corrigé-type. Une réponse complète doit : 1) reprendre correctement les définitions ; 2) citer les données utiles ; 3) distinguer faits, hypothèses et règles ; 4) effectuer le calcul ou la classification si le module en comporte un ; 5) interpréter le résultat ; 6) proposer une action proportionnée sans présenter la simulation comme une certitude.</p><ul><li><strong>Publics</strong> : PME/PMI, étudiants, investisseurs</li><li><strong>Niveau</strong> : N2-N4</li><li><strong>Objectif mesurable</strong> : comprendre capex vert; calculer un retour simple; distinguer impact et rentabilité</li><li><strong>Prérequis</strong> : Fondamentaux du parcours concerné ; source active lorsque la règle est évolutive.</li><li><strong>Notion</strong> : Définition pédagogique — Réf.</li><li><strong>Finance verte</strong> : Approche de financement ou d’investissement intégrant des objectifs environnementaux, tout en exigeant une analyse des coûts, économies, risques, durée et viabilité financière. — [S47]</li><li><strong>CAPEX</strong> : Dépense d’investissement destinée à acquérir ou améliorer un actif utilisé durablement dans l’activité. — [S13], [S42]</li><li><strong>Payback</strong> : Délai de récupération simple d’un investissement, souvent estimé par investissement initial divisé par économie ou cash-flow annuel lorsque l’hypothèse de stabilité est acceptable. — [S47]</li><li><strong>Rendement</strong> : Variation de valeur ou revenu généré par un placement sur une période, à analyser conjointement avec le risque, les frais, la liquidité et l’horizon. — [S01], [S41]</li></ul>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('79dda505-6e07-5d09-b0d2-347385cc0a59', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'text', 7, '{"html": "<h2>Investissement vert</h2><p>Un investissement vert peut viser réduction d''énergie, d''eau, de déchets ou d''émissions. Il doit être évalué financièrement comme tout projet : coût initial, économies, durée de vie, maintenance et risques.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('28b1cba0-ec7a-5889-84e0-8b753c5a99b2', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'text', 8, '{"html": "<h2>Payback et ROI</h2><p>Le délai de récupération simple = investissement initial / économie annuelle approximative, lorsque les flux sont relativement stables. C''est un indicateur simple mais incomplet.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('df749746-1075-554f-bd15-665c0a31eae0', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'callout', 9, '{"variant": "info", "title": "Cas algérien", "html": "<p>Installation énergétique : coût 8 M DA, économie estimée 1,9 M DA/an. Payback simple ≈ 4,2 ans, avant prise en compte de maintenance, financement et variation des économies.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('88b804df-e551-5b8b-aeef-9603da90e74f', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'text', 10, '{"html": "<h2>Exercice d’application</h2><p>Évaluez un projet fictif d''efficacité énergétique avec coût, économies et trois scénarios de prix de l''énergie.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('fcd99421-9090-5cc0-9448-0d85f92b1d91', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'text', 11, '{"html": "<h2>Corrigé-type</h2><p>Corrigé-type : payback simple = investissement initial / économies annuelles. Construire un scénario bas, central et haut de prix/économies ; intégrer maintenance, durée de vie, financement et risques. Un payback court ne suffit pas à prouver la rentabilité globale ni l’impact réel.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('be827f04-6fbc-59c7-9a64-29d9739cc30c', 'c313aa62-41fd-5324-ba86-290d461b7d4a', 'text', 12, '{"html": "<p>Validation  : QCM ≥ 80 %, exercice ≥ 70 %, mission/trace terminée et aucune erreur critique. Les données fiscales, religieuses ou réglementaires actives sont datées et sourcées.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
