INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8bfa5875-126b-575a-b4b8-26710ca9216d', 'b0e350bc-120a-5925-905a-c930c72d9bc7', 'text', 1, '{"html": "<p>Scénario : un salarié développe une activité complémentaire, souhaite comprendre sa fiche de paie, identifier les informations nécessaires à sa situation fiscale, planifier un module Zakat facultatif et comparer un investissement d’efficacité énergétique. Il doit séparer les cadres fiscal, religieux et financier.</p>"}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO `lesson_blocks` (`id`, `courseId`, `type`, `position`, `data`, `createdAt`, `updatedAt`) VALUES ('8cf28d3a-2c7c-5f0d-a45d-ccade182ddab', 'b0e350bc-120a-5925-905a-c930c72d9bc7', 'table', 2, '{"headers": ["Travail demandé", "Corrigé-type attendu"], "rows": [["Repérer brut, retenues et net sur une fiche fictive", "Le budget s’appuie sur le net récurrent ; les éléments exceptionnels restent séparés."], ["Lister les informations à vérifier avant une obligation fiscale", "Statut, activité, base/CA, période, régime, source officielle et date ; ne pas appliquer un taux hors contexte."], ["Construire une estimation Zakat pédagogique", "Séparer avoirs, conditions, nisab/hawl et éléments nécessitant avis qualifié ; documenter la méthode."], ["Comparer un CAPEX vert", "Calculer payback et scénarios d’économies, puis intégrer maintenance, financement et risques."]], "caption": ""}', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
